Object.assign(window.TEM8_DICTIONARY, {"senile":{"media":{"uk":"media/uk/senile__gb_1.mp3","us":"media/us/senile__us_1.mp3"},"oxford":{"phon":"ˈsiːnaɪl","pos":"adjective","senses":[{"en":"behaving in a confused or strange way, and unable to remember things, because you are old","cn":"衰老的；年老糊涂的","lab":"often offensive","ex":{"en":"I think she's going senile.","cn":"我想她是衰老了。"}},{"en":"caused by old age","cn":"老年的；老年性的","lab":"medical","ex":{"en":"senile cataracts","cn":"老年性白内障"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"老糊涂的;老态龙钟的;年老而无力自理的","en":"If old people become senile, they become confused, can no longer remember things, and are unable to look after themselves."}]},"examples":[{"en":"an old man on the verge of senility","cn":"渐显龙钟之态的老年人"},{"en":"I think she's going senile.","cn":"我想她是衰老了。"}]},"sea":{"media":{"uk":"media/uk/sea__gb_1.mp3","us":"media/us/sea__us_1.mp3"},"oxford":{"phon":"siː","pos":"noun","senses":[{"en":"the salt water that covers most of the earth’s surface and surrounds its continents and islands","cn":"海；海洋","g":"[uncountable]","lab":"literary","ex":{"en":"The waste was dumped in the sea.","cn":"废物倒入海中。"}},{"en":"a large area of salt water that is part of an ocean or surrounded by land","cn":"海","g":"[countable]","ex":{"en":"the North Sea","cn":"北海"}},{"en":"the movement of the waves of the sea","cn":"海面情况；海浪状况","g":"[countable]","ex":{"en":"It was a calm sea.","cn":"海上风平浪静。"}},{"en":"a large amount of something that stretches over a wide area","cn":"大量；茫茫一片","g":"[singular]","ex":{"en":"He looked down at the sea of smiling faces before him.","cn":"他看着眼前这笑脸的海洋。"}}]},"collins":{"senses":[{"pos":"N-SING 单数名词","cn":"海;海洋","en":"The sea is the salty water that covers about three-quarters of the earth's surface.","ex":{"en":"Most of the kids have never seen the sea","cn":"多数孩子从未见过海。"}},{"pos":"N-PLURAL 复数名词","cn":"海面状态;海域","en":"You use seas when you are describing the sea at a particular time or in a particular area.","ex":{"en":"He drowned after 30 minutes in the rough seas","cn":"他在汹涌的海浪中挣扎了 30 分钟后淹死了。"}},{"pos":"N-COUNT; N-IN-NAMES 名称名词；名称名词","cn":"内海","en":"A sea is a large area of salty water that is part of an ocean or is surrounded by land.","ex":{"en":"...the North Sea.","cn":"北海"}},{"pos":"N-SING 单数名词","cn":"大量;茫茫一片","en":"A sea of people or things is a very large number of them together.","ex":{"en":"Down below them was the sea of upturned faces","cn":"他们下面是无数张仰望的脸。"}},{"pos":"PHRASE 短语","cn":"茫然;困惑;不知所措","en":"You can say that someone is all at sea when they are in a state of confusion or uncertainty.","ex":{"en":"If you had never seen a telly ad, you would be all at sea with popular culture.","cn":"如果你从没看过电视广告，你就搞不懂什么是大众文化。"}},{"pos":"PHRASE 短语","cn":"在海上;在海里","en":"At sea means on or under the sea, far away from land.","ex":{"en":"The boats remain at sea for an average of ten days at a time","cn":"这些船只每次在海上平均航行 10 天。"}},{"pos":"PHRASE 短语","cn":"到海上;向海上","en":"If you go or look out to sea, you go or look across the sea.","ex":{"en":"...fishermen who go to sea for two weeks at a time","cn":"每次出海两周的渔夫们"}}]},"examples":[{"en":"She fell overboard and was swept out to sea.","cn":"她从船上落入水中，被海浪冲向外海。"},{"en":"A swimmer drowned in the sea/ocean this morning.","cn":"今天早上一名游泳者在海里淹死了。"}]},"self-respect":{"oxford":{"phon":"ˌself rɪˈspekt","pos":"noun","senses":[{"en":"a feeling of being proud of yourself and that what you do, say, etc. is right and good","cn":"自尊（心）","ex":{"en":"Despite poverty and appalling conditions, these people still manage to keep their dignity and self-respect.","cn":"虽然面对贫穷和恶劣条件，这些人仍然设法保持自己的尊严和自尊。"}}]},"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"自尊(心)","en":"Self-respect is a feeling of confidence and pride in your own ability and worth.","ex":{"en":"They have lost not only their jobs, but their homes, their self-respect and even their reason for living.","cn":"他们不仅丢掉了工作，还失去了居所、自尊乃至生存的理由。"}}]},"media":{"uk":"media/uk/self_respect_1_gb_1.mp3","us":"media/us/self_respect_1_us_1.mp3"},"examples":[{"en":"It’s difficult to keep your self-respect when you have been unemployed for a long time.","cn":"你长时间失业就很难维持自尊。"}]},"secure":{"media":{"uk":"media/uk/secure__gb_1.mp3","us":"media/us/secure__us_1.mp3"},"oxford":{"phon":"sɪˈkjʊə(r)","pos":"verb","senses":[{"en":"to obtain or achieve something, especially when this means using a lot of effort","cn":"（尤指经过努力）获得，取得，实现","sc":"get something","ex":{"en":"to secure a contract/deal/funding","cn":"订立合同；达成协议；获得资金"}},{"en":"to attach or fasten something so that it does not move","cn":"拴牢；扣紧；系牢","sc":"fasten something","ex":{"en":"She secured the rope firmly to the back of the car.","cn":"她把绳子牢牢地拴在车尾。"}},{"en":"to protect something so that it is safe and difficult to attack or damage","cn":"保护；保卫；使安全","lab":"figurative","sc":"protect from harm","ex":{"en":"to secure a property against intruders","cn":"保护房产以免外人闯入"}},{"en":"to legally agree to give somebody property or goods that are worth the same amount as the money that you have borrowed from them, if you are unable to pay the money back","cn":"抵押","sc":"a loan","ex":{"en":"a loan secured on the house","cn":"以房子作抵押的贷款"}},{"en":"likely to continue or be successful for a long time","cn":"可靠的；牢靠的；稳固的","sc":"certain/safe","ex":{"en":"a secure job/income","cn":"稳定的工作／收入"},"pos":"adjective"},{"en":"where somebody/something cannot be harmed; that cannot be affected or harmed by something","cn":"安全的；稳妥的","sc":"certain/safe","ex":{"en":"It's important to keep your documents secure.","cn":"保证你的文件安全很重要。"},"pos":"adjective"},{"en":"feeling happy and confident about yourself or a particular situation","cn":"安心的；有把握的","sc":"happy/confident","ex":{"en":"At last they were able to feel secure about the future.","cn":"他们终于觉得不必为将来而担忧了。"},"pos":"adjective"},{"en":"guarded and/or made stronger so that it is difficult for people to enter or leave","cn":"严密把守的；牢固的；坚固的","sc":"building/door/room","ex":{"en":"Check that all windows and doors have been made as secure as possible.","cn":"看看是不是所有的门窗都关紧了。"},"pos":"adjective"},{"en":"not likely to move, fall down, etc.","cn":"牢固的；稳固的；坚固的","lab":"figurative","sc":"not likely to move or fall","ex":{"en":"The aerial doesn't look very secure to me.","cn":"我看这天线不太牢固。"},"pos":"adjective"}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"(经过努力)获得，争取到","en":"If you secure something that you want or need, you obtain it, often after a lot of effort.","ex":{"en":"Federal leaders continued their efforts to secure a ceasefire","cn":"联邦领导人继续争取促成停火协议。"}},{"pos":"VERB 动词","cn":"使…免遭攻击(或伤害);保卫;保护","en":"If you secure a place, you make it safe from harm or attack.","ex":{"en":"Staff withdrew from the main part of the prison but secured the perimeter","cn":"工作人员从监狱的主要区域撤出，但外围仍派人守卫。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"锁牢的;严密防守的","en":"A secure place is tightly locked or well protected, so that people cannot enter it or leave it.","ex":{"en":"We shall make sure our home is as secure as possible from now on.","cn":"我们应该确保家里从今往后尽量锁紧门窗。"}},{"pos":"VERB 动词","cn":"使固定;缚牢;系紧","en":"If you secure an object, you fasten it firmly to another object.","ex":{"en":"He helped her close the cases up, and then he secured the canvas straps as tight as they would go","cn":"他帮她关上箱子，然后将帆布带子尽量系紧。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"固定不动的;绑紧的;系牢的","en":"If an object is secure, it is fixed firmly in position.","ex":{"en":"Check joints are secure and the wood is sound","cn":"检查一下连接处是否稳固及木料是否结实。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"稳固的;稳定的;可靠的","en":"If you describe something such as a job as secure, it is certain not to change or end.","ex":{"en":"...trade union demands for secure wages and employment","cn":"工会要求稳定的工资和工作。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"(基础)坚固的，坚实的，可靠的","en":"A secure base or foundation is strong and reliable.","ex":{"en":"He was determined to give his family a secure and solid base.","cn":"他决定给家人一个牢固坚实的生活基础。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"安心的;心里踏实的;无忧无虑的","en":"If you feel secure, you feel safe and happy and are not worried about life.","ex":{"en":"She felt secure and protected when she was with him","cn":"和他在一起的时候，她感到一种被人保护的安全感。"}},{"pos":"VERB 动词","cn":"为(借款等)作保","en":"If a loan is secured, the person who lends the money may take property such as a house from the person who borrows the money if they fail to repay it.","ex":{"en":"The loan is secured against your home","cn":"这笔贷款以你的房子作为抵押。"}}]},"examples":[{"en":"She finished the match, secure in the knowledge that she was through to the next round.","cn":"她打完比赛，知道自己已进入下一轮，心里踏实了。"},{"en":"Information must be stored so that it is secure from accidental deletion.","cn":"必须把资料保存起来，这样才不至于无意中删除。"}]},"sequence":{"media":{"uk":"media/uk/sequence__gb_1.mp3","us":"media/us/sequence__us_1.mp3"},"oxford":{"phon":"ˈsiːkwəns","pos":"noun","senses":[{"en":"a set of events, actions, numbers, etc. which have a particular order and which lead to a particular result","cn":"一系列；一连串","g":"[countable]","ex":{"en":"He described the sequence of events leading up to the robbery.","cn":"他描述了抢劫案发生前的一系列有关情况。"}},{"en":"the order that events, actions, etc. happen in or should happen in","cn":"顺序；次序","g":"[countable, uncountable]","ex":{"en":"The tasks had to be performed in a particular sequence.","cn":"这些任务必须按一定次序去执行。"}},{"en":"a part of a film that deals with one subject or topic or consists of one scene","cn":"序列（电影中表现同一主题或场面的片段）","g":"[countable]","ex":{"en":"the dream sequence in the middle of the movie","cn":"电影中间的梦境片段"}},{"en":"to arrange things into a sequence","cn":"按顺序排列","lab":"specialist","pos":"verb"},{"en":"to identify the order in which a set of genes or parts of molecules are arranged","cn":"测定（整套基因或分子成分的）序列","lab":"biology","ex":{"en":"The human genome has now been sequenced.","cn":"人体基因组的序列现已测定。"},"pos":"verb"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"一系列;一连串","en":"A sequence of events or things is a number of events or things that come one after another in a particular order.","ex":{"en":"...the sequence of events which led to the murder.","cn":"导致谋杀发生的一连串事件"}},{"pos":"N-COUNT 可数名词","cn":"顺序;次序;序列","en":"A particular sequence is a particular order in which things happen or are arranged.","ex":{"en":"...the colour sequence yellow, orange, purple, blue, green and white","cn":"黄、橙、紫、蓝、绿、白的颜色顺序"}},{"pos":"N-COUNT 可数名词","cn":"(电影中描述某一组动作的)连续镜头,片段","en":"A film sequence is a part of a film that shows a single set of actions.","ex":{"en":"The best sequence in the film occurs when Roth stops at a house he used to live in.","cn":"电影中最棒的一组镜头出现于罗思在他曾住过的一幢屋子前驻足时。"}},{"pos":"N-COUNT 可数名词","cn":"(基因)排列顺序，序列","en":"A gene sequence or a DNA sequence is the order in which the elements making up a particular gene are combined.","ex":{"en":"The project is nothing less than mapping every gene sequence in the human body.","cn":"这个项目就是要绘制人体所有基因序列的图谱。"}}]},"examples":[{"en":"He described the sequence of events leading up to the robbery.","cn":"他描述了抢劫案发生前的一系列有关情况。"},{"en":"The tasks had to be performed in a particular sequence.","cn":"这些任务必须按一定次序去执行。"}]},"semantically":{"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"relating to the meanings of words","cn":""}]},"media":{"uk":"media/uk/semantically__gb_1.mp3","us":"media/us/semantically__us_1.mp3"},"oxford":{"phon":"sɪˈmæntɪkli","pos":"adverb","senses":[{"en":"in a way that is connected with the meaning of words and sentences","cn":"语义的","ex":{"en":"semantically related words","cn":"语义相关的词汇"}}]}},"seine":{"media":{"uk":"media/uk/seine__gb_1.mp3","us":"media/us/seine__us_1.mp3"},"oxford":{"phon":"seɪn","pos":"noun","senses":[{"en":"a type of fishing net which hangs down in the water and is pulled together at the ends to catch fish","cn":"（捕鱼用）围网"}]}},"self-conscious":{"oxford":{"phon":"ˌself ˈkɒnʃəs","pos":"adjective","senses":[{"en":"nervous or embarrassed about your appearance or what other people think of you","cn":"（因在意自己的外表或他人的看法）局促不安的，难为情的，不自然的","ex":{"en":"He's always been self-conscious about being so short.","cn":"他老为自己身材矮小而觉得难为情。"}},{"en":"done in a way that shows you are aware of the effect that is being produced","cn":"刻意的；有意而为的","lab":"often disapproving","ex":{"en":"The humour of the play is self-conscious and contrived.","cn":"这部剧的幽默是刻意而为的，而且牵强做作。"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"忸怩的;害羞的;难为情的;不自然的","en":"Someone who is self-conscious is easily embarrassed and nervous because they feel that everyone is looking at them and judging them.","ex":{"en":"I felt a bit self-conscious in my swimming costume","cn":"我穿着游泳衣觉得有点害羞。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"有强烈自我意识的;高度自觉的","en":"If you describe someone or something as self-conscious, you mean that they are strongly aware of who or what they are.","ex":{"en":"They were forged by them, moreover, into a self-conscious nation as early as the 10th century","cn":"另外，早在10世纪，他们就被其锻造成了一个具有自我意识的民族。"}}]},"media":{"uk":"media/uk/self_conscious_1_gb_1.mp3","us":"media/us/self_conscious_1_us_1.mp3"},"examples":[{"en":"The humour of the play is self-conscious and contrived.","cn":"这部剧的幽默是刻意而为的，而且牵强做作。"},{"en":"He's always been self-conscious about being so short.","cn":"他老为自己身材矮小而觉得难为情。"}]},"sewn":{"collins":{"senses":[{"pos":"","cn":"","en":"Sewn is the past participle of sew."}]},"media":{"uk":"media/uk/sewn__gb_1.mp3","us":"media/us/sewn__us_1.mp3"}},"seat":{"media":{"uk":"media/uk/seat__gb_1.mp3","us":"media/us/seat__us_1.mp3"},"oxford":{"phon":"siːt","pos":"noun","senses":[{"en":"a place where you can sit, for example a chair","cn":"座位，坐处（如椅子等）","sc":"place to sit","ex":{"en":"She sat back in her seat.","cn":"她坐在座位上，朝后靠着。"}},{"en":"with the number of seats mentioned","cn":"有…座位的；有…座的","lab":"British English","sc":"-seater","ex":{"en":"a ten-seater minibus","cn":"十座小公共汽车"}},{"en":"the part of a chair, etc. on which you actually sit","cn":"（椅子等的）座部","sc":"part of chair","ex":{"en":"a steel chair with a plastic seat","cn":"塑料座部的钢架椅子"}},{"en":"a place where you pay to sit in a plane, train, theatre, etc.","cn":"座位","sc":"in plane/train/theatre","ex":{"en":"Call the theatre box office to book your seats.","cn":"致电剧院售票处预订座位。"}},{"en":"an official position as a member of a parliament, council, committee, etc.","cn":"（议会、理事会、委员会等的）席位","lab":"British English","sc":"official position","ex":{"en":"a seat on the city council/in Parliament/in Congress","cn":"市政会／议会／国会席位"}},{"en":"a place where people are involved in a particular activity, especially a city that has a university or the offices of a government","cn":"（尤指大学或政府机关）所在地；中心","lab":"formal","sc":"town/city","ex":{"en":"Washington is the seat of government of the US.","cn":"华盛顿是美国政府所在地。"}},{"en":"a large house in the country that belongs to a member of the upper class","cn":"（上层社会人士的）乡村宅第","lab":"British English","sc":"country house","ex":{"en":"For the first two years of her life she lived at Ickworth, the family seat in Sussex.","cn":"在她生命的头两年里，她住在苏塞克斯的家族所在地伊克沃斯。"}},{"en":"the part of the body on which a person sits","cn":"臀部","lab":"especially formal","sc":"part of body"},{"en":"the part of a pair of trousers that covers a person’s seat","cn":"（裤子的）后裆，臀部","sc":"part of trousers/pants"},{"en":"to give somebody a place to sit; to sit down in a place","cn":"向…提供座位；（使）就座；坐；落座","lab":"formal","sc":"sit down","ex":{"en":"Please wait to be seated (= in a restaurant, etc.).","cn":"请等候安排入座。"},"pos":"verb"},{"en":"to have enough seats for a particular number of people","cn":"可坐…人；能容纳…人","sc":"of building/vehicle","ex":{"en":"The aircraft seats 200 passengers.","cn":"这架飞机能坐 200 名乘客。"},"pos":"verb"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"座椅;椅子;座位","en":"A seat is an object that you can sit on, for example a chair.","ex":{"en":"Stephen returned to his seat","cn":"斯蒂芬回到自己的座位上。"}},{"pos":"N-COUNT 可数名词","cn":"(椅子等的)座部,椅面","en":"The seat of a chair is the part that you sit on.","ex":{"en":"The stool had a torn, red plastic seat.","cn":"那个凳子的红色塑料座面已经破旧不堪。"}},{"pos":"VERB 动词","cn":"坐下;就座","en":"If you seat yourself somewhere, you sit down.","ex":{"en":"He waved towards a chair, and seated himself at the desk.","cn":"他挥手指了指一把椅子，自己在书桌旁坐了下来。"}},{"pos":"VERB 动词","cn":"(房间、车辆)可坐…人，容纳…人","en":"A building or vehicle that seats a particular number of people has enough seats for that number.","ex":{"en":"The Theatre seats 570.","cn":"那个剧院可容纳 570 人。"}},{"pos":"N-SING 单数名词","cn":"(裤子的)臀部","en":"The seat of a piece of clothing is the part that covers your bottom.","ex":{"en":"Then he got up and brushed off the seat of his jeans.","cn":"然后他站起来，拍了拍牛仔裤的臀部。"}},{"pos":"N-COUNT 可数名词","cn":"(国会、议会、参议院中的)席位","en":"When someone is elected to a parliament, congress, or senate, you can say that they, or their party, have won a seat .","ex":{"en":"Independent candidates won the majority of seats on the local council.","cn":"无党派候选人在地方议会选举中赢得了多数席位。"}},{"pos":"N-COUNT 可数名词","cn":"(公司董事会、委员会中的)席位，职位","en":"If someone has a seat on the board of a company or on a committee, they are a member of it.","ex":{"en":"He has been unsuccessful in his attempt to win a seat on the board of the company.","cn":"他始终未能如愿以偿地在公司董事会中谋得一席之地。"}},{"pos":"N-COUNT 可数名词","cn":"(组织、活动的)中心地，所在地;(豪门的)宅邸","en":"The seat of an organization, a wealthy family, or an activity is its base.","ex":{"en":"Gunfire broke out early this morning around the seat of government in Lagos.","cn":"今天凌晨在拉各斯的政府大楼周围发生了枪战。"}},{"pos":"PHRASE 短语","cn":"让权于他人;退居次要位置","en":"If you take a back seat, you allow other people to have all the power and to make all the decisions.","ex":{"en":"You need to take a back seat and think about both past and future","cn":"你得退居二线，把过去和将来都捋清楚。"}},{"pos":"PHRASE 短语","cn":"坐下;入座","en":"If you take a seat, you sit down.","ex":{"en":"'Take a seat,' he said in a bored tone","cn":"“请坐，”他不耐烦地说道。"}},{"pos":"","cn":"","en":"bums on seats→see: ; in the driving seat→see: ; by the seat of your pants→see: ;"}]},"examples":[{"en":"We all filed back to our seats in silence.","cn":"我们都默默无语，一个跟一个地回到座位上。"},{"en":"The majority of seats on the board will be held by business representatives.","cn":"理事会的多数席位将由工商界代表担任。"}]},"searching":{"oxford":{"phon":"ˈsɜːtʃɪŋ","pos":"adjective","senses":[{"en":"trying to find out the truth about something; complete and serious","cn":"深挖细究的；认真彻底的","ex":{"en":"a searching investigation/analysis/examination","cn":"认真彻底的调查／分析／检查"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"(问题、目光)洞察真相的，质问的","en":"A searching question or look is intended to discover the truth about something.","ex":{"en":"They asked her some searching questions on moral philosophy and logic.","cn":"他们深入询问了她一些有关伦理学和逻辑学的问题。"}}]},"media":{"uk":"media/uk/searching__gb_1.mp3","us":"media/us/searching__us_1.mp3"},"examples":[{"en":"The police asked him some searching questions.","cn":"警方问了他一些深入的问题。"},{"en":"He gave her a long searching look.","cn":"他用探究的目光盯着她瞧。"}]},"senate":{"oxford":{"phon":"ˈsenət","pos":"noun","senses":[{"en":"one of the two groups of elected politicians who make laws in some countries, for example in the US, Australia, Canada and France. The Senate is smaller than the other group but higher in rank. Many state parliaments in the US also have a Senate.","cn":"参议院（美国、澳大利亚、加拿大、法国等国家的两个立法机构之一；美国许多州议会也设有参议院）","g":"[singular]","lab":"especially North American English","ex":{"en":"a member of the Senate","cn":"参议员"}},{"en":"(in some countries) the group of people who control a university","cn":"（某些国家的）大学理事会，大学评议会","g":"[countable, usually singular, uncountable]","ex":{"en":"the senate of Loughborough University","cn":"拉夫伯勒大学评议会"}},{"en":"(in ancient Rome) the most important council of the government; the building where the council met","cn":"（古罗马的）元老院","g":"[singular]"}]},"collins":{"senses":[{"pos":"N-PROPER-COLL 专有集合名词","cn":"(美国、澳大利亚等国议会的)参议院","en":"The Senate is the smaller and more important of the two parts of the parliament in some countries, for example the United States and Australia. →see usage note at:","ex":{"en":"The Senate is expected to pass the bill shortly.","cn":"预计参议院不久就会通过此议案。"}},{"pos":"N-PROPER-COLL 专有集合名词","cn":"（某些大学的）大学理事会，大学评议会","en":"Senate or the Senate is the governing council at some universities.","ex":{"en":"By the time I was Vice Chancellor, Senate had become a much larger and a much more democratic body","cn":"到了我当校长的时候，大学评议会的人员规模已显著扩大，也变得更加民主了。"}}]},"media":{"uk":"media/uk/senate__gb_1.mp3","us":"media/us/senate__us_1.mp3"},"examples":[{"en":"the senate of Loughborough University","cn":"拉夫伯勒大学评议会"},{"en":"a Senate committee","cn":"参议院委员会"}]},"severe":{"media":{"uk":"media/uk/severe__gb_1.mp3","us":"media/us/severe__us_1.mp3"},"oxford":{"phon":"sɪˈvɪə(r)","pos":"adjective","senses":[{"en":"extremely bad or serious","cn":"极为恶劣的；十分严重的","sc":"very bad","ex":{"en":"His injuries are severe.","cn":"他的伤很重。"}},{"en":"punishing somebody in an extreme way when they break a particular set of rules","cn":"严厉的；重的","sc":"punishment","ex":{"en":"a severe punishment/sentence/penalty","cn":"严惩；重判；重罚"}},{"en":"not kind or showing sympathy; not smiling or showing approval","cn":"严厉的；严肃的；苛刻的","sc":"not kind","ex":{"en":"a severe expression","cn":"严厉的表情"}},{"en":"extremely difficult and requiring a lot of skill or ability","cn":"艰难的；艰巨的；难度很大的","sc":"very difficult","ex":{"en":"The marathon is a severe test of stamina.","cn":"马拉松赛跑是对耐力的严峻考验。"}},{"en":"extremely plain and without any decoration","cn":"过于简朴的","lab":"disapproving","sc":"style/appearance/clothing","ex":{"en":"Modern furniture is a little too severe for my taste.","cn":"现代家具有点过于简朴，我不大喜欢。"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"十分严重的;极为恶劣的","en":"You use severe to indicate that something bad or undesirable is great or intense.","ex":{"en":"...a business with severe cash flow problems","cn":"有严重资金周转问题的公司"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"(惩罚、批评)严厉的，严重的，苛刻的","en":"Severe punishments or criticisms are very strong or harsh.","ex":{"en":"This was a dreadful crime and a severe sentence is necessary","cn":"这一罪行十分恶劣，必须要重判。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"(外貌、外观)简朴的，朴素的,不加修饰的","en":"If you describe the appearance of someone or something as severe, you do not like its plain appearance and lack of decoration.","ex":{"en":"...wearing her felt hats and severe grey suits","cn":"戴着她的毡帽，穿着朴素的灰色套装"}}]},"examples":[{"en":"She was a severe woman who seldom smiled.","cn":"她是个严肃的女人，脸上很少出现笑容。"},{"en":"The chances of a full recovery will depend on the severity of her injuries.","cn":"能否彻底康复取决于她受伤的严重程度。"}]},"self-pity":{"oxford":{"phon":"ˌself ˈpɪti","pos":"noun","senses":[{"en":"a feeling of sadness for yourself, especially because of something unpleasant or unfair that has happened to you","cn":"自怜","ex":{"en":"She's not someone who likes to wallow in self-pity.","cn":"她不是那种喜欢自怜的人。"}}]},"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"(尤指不必要或过度夸张的)自怜，自哀","en":"Self-pity is a feeling of unhappiness that you have about yourself and your problems, especially when this is unnecessary or greatly exaggerated.","ex":{"en":"I was unable to shake off my self-pity","cn":"我无法摆脱自怜自哀的情绪。"}}]},"media":{"uk":"media/uk/self_pity_1_gb_1.mp3","us":"media/us/self_pity_1_us_1.mp3"},"examples":[{"en":"She's not someone who likes to wallow in self-pity.","cn":"她不是那种喜欢自怜的人。"},{"en":"a note of self-pity in her voice","cn":"她话音中一点自怜的口气"}]},"separates":{"oxford":{"phon":"ˈseprəts","pos":"noun","senses":[{"en":"individual pieces of clothing, for example skirts, jackets, and trousers, that are designed to be worn together in different combinations","cn":"（可与其他衣服搭配穿着的）单件衣服，单品"}]},"media":{"uk":"media/uk/separates__gb_1.mp3","us":"media/us/separates__us_1.mp3"}},"se":{"oxford":{"phon":"","pos":"abbreviation","senses":[{"en":"south-east; south-eastern","cn":"东南方（的）；东南部（的）","ex":{"en":"SE Asia","cn":"东南亚"}}]},"media":{"uk":"media/ldoce/hwd/bre/0/lpd_se.mp3","us":"media/ldoce/hwd/ame/0/lpd_se.mp3"},"examples":[{"en":"SE Asia","cn":"东南亚"}],"collins":{"senses":[{"pos":"","cn":"","en":"SE is a written abbreviation for (书面缩略=) south-east."}]}},"sect":{"oxford":{"phon":"sekt","pos":"noun","senses":[{"en":"a small group of people who belong to a particular religion but who have some beliefs or practices which separate them from the rest of the group","cn":"派别；宗派","ex":{"en":"The Shakers are an American religious sect, founded in the 18th century.","cn":"震颤派是美国的一个宗教派别，创立于18世纪。"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"派别;宗派;教派;党派","en":"A sect is a group of people that has separated from a larger group and has a particular set of religious or political beliefs."}]},"media":{"uk":"media/uk/sect__gb_1.mp3","us":"media/us/sect__us_1.mp3"}},"semen":{"oxford":{"phon":"ˈsiːmən","pos":"noun","senses":[{"en":"the white liquid containing sperm that is produced by the sex organs of men and male animals","cn":"精液"}]},"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"精液","en":"Semen is the liquid containing sperm that is produced by the sex organs of men and male animals."}]},"media":{"uk":"media/uk/seaman__gb_1.mp3","us":"media/us/semen__us_1.mp3"}},"sewing":{"media":{"img":["media/pic/knitting_comp.jpg","media/thumb/sewing.jpg"],"uk":"media/uk/sewing__gb_1.mp3","us":"media/us/sewing__us_1.mp3"},"oxford":{"phon":"ˈsəʊɪŋ","pos":"noun","senses":[{"en":"the activity of making, repairing or decorating things made of cloth using a needle and thread","cn":"缝纫","ex":{"en":"knitting and sewing","cn":"编织和缝纫"}},{"en":"something that is being sewn","cn":"缝制中的衣物","ex":{"en":"a pile of sewing","cn":"一堆针线活儿"}}]},"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"缝纫;缝补","en":"Sewing is the activity of making or mending clothes or other things using a needle and thread.","ex":{"en":"Her mother had always done all the sewing.","cn":"所有的针线活一直都是她母亲来做。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"缝纫的衣物;针线活","en":"Sewing is clothes or other things that are being sewn.","ex":{"en":"We all got out our own sewing and sat in front of the log fire.","cn":"我们都把自己的针线活拿出来，坐到了火堆前。"}}]},"examples":[{"en":"a pile of sewing","cn":"一堆针线活儿"},{"en":"knitting and sewing","cn":"编织和缝纫"}]},"seventy":{"oxford":{"phon":"ˈsevnti","pos":"","senses":[{"en":"70","cn":"七十"},{"en":"numbers, years or temperatures from 70 to 79","cn":"七十几；七十年代","g":"[plural]"}]},"collins":{"senses":[{"pos":"NUM 数词","cn":"(数字) 70","en":"Seventy is the number 70.","ex":{"en":"Seventy people were killed.","cn":"70 人丧生。"}},{"pos":"N-PLURAL 复数名词","cn":"七十几(指 70 至 79 之间的数字)","en":"When you talk about the seventies, you are referring to numbers between 70 and 79. For example, if you are in your seventies, you are aged between 70 and 79. If the temperature is in the seventies, it is between 70 and 79.","ex":{"en":"It's a long way to go for two people in their seventies.","cn":"对于两个七十几岁的人来说,这段路太远了。"}},{"pos":"N-PLURAL 复数名词","cn":"七十年代(指 1970 年至 1979 年)","en":"The seventies is the decade between 1970 and 1979.","ex":{"en":"In the late Seventies, things had to be new, modern, revolutionary.","cn":"20 世纪 70 年代晚期，一切都要新奇、时髦、标新立异。"}}]},"media":{"uk":"media/uk/seventy__gb_1.mp3","us":"media/us/seventy__us_1.mp3"},"examples":[{"en":"We lost touch during the seventies.","cn":"我们在70年代失去了联系。"},{"en":"In the early seventies, Sag Harbor was still a peaceful village.","cn":"在70年代初﹐萨格港还是一个宁静的村子。"}]},"serving":{"media":{"uk":"media/uk/serving__gb_1.mp3","us":"media/us/serving__us_1.mp3"},"oxford":{"phon":"ˈsɜːvɪŋ","pos":"noun","senses":[{"en":"an amount of food for one person","cn":"（供一个人吃的）一份食物","ex":{"en":"This recipe will be enough for four servings.","cn":"本食谱为四人量。"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"(供一个人吃的)一份食物的量","en":"A serving is an amount of food that is given to one person at a meal.","ex":{"en":"Quantities will vary according to how many servings of soup you want to prepare","cn":"量的多少根据你想准备的汤的份数而定。"}},{"pos":"ADJ 形容词","cn":"(勺子、盘子)分菜用的，上菜用的","en":"A serving spoon or dish is used for giving out food at a meal.","ex":{"en":"Pile the potatoes into a warm serving dish.","cn":"将土豆堆在一个保温菜盘里。"}}]},"examples":[{"en":"This recipe will be enough for four servings.","cn":"本食谱为四人量。"},{"en":"This should make enough for four servings.","cn":"这些应该够四个人吃的。"}]},"securely":{"oxford":{"phon":"sɪˈkjʊəli","pos":"adverb","senses":[{"en":"in a way that is safe or protected against harm, crime, etc.","cn":"安全地","ex":{"en":"She locked the door securely behind her.","cn":"她随手把门锁好。"}},{"en":"in a way that is not likely to move, fall down, etc.","cn":"牢固的；稳固的；坚固的","ex":{"en":"Make sure the ropes are securely fastened.","cn":"确保绳索已系牢。"}},{"en":"in a way that is likely to continue or be successful for a long time","cn":"可靠的；牢靠的；稳固的","ex":{"en":"His power was securely established.","cn":"他的权力已经稳固地确立了。"}}]},"media":{"uk":"media/uk/securely__gb_1.mp3","us":"media/us/securely__us_1.mp3"},"examples":[{"en":"She locked the door securely behind her.","cn":"她随手把门锁好。"},{"en":"Make sure the ropes are securely fastened.","cn":"务必把绳子拴牢。"}]},"semi-detached":{"oxford":{"phon":"ˌsemi dɪˈtætʃt","pos":"adjective","senses":[{"en":"joined to another house by a wall on one side that is shared","cn":"半独立式的"},{"en":"a house that is joined to another house by a wall on one side that is shared","cn":"半独立式的","pos":"noun"}]},"collins":{"senses":[{"pos":"ADJ 形容词","cn":"(房屋)半独立式的，与他屋共用一墙的","en":"A semi-detached house is a house that is joined to another house on one side by a shared wall.","ex":{"en":"...a semi-detached house in Highgate.","cn":"位于海格特的一幢半独立式房子"}}]},"media":{"img":["media/pic/homes_comp.jpg","media/thumb/semidetached.jpg"],"uk":"media/uk/semi_detached_1_gb_1.mp3","us":"media/us/semi_detached_1_us_1.mp3"}},"semi":{"media":{"uk":"media/uk/semi__gb_1.mp3","us":"media/us/semi__us_1.mp3"},"oxford":{"phon":"ˈsemi","pos":"noun","senses":[{"en":"a semi-detached house (= one that is joined to another house by one shared wall)","cn":"半独立式住宅","lab":"British English, informal，，","ex":{"en":"suburban semis","cn":"郊区的半独立式住宅"}},{"en":"a trailer that has wheels at the back and is supported at the front by the vehicle that is pulling it","cn":"半挂车；半拖车","lab":"North American English"},{"en":"one of the two games or parts of a sports competition that are held to decide who will compete in the last part (the final)","cn":"半决赛"},{"en":"half; partly","cn":"半；部分","ex":{"en":"semicircular","cn":"半圆形的"},"pos":"prefix"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"半独立式住宅","en":"A semi is a semi-detached house."},{"pos":"N-COUNT 可数名词","cn":"(体育比赛中的)半决赛","en":"In a sporting competition, the semis are the semi-finals.","ex":{"en":"He reached the semis after beating Lendl in the quarterfinal.","cn":"在 1/4 决赛中他击败了伦德尔，闯入半决赛。"}},{"pos":"N-COUNT 可数名词","cn":"半拖车；半挂车","en":"A semi is a semi-trailer ."}]},"examples":[{"en":"suburban semis","cn":"郊区的半独立式住宅"},{"en":"a three-bedroomed semi","cn":"一栋三个卧室的半独立式住房"}]},"sensitivity":{"oxford":{"phon":"ˌsensəˈtɪvəti","pos":"noun","senses":[{"en":"the ability to understand other people’s feelings","cn":"体贴；体恤；体察","g":"[uncountable]","sc":"to people’s feelings","ex":{"en":"sensitivity to the needs of children","cn":"体察孩子们的需要"}},{"en":"the ability to understand art, music and literature and to express yourself through them","cn":"敏锐的感觉；悟性","g":"[uncountable]","sc":"to art/music/literature","ex":{"en":"She played with great sensitivity.","cn":"她的表演很有悟性。"}},{"en":"the fact of being easily offended or upset by something","cn":"易怒；敏感","g":"[uncountable, countable, usually plural]","sc":"being easily upset","ex":{"en":"He's a mixture of anger and sensitivity.","cn":"他气量小又敏感。"}},{"en":"the fact of needing to be treated very carefully because it may offend or upset people","cn":"敏感性","g":"[uncountable]","sc":"of information/subject","ex":{"en":"Confidentiality is important because of the sensitivity of the information.","cn":"这情报很敏感，务必保密。"}},{"en":"the fact of reacting quickly or more than usual to something","cn":"敏感；过敏","g":"[uncountable, countable, usually plural]","lab":"specialist","sc":"to food/cold/light, etc.","ex":{"en":"food sensitivity","cn":"食物过敏"}},{"en":"the ability to measure very small changes","cn":"灵敏度","g":"[uncountable]","sc":"to small changes","ex":{"en":"the sensitivity of the test","cn":"测试的灵敏度"}}]},"media":{"uk":"media/uk/sensitivity__gb_1.mp3","us":"media/us/sensitivity__us_1.mp3"},"examples":[{"en":"She pointed out with tact and sensitivity exactly where he had gone wrong.","cn":"她明确指出了他的错误所在，既委婉又体贴。"},{"en":"The eyes of some fish have a greater sensitivity to light than ours do.","cn":"有些鱼的眼睛比人类的眼睛对光更敏感。"}]},"separation":{"media":{"uk":"media/uk/separation__gb_1.mp3","us":"media/us/separation__us_1.mp3"},"oxford":{"phon":"ˌsepəˈreɪʃn","pos":"noun","senses":[{"en":"the act of separating people or things; the state of being separate","cn":"分离；分开；分割；隔离","g":"[uncountable, singular]","ex":{"en":"the state’s eventual separation from the federation","cn":"那个州最终与联邦的脱离"}},{"en":"a period of time that people spend apart from each other","cn":"离别","g":"[countable]","ex":{"en":"They were reunited after a separation of more than 20 years.","cn":"他们离别 20 多年后重又聚首。"}},{"en":"a decision that a husband and wife make to live apart while they are still legally married","cn":"分居","g":"[countable]","ex":{"en":"a legal separation","cn":"合法分居"}}]},"collins":{"senses":[{"pos":"N-VAR 可变名词","cn":"分离;分开;分散;隔离","en":"The separation of two or more things or groups is the fact that they are separate or become separate, and are not linked.","ex":{"en":"He believes in the separation of the races.","cn":"他认为应该实施种族隔离。"}},{"pos":"N-VAR 可变名词","cn":"分离期;离别;分开","en":"During a separation, people who usually live together are not together.","ex":{"en":"She wondered if Harry had been unfaithful to her during this long separation","cn":"她不知道和哈里分开这么久,他是否曾对她不忠。"}},{"pos":"N-VAR 可变名词","cn":"分居","en":"If a couple who are married or living together have a separation, they decide to live apart.","ex":{"en":"They agreed to a trial separation.","cn":"他们同意暂时分居。"}}]},"examples":[{"en":"They were reunited after a separation of more than 20 years.","cn":"他们离别 20 多年后重又聚首。"},{"en":"the state's eventual separation from the federation","cn":"那个州最终与联邦的脱离"}]},"session":{"media":{"uk":"media/uk/session__gb_1.mp3","us":"media/us/session__us_1.mp3"},"oxford":{"phon":"ˈseʃn","pos":"noun","senses":[{"en":"a period of time that is spent doing a particular activity","cn":"一场；一节；一段时间","g":"[countable]","ex":{"en":"a training/practice session","cn":"训练／练习时间"}},{"en":"a formal meeting or series of meetings of a court, a parliament, etc.; a period of time when such meetings are held","cn":"（法庭的）开庭，开庭期；（议会等的）会议，会期","g":"[countable, uncountable]","ex":{"en":"a session of the UN General Assembly","cn":"一届联合国大会"}},{"en":"a school or university year","cn":"学年","g":"[countable]"},{"en":"an occasion when people meet to play music, especially Irish music, in a pub","cn":"（酒吧里的）演奏会（尤指演奏爱尔兰音乐）","g":"[countable]"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"(议会等的)会议;(法庭的)开庭","en":"A session is a meeting of a court, parliament, or other official group.","ex":{"en":"...an emergency session of parliament","cn":"议会紧急会议"}},{"pos":"N-COUNT 可数名词","cn":"(议会等的)会期;(法庭的)开庭期","en":"A session is a period during which the meetings of a court, parliament, or other official group are regularly held.","ex":{"en":"The parliamentary session ends on October 4th","cn":"议会会期在10月4日结束。"}},{"pos":"N-COUNT 可数名词","cn":"(某项活动的)一段时间，一场，一节","en":"A session of a particular activity is a period of that activity.","ex":{"en":"The two leaders emerged for a photo session.","cn":"两位领导现身接受记者拍照。"}},{"pos":"ADJ 形容词","cn":"(音乐家)伴奏的","en":"Session musicians are employed to play backing music in recording studios.","ex":{"en":"He established himself as a session musician.","cn":"他成为了一位伴奏音乐家。"}}]},"examples":[{"en":"The course is made up of 12 two-hour sessions.","cn":"这门课总共上 12 次，每次两小时。"},{"en":"The committee met in closed session (= with nobody else present).","cn":"委员会举行了秘密会议。"}]},"seeming":{"media":{"uk":"media/uk/seeming__gb_1.mp3","us":"media/us/seeming__us_1.mp3"},"oxford":{"phon":"ˈsiːmɪŋ","pos":"adjective","senses":[{"en":"appearing to be something that may not be true","cn":"看似…（而实际未必）的；表面上的；貌似…的","ex":{"en":"a seeming impossibility","cn":"表面看来不可能的事"}}]},"collins":{"senses":[{"pos":"ADJ 形容词","cn":"表面上的;貌似的;似是而非的","en":"Seeming means appearing to be the case, but not necessarily the case. For example, if you talk about someone's seeming ability to do something, you mean that they appear to be able to do it, but you are not certain.","ex":{"en":"Wall Street analysts have been highly critical of the company's seeming inability to control costs","cn":"华尔街的分析家们对该公司似乎无力控制成本一事一直都严厉指责。"}}]},"examples":[{"en":"She handled the matter with seeming indifference.","cn":"她看似漫不经心地处理了这件事。"},{"en":"a seeming impossibility","cn":"表面看来不可能的事"}]},"serious":{"media":{"uk":"media/uk/serious__gb_1.mp3","us":"media/us/serious__us_1.mp3"},"oxford":{"phon":"ˈsɪəriəs","pos":"adjective","senses":[{"en":"bad or dangerous","cn":"不好的；严重的；有危险的","sc":"bad","ex":{"en":"a serious illness/offence/crime","cn":"严重的疾病／罪行"}},{"en":"thinking about things in a careful and sensible way; not silly","cn":"严肃的；稳重的","sc":"not silly","ex":{"en":"Be serious for a moment; this is important.","cn":"严肃点儿，这件事很重要。"}},{"en":"sincere about something; not joking or meant as a joke","cn":"当真的；认真的","lab":"informal","sc":"not joking","ex":{"en":"Believe me, I'm deadly (= extremely) serious.","cn":"相信我，我绝对是当真的。"}},{"en":"needing to be thought about carefully; not only for pleasure","cn":"需认真思考的；严肃的","sc":"needing thought","ex":{"en":"a serious article","cn":"一篇严肃的文章"}},{"en":"that must be treated as important","cn":"重要的；须重视的","sc":"important","ex":{"en":"a serious matter","cn":"严重事情"}},{"en":"used to emphasize that there is a large amount of something","cn":"（强调大量）","lab":"informal","sc":"large amount","ex":{"en":"You can earn serious money doing that.","cn":"干那个，你能挣一大笔钱。"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"严重的;危急的;令人担忧的","en":"Serious problems or situations are very bad and cause people to be worried or afraid.","ex":{"en":"Crime is an increasingly serious problem in Russian society","cn":"犯罪猖獗是俄罗斯社会面临的一个日益严重的问题。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"重要的;需要认真考虑的;严肃的","en":"Serious matters are important and deserve careful and thoughtful consideration.","ex":{"en":"I regard this as a serious matter","cn":"我认为这件事很重要。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"认真的;郑重的;严肃的","en":"When important matters are dealt with in a serious way, they are given careful and thoughtful consideration.","ex":{"en":"My parents never really faced up to my drug use in any serious way","cn":"我父母从未认真地正视过我的吸毒问题。"}},{"pos":"ADJ 形容词","cn":"(音乐、文学作品)严肃的，非供消遣(或娱乐)的","en":"Serious music or literature requires concentration to understand or appreciate it.","ex":{"en":"...serious classical music","cn":"严肃的古典音乐"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"认真的;当真的;真心的;郑重其事的","en":"If someone is serious about something, they are sincere about what they are saying, doing, or intending to do.","ex":{"en":"You really are serious about this, aren't you?","cn":"你这话的确是发自内心的，是不是？"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"(人)若有所思的，庄重的，严肃的","en":"Serious people are thoughtful and quiet, and do not laugh very often.","ex":{"en":"He's quite a serious person","cn":"他是一个非常一本正经的人。"}},{"pos":"ADJ 形容词","cn":"(钱等)数目巨大的，大量的","en":"Serious money is a very large amount of money.","ex":{"en":"He started earning serious money only in the sixties.","cn":"他在 60 年代才开始挣大钱。"}}]},"examples":[{"en":"The earnest young doctor answered all our questions.","cn":"这个认真的年轻医生回答了我们所有的问题。"},{"en":"He's really serious about Penny and wants to get engaged.","cn":"他对彭尼的确是认真的，他想跟她订婚。"}]},"seminal":{"media":{"uk":"media/uk/seminal__gb_1.mp3","us":"media/us/seminal__us_1.mp3"},"oxford":{"phon":"ˈsemɪnl","pos":"adjective","senses":[{"en":"very important and having a strong influence on later developments","cn":"（对以后的发展）影响深远的，有重大意义的","lab":"formal","ex":{"en":"a seminal work/article/study","cn":"有巨大影响的著作／文章／研究"}},{"en":"of or containing semen","cn":"精液的；含精液的","g":"[usually before noun]","lab":"specialist","ex":{"en":"seminal fluid","cn":"精液"}}]},"collins":{"senses":[{"pos":"ADJ 形容词","cn":"(书、作品等在某一领域)有重大影响的，影响深远的","en":"Seminal is used to describe things such as books, works, events, and experiences that have a great influence in a particular field.","ex":{"en":"...author of the seminal book 'Animal Liberation'","cn":"有着巨大影响的《动物解放》一书的作者"}}]},"examples":[{"en":"a seminal work/article/study","cn":"有巨大影响的著作/文章/研究"},{"en":"seminal fluid","cn":"精液"}]},"settle":{"media":{"uk":"media/uk/settle__gb_1.mp3","us":"media/us/settle__us_1.mp3"},"oxford":{"phon":"ˈsetl","pos":"verb","senses":[{"en":"to put an end to an argument or a disagreement","cn":"结束（争论、争端等）；解决（分歧、纠纷等）","g":"[transitive, intransitive]","sc":"end argument","ex":{"en":"to settle a dispute/a matter/an issue","cn":"解决争端／事情／问题"}},{"en":"to decide or arrange something finally","cn":"（最终）决定，确定，安排好","g":"[transitive, often passive]","sc":"decide/arrange","ex":{"en":"It's all settled—we're leaving on the nine o'clock plane.","cn":"一切都定下来了，我们乘九点的航班走。"}},{"en":"to make a place your permanent home","cn":"定居","g":"[intransitive]","sc":"choose permanent home","ex":{"en":"She settled in Vienna after her father's death.","cn":"父亲死后，她就在维也纳定居了。"}},{"en":"to make your permanent home in a country or an area as colonists","cn":"殖民；作为移民在殖民地定居","g":"[transitive, usually passive, intransitive]","sc":"choose permanent home","ex":{"en":"This region was settled by the Dutch in the nineteenth century.","cn":"荷兰人于 19 世纪来到这一地区定居。"}},{"en":"to make yourself or somebody else comfortable in a new position","cn":"使处于舒适的位置","g":"[intransitive, transitive]","sc":"into comfortable position/state","ex":{"en":"Ellie settled back in her seat.","cn":"埃利舒适地靠着椅背坐下。"}},{"en":"to put something carefully in a position so that it does not move","cn":"把…放好；安放","g":"[transitive]","sc":"into comfortable position/state","ex":{"en":"She settled the blanket around her knees.","cn":"她用毯子裹住膝盖。"}},{"en":"to become or make somebody/something become calm or relaxed","cn":"（使）平静下来，安静下来，定下心来","g":"[intransitive, transitive]","sc":"into comfortable position/state","ex":{"en":"The baby wouldn't settle.","cn":"婴儿安静不下来。"}},{"en":"to fall from above and come to rest on something; to stay for some time on something","cn":"降落；停留","g":"[intransitive]","sc":"come to rest","ex":{"en":"Dust had settled on everything.","cn":"到处落满灰尘。"}},{"en":"to sink slowly down; to make something do this","cn":"（使）沉降，下陷，变得密实","g":"[intransitive, transitive]","sc":"sink down","ex":{"en":"The contents of the package may have settled in transit.","cn":"包裹里的东西可能在运输途中摇密实了。"}},{"en":"to pay the money that you owe","cn":"付清（欠款）；结算；结账","g":"[transitive, intransitive]","sc":"pay money","ex":{"en":"Please settle your bill before leaving the hotel.","cn":"请您先结账再离开旅馆。"}},{"en":"an old-fashioned piece of furniture with a long wooden seat and a high back and arms, often also with a box for storing things under the seat","cn":"高背长椅（老式木家具，有扶手，座下多带柜）","pos":"noun"}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"解决，结束(争端、纠纷)","en":"If people settle an argument or problem, or if something settles it, they solve it, for example by making a decision about who is right or about what to do.","ex":{"en":"They agreed to try to settle their dispute by negotiation","cn":"他们同意通过谈判来努力解决纠纷。"}},{"pos":"VERB 动词","cn":"庭外和解","en":"If people settle a legal dispute or if they settle, they agree to end the dispute without going to a court of law, for example by paying some money or by apologizing.","ex":{"en":"In an attempt to settle the case, Molken has agreed to pay restitution","cn":"为了争取庭外和解，莫尔肯同意赔款。"}},{"pos":"VERB 动词","cn":"付清(欠款);结算(账单);结(账)","en":"If you settle a bill or debt, you pay the amount that you owe.","ex":{"en":"I settled the bill for my coffee and his two glasses of wine","cn":"我为我的咖啡和他的两杯葡萄酒付了账。"}},{"pos":"VERB 动词","cn":"决定;确定;安排好","en":"If something is settled, it has all been decided and arranged.","ex":{"en":"As far as we're concerned, the matter is settled","cn":"我们这边已经安排妥当了。"}},{"pos":"VERB 动词","cn":"(以遗嘱等正式方式)赠予,授予","en":"To settle money on someone means to formally give it to them, for example in a will.","ex":{"en":"She offered to settle a legacy on Katharine.","cn":"她提出要把一笔遗产留给凯瑟琳。"}},{"pos":"V-ERG 及物/不及物动词","cn":"在…定居;使定居;把…安置在","en":"When people settle a place or in a place, or when a government settles them there, they start living there permanently.","ex":{"en":"Refugees settling in Britain suffer from a number of problems","cn":"在英国定居的难民面临很多问题。"}},{"pos":"VERB 动词","cn":"(使)坐下;(使)处于舒适的位置","en":"If you settle yourself somewhere or settle somewhere, you sit down or make yourself comfortable.","ex":{"en":"Albert settled himself on the sofa","cn":"艾伯特舒舒服服地坐在沙发上。"}},{"pos":"V-ERG 及物/不及物动词","cn":"(使)缓慢沉落;(使)逐渐下陷","en":"If something settles or if you settle it, it sinks slowly down and becomes still.","ex":{"en":"A black dust settled on the walls","cn":"墙上落了一层黑色的粉尘。"}},{"pos":"VERB 动词","cn":"(目光)落在…上，注视着","en":"If your eyes settle on or upon something, you stop looking around and look at that thing for some time.","ex":{"en":"The man let his eyes settle upon Cross's face.","cn":"那名男子的目光落在了克罗斯的脸上。"}},{"pos":"VERB 动词","cn":"(鸟、昆虫)降落，栖息","en":"When birds or insects settle on something, they land on it from above.","ex":{"en":"Moths flew in front of it, eventually settling on the rough painted metal.","cn":"几只蛾子在它前面飞，最终落在了那块粗糙的喷漆金属上。"}},{"pos":"","cn":"","en":"when the dust settles→see: ; to settle a score→see: ;"},{"pos":"","cn":"","en":"相关词组：settle down settle for settle in settle on settle up"}]},"examples":[{"en":"‘Who would do such a thing?’ ‘Maybe someone with an old score to settle.’ “","cn":"谁做得出这样的事呢？” “也许是结有宿怨的人吧。”"},{"en":"I couldn't afford the house I really wanted, so I had to settle for second best.","cn":"我真心想要的房子我买不起，所以只得退而求其次了。"}]},"sexy":{"media":{"uk":"media/uk/sexy__gb_1.mp3","us":"media/us/sexy__us_1.mp3"},"oxford":{"phon":"ˈseksi","pos":"adjective","senses":[{"en":"sexually attractive","cn":"性感的","ex":{"en":"the sexy lead singer","cn":"性感的主唱"}},{"en":"sexually exciting","cn":"引起性欲的；性感的","ex":{"en":"sexy underwear","cn":"性感的内衣"}},{"en":"sexually excited","cn":"性欲发作的；性兴奋的","ex":{"en":"The music was making him feel sexy.","cn":"音乐让他感觉性感。"}},{"en":"exciting and interesting","cn":"刺激有趣的；令人兴奋的","lab":"informal","ex":{"en":"a sexy new range of software","cn":"一系列很棒的新软件"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"性感的;引起性欲的","en":"You can describe people and things as sexy if you think they are sexually exciting or sexually attractive.","ex":{"en":"She was one of the sexiest women I had seen","cn":"她是我见过的最性感的女人之一。"}}]},"examples":[{"en":"She looked incredibly sexy in a black evening gown.","cn":"她穿着黑色的晚礼服，显得性感极了。"},{"en":"The music and wine began to make him feel sexy.","cn":"那音乐和酒逐渐使他性欲萌动。"}]},"second":{"media":{"uk":"media/uk/second__gb_1.mp3","us":"media/us/second__us_1.mp3"},"oxford":{"phon":"ˈsekənd","pos":"determiner, ordinal number","senses":[{"en":"happening or coming next after the first in a series of similar things or people; 2nd","cn":"第二（的）","ex":{"en":"This is the second time it's happened.","cn":"这已是第二次了。"}},{"en":"next in order of importance, size, quality, etc. to one other person or thing","cn":"（重要性、规模、质量等）居第二位的","ex":{"en":"Osaka is Japan's second-largest city.","cn":"大阪是日本的第二大城市。"}},{"en":"another; in addition to one that you already own or use","cn":"另外的；外加的","g":"[only before noun]","ex":{"en":"They have a second home in Tuscany.","cn":"他们在托斯卡纳还有一个家。"}},{"en":"after one other person or thing in order or importance","cn":"以第二名；以第二位","ex":{"en":"She came second in the marathon.","cn":"她在马拉松比赛中获得第二名。"},"pos":"adverb"},{"en":"used to introduce the second of a list of points you want to make in a speech or piece of writing","cn":"（用于列举）第二，其次","ex":{"en":"She did it first because she wanted to, and second because I asked her to.","cn":"她做那件事，首先是因为她自己想做，其次是因为我要她做。"},"pos":"adverb"},{"en":"a unit for measuring time. There are 60 seconds in one minute.","cn":"秒（时间单位）","g":"[countable]","ex":{"en":"She can run 100 metres in just over 11 seconds.","cn":"她跑 100 米只需 11 秒多一点。"},"pos":"noun"},{"en":"a very short time","cn":"片刻；瞬间","g":"[countable]","lab":"informal","ex":{"en":"I'll be with you in a second.","cn":"我马上就去你那儿。"},"pos":"noun"},{"en":"a unit for measuring angles. There are 60 seconds in one minute.","cn":"秒（角度单位）","g":"[countable]","ex":{"en":"1° 6′ 10″ (= one degree, six minutes and ten seconds)","cn":"1 度 6 分 10 秒"},"pos":"noun"},{"en":"a second amount of the same food that you have just eaten","cn":"再来的一份食物","g":"[plural]","lab":"informal","ex":{"en":"Seconds, anybody?","cn":"有谁需要再来一份吗？"},"pos":"noun"},{"en":"an item that is sold at a lower price than usual because it is not perfect","cn":"次货；二等货；等外品","g":"[countable, usually plural]","pos":"noun"},{"en":"one of six or seven positions of the gears in a vehicle","cn":"（车辆的）二挡","g":"[uncountable]","ex":{"en":"to change down from third to second","cn":"从第三降到第二"},"pos":"noun"},{"en":"a level of university degree at British universities. An upper second is a good degree and a lower second is average.","cn":"二等学位（英国大学学位等级，upper second 为二等上，较好；lower second 为二等下，一般）","g":"[countable]","ex":{"en":"He got a good second in history.","cn":"他获得历史专业的二级优等学位。"},"pos":"noun"},{"en":"a person whose role is to help and support somebody else, for example in a boxing match or in a formal duel in the past","cn":"（拳击比赛或旧时正式决斗的）助手","g":"[countable]","pos":"noun"},{"en":"to state officially at a meeting that you support another person’s idea, suggestion, etc. so that it can be discussed and/or voted on","cn":"支持，赞成（主意、建议等）；附议","lab":"informal","ex":{"en":"Any proposal must be seconded by two other members of the committee.","cn":"任何提案须有委员会其他两名委员附议。"},"pos":"verb"},{"en":"to send an employee to another department, office, etc. in order to do a different job for a short period of time","cn":"临时调派；短期调任","ex":{"en":"Each year two teachers are seconded to industry for six months.","cn":"每年有两名教师派到产业部门工作六个月。"},"pos":"verb"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"秒(a second 或 seconds 往往用以表示很短的时间)","en":"A second is one of the sixty parts that a minute is divided into. People often say 'a second' or 'seconds' when they simply mean a very short time.","ex":{"en":"For a few seconds nobody said anything","cn":"有几秒钟大家都沉默无语。"}},{"pos":"ORD 序数词","cn":"第二的;第二个的","en":"The second item in a series is the one that you count as number two.","ex":{"en":"...the second day of his visit to Delhi.","cn":"他到访德里的第二天"}},{"pos":"ORD 序数词","cn":"(用于形容词最高级前)第二…的","en":"Second is used before superlative adjectives to indicate that there is only one thing better or larger than the thing you are referring to.","ex":{"en":"The party is still the second strongest in Italy.","cn":"该党仍是意大利的第二大党。"}},{"pos":"ADV 副词","cn":"第二;其次","en":"You say second when you want to make a second point or give a second reason for something.","ex":{"en":"The soil is depleted first by having crops grown in it and second by natural weathering and bacterial action.","cn":"土壤首先是被种植其中的作物消耗掉，其次受自然风化和细菌活动的侵蚀。"}},{"pos":"N-COUNT 可数名词","cn":"二级甲等/乙等优秀学位","en":"In Britain, an upper second is a good honours degree and a lower second is an average honours degree.","ex":{"en":"I then went up to Lancaster University and got an upper second.","cn":"后来，我考上了兰开斯特大学，获得了二级甲等学位。"}},{"pos":"N-PLURAL 复数名词","cn":"添菜","en":"If you have seconds, you have a second helping of food.","ex":{"en":"There's seconds if you want them.","cn":"如果需要的话可以添菜。"}},{"pos":"N-COUNT 可数名词","cn":"二级品;二等货;次货;等外品","en":"Seconds are goods that are sold cheaply in shops because they have slight faults.","ex":{"en":"It's a new shop selling discounted lines and seconds.","cn":"这是家新开的商店，出售打折商品和等外品。"}},{"pos":"N-COUNT 可数名词","cn":"(拳击或国际象棋锦标赛的)副手，助手","en":"The seconds of someone who is taking part in a boxing match or chess tournament are the people who assist and encourage them.","ex":{"en":"He shouted to his seconds, 'I did it! I did it!'","cn":"他对助手们喊道：“我赢了！我赢了!”"}},{"pos":"VERB 动词","cn":"附议，赞同(提案)","en":"If you second a proposal in a meeting or debate, you formally express your agreement with it so that it can then be discussed or voted on.","ex":{"en":"...Bryan Sutton, who seconded the motion against fox hunting","cn":"赞同反对猎狐动议的布赖恩·萨顿"}},{"pos":"VERB 动词","cn":"赞成;持相同观点","en":"If you second what someone has said, you say that you agree with them or say the same thing yourself.","ex":{"en":"The Prime Minister seconded the call for discipline in a speech last week.","cn":"上周首相在一次演讲中对严肃纪律的号召表示支持。"}},{"pos":"PHRASE 短语","cn":"听说地;非亲身经历地","en":"If you experience something at second hand, you are told about it by other people rather than experiencing it yourself.","ex":{"en":"Most of them had only heard of the massacre at second hand.","cn":"他们中的大多数人只是听说了那次大屠杀。"}},{"pos":"PHRASE 短语","cn":"不比任何事物差;首屈一指","en":"If you say that something is second to none, you are emphasizing that it is very good indeed or the best that there is.","ex":{"en":"Our scientific research is second to none.","cn":"我们的科学研究是顶尖的。"}},{"pos":"PHRASE 短语","cn":"只比…差;仅次于","en":"If you say that something is second only to something else, you mean that only that thing is better or greater than it.","ex":{"en":"As a major health risk hepatitis is second only to tobacco.","cn":"肝炎是仅次于吸烟的主要健康隐患。"}},{"pos":"","cn":"","en":"second nature→see: ; in the second place→see: ;"},{"pos":"VERB 动词","cn":"临时调任;临时调派","en":"If you are seconded somewhere, you are sent there temporarily by your employer in order to do special duties.","ex":{"en":"In 1937 he was seconded to the Royal Canadian Air Force in Ottawa as air armament adviser","cn":"1937 年他被临时调往渥太华的加拿大皇家空军担任军备顾问。"}}]},"examples":[{"en":"She did it first because she wanted to, and second because I asked her to.","cn":"她做那件事，首先是因为她自己想做，其次是因为我要她做。"},{"en":"The spreadsheet application is second only to word processing in terms of popularity.","cn":"就受欢迎程度而言，电子制表软件仅次于文字处理软件。"}]},"series":{"media":{"uk":"media/uk/series__gb_1.mp3","us":"media/us/series__us_1.mp3"},"oxford":{"phon":"ˈsɪəriːz","pos":"noun","senses":[{"en":"a set of television or radio programmes or podcasts that deal with the same subject or that have the same characters","cn":"（电视、广播或播客的）系列节目，连续剧","g":"[countable]","lab":"British English","ex":{"en":"The first episode of the new series is on Saturday.","cn":"新系列的第一集周六播出。"}},{"en":"several events or things of a similar kind that happen one after the other","cn":"一系列；连续；接连","g":"[countable, usually singular]","ex":{"en":"The incident sparked off a series of events that nobody had foreseen.","cn":"该事件引发了一系列无人预见的事件。"}},{"en":"a set of sports games played between the same two teams","cn":"（两队之间的）系列比赛","g":"[countable]","lab":"sport","ex":{"en":"the World Series (= in baseball)","cn":"世界系列美国职业棒球锦标赛"}},{"en":"an electrical circuit in which the current passes through all the parts in the correct order","cn":"串联","g":"[uncountable, countable]","lab":"specialist","ex":{"en":"batteries connected in series","cn":"串联电池"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"一连串;一系列;连续;接连","en":"A series of things or events is a number of them that come one after the other.","ex":{"en":"...a series of meetings with students and political leaders.","cn":"与学生和政治领袖的一系列会面"}},{"pos":"N-COUNT 可数名词","cn":"(广播或电视的)系列节目,系列片","en":"A radio or television series is a set of programmes of a particular kind which have the same title.","ex":{"en":"...the TV series 'The Trials of Life' presented by David Attenborough.","cn":"由戴维·阿滕伯勒主持的电视系列片《生命之源》"}}]},"examples":[{"en":"England have lost the Test series (= of cricket matches) against India.","cn":"英格兰板球队在同印度队的系列比赛中落败。"},{"en":"The incident sparked off a whole series of events that nobody had foreseen.","cn":"那一事件引发出一连串谁都没有料到的事。"}]},"self-image":{"oxford":{"phon":"ˌself ˈɪmɪdʒ","pos":"noun","senses":[{"en":"the opinion or idea you have of yourself, especially of your appearance or abilities","cn":"自我形象；自我印象","ex":{"en":"to have a positive/negative self-image","cn":"有着正面的／负面的自我形象"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"自我形象;自我印象","en":"Your self-image is the set of ideas you have about your own qualities and abilities.","ex":{"en":"Children who have a positive self-image are less likely to present behaviour and discipline problems.","cn":"自我感觉良好的孩子较少出现行为和纪律上的问题。"}}]},"media":{"uk":"media/uk/self_image_1_gb_1.mp3","us":"media/us/self_image_1_us_1.mp3"},"examples":[{"en":"to have a positive/negative self-image","cn":"有着正面的/负面的自我形象"}]},"self-discipline":{"oxford":{"phon":"ˌself ˈdɪsəplɪn","pos":"noun","senses":[{"en":"the ability to make yourself do something, especially something difficult or unpleasant","cn":"自律能力；自我约束能力","ex":{"en":"It takes a lot of self-discipline to go jogging in winter.","cn":"在冬天跑步是需要很大的自律力的。"}}]},"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"自我约束;律己","en":"Self-discipline is the ability to control yourself and to make yourself work hard or behave in a particular way without needing anyone else to tell you what to do.","ex":{"en":"Exercising at home alone requires a tremendous amount of self-discipline.","cn":"自己在家锻炼需要很强的自我约束能力。"}}]},"media":{"uk":"media/uk/self_discipline_1_gb_1.mp3","us":"media/us/self_discipline_1_us_1.mp3"},"examples":[{"en":"It takes a lot of self-discipline to go jogging in winter.","cn":"在冬天跑步是需要很大的自律力的。"},{"en":"A lot of the kids seemed to lack self-discipline.","cn":"这些小孩中有许多好像都缺乏自我约束力。"}]},"sense":{"media":{"uk":"media/uk/sense__gb_1.mp3","us":"media/us/sense__us_1.mp3"},"oxford":{"phon":"sens","pos":"noun","senses":[{"en":"an understanding about something; an ability to judge something","cn":"理解力；判断力","g":"[singular]","lab":"figurative","sc":"understanding/judgement","ex":{"en":"One of the most important things in a partner is a sense of humour (= the ability to find things funny or make people laugh).","cn":"作为一个生活伴侣，最重要的素质之一是幽默感。"}},{"en":"good understanding and judgement; knowledge of what is sensible or practical behaviour","cn":"见识；良好的判断；清醒的认识","g":"[uncountable]","sc":"understanding/judgement","ex":{"en":"You should have the sense to take advice when it is offered.","cn":"你要知道好歹，别人给你忠告，就该接受。"}},{"en":"the meaning that a word or phrase has; a way of understanding something","cn":"意义；含义；理解…的方式；看待…的角度","g":"[countable]","lab":"formal","sc":"meaning","ex":{"en":"That word has three senses.","cn":"那个词有三个意思。"}},{"en":"one of the five powers (sight, hearing, smell, taste and touch) that your body uses to get information about the world around you","cn":"感觉官能（即视、听、嗅、味、触五觉）","g":"[countable]","sc":"sight/hearing, etc.","ex":{"en":"the five senses","cn":"五种感觉官能"}},{"en":"a feeling about something important","cn":"（对重大事情的）感觉，意识","g":"[countable]","sc":"feeling","ex":{"en":"His career was guided by a strong sense of duty.","cn":"强烈的责任感引领着他的事业。"}},{"en":"a normal state of mind; the ability to think clearly","cn":"健全的心智；清醒的思维能力；理智","g":"[plural]","lab":"old-fashioned","sc":"normal state of mind","ex":{"en":"If she threatens to leave, it should bring him to his senses.","cn":"假如她威胁着要走，说不定他会清醒过来。"}},{"en":"to become aware of something even though you cannot see it, hear it, etc.","cn":"感觉到；意识到；觉察出","sc":"become aware","ex":{"en":"Sensing danger, they started to run.","cn":"他们感到有危险，撒腿就跑。"},"pos":"verb"},{"en":"to discover and record something","cn":"检测出","sc":"of machine","ex":{"en":"equipment that senses the presence of toxic gases","cn":"检测有毒气体的设备"},"pos":"verb"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"感觉官能(即视觉、嗅觉、听觉、触觉、味觉)","en":"Your senses are the physical abilities of sight, smell, hearing, touch, and taste.","ex":{"en":"She stared at him again, unable to believe the evidence of her senses.","cn":"她再度盯着他看，无法相信自己的眼睛和耳朵。"}},{"pos":"VERB 动词","cn":"感觉到;觉察到;意识到","en":"If you sense something, you become aware of it or you realize it, although it is not very obvious.","ex":{"en":"She probably sensed that I wasn't telling her the whole story","cn":"她可能意识到了我并没有对她全盘托出。"}},{"pos":"N-SING 单数名词","cn":"感觉;意识","en":"If you have a sense that something is the case, you think that it is the case, although you may not have firm, clear evidence for this belief.","ex":{"en":"Suddenly you got this sense that people were drawing themselves away from each other","cn":"突然间你就有这样一种感觉：人们正在彼此疏远。"}},{"pos":"N-SING 单数名词","cn":"(负罪或释然的)感觉","en":"If you have a sense of guilt or relief, for example, you feel guilty or relieved.","ex":{"en":"When your child is struggling for life, you feel this overwhelming sense of guilt","cn":"当你的孩子在挣扎求生时，你会感到非常内疚。"}},{"pos":"N-SING 单数名词","cn":"意识;观念","en":"If you have a sense of something such as duty or justice, you are aware of it and believe it is important.","ex":{"en":"My sense of justice was offended","cn":"我的正义感被激了起来。"}},{"pos":"N-SING 单数名词","cn":"天赋;悟性;资质","en":"Someone who has a sense of timing or style has a natural ability with regard to timing or style. You can also say that someone has a bad sense of timing or style.","ex":{"en":"He has an impeccable sense of timing","cn":"他有着无可挑剔的节奏感。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"理智;头脑;良好的判断力","en":"Sense is the ability to make good judgments and to behave sensibly.","ex":{"en":"...when he was younger and had a bit more sense","cn":"在他年纪更轻一些而且还有点头脑的时候"}},{"pos":"N-SING 单数名词","cn":"好处;意义","en":"If you say that there is no sense or little sense in doing something, you mean that it is not a sensible thing to do because nothing useful would be gained by doing it.","ex":{"en":"There's no sense in pretending this doesn't happen","cn":"假装这件事没有发生毫无意义。"}},{"pos":"N-COUNT 可数名词","cn":"(词语、表达的)意思，含义，意义","en":"A sense of a word or expression is one of its possible meanings.","ex":{"en":"...a noun which has two senses","cn":"有两个意思的名词"}},{"pos":"PHRASE 短语","cn":"从某种意义上说/总的来说。","en":"Sense is used in several expressions to indicate how true your statement is. For example, if you say that something is true in a sense, you mean that it is partly true, or true in one way. If you say that something is true in a general sense, you mean that it is true in a general way.","ex":{"en":"In a sense, both were right","cn":"从某种意义上来说，两者都对。"}},{"pos":"PHRASE 短语","cn":"可以理解;讲得通","en":"If something makes sense, you can understand it.","ex":{"en":"He was sitting there saying, 'Yes, the figures make sense.'","cn":"他坐在那儿说：“是的，这些数字可以理解。”"}},{"pos":"PHRASE 短语","cn":"理解;弄懂","en":"When you make sense of something, you succeed in understanding it.","ex":{"en":"Provided you didn't try to make sense of it, it sounded beautiful","cn":"只要不非得弄懂它的意思，它听上去还是很美的。"}},{"pos":"PHRASE 短语","cn":"(行为方式)有道理，合乎情理","en":"If a course of action makes sense, it seems sensible.","ex":{"en":"It makes sense to look after yourself","cn":"自己应该照顾自己。"}},{"pos":"PHRASE 短语","cn":"恢复理性;清醒过来;醒悟过来","en":"If you say that someone has come to their senses or has been brought to their senses, you mean that they have stopped being foolish and are being sensible again.","ex":{"en":"Eventually the world will come to its senses and get rid of them","cn":"最终这世界会清醒过来，将它们全部丢弃。"}},{"pos":"PHRASE 短语","cn":"发疯;失去理智;精神失常","en":"If you say that someone seems to have taken leave of their senses, you mean that they have done or said something very foolish.","ex":{"en":"They looked at me as if I had taken leave of my senses.","cn":"他们看着我，就像我已经疯了一样。"}},{"pos":"PHRASE 短语","cn":"说得有理","en":"If you say that someone talks sense, you mean that what they say is sensible."},{"pos":"PHRASE 短语","cn":"认为;觉得","en":"If you have a sense that something is true or get a sense that something is true, you think that it is true.","ex":{"en":"Do you have the sense that you are loved by the public?","cn":"你认为自己深受民众喜爱吗？"}},{"pos":"","cn":"","en":"to see sense"}]},"examples":[{"en":"Candles on the table gave the evening a sense of occasion.","cn":"桌上点了一些蜡烛，使得那个晚上有一种特别的气氛。"},{"en":"The mixture of sights, smells and sounds around her made her senses reel.","cn":"四周的物象、气味和声音纷至沓来，使她晕头转向。"}]},"secede":{"media":{"uk":"media/uk/secede__gb_1.mp3","us":"media/us/secede__us_1.mp3"},"oxford":{"phon":"sɪˈsiːd","pos":"verb","senses":[{"en":"to officially leave a larger state or organization of states and become independent","cn":"退出，脱离（国家、组织等）","ex":{"en":"The Republic of Panama seceded from Colombia in 1903.","cn":"巴拿马共和国于 1903 年脱离哥伦比亚。"}}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"(从国家、大集团中正式)退出，脱离，分离","en":"If a region or group secedes from the country or larger group to which it belongs, it formally becomes a separate country or stops being a member of the larger group.","ex":{"en":"Singapore seceded from the Federation of Malaysia and became an independent sovereign state","cn":"新加坡脱离马来西亚联邦成为一个独立的主权国家。"}}]},"examples":[{"en":"The Republic of Panama seceded from Colombia in 1903.","cn":"巴拿马共和国于 1903 年脱离哥伦比亚。"},{"en":"By 1861, 11 states had seceded from the Union.","cn":"到1861年﹐已有11个州退出联邦。"}]},"semester":{"oxford":{"phon":"sɪˈmestə(r)","pos":"noun","senses":[{"en":"one of the two periods that the school or college year is divided into","cn":"学期（一学年分两个学期）","ex":{"en":"the spring/fall semester","cn":"春季／秋季学期"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"(某些国家中学院及大学的)学期,半学年","en":"In colleges and universities in some countries, a semester is one of the two main periods into which the year is divided."}]},"media":{"uk":"media/uk/semester__gb_1.mp3","us":"media/us/semester__us_1.mp3"},"examples":[{"en":"the spring/fall semester","cn":"春季/秋季学期"},{"en":"the fall semester","cn":"秋季学期"}]},"serene":{"media":{"uk":"media/uk/serene__gb_1.mp3","us":"media/us/serene__us_1.mp3"},"oxford":{"phon":"səˈriːn","pos":"adjective","senses":[{"en":"calm and peaceful","cn":"平静的；宁静的；安详的","ex":{"en":"a lake, still and serene in the sunlight","cn":"阳光下宁静安谧的湖水"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"平静的;宁静的;安详的","en":"Someone or something that is serene is calm and quiet.","ex":{"en":"She looked as calm and serene as she always did","cn":"她看上去和以往一样平静安详。"}}]},"examples":[{"en":"The hotel offers a haven of peace and serenity away from the bustle of the city.","cn":"那家旅馆远离闹市，是一个幽静安谧的好去处。"},{"en":"a lake, still and serene in the sunlight","cn":"阳光下宁静安谧的湖水"}]},"secret":{"media":{"uk":"media/uk/secret__gb_1.mp3","us":"media/us/secret__us_1.mp3"},"oxford":{"phon":"ˈsiːkrət","pos":"adjective","senses":[{"en":"known about by only a few people; kept hidden from others","cn":"秘密的；保密的；外人不得而知的","ex":{"en":"secret information/meetings/talks","cn":"秘密信息／会议／会谈"}},{"en":"used to describe actions and behaviour that you do not tell other people about","cn":"（指行为与习惯）暗中进行的，未公开的，隐秘的","g":"[only before noun]","ex":{"en":"He's a secret drinker.","cn":"他偷偷地喝酒。"}},{"en":"liking to have secrets that other people do not know about; showing this","cn":"诡秘；神秘","ex":{"en":"They were so secret about everything.","cn":"他们无论对什么都那样神秘兮兮的。"}},{"en":"something that is known about by only a few people and not told to others","cn":"秘密；机密","g":"[countable]","ex":{"en":"Can you keep a secret?","cn":"你能保守秘密吗？"},"pos":"noun"},{"en":"the best or only way to achieve something; the way a particular person achieves something","cn":"诀窍；秘诀","g":"[singular]","ex":{"en":"She still looks so young. What's her secret?","cn":"她看上去依旧那么年轻，她的保养秘诀是什么呢？"},"pos":"noun"},{"en":"a thing that is not yet fully understood or that is difficult to understand","cn":"奥秘；奥妙","g":"[countable, usually plural]","ex":{"en":"the secrets of the universe","cn":"宇宙的奥秘"},"pos":"noun"}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"秘密的;机密的;保密的","en":"If something is secret, it is known about by only a small number of people, and is not told or shown to anyone else.","ex":{"en":"Soldiers have been training at a secret location","cn":"士兵们一直在一个秘密场所训练。"}},{"pos":"N-COUNT 可数名词","cn":"秘密;机密;内情","en":"A secret is a fact that is known by only a small number of people, and is not told to anyone else.","ex":{"en":"I think he enjoyed keeping our love a secret","cn":"我觉得他喜欢和我偷偷摸摸地谈恋爱。"}},{"pos":"N-SING 单数名词","cn":"秘诀;诀窍","en":"If you say that a particular way of doing things is the secret of achieving something, you mean that it is the best or only way to achieve it.","ex":{"en":"The secret of success is honesty and fair dealing","cn":"成功的秘诀在于诚实和公平交易。"}},{"pos":"N-COUNT 可数名词","cn":"奥秘;奥妙","en":"Something's secrets are the things about it which have never been fully explained.","ex":{"en":"We have an opportunity now to really unlock the secrets of the universe","cn":"我们现在有机会去真正解开宇宙的奥秘。"}},{"pos":"PHRASE 短语","cn":"秘密地;暗地里","en":"If you do something in secret, you do it without anyone else knowing.","ex":{"en":"Dan found out that I had been meeting my ex-boyfriend in secret.","cn":"丹发现我一直在跟前男友偷偷见面。"}},{"pos":"PHRASE 短语","cn":"保守秘密","en":"If you say that someone can keep a secret, you mean that they can be trusted not to tell other people a secret that you have told them.","ex":{"en":"Tom was utterly indiscreet, and could never keep a secret.","cn":"汤姆言语很不谨慎，什么时候也别想他守住秘密。"}},{"pos":"PHRASE 短语","cn":"不隐瞒;开诚布公","en":"If you make no secret of something, you tell others about it openly and clearly.","ex":{"en":"His wife made no secret of her hatred for the formal occasions","cn":"他的妻子公开表示厌恶那些礼节性的场合。"}}]},"examples":[{"en":"She still looks so young. What's her secret?","cn":"她看上去依旧那么年轻，她的保养秘诀是什么呢？"},{"en":"They were so secret about everything.","cn":"他们无论对什么都那样神秘兮兮的。"}]},"sexual":{"oxford":{"phon":"ˈsekʃuəl","pos":"adjective","senses":[{"en":"connected with the physical activity of sex","cn":"性行为的；性的","g":"[usually before noun]","ex":{"en":"sexual behaviour/activity/desire","cn":"性行为；性活动；性欲"}},{"en":"connected with the process of producing young","cn":"生殖的；有性繁殖的","g":"[only before noun]","ex":{"en":"the sexual organs (= the penis, vagina, etc.)","cn":"生殖器官"}},{"en":"connected with the state of being male or female","cn":"性别的；性的","g":"[usually before noun]","ex":{"en":"sexual characteristics","cn":"性别特征"}}]},"collins":{"senses":[{"pos":"ADJ 形容词","cn":"性爱的;性欲的;性行为的","en":"Sexual feelings or activities are connected with the act of sex or with people's desire for sex.","ex":{"en":"This was the first sexual relationship I had had","cn":"这是我第一次与人发生性关系。"}},{"pos":"ADJ 形容词","cn":"性别的;性别差异的;两性间的","en":"Sexual means relating to the differences between male and female people.","ex":{"en":"Women's groups denounced sexual discrimination.","cn":"一些女性团体谴责性别歧视。"}},{"pos":"ADJ 形容词","cn":"性取向的;不同性观念的","en":"Sexual means relating to the differences between heterosexuals and homosexuals.","ex":{"en":"...couples of all sexual persuasions.","cn":"有各种不同性观念的夫妇们"}},{"pos":"ADJ 形容词","cn":"生殖的;有性繁殖的","en":"Sexual means relating to the biological process by which people and animals produce young.","ex":{"en":"Girls generally reach sexual maturity two years earlier than boys.","cn":"通常女孩性发育成熟要比男孩早两年。"}}]},"media":{"uk":"media/uk/sexual__gb_1.mp3","us":"media/us/sexual__us_1.mp3"},"examples":[{"en":"Her interest in him is purely sexual.","cn":"她对他感兴趣纯粹是因为性的原因。"},{"en":"sexual orientation (= whether you are heterosexual or homosexual )","cn":"性爱倾向（指异性恋或同性恋）"}]},"self-improvement":{"oxford":{"phon":"ˌself ɪmˈpruːvmənt","pos":"noun","senses":[{"en":"the process by which a person improves their knowledge, status, character, etc. by their own efforts","cn":"（在知识、地位、性格等方面的）自我改进，自我提高"}]},"media":{"uk":"media/uk/self_improvement_1_gb_1.mp3","us":"media/us/self_improvement_1_us_1.mp3"}},"secretly":{"oxford":{"phon":"ˈsiːkrətli","pos":"adverb","senses":[{"en":"in a way that is kept hidden from people","cn":"秘密地","ex":{"en":"The police had secretly filmed the conversations.","cn":"警方秘密拍摄了对话过程。"}}]},"media":{"uk":"media/uk/secretly__gb_1.mp3","us":"media/us/secretly__us_1.mp3"},"examples":[{"en":"The police had secretly filmed the conversations.","cn":"警察已秘密地把几次谈话拍摄下来。"},{"en":"She was secretly pleased to see him.","cn":"见到他，她心中窃喜。"}]},"sea-green":{"oxford":{"phon":"ˌsiː ˈɡriːn","pos":"noun","senses":[{"en":"a blue-green colour, like the colour of the sea","cn":"（像海水似的）淡蓝绿色的；海绿色的"},{"en":"blue-green in colour, like the sea","cn":"（像海水似的）淡蓝绿色的；海绿色的","pos":"adjective"}]},"collins":{"senses":[{"pos":"COLOUR 颜色词","cn":"海绿色;淡蓝绿色","en":"Something that is sea-green is a bluish-green colour like the colour of the sea.","ex":{"en":"...her sea-green eyes.","cn":"她那海绿色的眼睛"}}]},"media":{"uk":"media/uk/sea_green_1_gb_1.mp3","us":"media/us/sea_green_1_us_1.mp3"},"examples":[{"en":"Jo’s large sea-green eyes","cn":"乔蓝绿色的大眼睛"}]},"senator":{"media":{"uk":"media/uk/senator__gb_1.mp3","us":"media/us/senator__us_1.mp3"},"oxford":{"phon":"ˈsenətə(r)","pos":"noun","senses":[{"en":"a member of a senate","cn":"参议员","ex":{"en":"Senator McCarthy","cn":"参议员麦卡锡"}}]},"collins":{"senses":[{"pos":"N-COUNT; N-TITLE 可数名词；头衔名词","cn":"(美国、澳大利亚等国的)参议员","en":"A senator is a member of a political Senate, for example in the United States or Australia. →see usage note at:"}]},"examples":[{"en":"She has served as a Democratic senator for North Carolina since 2009.","cn":"自 2009 年以来，她一直是北卡罗来纳州的民主党参议员。"},{"en":"Senator McCarthy","cn":"麦卡锡参议员"}]},"seed":{"oxford":{"phon":"siːd","pos":"noun","senses":[{"en":"the small hard part produced by a plant, from which a new plant can grow","cn":"种子；籽","g":"[countable, uncountable]","sc":"of plants/fruit","ex":{"en":"a packet of wild flower seeds","cn":"一包野花籽"}},{"en":"the small hard seed that is found in some types of fruit","cn":"（某些水果的）种子，籽","g":"[countable]","lab":"North American English","sc":"of plants/fruit"},{"en":"the beginning of a feeling or development that continues to grow","cn":"起源；起因；萌芽；开端","g":"[countable, usually plural]","sc":"beginning","ex":{"en":"the seeds of rebellion","cn":"反叛的起因"}},{"en":"one of the best players in a competition. The seeds are given a position in a list to try and make sure that they do not play each other in the early parts of the competition.","cn":"种子选手","g":"[countable]","sc":"in tennis","ex":{"en":"The top seed won comfortably.","cn":"头号种子选手轻松获胜。"}},{"en":"semen","cn":"精液","g":"[uncountable]","lab":"old-fashioned or humorous","sc":"of a man"},{"en":"all the people who are the children, grandchildren, etc. of one man","cn":"（统称某人的）子孙，后裔，后代","g":"[uncountable]","lab":"literary","sc":"of a man"},{"en":"to produce seeds","cn":"结籽","g":"[intransitive]","sc":"of a plant","pos":"verb"},{"en":"to produce other plants using its own seeds","cn":"（种子）繁殖","g":"[transitive]","sc":"of a plant","pos":"verb"},{"en":"to plant seeds in an area of ground","cn":"在…播种","g":"[transitive, usually passive]","sc":"area of ground","ex":{"en":"The site has been seeded with prairie grasses and wildflowers.","cn":"这处场地撒上了牧草和野花种子。"},"pos":"verb"},{"en":"to make somebody a seed in a competition","cn":"确定（某人）为种子选手","g":"[transitive, usually passive]","sc":"in tennis","ex":{"en":"He has been seeded 14th at Wimbledon next week.","cn":"他被确定为下周温布尔登网球赛的第 14 号种子选手。"},"pos":"verb"}]},"collins":{"senses":[{"pos":"N-VAR 可变名词","cn":"籽;种子","en":"A seed is the small, hard part of a plant from which a new plant grows.","ex":{"en":"...a packet of cabbage seed","cn":"一包卷心菜籽"}},{"pos":"VERB 动词","cn":"在(地里)播种","en":"If you seed a piece of land, you plant seeds in it.","ex":{"en":"Men mowed the wide lawns and seeded them","cn":"人们割了大片草地的草，然后在上面播种。"}},{"pos":"N-PLURAL 复数名词","cn":"(感情、过程的)起源，开端，萌芽","en":"You can refer to the seeds of something when you want to talk about the beginning of a feeling or process that gradually develops and becomes stronger or more important.","ex":{"en":"He raised questions meant to plant seeds of doubts in the minds of jurors","cn":"他提出几个问题意欲引起陪审员的疑心。"}},{"pos":"N-COUNT 可数名词","cn":"(网球、羽毛球等体育项目中的)种子选手","en":"In sports such as tennis or badminton, a seed is a player who has been ranked according to his or her ability.","ex":{"en":"...Pete Sampras, Wimbledon's top seed and the world No.1","cn":"皮特·桑普拉斯，温布尔登网球锦标赛的头号种子，世界排名第一"}},{"pos":"VERB 动词","cn":"将(选手或参赛队)排列名次","en":"When a player or a team is seeded in a sports competition, they are ranked according to their ability.","ex":{"en":"In the UEFA Cup the top 16 sides are seeded for the first round","cn":"在欧洲联盟杯比赛中，排名前 16 位的球队已按位次进入首轮。"}},{"pos":"PHRASE 短语","cn":"开花结籽","en":"If vegetable plants go to seed or run to seed, they produce flowers and seeds as well as leaves.","ex":{"en":"If unused, winter radishes run to seed in spring.","cn":"如果不去动的话，冬萝卜会在春天开花结籽。"}},{"pos":"PHRASE 短语","cn":"衰老;风光不再;衰退;退化","en":"If you say that someone or something has gone to seed or has run to seed, you mean that they have become much less attractive, healthy, or efficient.","ex":{"en":"He says the economy has gone to seed","cn":"他说经济已经走向衰退。"}}]},"media":{"img":["media/pic/fruit_comp.jpg","media/thumb/watermelon.jpg","media/ldoce/img/kiwi.jpg"],"uk":"media/uk/seed__gb_1.mp3","us":"media/us/seed__us_1.mp3"},"examples":[{"en":"He has been seeded 14th at Wimbledon next week.","cn":"他被确定为下周温布尔登网球公开赛的第 14 号种子选手。"},{"en":"This planted the seeds of doubt in my mind.","cn":"这件事在我心中播下了怀疑的种子。"}]},"seaweed":{"oxford":{"phon":"ˈsiːwiːd","pos":"noun","senses":[{"en":"a plant that grows in the sea, or on rocks at the edge of the sea. There are many different types of seaweed, some of which are eaten as food.","cn":"海草；海藻"}]},"collins":{"senses":[{"pos":"N-MASS 物质名词","cn":"海草;海藻","en":"Seaweed is a plant that grows in the sea. There are many kinds of seaweed.","ex":{"en":"...seaweed washed up on a beach.","cn":"被冲到海滩上的海草"}}]},"media":{"uk":"media/uk/seaweed__gb_1.mp3","us":"media/us/seaweed__us_1.mp3"}},"self-reliant":{"oxford":{"phon":"ˌself rɪˈlaɪənt","pos":"adjective","senses":[{"en":"able to do or decide things by yourself, rather than depending on other people for help","cn":"自立的；自力更生的；自主的","ex":{"en":"a truly self-reliant community","cn":"一个真正自力更生的社区"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"自主的;自立的;自力更生的","en":"If you are self-reliant, you are able to do things and make decisions by yourself, without needing other people to help you.","ex":{"en":"She is intelligent and self-reliant, speaking her mind and not suffering fools gladly.","cn":"她聪慧自立，大胆直言，对蠢人没有耐心。"}}]},"media":{"uk":"media/uk/self_reliant_1_gb_1.mp3","us":"media/us/self_reliant_1_us_1.mp3"},"examples":[{"en":"Our aim is to teach our son to become an independent self-reliant adult.","cn":"我们的目标是把儿子培养成为独立自主的成年人。"}]},"setup":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"体制;组织方式;建制","en":"A particular set-up is a particular system or way of organizing something.","ex":{"en":"It appears to be an idyllic domestic set-up","cn":"这似乎是一种田园诗般的家庭组成格局。"}},{"pos":"N-COUNT 可数名词","cn":"陷害;栽赃","en":"If you describe a situation as a set-up, you mean that people have planned it in order to deceive you or to make it look as if you have done something wrong.","ex":{"en":"He was asked to pick somebody up and bring them to a party, not realizing it was a setup.","cn":"有人让他开车去接几个人来参加聚会，他并没有意识到这是个陷阱。"}},{"pos":"N-SING 单数名词","cn":"(软件或硬件的)安装，设置","en":"The set-up of computer hardware or software is the process of installing it and making it ready to use.","ex":{"en":"The worst part of the set-up is the poor instruction manual","cn":"安装时最糟糕就是操作指南讲述不够清楚。"}}]}},"settlement":{"media":{"uk":"media/uk/settlement__gb_1.mp3","us":"media/us/settlement__us_1.mp3"},"oxford":{"phon":"ˈsetlmənt","pos":"noun","senses":[{"en":"an official agreement that ends an argument between two people or groups","cn":"（解决纷争的）协议","g":"[countable]","ex":{"en":"to negotiate a peace settlement","cn":"就和平协议进行谈判"}},{"en":"the action of reaching an agreement","cn":"解决；处理","g":"[uncountable]","ex":{"en":"the settlement of a dispute","cn":"争端的解决"}},{"en":"the conditions, or a document stating the conditions, on which money or property is given to somebody","cn":"（关于钱财转让的）协议（书）","g":"[countable]","lab":"law","ex":{"en":"a divorce/marriage/property settlement","cn":"离婚／结婚／财产协议"}},{"en":"the action of paying back money that you owe","cn":"（欠款的）支付，偿付，结算","g":"[uncountable]","ex":{"en":"the settlement of a debt","cn":"债务的偿还"}},{"en":"a place where people have come to live and make their homes, especially where few or no people lived before","cn":"（尤指拓荒安家的）定居点","g":"[countable]","ex":{"en":"signs of an Iron Age settlement","cn":"铁器时代村落遗址"}},{"en":"the process of people making their homes in a place","cn":"移民；殖民；开拓","g":"[uncountable]","ex":{"en":"the settlement of the American West","cn":"美国西部的开拓过程"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"(争议双方的)正式协议，和解","en":"A settlement is an official agreement between two sides who were involved in a conflict or argument.","ex":{"en":"Our objective must be to secure a peace settlement","cn":"我们一定要达成和平协议。"}},{"pos":"N-COUNT 可数名词","cn":"(通过赔偿等达成的)庭外和解","en":"A settlement is an agreement to end a disagreement or dispute without going to a court of law, for example by offering someone money.","ex":{"en":"She accepted an out-of-court settlement of £4,000.","cn":"她同意支付 4,000 英镑的庭外和解赔偿金。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"(欠款的)偿付，支付，结算，清偿","en":"The settlement of a debt is the act of paying back money that you owe.","ex":{"en":"...ways to delay the settlement of debts.","cn":"延期清偿债务的办法"}},{"pos":"N-COUNT 可数名词","cn":"定居点;聚居地","en":"A settlement is a place where people have come to live and have built homes.","ex":{"en":"The village is a settlement of just fifty houses.","cn":"这个村子里只住了 50户人。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"移民;殖民;开拓","en":"The settlement of a group of people is the process in which they settle in a place where people from their country have never lived before.","ex":{"en":"...the settlement of immigrants in the occupied territories.","cn":"向占领地移民的殖民开拓"}}]},"examples":[{"en":"The management and unions have reached a settlement over new working conditions.","cn":"资方和工会已就新的工作条件达成协议。"},{"en":"the settlement of the American West","cn":"美国西部的开拓过程"}]},"season":{"media":{"uk":"media/uk/season__gb_1.mp3","us":"media/us/season__us_1.mp3"},"oxford":{"phon":"ˈsiːzn","pos":"noun","senses":[{"en":"any of the four main periods of the year: spring, summer, autumn and winter","cn":"季；季节","ex":{"en":"the changing seasons","cn":"四时更迭"}},{"en":"a period of the year in tropical countries when it is either very dry or it rains a lot","cn":"（热带地区的）旱季，雨季","ex":{"en":"In this climate there are no real changes of temperature, just a wet and a dry season.","cn":"在这种气候区，温度没有太大的变化，只有雨季和旱季之分。"}},{"en":"a period of time during a year when a particular activity happens or is done","cn":"（一年中开展某项活动的）季节，旺季","lab":"British English","ex":{"en":"the cricket/football/hunting/shooting season","cn":"板球/足球/狩猎/射击季节"}},{"en":"a period of time in which a play is shown in one place; a series of plays, films or television programmes","cn":"（一部戏剧在某地的）演出期，上演期；（戏剧、电影或电视节目的）一季，演播季","ex":{"en":"The play opens for a second season in London next week.","cn":"下周，这部剧将在伦敦开始第二轮演出。"}},{"en":"a period of time during one year when a particular style of clothes, hair, etc. is popular and fashionable","cn":"（一年中时装、发型等的）流行期","ex":{"en":"This season's look is soft and romantic.","cn":"这段时间的流行风格是柔和、浪漫。"}},{"en":"a set of television or radio programmes that have the same characters or deal with the same subject","cn":"（电视或广播节目的）季，系列","lab":"especially North American English","ex":{"en":"The show begins its second season next week.","cn":"节目的第二季下周开播。"}},{"en":"to add salt, pepper, etc. to food in order to make it taste better","cn":"加调料调味；加作料","ex":{"en":"Season the lamb with garlic.","cn":"给羊肉加蒜调味。"},"pos":"verb"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"季;季节;时节","en":"The seasons are the main periods into which a year can be divided and which each have their own typical weather conditions.","ex":{"en":"Autumn's my favourite season.","cn":"秋天是我最喜欢的季节。"}},{"pos":"N-COUNT 可数名词","cn":"(一年中某项活动或某一事件发生的)节期，时期","en":"You can use season to refer to the period during each year when a particular activity or event takes place. For example, the planting season is the period when a particular plant or crop is planted.","ex":{"en":"...birds arriving for the breeding season","cn":"飞来准备度过繁殖季节的鸟群"}},{"pos":"N-COUNT 可数名词","cn":"(水果、蔬菜等的)当令期，上市期","en":"You can use season to refer to the period when a particular fruit, vegetable, or other food is ready for eating and is widely available.","ex":{"en":"The plum season is about to begin","cn":"快到吃李子的季节了。"}},{"pos":"N-COUNT 可数名词","cn":"(体育项目的)赛季","en":"You can use season to refer to a fixed period during each year when a particular sport is played.","ex":{"en":"...the baseball season","cn":"棒球赛季"}},{"pos":"N-COUNT 可数名词","cn":"(戏剧、表演的)上演期，会演期，献演期","en":"A season is a period in which a play or show, or a series of plays or shows, is performed in one place.","ex":{"en":"...a season of three new plays.","cn":"3 部新戏剧的上演期"}},{"pos":"N-COUNT 可数名词","cn":"(一系列相关影片的)上映期","en":"A season of films is several of them shown as a series because they are connected in some way.","ex":{"en":"...a brief season of films in which Artaud appeared.","cn":"阿尔托出演的系列影片的短暂上映期"}},{"pos":"N-COUNT 可数名词","cn":"度假旺季;法定假期","en":"The holiday or vacation season is the time when most people have their holiday.","ex":{"en":"...the peak holiday season","cn":"休假高峰期"}},{"pos":"VERB 动词","cn":"给…调味;加味于","en":"If you season food with salt, pepper, or spices, you add them to it in order to improve its flavour.","ex":{"en":"Season the meat with salt and pepper","cn":"用盐和胡椒粉给肉调味。"}},{"pos":"VERB 动词","cn":"对(木材)作干燥处理;风干，晒干(木材)","en":"If wood is seasoned, it is made suitable for making into furniture or for burning, usually by being allowed to dry out gradually.","ex":{"en":"Ensure that new wood has been seasoned.","cn":"确保新木材已经风干。"}},{"pos":"PHRASE 短语","cn":"(雌性动物)处于发情期","en":"If a female animal is in season, she is in a state where she is ready to have sex."}]},"examples":[{"en":"( NAmE ) the holiday season (= the time of Thanksgiving, Hanukkah, Christmas and New Year)","cn":"节假日（包括感恩节、犹太教修殿节、圣诞节和新年）"},{"en":"He scored his first goal of the season on Saturday.","cn":"他在星期六的比赛中攻进了他在本赛季的第一个球。"}]},"selective":{"media":{"uk":"media/uk/selective__gb_1.mp3","us":"media/us/selective__us_1.mp3"},"oxford":{"phon":"sɪˈlektɪv","pos":"adjective","senses":[{"en":"affecting or involving only a small number of people or things from a larger group","cn":"选择性的；有选择的","g":"[usually before noun]","ex":{"en":"the selective breeding of cattle","cn":"牛的选择性培育"}},{"en":"tending to be careful about what or who you choose","cn":"认真挑选的；严格筛选的","ex":{"en":"You will have to be selective about which information to include in the report.","cn":"究竟要把哪些资料收入报告，你得仔细斟酌挑选。"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"选择性的;有选择的;选取少量的","en":"A selective process applies only to a few things or people.","ex":{"en":"Selective breeding may result in a greyhound running faster and seeing better than a wolf.","cn":"选择性交配繁殖有可能培育出比狼速度更快、视力更佳的灵犭是。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"仔细挑选的;严格筛选的","en":"When someone is selective, they choose things carefully, for example the things that they buy or do.","ex":{"en":"Sales still happen, but buyers are more selective","cn":"销量仍在，但购买者更加挑剔。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"(记忆)选择性的，只记一部分的","en":"If you say that someone has a selective memory, you disapprove of the fact that they remember certain facts about something and deliberately forget others, often because it is convenient for them to do so.","ex":{"en":"We seem to have a selective memory for the best bits of the past","cn":"我们似乎只记得过去最美好的时光。"}}]},"examples":[{"en":"You will have to be selective about which information to include in the report.","cn":"究竟要把哪些资料收入报告，你得仔细斟酌挑选。"},{"en":"The product will be selectively marketed in the US (= only in some areas).","cn":"这种产品将有选择地投放到美国某些地区的市场。"}]},"service":{"media":{"uk":"media/uk/service__gb_1.mp3","us":"media/us/service__us_1.mp3"},"oxford":{"phon":"ˈsɜːvɪs","pos":"noun","senses":[{"en":"a system that provides something that the public needs, organized by the government or a private company","cn":"公共服务系统；公共事业","g":"[countable]","sc":"providing something","ex":{"en":"the ambulance/bus/postal service","cn":"救护车／公共汽车／邮政服务系统"}},{"en":"an organization or a company that provides something for the public or does something for the government","cn":"公共事业机构（或公司）","g":"[countable]","sc":"providing something","ex":{"en":"the prison service","cn":"监狱管理机构"}},{"en":"a business whose work involves doing something for customers but not producing goods; the work that such a business does","cn":"服务性企业（或行业、业务）","g":"[countable, uncountable]","sc":"providing something","ex":{"en":"financial services","cn":"金融服务业"}},{"en":"the serving of customers in hotels, restaurants, and shops","cn":"（对顾客的）接待，服务","g":"[uncountable]","lab":"especially British English","sc":"in hotel/shop/restaurant","ex":{"en":"The food was good but the service was very slow.","cn":"饭菜不错，但动作太慢。"}},{"en":"the work that somebody does for an organization, etc., especially when it continues for a long time or is admired very much","cn":"（尤指长期、受到敬重的）工作，效劳，服务","g":"[uncountable]","sc":"work for organization","ex":{"en":"She has just celebrated 25 years' service with the company.","cn":"她刚庆祝了自己在公司任职 25 周年。"}},{"en":"the army, the navy and the air force; the work done by people in them","cn":"海陆空三军；兵役","g":"[countable, usually plural, uncountable]","sc":"army, etc.","ex":{"en":"Most of the boys went straight into the services.","cn":"多数男生直接去服兵役了。"}},{"en":"the use that you can get from a vehicle or machine; the state of being used","cn":"使用；使用状况","g":"[uncountable]","sc":"of vehicle/machine","ex":{"en":"That computer gave us very good service.","cn":"我们那台计算机很好用。"}},{"en":"an examination of a vehicle or machine followed by any work that is necessary to keep it operating well","cn":"检修；维护；维修；保养","g":"[countable, uncountable]","lab":"British English","sc":"of vehicle/machine","ex":{"en":"a service engineer","cn":"维修技师"}},{"en":"the particular skills or help that a person is able to offer","cn":"（提供技术或帮助的）服务","g":"[usually plural]","lab":"formal","sc":"skills/help","ex":{"en":"You need the services of a good lawyer.","cn":"你需要找一位好律师来帮助你。"}},{"en":"a religious ceremony","cn":"宗教礼仪；礼拜仪式","g":"[countable]","lab":"North American English","sc":"religious ceremony","ex":{"en":"a funeral/memorial service","cn":"丧葬／追思宗教仪式"}},{"en":"a bus, train, etc. that goes regularly to a particular place at a particular time","cn":"班车；车次","g":"[countable, usually singular]","sc":"bus/train","ex":{"en":"the cancellation of the 10.15 service to Glasgow","cn":"10 点 15 分开往格拉斯哥的车次取消"}},{"en":"a place next to a motorway where you can stop for petrol, a meal, the toilets, etc.","cn":"（高速公路旁的）服务区，服务站","g":"[singular + singular or plural verb]","lab":"British English","sc":"on motorway","ex":{"en":"motorway services","cn":"高速公路服务站"}},{"en":"an act of hitting the ball in order to start playing; the way that you hit it","cn":"发球；发球方式","g":"[singular]","sc":"in tennis","ex":{"en":"It's your service (= your turn to start playing).","cn":"该你发球了。"}},{"en":"a complete set of plates, dishes, etc. that match each other","cn":"整套餐具","g":"[countable]","sc":"set of plates, etc.","ex":{"en":"a tea service (= cups, saucers, a teapot and plates, for serving tea)","cn":"一套茶具"}},{"en":"the state or position of being a servant","cn":"仆人地位（或身份）","g":"[uncountable]","lab":"old-fashioned","sc":"being servant","ex":{"en":"to be in/go into service (= to be/become a servant)","cn":"做／去当佣人"}},{"en":"the formal giving of an official document, etc. to somebody","cn":"送达","g":"[uncountable]","lab":"law","sc":"of official document","ex":{"en":"the service of a demand for payment","cn":"缴款通知的送达"}},{"en":"to examine a vehicle or machine and repair it if necessary so that it continues to work correctly","cn":"检修；维护；维修；保养","g":"[usually passive]","sc":"vehicle/machine","ex":{"en":"We need to have the car serviced.","cn":"我们得把车送去检修一下了。"},"pos":"verb"},{"en":"to provide people with something they need, such as shops, or a transport system","cn":"提供服务","g":"[often passive]","sc":"provide something","ex":{"en":"Botley is well serviced by a regular bus route into Oxford.","cn":"从博特利到牛津有一条公交线路，按时发车，十分便利。"},"pos":"verb"},{"en":"to pay interest on money that has been borrowed","cn":"支付（债务）利息","lab":"finance","sc":"pay interest","ex":{"en":"The company can no longer service its debts.","cn":"那家公司已无力支付债务利息。"},"pos":"verb"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"公共服务事业;公共服务系统","en":"A service is something that the public needs, such as transport, communications facilities, hospitals, or energy supplies, which is provided in a planned and organized way by the government or an official body.","ex":{"en":"Britain still boasts the cheapest postal service","cn":"英国仍拥有最便宜的邮政服务系统。"}},{"pos":"N-COUNT 可数名词","cn":"公共事业机构(或公司)","en":"You can sometimes refer to an organization or private company as a particular service when it provides something for the public or acts on behalf of the government.","ex":{"en":"...the BBC World Service.","cn":"英国广播公司国际广播台"}},{"pos":"N-COUNT 可数名词","cn":"(机构或公司提供的某一)服务","en":"If an organization or company provides a particular service, they can do a particular job or a type of work for you.","ex":{"en":"The kitchen maintains a twenty-four hour service and can be contacted via Reception","cn":"厨房提供24小时餐饮服务，可通过前台进行联系。"}},{"pos":"N-PLURAL 复数名词","cn":"服务业;服务性活动","en":"Services are activities such as tourism, banking, and selling things which are part of a country's economy, but are not concerned with producing or manufacturing goods.","ex":{"en":"Mining rose by 9.1%, manufacturing by 9.4% and services by 4.3%.","cn":"采矿业增长了 9.1%, 制造业增长了 9.4%，服务业增长了 4.3%。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"服务内容;服务(质量);服务态度","en":"The level or standard of service provided by an organization or company is the amount or quality of the work it can do for you.","ex":{"en":"Taking risks is the only way employees can provide effective and efficient customer service","cn":"员工能够为客户提供有价值、高效的服务的唯一途径就是敢于冒险。"}},{"pos":"N-COUNT 可数名词","cn":"(公共汽车或火车的)路线，行程车次，班车","en":"A bus or train service is a route or regular journey that is part of a transport system.","ex":{"en":"A bus service operates between Bolton and Salford.","cn":"博尔顿和索尔福德之间有一班公共汽车往返。"}},{"pos":"N-PLURAL 复数名词","cn":"(提供技术或帮助的)服务","en":"Your services are the things that you do or the skills that you use in your job, which other people find useful and are usually willing to pay you for.","ex":{"en":"I have obtained the services of a top photographer to take our pictures","cn":"我已请到了一位顶级摄影师来给我们拍照。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"(为某组织或活动所做的)工作，服务，效劳","en":"If you refer to someone's service or services to a particular organization or activity, you mean that they have done a lot of work for it or spent a lot of their time on it.","ex":{"en":"You've given a lifetime of service to athletics","cn":"你为田径运动贡献了一生。"}},{"pos":"N-COUNT 可数名词","cn":"海陆空三军;军队;部队","en":"The Services are the army, the navy, and the air force.","ex":{"en":"In June 1945, Britain still had forty-five per cent of its workforce in the Services and munitions industries.","cn":"1945 年 6 月，英国仍然有45％的劳动力在部队服役或就职于军火工业。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"兵役;作战","en":"Service is the work done by people or equipment in the army, navy, or air force, for example during a war.","ex":{"en":"The regiment was recruited from the Highlands specifically for service in India.","cn":"该军团是专门为在印度作战而从苏格兰高地征募来的。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"(饭店、酒店，商店提供的)服务","en":"When you receive service in a restaurant, hotel, or shop, an employee asks you what you want or gives you what you have ordered.","ex":{"en":"A five-course meal including coffee, service and VAT is £30.","cn":"包括咖啡、服务费及增值税在内，一顿五道菜正餐的价格为 30 英镑。"}},{"pos":"N-COUNT 可数名词","cn":"宗教礼仪;礼拜仪式","en":"A service is a religious ceremony that takes place in a church.","ex":{"en":"After the hour-long service, his body was taken to a cemetery in the south of the city.","cn":"在长达一小时的悼念仪式结束后，他的遗体被抬到了城南的一所公墓。"}},{"pos":"N-COUNT 可数名词","cn":"整套餐具(或茶具)","en":"A dinner service or a tea service is a complete set of plates, cups, saucers, and other pieces of china.","ex":{"en":"...a 60-piece dinner service.","cn":"一套六十件套的餐具"}},{"pos":"N-COUNT 可数名词","cn":"(高速公路边可加油、购物或用餐的)服务站","en":"A services is a place beside a motorway where you can buy petrol and other things, or have a meal.","ex":{"en":"They had to pull up, possibly go to a motorway services or somewhere like that","cn":"他们只好停车，可能得去高速公路服务站之类的地方。"}},{"pos":"N-COUNT 可数名词","cn":"(网球、羽毛球等的)发球权，开球局","en":"In tennis, badminton, and some other sports, when it is your service, it is your turn to serve.","ex":{"en":"She conceded just three points on her service during the first set.","cn":"她在第一盘自己的发球局仅失了 3 分。"}},{"pos":"ADJ 形容词","cn":"(大楼、建筑中的设施）员工专用的，后勤专用的","en":"Service is used to describe the parts of a building or structure that are used by the staff who clean, repair, or look after it, and are not usually used by the public.","ex":{"en":"He wheeled the trolley down the corridor and disappeared with it into the service lift.","cn":"他推着小推车走过走廊，之后进了员工专用电梯不见了。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"服侍;伺候","en":"If someone is in service, they are working as a servant.","ex":{"en":"If a young woman did not have a dowry, she went into domestic service.","cn":"如果一个年轻女子没有嫁妆，她就要做家政服务赚钱。"}},{"pos":"VERB 动词","cn":"维修，检修,维护(机器、车辆)","en":"If you have a vehicle or machine serviced, you arrange for someone to examine, adjust, and clean it so that it will keep working efficiently and safely.","ex":{"en":"I had had my car serviced at the local garage","cn":"我已经把我的车送到当地汽修厂检修了。"}},{"pos":"VERB 动词","cn":"(国家、组织)支付(债息)","en":"If a country or organization services its debts, it pays the interest on them.","ex":{"en":"Almost a quarter of the country's export earnings go to service a foreign debt of $29 billion.","cn":"该国几乎 1/4 的出口收入都用来支付 290 亿美元外债的利息了。"}},{"pos":"VERB 动词","cn":"为…提供服务;满足…的需求","en":"If someone or something services an organization, a project, or a group of people, they provide it with the things that it needs in order to function properly or effectively.","ex":{"en":"There are now 400 staff at headquarters, servicing our regional and overseas work","cn":"现在总部有 400 名职员负责地区和海外事务。"}},{"pos":"PHRASE 短语","cn":"随时可供…使用;随时为…提供帮助","en":"To be at the service of a person or organization means to be available to help or be used by that person or organization.","ex":{"en":"The intellectual and moral potential of the world's culture must be put at the service of politics.","cn":"世界文化潜在的知识和道德力量一定要为政治所用。"}},{"pos":"CONVENTION 惯用语","cn":"随时为您效劳;随时听您的吩咐","en":"You can use 'at your service' after your name as a formal way of introducing yourself to someone and saying that you are willing to help them in any way you can.","ex":{"en":"She bowed dramatically. 'Anastasia Krupnik, at your service,' she said.","cn":"她夸张地鞠了个躬。“阿纳斯塔西娅·克鲁布尼克，随时为您效劳，”她说。"}},{"pos":"PHRASE 短语","cn":"帮…一个忙;对…有益","en":"If you do someone a service, you do something that helps or benefits them.","ex":{"en":"You are doing me a great service, and I'm very grateful to you","cn":"你帮了我一个大忙，非常感激。"}},{"pos":"PHRASE 短语","cn":"(车辆、设备)在使用中,可以使用/(通常因发生故障而)未在使用","en":"If a piece of equipment or type of vehicle is in service, it is being used or is able to be used. If it is out of service, it is not being used, usually because it is not working properly.","ex":{"en":"Cuts in funding have meant that equipment has been kept in service long after it should have been replaced","cn":"资金的削减意味着早该换掉的设备一直在长期运转。"}},{"pos":"PHRASE 短语","cn":"有用;有帮助","en":"If someone or something is of service to you, they help you or are useful to you.","ex":{"en":"That is, after all, the primary reason we live — to be of service to others.","cn":"别忘了，那是我们活着的主要原因——帮助他人。"}},{"pos":"","cn":"","en":"to be pressed into service→see: ;"}]},"examples":[{"en":"Botley is well serviced by a regular bus route into Oxford.","cn":"从博特利到牛津有一路公共汽车，按时发车，十分便利。"},{"en":"The government aims to improve public services , especially education.","cn":"政府致力于改善公共服务事业，尤其是教育。"}]},"severity":{"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"very bad","cn":""},{"en":"very bad, especially in a way that shocks or upsets you","cn":""}]},"examples":[{"en":"His injuries were quite severe.","cn":"","src":"ld"},{"en":"She’s suffering from severe depression.","cn":"","src":"ld"}],"media":{"uk":"media/uk/severity__gb_1.mp3","us":"media/us/severity__us_1.mp3"},"oxford":{"phon":"sɪˈverəti","pos":"noun","senses":[{"en":"the fact or condition of something being extremely bad or serious","cn":"极其糟糕或严重的事实或情况","ex":{"en":"A prison sentence should match the severity of the crime.","cn":"刑期长短应与罪行轻重相符。"}},{"en":"the fact of something, especially a punishment, being very strict or extreme","cn":"严重性：某些事实，特别是一种惩罚，是非常严格的或极端的","ex":{"en":"The severity of the sentence surprised many people.","cn":"判决之严厉让很多人感到惊讶。"}},{"en":"the fact of not being kind and not showing sympathy or approval","cn":"严重性：不友善，不表示同情或认同","ex":{"en":"He frowned with mock severity.","cn":"他假装严厉地皱了皱眉。"}},{"en":"the fact of being extremely difficult and requiring a lot of skill or ability","cn":"极其困难并需要大量技能或能力的事实","ex":{"en":"The severity of the task ahead became apparent.","cn":"眼前任务的严峻性已经显而易见。"}},{"en":"the fact of being extremely plain and without any decoration","cn":"极其朴素且没有任何装饰的事实","lab":"disapproving","ex":{"en":"The elaborate facade contrasts strongly with the severity of the interior.","cn":"外表的精美和内部的简朴形成了鲜明的对比。"}}]}},"sending":{"oxford":{"phon":"send","pos":"verb","senses":[{"en":"to make sth go or be taken to a place, especially by post/mail, email, radio, etc.","cn":"邮寄；发送"},{"en":"to tell sb sth by sending them a message","cn":"传达；转致；告知"}]},"media":{"uk":"media/uk/send__gb_1.mp3","us":"media/us/send__us_1.mp3"}},"servants":{"oxford":{"phon":"ˈsɜːvənt","pos":"noun","senses":[{"en":"a person who works in another person's house, and cooks, cleans, etc. for them","cn":"仆人；用人"},{"en":"a person who works for a company or an organization （","cn":"公司或机构的）雇员，职员"}]}},"sentence":{"media":{"uk":"media/uk/sentence__gb_1.mp3","us":"media/us/sentence__us_1.mp3"},"oxford":{"phon":"ˈsentəns","pos":"noun","senses":[{"en":"a set of words expressing a statement, a question or an order, usually containing a subject and a verb. In written English sentences begin with a capital letter and end with a full stop/period (.), a question mark (?) or an exclamation mark (!).","cn":"句子","g":"[countable]","lab":"grammar","ex":{"en":"Does the sentence contain an adverb?","cn":"这个句子里有副词吗？"}},{"en":"the punishment given by a court","cn":"判决；宣判；判刑","g":"[countable, uncountable]","lab":"especially North American English","ex":{"en":"a jail/prison sentence","cn":"判处监禁"}},{"en":"to say officially in court that somebody is to receive a particular punishment","cn":"判决；宣判；判刑","ex":{"en":"He sentenced the defendant to life in prison.","cn":"他判处被告终身监禁。"},"pos":"verb"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"句子","en":"A sentence is a group of words which, when they are written down, begin with a capital letter and end with a full stop, question mark, or exclamation mark. Most sentences contain a subject and a verb."},{"pos":"N-VAR 可变名词","cn":"判决;宣判;判刑","en":"In a law court, a sentence is the punishment that a person receives after they have been found guilty of a crime.","ex":{"en":"They are already serving prison sentences for their part in the assassination","cn":"他们因参与这起刺杀已经开始在监狱服刑了。"}},{"pos":"VERB 动词","cn":"判决;宣判;判刑","en":"When a judge sentences someone, he or she states in court what their punishment will be.","ex":{"en":"A military court sentenced him to death in his absence","cn":"一所军事法庭在他缺席的情况下判处他死刑。"}}]},"examples":[{"en":"The prisoner has served (= completed) his sentence and will be released tomorrow.","cn":"犯人已服刑期满，明天将获释。"},{"en":"to be sentenced to death/life imprisonment/three years in prison","cn":"被判死刑/终身监禁/三年徒刑"}]},"segments":{"oxford":{"phon":"ˈseɡmənt","pos":"noun","senses":[{"en":"a part of sth that is separate from the other parts or can be considered separately","cn":"部分；份；片；段"},{"en":"one of the sections of an orange, a lemon, etc. （","cn":"柑橘、柠檬等的）瓣"}]}},"sector":{"media":{"img":["media/pic/circles_comp.jpg","media/thumb/circles2.jpg"],"uk":"media/uk/sector__gb_1.mp3","us":"media/us/sector__us_1.mp3"},"oxford":{"phon":"ˈsektə(r)","pos":"noun","senses":[{"en":"a part of an area of activity, especially of a country’s economy","cn":"（尤指一国经济的）部门，领域，行业","ex":{"en":"the service/banking/manufacturing/financial sector","cn":"服务业；银行业；制造业；金融业"}},{"en":"a part of a particular area, especially an area under military control","cn":"（尤指军事管制的）区域，地带","ex":{"en":"each sector of the war zone","cn":"战区的每个军控地段"}},{"en":"a part of a circle lying between two straight lines drawn from the centre to the edge","cn":"扇形","lab":"geometry"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"(经济的)部门，行业，领域","en":"A particular sector of a country's economy is the part connected with that specified type of industry.","ex":{"en":"...the nation's manufacturing sector.","cn":"该国的制造业"}},{"pos":"N-COUNT 可数名词","cn":"(大型组织的)部分,小群体","en":"A sector of a large group is a smaller group which is part of it.","ex":{"en":"Workers who went to the Gulf came from the poorest sectors of Pakistani society.","cn":"前往海湾的工人来自巴基斯坦最贫穷的社会阶层。"}},{"pos":"N-COUNT 可数名词","cn":"军事管制区;军事防御区","en":"A sector is an area of a city or country which is controlled by a military force.","ex":{"en":"Officers were going to retake sectors of the city.","cn":"军官们打算重新夺回该市的防御区。"}},{"pos":"N-COUNT 可数名词","cn":"扇形","en":"A sector is a part of a circle which is formed when you draw two straight lines from the centre of the circle to the edge."}]},"examples":[{"en":"each sector of the war zone","cn":"战区的每个军控地段"},{"en":"service-sector jobs (= in hotels, restaurants, etc.)","cn":"服务性行业的工作"}]},"secondary":{"media":{"uk":"media/uk/secondary__gb_1.mp3","us":"media/us/secondary__us_1.mp3"},"oxford":{"phon":"ˈsekəndri","pos":"adjective","senses":[{"en":"connected with teaching children of 11–18 years","cn":"中等教育的；中学的","g":"[only before noun]","ex":{"en":"secondary teachers","cn":"中学教师"}},{"en":"less important than something else","cn":"次要的；从属的；辅助的","ex":{"en":"That is just a secondary consideration.","cn":"那只不过是次要的考虑因素。"}},{"en":"happening as a result of something else","cn":"间接引发的；继发性的；次生的","g":"[usually before noun]","ex":{"en":"a secondary infection","cn":"继发感染"}}]},"collins":{"senses":[{"pos":"ADJ 形容词","cn":"第二位的;次要的;从属的","en":"If you describe something as secondary, you mean that it is less important than something else.","ex":{"en":"The street erupted in a huge explosion, with secondary explosions in the adjoining buildings","cn":"街上发生了剧烈爆炸，邻近的建筑里也发生了程度较轻的爆炸。"}},{"pos":"ADJ 形容词","cn":"(疾病、感染)继发性的，第二期的","en":"Secondary diseases or infections happen as a result of another disease or infection that has already happened.","ex":{"en":"He had kidney cancer, with secondary tumours in the brain and lungs.","cn":"他患有肾癌，还有脑部和肺部的继发性肿瘤。"}},{"pos":"ADJ 形容词","cn":"(教育)中等的，中学的","en":"Secondary education is given to pupils between the ages of 11 or 12 and 17 or 18.","ex":{"en":"Examinations for the GCSE are taken after about five years of secondary education.","cn":"在接受中等教育约5年后便可参加普通中等教育证书的考试。"}}]},"examples":[{"en":"Raising animals was only secondary to other forms of farming.","cn":"与其他农业生产相对而言，动物饲养只是副业。"},{"en":"Their clothing is primarily functional and only secondarily decorative.","cn":"他们的衣服首重实用，其次才讲花式。"}]},"sensuous":{"media":{"uk":"media/uk/sensuous__gb_1.mp3","us":"media/us/sensuous__us_1.mp3"},"oxford":{"phon":"ˈsenʃuəs","pos":"adjective","senses":[{"en":"giving pleasure to your senses","cn":"愉悦感官的","ex":{"en":"sensuous music","cn":"悦耳的音乐"}},{"en":"suggesting an interest in sexual pleasure","cn":"肉感的；性感的","ex":{"en":"his full sensuous lips","cn":"他的丰满性感的嘴唇"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"愉悦感官的;给人以美感的","en":"Something that is sensuous gives pleasure to the mind or body through the senses.","ex":{"en":"The film is ravishing to look at and boasts a sensuous musical score","cn":"这部电影画面迷人，配乐悦耳动听。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"性感的;耽于肉欲的","en":"Someone or something that is sensuous shows or suggests a great liking for sexual pleasure.","ex":{"en":"...his sensuous young mistress, Marie-Therese.","cn":"他年轻性感的情妇玛丽－特蕾泽"}}]},"examples":[{"en":"I'm drawn to the poetic, sensuous qualities of her paintings.","cn":"我喜欢她的画中那种充满诗意、赏心悦目的特性。"},{"en":"his full sensuous lips","cn":"他的丰满性感的嘴唇"}]},"secretary":{"oxford":{"phon":"ˈsekrətri","pos":"noun","senses":[{"en":"a person who works in an office, working for another person, dealing with mail and phone calls, keeping records, arranging meetings with people, etc.","cn":"秘书","ex":{"en":"a legal/medical secretary","cn":"法律／医务秘书"}},{"en":"an official of a club, society, etc. who deals with mail, keeping records and making business arrangements","cn":"（俱乐部、社团等的）干事，文书","ex":{"en":"the membership secretary","cn":"组织干事"}},{"en":"(in the UK) the head of an important government department","cn":"（英国）大臣"},{"en":"the head of a government department, chosen by the president","cn":"政府部门首长；部长","ex":{"en":"Secretary of the Treasury","cn":"财政部长"}},{"en":"an assistant of a government minister, an ambassador, etc.","cn":"（大臣、大使等的）助理","ex":{"en":"Ms Watson is a former parliamentary secretary to the Minister of Education.","cn":"沃森女士是教育部长的前议会秘书。"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"秘书","en":"A secretary is a person who is employed to do office work, such as typing letters, answering phone calls, and arranging meetings."},{"pos":"N-COUNT 可数名词","cn":"(工会、政党、俱乐部等的)干事,书记员","en":"The secretary of an organization such as a trade union, a political party, or a club is its official manager.","ex":{"en":"My grandfather was secretary of the Scottish Miners' Union.","cn":"我的祖父是苏格兰矿工工会干事。"}},{"pos":"N-COUNT 可数名词","cn":"(公司的)秘书，文书","en":"The secretary of a company is the person who has the legal duty of keeping the company's records."},{"pos":"N-COUNT; N-TITLE 可数名词；头衔名词","cn":"部长;大臣","en":"Secretary is used in the titles of ministers and officials who are in charge of main government departments.","ex":{"en":"...the British Foreign Secretary.","cn":"英国外交大臣"}}]},"media":{"uk":"media/uk/secretary__gb_1.mp3","us":"media/us/secretary__us_1.mp3"},"examples":[{"en":"Please contact my secretary to make an appointment.","cn":"请和我的秘书联系，预约一个时间。"},{"en":"a legal/medical secretary","cn":"法律/医务秘书"}]},"section":{"media":{"uk":"media/uk/section__gb_1.mp3","us":"media/us/section__us_1.mp3"},"oxford":{"phon":"ˈsekʃn","pos":"noun","senses":[{"en":"any of the parts into which something is divided","cn":"部分；部门","g":"[countable]","sc":"part/piece","ex":{"en":"That section of the road is still closed.","cn":"那段公路依旧封闭。"}},{"en":"a separate part of a structure from which the whole can be put together","cn":"部件；散件","g":"[countable]","sc":"part/piece","ex":{"en":"The shed comes in sections that you assemble yourself.","cn":"棚屋以散件出售，需要自己组装。"}},{"en":"a separate part of a document, book, etc.","cn":"节；款；项；段；部分","g":"[countable]","sc":"of document/book","ex":{"en":"These issues will be discussed more fully in the next section.","cn":"这些问题将在下一节中有更充分的讨论。"}},{"en":"a separate group within a larger group of people","cn":"阶层；界；组","g":"[countable]","sc":"group of people","ex":{"en":"an issue that will affect large sections of the population","cn":"涉及人口中广大阶层的问题"}},{"en":"a department in an organization, institution, etc.","cn":"部门；处；科；股；组","g":"[countable]","sc":"of organization","ex":{"en":"He's the director of the finance section.","cn":"他是财务处处长。"}},{"en":"a district of a town, city or county","cn":"区；地区；地段","g":"[countable]","lab":"North American English","sc":"district","ex":{"en":"the Dorchester section of Boston","cn":"波士顿的多切斯特区"}},{"en":"a measure of land, equal to one square mile","cn":"（土地单位）一平方英里","g":"[countable]","lab":"North American English","sc":"measurement"},{"en":"a drawing or diagram of something as it would look if it were cut from top to bottom or from one side to the other","cn":"剖面图；断面图","g":"[countable]","sc":"diagram","ex":{"en":"The illustration shows a section through a leaf.","cn":"图中所示为叶的剖面。"}},{"en":"the act of cutting or separating something in an operation","cn":"切开；切断","g":"[countable, uncountable]","lab":"medical","sc":"medical","ex":{"en":"The surgeon performed a section (= made a cut) on the vein.","cn":"外科医生施行了静脉切开手术。"}},{"en":"a very thin flat piece cut from body tissue to be looked at under a microscope","cn":"（供显微镜下观察的）切片","g":"[countable]","lab":"medical, biology，，","sc":"medical","ex":{"en":"to examine a section from the kidney","cn":"观察肾脏切片"}},{"en":"to divide body tissue by cutting","cn":"切开；切断","lab":"medical","sc":"medical/biology","pos":"verb"},{"en":"to cut animal or plant tissue into thin slices in order to look at it under a microscope","cn":"做（动物或植物组织的）切片","lab":"biology","sc":"medical/biology","pos":"verb"},{"en":"to officially send somebody to a psychiatric hospital, using a law that can force them to stay there to have treatment","cn":"（依法令精神病人）强制入院治疗","g":"[often passive]","lab":"British English","sc":"send to hospital","ex":{"en":"He was sectioned under the Mental Health Act because he was harming himself.","cn":"他因自残而根据《精神健康法》被分院。"},"pos":"verb"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"部分","en":"A section of something is one of the parts into which it is divided or from which it is formed.","ex":{"en":"He said it was wrong to single out any section of society for Aids testing","cn":"他说把社会中的任何一部分人抽选出来做艾滋病检查都是不对的。"}},{"pos":"VERB 动词","cn":"把…切成片;把…分成段(或组等)","en":"If something is sectioned, it is divided into sections.","ex":{"en":"It holds vegetables in place while they are being peeled or sectioned.","cn":"将蔬菜削皮或切片时用它来固定。"}},{"pos":"N-COUNT 可数名词","cn":"(文件的)节,章;(法律的)条，款，项","en":"A section of an official document such as a report, law, or constitution is one of the parts into which it is divided.","ex":{"en":"...section 14 of the Trade Descriptions Act 1968.","cn":"1968 年《商品说明法》第 14 条"}},{"pos":"N-COUNT 可数名词","cn":"断面图;剖面图;截面图","en":"A section is a diagram of something such as a building or a part of the body. It shows how the object would appear to you if it were cut from top to bottom and looked at from the side.","ex":{"en":"For some buildings a vertical section is more informative than a plan.","cn":"有些建筑的立面图能比平面图提供更多的信息。"}},{"pos":"","cn":"","en":"Caesarean section→see: ;"},{"pos":"","cn":"","en":"相关词组：section off"}]},"examples":[{"en":"These issues will be discussed more fully in the next section.","cn":"这些问题将在下一节中有更充分的讨论。"},{"en":"The library has a large biology section.","cn":"这个图书馆有大量的生物学藏书。"}]},"seventeen":{"media":{"uk":"media/uk/seventeen__gb_1.mp3","us":"media/us/seventeen__us_1.mp3"},"oxford":{"phon":"ˌsevnˈtiːn","pos":"number","senses":[{"en":"17","cn":"十七"}]},"collins":{"senses":[{"pos":"NUM 数词","cn":"(数字) 17","en":"Seventeen is the number 17.","ex":{"en":"Jenny is seventeen years old.","cn":"珍妮 17 岁了。"}}]},"examples":[{"en":"a group of seventeen American military officers","cn":"由17名美国军官组成的团体"},{"en":"I left home when I was seventeen (= 17 years old ) .","cn":"我17岁时离开家。"}]},"seven":{"media":{"uk":"media/uk/seven__gb_1.mp3","us":"media/us/seven__us_1.mp3"},"oxford":{"phon":"ˈsevn","pos":"number","senses":[{"en":"7","cn":"七","ex":{"en":"There are seven cookies left.","cn":"还剩下七块饼干。"}}]},"collins":{"senses":[{"pos":"NUM 数词","cn":"(数字)7","en":"Seven is the number 7.","ex":{"en":"Sarah and Ella have been friends for seven years.","cn":"萨拉和埃拉已经有7年的交情了。"}}]},"examples":[{"en":"The women visited cities in seven states.","cn":"这些女性访问了七个州的城市。"},{"en":"We close the store at seven (= seven o'clock ) .","cn":"我们商店七点关门。"}]},"ses":{"oxford":{"phon":"","pos":"abbr.","senses":[{"en":"south-east; south-eastern","cn":"东南方（的）；东南部（的）"}]}},"semi-precious":{"oxford":{"phon":"ˌsemi ˈpreʃəs","pos":"adjective","senses":[{"en":"less valuable than the most valuable types of jewels","cn":"次贵重的；半宝石的"}]},"collins":{"senses":[{"pos":"ADJ 形容词","cn":"（宝石）半珍贵的，次贵重的，半宝石的","en":"Semi-precious stones are stones such as turquoises and amethysts that are used in jewellery but are less valuable than precious stones such as diamonds and rubies."}]},"media":{"uk":"media/uk/semi_precious_1_gb_1.mp3","us":"media/us/semi_precious_1_us_1.mp3"}},"self-sufficient":{"oxford":{"phon":"ˌself səˈfɪʃnt","pos":"adjective","senses":[{"en":"able to do or produce everything that you need without the help of other people","cn":"自给自足的；自立的","ex":{"en":"The country is totally self-sufficient in food production.","cn":"在粮食生产上，这个国家完全做到了自给自足。"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"(国家或团体)自给自足的,自立的","en":"If a country or group is self-sufficient, it is able to produce or make everything that it needs.","ex":{"en":"This enabled the country to become self-sufficient in sugar","cn":"这使得该国的食糖能自给自足。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"(人)独立生活的，自立的","en":"Someone who is self-sufficient is able to live happily without anyone else.","ex":{"en":"Although she had various boyfriends, Madeleine was, and remains, fiercely self-sufficient","cn":"尽管有过各种各样的男朋友，马德琳过去和现在一直都非常自立。"}}]},"media":{"uk":"media/uk/self_sufficient_1_gb_1.mp3","us":"media/us/self_sufficient_1_us_1.mp3"},"examples":[{"en":"The country is totally self-sufficient in food production.","cn":"在粮食生产上，这个国家完全做到了自给自足。"},{"en":"Australia is 65% self-sufficient in oil.","cn":"澳大利亚65%的用油能够自给自足。"}]},"sex":{"oxford":{"phon":"seks","pos":"noun","senses":[{"en":"the state of being male or female","cn":"性别","g":"[uncountable, countable]","ex":{"en":"How can you tell what sex a fish is?","cn":"你怎样辨别一条鱼的雌雄？"}},{"en":"either of the two groups that people, animals, and plants are divided into according to their function of producing young","cn":"男性；女性；雄性；雌性","g":"[countable]","ex":{"en":"a member of the opposite sex","cn":"一名异性成员"}},{"en":"physical activity between two people in which they touch each other’s sexual organs, and which may include sexual intercourse","cn":"性；性交；性行为；性活动","g":"[uncountable]","ex":{"en":"He had sex with someone he met in a bar.","cn":"他与在酒吧认识的人发生了性关系。"}},{"en":"having the amount of sexual activity or desire mentioned","cn":"性行为…的；性欲…的","ex":{"en":"a highly-sexed person","cn":"一个高度性感的人"}},{"en":"to examine an animal in order to find out whether it is male or female","cn":"区分（动物）的性别","pos":"verb"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"男性;女性;雌性;雄性","en":"The two sexes are the two groups, male and female, into which people and animals are divided according to the function they have in producing young.","ex":{"en":"...an entertainment star who appeals to all ages and both sexes.","cn":"男女老幼都喜欢的娱乐明星"}},{"pos":"N-COUNT 可数名词","cn":"性别;性别特征","en":"The sex of a person or animal is their characteristic of being either male or female.","ex":{"en":"She continually failed to gain promotion because of her sex","cn":"她因为是女性而迟迟得不到晋升。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"性行为;性交;性活动","en":"Sex is the physical activity by which people can produce young.","ex":{"en":"He was very open in his attitudes about sex","cn":"他对待性的态度非常开放。"}},{"pos":"VERB 动词","cn":"辨别…的性别;辨识…的雌雄","en":"If an animal is sexed, someone finds out whether it is male or female.","ex":{"en":"The birds must be weighed, sexed and tagged.","cn":"必须对这些鸟称重，辨识雌雄并挂上标牌。"}},{"pos":"PHR-RECIP 相互短语","cn":"发生性关系;做爱","en":"If two people have sex, they perform the act of sex.","ex":{"en":"I had no intention of having sex with him on a first date.","cn":"我并没想第一次约会就和他上床。"}},{"pos":"","cn":"","en":"相关词组：sex up"}]},"media":{"uk":"media/uk/sex__gb_1.mp3","us":"media/us/sex__us_1.mp3"},"examples":[{"en":"It is illegal to have sex with a person under the age of 16.","cn":"和 16 岁以下的未成年人发生性行为是违法的。"},{"en":"The profession is trying to sex up its image.","cn":"这个行业正在设法使自身形象更加吸引人。"}]},"sensationalism":{"oxford":{"phon":"senˈseɪʃənəlɪzəm","pos":"noun","senses":[{"en":"a way of getting people’s interest by using words that are intended to shock you or by presenting facts and events as worse or more shocking than they really are","cn":"（行文或报道）耸人听闻，哗众取宠","ex":{"en":"the sensationalism of the popular press","cn":"为大众服务的新闻界所使用的耸动视听的做法。"}}]},"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"(报道的)耸人听闻，哗众取宠","en":"Sensationalism is the presenting of facts or stories in a way that is intended to produce strong feelings of shock, anger, or excitement.","ex":{"en":"The report criticises the newspaper for sensationalism.","cn":"这篇报道批评了报纸哗众取宠的作风。"}}]},"media":{"uk":"media/uk/sensationalism__gb_1.mp3","us":"media/us/sensationalism__us_1.mp3"},"examples":[{"en":"sensationalist headlines","cn":"耸人听闻的标题"}]},"seen":{"collins":{"senses":[{"pos":"","cn":"","en":"Seen is the past participle of see."}]},"media":{"uk":"media/uk/seen__gb_1.mp3","us":"media/us/seen__us_1.mp3"}},"seeker":{"media":{"uk":"media/uk/seeker__gb_1.mp3","us":"media/us/seeker__us_1.mp3"},"oxford":{"phon":"ˈsiːkə(r)","pos":"noun","senses":[{"en":"a person who is trying to find or get the thing mentioned","cn":"寻找者；寻求者；追求者；谋求者","ex":{"en":"an attention/a publicity seeker","cn":"故意引人注意的人；追求出名的人"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"寻找者;寻求者;追求者;谋求者","en":"A seeker is someone who is looking for or trying to get something.","ex":{"en":"I am a seeker after truth","cn":"我追求真理。"}}]},"examples":[{"en":"an attention/a publicity seeker","cn":"故意引人注意的人；追求出名的人"},{"en":"seekers after the truth","cn":"追求真理的人"}]},"sequencing":{"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"(对基因、DNA的)排序","en":"Gene sequencing or DNA sequencing involves identifying the order in which the elements making up a particular gene are combined.","ex":{"en":"...the US government's own gene sequencing programme.","cn":"美国政府自己的基因排序项目"}}]},"media":{"uk":"media/uk/sequencing__gb_1.mp3","us":"media/us/sequencing__us_1.mp3"},"examples":[{"en":"a gene sequencing project","cn":"基因测序项目"}],"oxford":{"phon":"ˈsiːkwənsɪŋ","pos":"noun","senses":[{"en":"the process of identifying the order in which a set of genes or parts of molecules are arranged","cn":"测定（整套基因或分子成分的）序列","lab":"biology","ex":{"en":"a gene sequencing project","cn":"基因测序项目"}},{"en":"the process of arranging things into a sequence","cn":"按顺序排列","ex":{"en":"The sequencing of the songs has been carefully thought about.","cn":"歌曲的排序是经过仔细考虑的。"}}]}},"setting":{"media":{"uk":"media/uk/setting__gb_1.mp3","us":"media/us/setting__us_1.mp3"},"oxford":{"phon":"ˈsetɪŋ","pos":"noun","senses":[{"en":"an environment where something is located; the place at which something happens","cn":"环境；背景","ex":{"en":"a rural/an ideal/a beautiful/an idyllic setting","cn":"乡村／理想／优美／田园环境"}},{"en":"the place and time at which the action of a play, novel, etc. takes place","cn":"（戏剧、小说等的）情节背景","ex":{"en":"short stories with a contemporary setting","cn":"以当代生活为背景的短篇小说"}},{"en":"a position at which the controls on a machine can be set, to set the speed, height, temperature, etc.","cn":"（机器上调节速度、高度、温度等的）挡，级，点","ex":{"en":"There are three speed settings: high, medium, and low.","cn":"有三种速度设置：高、中、低。"}},{"en":"the place on a computer or other electronic device where you can choose the way that it works or looks; the particular choices that you make","cn":"（计算机或其他电子装置的）设置区，设定","g":"[plural]","ex":{"en":"To change the size of the font, go to Settings.","cn":"要更改字体的大小，请前往“设置”。"}},{"en":"music written to go with a poem, etc.","cn":"（为诗等谱的）曲","lab":"music","ex":{"en":"Schubert’s setting of a poem by Goethe","cn":"舒伯特为歌德的一首诗谱的曲"}},{"en":"a piece of metal in which a precious stone is fixed to form a piece of jewellery","cn":"（镶嵌宝石的）底座，底板，托板","ex":{"en":"a ruby in a heavy gold setting","cn":"重金镶托的红宝石"}},{"en":"a complete set of equipment for eating with (knife, fork, spoon, glass, etc.) for one person, arranged on a table","cn":"（摆在桌上供一人用的）一套餐具","ex":{"en":"a place setting","cn":"一个座位的整套餐具"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"环境;背景;地点","en":"A particular setting is a particular place or type of surroundings where something is or takes place.","ex":{"en":"Rome is the perfect setting for romance","cn":"罗马是最适合谈情说爱的地方。"}},{"pos":"N-COUNT 可数名词","cn":"(炉具、热水器等上可供调节的)挡，级，点，刻度","en":"A setting is one of the positions to which the controls of a device such as a cooker, stove, or heater can be adjusted.","ex":{"en":"You can boil the fish fillets on a high setting.","cn":"可以用高火煮无骨鱼片。"}},{"pos":"N-COUNT 可数名词","cn":"一套餐具","en":"A table setting is the complete set of equipment that one person needs to eat a meal, including knives, forks, spoons, and glasses."}]},"examples":[{"en":"It was the perfect setting for a wonderful Christmas.","cn":"环境气氛无可挑剔，正是一个美好的圣诞节所需要的。"},{"en":"The performance of the engine was tested at different settings.","cn":"对引擎的性能在不同的挡上做了试验。"}]},"server":{"oxford":{"phon":"ˈsɜːvə(r)","pos":"noun","senses":[{"en":"a computer program that controls or supplies information to several computers connected in a network; the main computer on which this program is run","cn":"服务器","lab":"computing"},{"en":"a player who is serving, for example in tennis","cn":"发球者","lab":"sport"},{"en":"a kitchen utensil (= tool) used for putting food onto somebody’s plate","cn":"上菜用具（往各人盘子里盛食物的叉、铲、勺等）","g":"[usually plural]","ex":{"en":"salad servers","cn":"分色拉用的叉匙"}},{"en":"a person who serves food in a restaurant; a waiter or waitress","cn":"（餐馆给顾客上菜的）侍者","lab":"especially North American English"},{"en":"a person who helps a priest during a church service","cn":"（教堂做礼拜时的）助祭，辅祭"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"服务器","en":"In computing, a server is part of a computer network which does a particular task, for example storing or processing information, for all or part of the network."},{"pos":"N-COUNT 可数名词","cn":"(网球或羽毛球的)发球者","en":"In tennis and badminton, the server is the player whose turn it is to hit the ball or shuttlecock to start play.","ex":{"en":"...a brilliant server and volleyer.","cn":"一个发球和截球技术高超的发球上网型网球手"}},{"pos":"N-COUNT 可数名词","cn":"(叉、匙等)上菜用具","en":"A server is something such as a fork or spoon that is used for serving food.","ex":{"en":"...salad servers.","cn":"夹色拉的叉匙"}}]},"media":{"img":["media/pic/cutlery_diningroom_comp.jpg","media/thumb/server.jpg"],"uk":"media/uk/server__gb_1.mp3","us":"media/us/server__us_1.mp3"},"examples":[{"en":"salad servers","cn":"分色拉用的叉匙"},{"en":"The server’s down (= not working ) again.","cn":"主机又坏了。"}]},"sells":{"oxford":{"phon":"sel","pos":"verb","senses":[{"en":"to give sth to sb in exchange for money","cn":"出让；转让"},{"en":"to offer sth for people to buy","cn":"出售；售卖"}]},"media":{"uk":"media/uk/sell__gb_1.mp3","us":"media/us/sell__us_1.mp3"}},"setback":{"oxford":{"phon":"ˈsetbæk","pos":"noun","senses":[{"en":"a difficulty or problem that delays or prevents something, or makes a situation worse","cn":"挫折；阻碍","ex":{"en":"The team suffered a major setback when their best player was injured.","cn":"最优秀的队员受了伤，使得这支队伍的实力大打折扣。"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"挫折;障碍","en":"A setback is an event that delays your progress or reverses some of the progress that you have made.","ex":{"en":"The move represents a setback for the Middle East peace process","cn":"这个行动意味着中东和平进程受挫。"}}]},"media":{"uk":"media/uk/setback__gb_1.mp3","us":"media/us/setback__us_1.mp3"},"examples":[{"en":"The team suffered a major setback when their best player was injured.","cn":"最优秀的队员受了伤，使得这支队伍的实力大打折扣。"},{"en":"The breakdown in talks represents a temporary setback in the peace process.","cn":"谈判破裂意味着和平进程暂时受阻。"}]},"selfish":{"media":{"uk":"media/uk/selfish__gb_1.mp3","us":"media/us/selfish__us_1.mp3"},"oxford":{"phon":"ˈselfɪʃ","pos":"adjective","senses":[{"en":"caring only about yourself rather than about other people","cn":"自私的","ex":{"en":"selfish behaviour","cn":"自私的行为"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"自私的;自利的","en":"If you say that someone is selfish, you mean that he or she cares only about himself or herself, and not about other people.","ex":{"en":"I think I've been very selfish. I've been mainly concerned with myself.","cn":"我觉得我一直非常自私。总是只关心自己。"}}]},"examples":[{"en":"She looked forward, a little selfishly, to a weekend away from her family.","cn":"她有点自私，就盼着能够离家在外边度个周末。"},{"en":"It was selfish of him to leave all the work to you.","cn":"他把所有的工作都推给你，真是自私。"}]},"self":{"media":{"uk":"media/uk/self__gb_1.mp3","us":"media/us/self__us_1.mp3"},"oxford":{"phon":"self","pos":"noun","senses":[{"en":"the type of person you are, especially the way you normally behave, look or feel","cn":"（自己的）通常的行为方式，本来面目，惯常心态","g":"[countable, usually singular]","ex":{"en":"You'll soon be feeling your old self again (= feeling well or happy again).","cn":"你很快就会恢复原样的。"}},{"en":"a person’s personality or character that makes them different from other people","cn":"个性；自我","g":"[uncountable]","lab":"formal","ex":{"en":"Many people living in institutions have lost their sense of self (= the feeling that they are individual people).","cn":"许多生活在福利院里的人已经失去了个性意识。"}},{"en":"your own advantage or pleasure rather than that of other people","cn":"个人利益；一己的享乐；私心","g":"[uncountable]","lab":"formal","ex":{"en":"She didn't do it for any reason of self.","cn":"她那样做绝不是出于私心。"}},{"en":"used to refer to a person","cn":"（指一个人）自己，本人","g":"[countable]","ex":{"en":"You didn't hurt your little self, did you?","cn":"小家伙，你没伤着自己吧？"}},{"en":"of, to or by yourself or itself","cn":"自身的；对自身；由自身","ex":{"en":"self-control","cn":"自我控制"},"pos":"combining form"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"自身;本性;本我","en":"Your self is your basic personality or nature, especially considered in terms of what you are really like as a person.","ex":{"en":"You're looking more like your usual self","cn":"你现在看上去较像你平时的样子了。"}},{"pos":"N-COUNT 可数名词","cn":"个性;自我","en":"A person's self is the essential part of their nature which makes them different from everyone and everything else.","ex":{"en":"I want to explore and get in touch with my inner self","cn":"我想认真探寻、了解内心的自我。"}}]},"examples":[{"en":"Only with a few people could she be her real self (= show what she was really like rather than what she pretended to be).","cn":"只有和某几个人在一起时，她才能表现出真实的自我。"},{"en":"Many people living in institutions have lost their sense of self (= the feeling that they are individual people).","cn":"许多生活在福利院里的人已经失去了个性意识。"}]},"secrecy":{"media":{"uk":"media/uk/secrecy__gb_1.mp3","us":"media/us/secrecy__us_1.mp3"},"oxford":{"phon":"ˈsiːkrəsi","pos":"noun","senses":[{"en":"the fact of making sure that nothing is known about something; the state of being secret","cn":"保密；秘密","ex":{"en":"the need for absolute secrecy in this matter","cn":"在这件事情上绝对保密的必要性"}}]},"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"保密;秘密状态","en":"Secrecy is the act of keeping something secret, or the state of being kept secret.","ex":{"en":"The British government has thrown a blanket of secrecy over the details","cn":"英国政府对细节讳莫如深。"}}]},"examples":[{"en":"Everyone involved was sworn to secrecy.","cn":"所有相关人员均被要求宣誓保密。"},{"en":"the need for absolute secrecy in this matter","cn":"在这件事情上绝对保密的必要性"}]},"self-confidence":{"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"自信","en":"If you have self-confidence, you behave confidently because you feel sure of your abilities or value.","ex":{"en":"With the end of my love affair, I lost all the self-confidence I once had","cn":"恋爱告吹后，我一时间自信全无。"}}]},"media":{"uk":"media/uk/self_confidence_1_gb_1.mp3","us":"media/us/self_confidence_1_us_1.mp3"},"examples":[{"en":"He has no self-confidence.","cn":"他毫无自信。"}],"oxford":{"phon":"ˌself ˈkɒnfɪdəns","pos":"noun","senses":[{"en":"confidence in yourself and your abilities","cn":"自信的","ex":{"en":"He constantly tried to undermine her self-confidence.","cn":"他总想打击她的自信。"}}]}},"sediment":{"media":{"uk":"media/uk/sediment__gb_1.mp3","us":"media/us/sediment__us_1.mp3"},"oxford":{"phon":"ˈsedɪmənt","pos":"noun","senses":[{"en":"the solid material that settles at the bottom of a liquid","cn":"沉淀物","ex":{"en":"If milk is clean, there should be no sediment in the bottom of the bottle.","cn":"如果牛奶是干净的，瓶底应该没有沉淀物。"}},{"en":"sand, stones, mud, etc. carried by water or wind and left, for example, on the bottom of a lake, river, etc.","cn":"沉积物","lab":"geology"}]},"collins":{"senses":[{"pos":"N-VAR 可变名词","cn":"沉渣;沉淀物","en":"Sediment is solid material that settles at the bottom of a liquid, especially earth and pieces of rock that have been carried along and then left somewhere by water, ice, or wind.","ex":{"en":"Many organisms that die in the sea are soon buried by sediment.","cn":"海洋里死亡的许多生物会很快被沉淀物掩埋。"}}]},"examples":[{"en":"a thick layer of sediment","cn":"一层厚厚的沉积物"}]},"senior":{"media":{"uk":"media/uk/senior__gb_1.mp3","us":"media/us/senior__us_1.mp3"},"oxford":{"phon":"ˈsiːniə(r)","pos":"adjective","senses":[{"en":"high in rank or status; higher in rank or status than others","cn":"级别（或地位）高的","lab":"British English","sc":"of high rank","ex":{"en":"a senior official/officer/manager/executive","cn":"高级官员／军官／经理／主管"}},{"en":"for adults or people at a more advanced level","cn":"成人的；高级水平的","g":"[only before noun]","sc":"in sport","ex":{"en":"to take part in senior competitions","cn":"参加成人比赛"}},{"en":"for senior citizens (= older people, especially those who have retired from work)","cn":"（尤指已退休）年纪大的，老年的","g":"[only before noun]","sc":"for older people","ex":{"en":"Get one third off rail fares with a senior railcard.","cn":"持有老年火车通行优惠卡可减免三分之一车费。"}},{"en":"used after the name of a man who has the same name as his son, to make it clear who is being referred to","cn":"（父子同名时，加在父亲的名字后）老，大","sc":"father"},{"en":"for children over the age of 11 or 13","cn":"中等的，中学的（招收 11 或 13 岁以上学生）","g":"[only before noun]","lab":"British English","sc":"school/college"},{"en":"connected with the last year in high school or college","cn":"（高中或大学）毕业年级的","g":"[only before noun]","lab":"North American English","sc":"school/college","ex":{"en":"the senior prom","cn":"毕业年级舞会"}},{"en":"a person who is older than somebody else","cn":"较…年长的人","sc":"older person","ex":{"en":"She was ten years his senior.","cn":"她比他大十岁。"},"pos":"noun"},{"en":"an older person, especially somebody who has retired from work","cn":"（尤指领养老金的）老年人","lab":"especially North American English","sc":"older person","ex":{"en":"His company helps seniors maintain their independence","cn":"他的公司帮助老年人保持独立"},"pos":"noun"},{"en":"a person who is higher in rank or status","cn":"级别（或地位）较高者；上级；上司","sc":"higher rank","ex":{"en":"She felt unappreciated both by her colleagues and her seniors.","cn":"她觉得无论同事还是上司都不赏识她。"},"pos":"noun"},{"en":"adults or people who have reached an advanced level","cn":"资深成人运动员；高水平运动员","sc":"in sport","ex":{"en":"tennis coaching for juniors and seniors","cn":"初、高级网球训练"},"pos":"noun"},{"en":"a child at a senior school; an older child in a school","cn":"中学生；高年级学生","lab":"British English","sc":"in school/college","pos":"noun"},{"en":"(in the US and some other countries) a student in the last year at a high school or college","cn":"（美国等若干国家高中和大学的）毕业班学生","sc":"in school/college","ex":{"en":"high school seniors","cn":"高中毕业班学生"},"pos":"noun"}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"(在组织或专业领域中)级别高的，资深的","en":"The senior people in an organization or profession have the highest and most important jobs.","ex":{"en":"...senior officials in the Israeli government.","cn":"以色列政府的高级官员"}},{"pos":"ADJ 形容词","cn":"职位高于…的;资格比…老的;更资深的","en":"If someone is senior to you in an organization or profession, they have a higher and more important job than you or they are considered to be superior to you because they have worked there for longer and have more experience.","ex":{"en":"The position had to be filled by an officer senior to Haig","cn":"这个位置必须由一个职位高于黑格的官员来担任。"}},{"pos":"N-SING 单数名词","cn":"较年长的人;比…大…岁的人","en":"Senior is used when indicating how much older one person is than another. For example, if someone is ten years your senior, they are ten years older than you.","ex":{"en":"She became involved with a married man many years her senior.","cn":"她和一个比自己大很多岁的已婚男子好上了。"}},{"pos":"N-COUNT 可数名词","cn":"(中学或大学里的)高年级学生，毕业班学生","en":"Seniors are students in a high school, university, or college who are the oldest and who have reached an advanced level in their studies."},{"pos":"ADJ 形容词","cn":"(比赛)成人的，高水平的","en":"If you take part in a sport at senior level, you take part in competitions with adults and people who have reached a high degree of achievement in that sport.","ex":{"en":"This will be his fifth international championship and his third at senior level.","cn":"这将是他第五个世界冠军，第三个成人级别赛事的冠军。"}},{"pos":"N-COUNT 可数名词","cn":"(高尔夫、网球等体育运动中的)年长的运动员，资深运动员","en":"In sports such as golf and tennis, a senior is a professional player who is fairly old and who plays in special competitions against other older players."}]},"examples":[{"en":"Get one third off rail fares with a senior railcard.","cn":"持有老年火车通行优惠卡可减免三分之一车费。"},{"en":"( BrE ) Junior nurses usually work alongside more senior nurses.","cn":"初级护士通常和较高级的护士一起工作。"}]},"sentimental":{"media":{"uk":"media/uk/sentimental__gb_1.mp3","us":"media/us/sentimental__us_1.mp3"},"oxford":{"phon":"ˌsentɪˈmentl","pos":"adjective","senses":[{"en":"connected with your emotions, rather than reason","cn":"情感的（而非理性的）","ex":{"en":"He has a strong sentimental attachment to the place.","cn":"他对这个地方有着强烈的情感。"}},{"en":"producing emotions such as sympathy, romantic love, or being sad, which may be too strong or not appropriate; feeling these emotions too much","cn":"（失之过度或不恰当地）伤感的，充满柔情的；多愁善感的","lab":"often disapproving","ex":{"en":"a slushy, sentimental love story","cn":"庸俗缠绵的言情小说"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"感伤的;多情的;多愁善感的","en":"Someone or something that is sentimental feels or shows pity or love, sometimes to an extent that is considered exaggerated and foolish.","ex":{"en":"I'm trying not to be sentimental about the past","cn":"我努力不让自己表现得感怀过去。"}},{"pos":"ADJ 形容词","cn":"情感(上)的;(尤指)(出于)怀旧的","en":"Sentimental means relating to or involving feelings such as pity or love, especially for things in the past.","ex":{"en":"Our paintings and photographs are of sentimental value only","cn":"我们的画作和照片仅有纪念价值。"}}]},"examples":[{"en":"The ring wasn't worth very much but it had great sentimental value.","cn":"那枚戒指值不了几个钱，但却极有情感价值。"},{"en":"He's not the sort of man who gets sentimental about old friendships.","cn":"他不是那种为旧日的友情唏嘘感伤的人。"}]},"separately":{"oxford":{"phon":"ˈseprətli","pos":"adverb","senses":[{"en":"as a separate person or thing; not together","cn":"单独地；分别地","ex":{"en":"They were photographed separately and then as a group.","cn":"他们先单独照相，然后合影。"}}]},"collins":{"senses":[{"pos":"ADV 副词","cn":"单独地;分别地","en":"If people or things are dealt with separately or do something separately, they are dealt with or do something at different times or places, rather than together.","ex":{"en":"Cook each vegetable separately until just tender","cn":"每样蔬菜都单独烹调，煮到稍稍变软就好。"}}]},"media":{"uk":"media/uk/separately__gb_1.mp3","us":"media/us/separately__us_1.mp3"},"examples":[{"en":"They were photographed separately and then as a group.","cn":"他们先单独照相，然后合影。"},{"en":"Last year's figures are shown separately.","cn":"去年的数字分别列出。"}]},"separate":{"media":{"uk":"media/uk/separate__gb_1.mp3","us":"media/us/separate__us_1.mp3"},"oxford":{"phon":"ˈseprət","pos":"adjective","senses":[{"en":"forming a unit by itself; not joined to something else","cn":"单独的；独立的；分开的","ex":{"en":"They have begun to sleep in separate rooms.","cn":"他们开始分屋睡觉了。"}},{"en":"different; not connected","cn":"不同的；不相关的","g":"[usually before noun]","ex":{"en":"a separate incident/issue","cn":"单独的事件/问题"}},{"en":"to divide into different parts or groups; to divide things into different parts or groups","cn":"（使）分开，分离；分割；划分","g":"[intransitive, transitive]","ex":{"en":"Stir the sauce constantly so that it does not separate.","cn":"不停地搅动酱汁，免得出现分层。"},"pos":"verb"},{"en":"to move apart; to make people or things move apart","cn":"（使）分离，分散","g":"[intransitive, transitive]","ex":{"en":"South America and Africa separated 200 million years ago.","cn":"南美洲和非洲于 2 亿年前分离。"},"pos":"verb"},{"en":"to be between two people, areas, countries, etc. so that they are not touching or connected","cn":"隔开；阻隔","g":"[transitive]","ex":{"en":"A thousand kilometres separates the two cities.","cn":"两座城市相隔一千公里。"},"pos":"verb"},{"en":"to stop living together as a couple with your husband, wife or partner","cn":"分居","g":"[intransitive]","lab":"especially North American English","ex":{"en":"They separated last year.","cn":"他们于去年分居了。"},"pos":"verb"},{"en":"to make somebody/something different in some way from somebody/something else","cn":"区分；区别","g":"[transitive]","ex":{"en":"Politics is the only thing that separates us (= that we disagree about).","cn":"我们之间唯一的分歧是政治观点。"},"pos":"verb"}]},"collins":{"senses":[{"pos":"ADJ 形容词","cn":"分开的;单独的;独立的","en":"If one thing is separate from another, there is a barrier, space, or division between them, so that they are clearly two things.","ex":{"en":"Each villa has a separate sitting-room","cn":"每栋别墅都有一间独立的起居室。"}},{"pos":"ADJ 形容词","cn":"不同的;各别的","en":"If you refer to separate things, you mean several different things, rather than just one thing.","ex":{"en":"Use separate chopping boards for raw meats, cooked meats, vegetables and salads","cn":"切生肉、熟肉、蔬菜和拌色拉的青菜时要使用不同的切菜板。"}},{"pos":"V-RECIP-ERG","cn":"(使)分开;(使)分离;分割;划分","en":"If you separate people or things that are together, or if they separate, they move apart.","ex":{"en":"Police moved in to separate the two groups","cn":"警方介入进来，将两拨人分开。"}},{"pos":"V-RECIP-ERG","cn":"(使)分离;(使)分裂;(使)分开","en":"If you separate people or things that have been connected, or if one separates from another, the connection between them is ended.","ex":{"en":"They want to separate teaching from research","cn":"他们想把教学和研究分开。"}},{"pos":"V-RECIP 相互动词","cn":"分居","en":"If a couple who are married or living together separate, they decide to live apart.","ex":{"en":"Her parents separated when she was very young","cn":"她很小的时候父母就分居了。"}},{"pos":"VERB 动词","cn":"隔开;阻隔;使分开","en":"An object, obstacle, distance, or period of time which separates two people, groups, or things exists between them.","ex":{"en":"...the white-railed fence that separated the yard from the paddock","cn":"将院子和小围场隔开的白色围栏"}},{"pos":"VERB 动词","cn":"分辨;区分;区别","en":"If you separate one idea or fact from another, you clearly see or show the difference between them.","ex":{"en":"It is difficult to separate legend from truth","cn":"很难将传说和事实区别开来。"}},{"pos":"VERB 动词","cn":"使得以区分;使获得区别","en":"A quality or factor that separates one thing from another is the reason why the two things are different from each other.","ex":{"en":"The single most important factor that separates ordinary photographs from good photographs is the lighting","cn":"区分普通照片和出色照片的一个至关重要的因素就是光线。"}},{"pos":"VERB 动词","cn":"(两个参赛队或竞争者比分)相隔，相差","en":"If a particular number of points separate two teams or competitors, one of them is winning or has won by that number of points.","ex":{"en":"In the end only three points separated the two teams.","cn":"最终两队只相差 3 分。"}},{"pos":"V-ERG 及物/不及物动词","cn":"分割;划分;拆散","en":"If you separate a group of people or things into smaller elements, or if a group separates, it is divided into smaller elements.","ex":{"en":"The police wanted to separate them into smaller groups","cn":"警察想把他们拆散成几小股。"}},{"pos":"N-PLURAL 复数名词","cn":"(非覆盖全身的)单件衣服","en":"Separates are clothes such as skirts, trousers, and shirts which cover just the top half or the bottom half of your body."},{"pos":"PHRASE 短语","cn":"分道扬镳;分手;分路而行","en":"When two or more people who have been together for some time go their separate ways, they go to different places or end their relationship.","ex":{"en":"Sue and her husband decided to go their separate ways.","cn":"苏和丈夫决定离婚。"}},{"pos":"","cn":"","en":"to separate the wheat from the chaff→see: ;"},{"pos":"","cn":"","en":"相关词组：separate out"}]},"examples":[{"en":"Make a list of points and separate them into ‘desirable’ and ‘essential’.","cn":"列出各点，把它们分成“渴望拥有的”和“绝对必要的”两类。"},{"en":"Japan's long-standing sense of separateness and uniqueness","cn":"日本那种由来已久的自成一体、孑然独立的意识"}]},"sec":{"oxford":{"phon":"sek","pos":"noun","senses":[{"en":"a very short time; a second","cn":"片刻；霎时","ex":{"en":"Stay there. I'll be back in a sec.","cn":"待着别走。我马上回来。"}},{"en":"second(s)","cn":"秒","pos":"abbreviation"},{"en":"Securities and Exchange Commission","cn":"美国证券交易委员会","pos":""},{"en":"secretary","cn":"秘书；助理；部长；大臣","pos":"abbreviation"}]},"collins":{"senses":[{"pos":"","cn":"一会儿;片刻","en":"If you ask someone to wait a sec, you are asking them to wait for a very short time.","ex":{"en":"Can you just hang on a sec?","cn":"您能稍等一会儿吗？"}}]},"media":{"uk":"media/uk/sec__gb_1.mp3","us":"media/us/sec__us_1.mp3"},"examples":[{"en":"Stay there. I'll be back in a sec.","cn":"待着别走。我马上回来。"},{"en":"Hang on (= wait) a sec.","cn":"稍等一下。"}]},"severely":{"oxford":{"phon":"sɪˈvɪəli","pos":"adverb","senses":[{"en":"very badly or seriously","cn":"极为恶劣地；十分严重地","ex":{"en":"severely injured","cn":"重伤"}},{"en":"in an extreme or strict way","cn":"严厉地；严重地","ex":{"en":"Anyone breaking the law will be severely punished.","cn":"任何违反法律的人都将受到严惩。"}},{"en":"in a way that is not kind and does not show sympathy or approval","cn":"严厉地；严肃地；苛刻地","ex":{"en":"He looked severely at me.","cn":"他严厉地看着我。"}},{"en":"in a way that is extremely difficult and requires a lot of skill or ability","cn":"艰难地；艰巨地","ex":{"en":"Her patience was being severely tested.","cn":"她的耐心受到了巨大的挑战。"}},{"en":"in an extremely plain style that lacks any decoration","cn":"过于简朴地","lab":"disapproving","ex":{"en":"Her hair was tied severely in a bun.","cn":"她的头发简单地盘成了一个发髻。"}}]},"media":{"uk":"media/uk/severely__gb_1.mp3","us":"media/us/severely__us_1.mp3"},"examples":[{"en":"Her hair was tied severely in a bun.","cn":"她的头发简单地盘成了一个发髻。"},{"en":"Anyone breaking the law will be severely punished.","cn":"违法者将受到严惩。"}]},"seeds":{"oxford":{"phon":"siːd","pos":"noun","senses":[{"en":"the small hard part produced by a plant, from which a new plant can grow","cn":"种子；籽"},{"en":"the beginning of a feeling or a development which continues to grow","cn":"起源；起因；萌芽；开端"}]}},"seal":{"media":{"uk":"media/uk/seal__gb_1.mp3","us":"media/us/seal__us_1.mp3","img":["media/ldoce/img/seal.jpg"]},"oxford":{"phon":"siːl","pos":"verb","senses":[{"en":"to close an envelope, etc. by sticking the edges of the opening together","cn":"封上（信封）","sc":"close envelope","ex":{"en":"Make sure you've signed the cheque before sealing the envelope.","cn":"一定要在支票上签了名再封信封。"}},{"en":"to close a container tightly or fill a small opening, etc., especially so that air, liquid, etc. cannot get in or out","cn":"密封（容器）","g":"[often passive]","sc":"close container","ex":{"en":"He sealed the bag tightly with sticky tape.","cn":"他用胶带把袋子密封起来。"}},{"en":"to make something definite, so that it cannot be changed or argued about","cn":"确定；明确定下来；使成定局","sc":"make something definite","ex":{"en":"to seal a contract","cn":"订立合同"}},{"en":"to cover the surface of something with a substance in order to protect it","cn":"封盖…的表面","g":"[often passive]","sc":"cover surface","ex":{"en":"The floors had been stripped and sealed with varnish.","cn":"地板已清理干净，涂上了清漆。"}},{"en":"to prevent people from passing through a place","cn":"关闭；封闭；封锁","sc":"close borders/exits","ex":{"en":"Troops have sealed the borders between the countries.","cn":"军队已关闭了两国边界。"}},{"en":"an official design or mark, stamped on a document to show that it is real and carries the authority of a particular person or organization","cn":"印章；图章；玺；印记","g":"[countable]","sc":"official mark","ex":{"en":"The letter bore the president's seal.","cn":"信上盖有总统的印章。"},"pos":"noun"},{"en":"a thing that makes something definite","cn":"表示确认的事物；保证；信物","g":"[singular]","sc":"making something definite","ex":{"en":"The project has been given the government's seal of approval (= official approval).","cn":"项目已由政府正式批准。"},"pos":"noun"},{"en":"a substance, piece of material, etc. used to fill a small opening so that air, liquid, etc. cannot get in or out","cn":"密封垫（或带等）","g":"[countable]","sc":"on containers","ex":{"en":"a jar with a rubber seal in the lid","cn":"盖子上有橡胶密封垫的广口瓶"},"pos":"noun"},{"en":"a piece of wax (= a soft substance produced by bees), soft metal or paper that is placed across the opening of something such as a letter or box and which has to be broken before the letter or box can be opened","cn":"封蜡；封铅；封条；火漆","g":"[countable]","sc":"on letters/boxes","ex":{"en":"He broke the wax seal and unrolled the paper.","cn":"他揭去封蜡，把纸卷展开。"},"pos":"noun"},{"en":"a piece of metal, a ring, etc. with a design on it, used for stamping a wax or metal seal","cn":"封蜡模（印）；封铅模（印）","g":"[countable]","sc":"on letters/boxes","pos":"noun"},{"en":"a sea animal that eats fish and lives around coasts. There are many types of seal, some of which are hunted for their fur.","cn":"海豹","g":"[countable]","sc":"sea animal","ex":{"en":"a colony of seals","cn":"一群海豹"},"pos":"noun"}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"封住，粘住(信封)","en":"When you seal an envelope, you close it by folding part of it over and sticking it down, so that it cannot be opened without being torn.","ex":{"en":"He sealed the envelope and put on a stamp","cn":"他封住信封并贴上一张邮票。"}},{"pos":"VERB 动词","cn":"封住(容器、开口);把…密封(进容器)","en":"If you seal a container or an opening, you cover it with something in order to prevent air, liquid, or other material getting in or out. If you seal something in a container, you put it inside and then close the container tightly.","ex":{"en":"She merely filled the containers, sealed them with a cork, and pasted on labels","cn":"她只是装满容器，用软木塞封住，然后贴上标签。"}},{"pos":"N-COUNT 可数名词","cn":"密封处","en":"The seal on a container or opening is the part where it has been sealed.","ex":{"en":"When assembling the pie, wet the edges where the two crusts join, to form a seal.","cn":"在包馅饼时，先把两片馅饼皮边沿接头部分弄湿，再将其捏合。"}},{"pos":"N-COUNT 可数名词","cn":"密封装置;密封物","en":"A seal is a device or a piece of material, for example in a machine, which closes an opening tightly so that air, liquid, or other substances cannot get in or out.","ex":{"en":"Check seals on fridges and freezers regularly.","cn":"定期检查冰箱和冷冻柜的密封装置。"}},{"pos":"N-COUNT 可数名词","cn":"封条;封蜡;封铅;火漆","en":"A seal is something such as a piece of sticky paper or wax that is fixed to a container or door and must be broken before the container or door can be opened.","ex":{"en":"The seal on the box broke when it fell from its hiding-place","cn":"盒子从隐藏处掉落时，封口裂开了。"}},{"pos":"N-COUNT 可数名词","cn":"印章;图章;玺;印记","en":"A seal is a special mark or design, for example on a document, representing someone or something. It may be used to show that something is genuine or officially approved.","ex":{"en":"...a supply of note paper bearing the Presidential seal","cn":"一批盖有总统印章的便条纸"}},{"pos":"VERB 动词","cn":"封闭;封锁","en":"If someone in authority seals an area, they stop people entering or passing through it, for example by placing barriers in the way.","ex":{"en":"The soldiers were deployed to help paramilitary police seal the border","cn":"部署士兵协助准军事警察封锁边境。"}},{"pos":"VERB 动词","cn":"使成定局;确定","en":"To seal something means to make it definite or confirm how it is going to be.","ex":{"en":"McLaren are close to sealing a deal with Renault","cn":"麦克拉伦即将与雷诺达成一笔交易。"}},{"pos":"PHRASE 短语","cn":"使确定下来;使成定局","en":"If something sets or puts the seal on something, it makes it definite or confirms how it is going to be.","ex":{"en":"Such a visit may set the seal on a new relationship between the two governments","cn":"这样的一次访问可能会使两国政府间确立新关系。"}},{"pos":"PHRASE 短语","cn":"盖上印信的;不能拆开看的;保密的","en":"If a document is under seal, it is in a sealed envelope and cannot be looked at, for example because it is private.","ex":{"en":"Because the transcript is still under seal, I am precluded by law from discussing the evidence.","cn":"副本仍未公开，按照法律规定我不能讨论这项证据。"}},{"pos":"","cn":"","en":"seal of approval→see: ; to seal someone's fate→see: ; my lips are sealed→see: ; signed and sealed→see: ;"},{"pos":"","cn":"","en":"相关词组：seal in seal off seal up"},{"pos":"N-COUNT 可数名词","cn":"海豹","en":"A seal is a large animal with a rounded body and flat legs called flippers. Seals eat fish and live in and near the sea, usually in cold parts of the world."}]},"examples":[{"en":"I looked upon the gift as a seal on our friendship.","cn":"我把你的礼物看作我们之间友谊的见证。"},{"en":"Only drink bottled water and check the seal isn't broken.","cn":"只喝瓶装水，并且要看封口开了没有。"}]},"send":{"media":{"uk":"media/uk/send__gb_1.mp3","us":"media/us/send__us_1.mp3"},"oxford":{"phon":"send","pos":"verb","senses":[{"en":"to make something go or be taken to a place, especially by post, email, radio, etc.","cn":"邮寄；发送","lab":"British English","sc":"by mail/radio","ex":{"en":"She sent a letter of support.","cn":"她寄来一封表示支持的信。"}},{"en":"to tell somebody something by sending them a message","cn":"传达；转致；告知","lab":"figurative","sc":"message","ex":{"en":"My parents send their love.","cn":"我父母问您好。"}},{"en":"to tell somebody to go somewhere or to do something; to arrange for somebody to go somewhere","cn":"派遣；打发；安排去","sc":"somebody somewhere","ex":{"en":"Ed couldn't make it so they sent me instead.","cn":"埃德去不了，所以他们就派我去了。"}},{"en":"to make something/somebody move quickly or suddenly","cn":"使快速（或猛然）移动","sc":"make something move quickly","ex":{"en":"Every step he took sent the pain shooting up his leg.","cn":"他每走一步，疼痛就顺腿蹿上来。"}},{"en":"to make somebody behave or react in a particular way","cn":"使作出（某种反应）；使表现出（某种行为）","sc":"make somebody react","ex":{"en":"Her music always sends me to sleep.","cn":"她的音乐总使我进入梦乡。"}}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"寄;发送;送出","en":"When you send someone something, you arrange for it to be taken and delivered to them, for example by post.","ex":{"en":"Myra Cunningham sent me a note thanking me for dinner","cn":"迈拉·坎宁安给我寄了张便笺感谢我招待的晚餐。"}},{"pos":"VERB 动词","cn":"派遣;打发;叫…去…","en":"If you send someone somewhere, you tell them to go there.","ex":{"en":"Inspector Banbury came up to see her, but she sent him away","cn":"班伯里巡官过来看她，却被她打发走了。"}},{"pos":"VERB 动词","cn":"把…送进(学校或监狱);安排…去","en":"If you send someone to an institution such as a school or a prison, you arrange for them to stay there for a period of time.","ex":{"en":"It's his parents' choice to send him to a boarding school, rather than a convenient day school","cn":"把他送到寄宿学校而非一家就近的走读学校是他父母的决定。"}},{"pos":"VERB 动词","cn":"(通过无线电波或电流)发射，发送,传送(信号)","en":"To send a signal means to cause it to go to a place by means of radio waves or electricity.","ex":{"en":"The transmitters will send a signal automatically to a local base station","cn":"发射台会自动将信号发射到地方基站。"}},{"pos":"VERB 动词","cn":"使(向某方向)移动","en":"If something sends things or people in a particular direction, it causes them to move in that direction.","ex":{"en":"The explosion sent shrapnel flying through the sides of cars on the crowded highway","cn":"爆炸后飞溅出的炸弹碎片洞穿了拥堵在公路上的车辆车身。"}},{"pos":"VERB 动词","cn":"使进入(某种状态)","en":"To send someone or something into a particular state means to cause them to go into or be in that state.","ex":{"en":"My attempt to fix it sent Lawrence into fits of laughter.","cn":"我试着修理它，却让劳伦斯乐得前仰后合。"}},{"pos":"","cn":"","en":"to send someone to Coventry→see: ; to send someone packing→see: ;"},{"pos":"","cn":"","en":"相关词组：send away for send down send for send in send off send off for send on send out send out for send up"}]},"examples":[{"en":"The CD player was faulty so we sent it back to the manufacturers.","cn":"那台激光唱片机有毛病，因此我们把它送回了厂家。"},{"en":"All the publicity nearly sent him crazy.","cn":"成天生活在公众的注意之下让他差一点发疯了。"}]},"search":{"media":{"uk":"media/uk/search__gb_1.mp3","us":"media/us/search__us_1.mp3"},"oxford":{"phon":"sɜːtʃ","pos":"noun","senses":[{"en":"an attempt to find somebody/something, especially by looking carefully for them/it","cn":"搜索；搜寻；搜查；查找","ex":{"en":"a long search for the murder weapon","cn":"长时间搜寻杀人凶器"}},{"en":"an act or the activity of looking for information on a computer or on the internet","cn":"搜索；检索","ex":{"en":"I've just done a search on the internet and came up with this website.","cn":"我刚在网上搜了一下，找到了这个网站。"}},{"en":"to look carefully for something/somebody; to examine a particular place when looking for something/somebody","cn":"搜索；搜寻；搜查；查找","g":"[intransitive, transitive]","ex":{"en":"She searched in vain for her passport.","cn":"她翻找自己的护照，但没找着。"},"pos":"verb"},{"en":"to look for information on a computer or on the internet","cn":"（在电脑或网上）搜索，检索","g":"[intransitive, transitive]","ex":{"en":"You can search for any word or phrase in the text.","cn":"文本中的任何词或短语你都可以检索。"},"pos":"verb"},{"en":"to examine somebody’s clothes, their pockets, etc. in order to find something that they may be hiding","cn":"搜查；搜身","g":"[transitive]","ex":{"en":"Visitors are regularly searched as they enter the building.","cn":"参观者进入大楼时要接受例行的搜身检查。"},"pos":"verb"},{"en":"to think carefully about something, especially in order to find the answer to a problem","cn":"思索，细想（问题答案等）","g":"[intransitive]","ex":{"en":"He searched desperately for something to say.","cn":"他搜肠刮肚，想找点话说。"},"pos":"verb"}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"搜寻;搜索;搜查;寻求","en":"If you search for something or someone, you look carefully for them.","ex":{"en":"The Turkish security forces have started searching for the missing men","cn":"土耳其安全部队已经开始搜寻失踪人员。"}},{"pos":"VERB 动词","cn":"在…中搜寻(或搜索);搜查(某地)","en":"If you search a place, you look carefully for something or someone there.","ex":{"en":"Armed troops searched the hospital yesterday","cn":"武装部队昨天搜查了该医院。"}},{"pos":"N-COUNT 可数名词","cn":"搜寻;寻求","en":"A search is an attempt to find something or someone by looking for them carefully.","ex":{"en":"There was no chance of him being found alive and the search was abandoned","cn":"他没有生还的可能，因此人们放弃了搜寻。"}},{"pos":"VERB 动词","cn":"搜查;对…搜身","en":"If a police officer or someone else in authority searches you, they look carefully to see whether you have something hidden on you.","ex":{"en":"The man took her suitcase from her and then searched her","cn":"那名男子拿过她手中的提箱，然后对她搜身。"}},{"pos":"VERB 动词","cn":"(在电脑上)搜索，检索","en":"If you search for information on a computer, you give the computer an instruction to find that information.","ex":{"en":"You can use a directory service to search for people on the Internet.","cn":"你可以利用因特网的目录服务搜索人名。"}},{"pos":"PHRASE 短语","cn":"寻找;寻求","en":"If you go in search of something or someone, you try to find them.","ex":{"en":"Miserable, and unexpectedly lonely, she went in search of Jean-Paul","cn":"内心痛苦、突感寂寞的她去寻找琼－保罗。"}},{"pos":"CONVENTION 惯用语","cn":"(用于强调)我怎么知道","en":"You say 'search me' when someone asks you a question and you want to emphasize that you do not know the answer.","ex":{"en":"'So why did he get interested all of a sudden?' — 'Search me.'","cn":"“那他为什么突然感兴趣了？”——“我怎么知道。”"}},{"pos":"","cn":"","en":"相关词组：search out"}]},"examples":[{"en":"The youths were arrested and searched for anything that would incriminate them.","cn":"警察逮捕了那些年轻人，并进行搜身，看能不能找到可以认定他们有罪的物证。"},{"en":"His house had clearly been searched and the book was missing.","cn":"显然有人来搜过他的房子，那本书不见了。"}]},"seafood":{"media":{"uk":"media/uk/seafood__gb_1.mp3","us":"media/us/seafood__us_1.mp3"},"oxford":{"phon":"ˈsiːfuːd","pos":"noun","senses":[{"en":"fish and sea creatures that can be eaten, especially shellfish","cn":"海鲜，海味（尤指甲壳类）","ex":{"en":"a seafood restaurant","cn":"海鲜馆"}}]},"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"海产食品;海味","en":"Seafood is shellfish such as lobsters, mussels, and crabs, and sometimes other sea creatures that you can eat.","ex":{"en":"...a seafood restaurant.","cn":"海鲜餐馆"}}]},"examples":[{"en":"a seafood cocktail","cn":"海鲜冷盘"},{"en":"a seafood restaurant","cn":"海鲜馆"}]},"sell":{"media":{"uk":"media/uk/sell__gb_1.mp3","us":"media/us/sell__us_1.mp3"},"oxford":{"phon":"sel","pos":"verb","senses":[{"en":"to give something to somebody in exchange for money","cn":"卖出；出让；转让","g":"[transitive, intransitive]","sc":"exchange for money","ex":{"en":"I recently sold my bike.","cn":"最近我把自行车卖了。"}},{"en":"to offer something for people to buy","cn":"出售；售卖","g":"[transitive]","sc":"offer for sale","ex":{"en":"Most supermarkets sell a range of organic products.","cn":"多数超级市场都经销各种有机产品。"}},{"en":"to be bought by people in the way or in the numbers mentioned; to be offered at the price mentioned","cn":"销售得…；卖出…；售价是…","g":"[transitive, intransitive]","sc":"be bought","ex":{"en":"The book sold well and was reprinted many times.","cn":"这本书销路不错，重印了好多次。"}},{"en":"to make people want to buy something","cn":"促销；推销","g":"[intransitive, transitive]","sc":"persuade","ex":{"en":"You may not like it but advertising sells.","cn":"你也许不喜欢广告，但它能促销。"}},{"en":"to persuade somebody that something is a good idea, service, product, etc.; to persuade somebody that you are the right person for a job, position, etc.","cn":"推荐；推销；自荐；自我推销","g":"[transitive]","sc":"persuade","ex":{"en":"Now we have to try and sell the idea to management.","cn":"现在，我们必须设法说服管理层采纳这个意见。"}},{"en":"to accept money or a reward from somebody for doing something that is against your principles","cn":"出卖自己；卖身","g":"[transitive]","lab":"disapproving","sc":"take money/reward"},{"en":"something that is difficult/easy to persuade people to buy or accept","cn":"难卖（或好卖等）的商品；令人难以（或容易等）接受的事物","ex":{"en":"This policy is going to be a tough sell to the public.","cn":"这一政策将很难使公众接受。"},"pos":"noun"},{"en":"something that is not as good as it seemed to be","cn":"让人失望的东西","lab":"British English","ex":{"en":"The band only played for about half an hour—it was a real sell.","cn":"乐队仅仅演奏了大约半个小时，真让人失望。"},"pos":"noun"}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"卖;出让;转让","en":"If you sell something that you own, you let someone have it in return for money.","ex":{"en":"I sold everything I owned except for my car and my books","cn":"我把我所有的东西都卖掉了，只剩下汽车和书。"}},{"pos":"VERB 动词","cn":"(商店)经售，出售","en":"If a shop sells a particular thing, it is available for people to buy there.","ex":{"en":"It sells everything from hair ribbons to oriental rugs","cn":"这里出售各种商品，从发带到东方小地毯应有尽有。"}},{"pos":"VERB 动词","cn":"以…的价格出售;售价是…","en":"If something sells for a particular price, that price is paid for it.","ex":{"en":"Unmodernised property can sell for up to 40 per cent of its modernised market value.","cn":"没有装备现代化设施的房地产能够卖到它配置了现代化设施情况下的市价的 40%。"}},{"pos":"VERB 动词","cn":"有销路;大量卖出","en":"If something sells, it is bought by the public, usually in fairly large quantities.","ex":{"en":"Even if this album doesn't sell and the critics don't like it, we wouldn't ever change","cn":"即使这张专辑得不到市场和评论家的青睐，我们也不会作出任何改变。"}},{"pos":"VERB 动词","cn":"促进…的销路;推销","en":"Something that sells a product makes people want to buy the product.","ex":{"en":"It is only the sensational that sells news magazines.","cn":"只有轰动性的事件才能促进新闻杂志的销售。"}},{"pos":"VERB 动词","cn":"使接受;使采纳","en":"If you sell someone an idea or proposal, or sell someone on an idea, you convince them that it is a good one.","ex":{"en":"She tried to sell me the idea of buying my own paper shredder","cn":"她努力说服我买一台自己的碎纸机。"}},{"pos":"PHRASE 短语","cn":"出卖肉体;卖淫","en":"If someone sells their body, they have sex for money.","ex":{"en":"85 per cent said they would rather not sell their bodies for a living.","cn":"85%的人说如果存在其他选择，他们不会出卖肉体谋生。"}},{"pos":"PHRASE 短语","cn":"(为获得个人利益或好处而)出卖，背叛","en":"If someone sells you down the river, they betray you for some personal profit or advantage.","ex":{"en":"He has been sold down the river by the people who were supposed to protect him.","cn":"他被那些本应该保护他的人出卖了。"}},{"pos":"PHRASE 短语","cn":"低估;轻视;怠慢","en":"If you sell someone short, you do not point out their good qualities as much as you should or do as much for them as you should.","ex":{"en":"They need to improve their image — they are selling themselves short","cn":"他们需要提升自己的形象——他们是在自贬身价。"}},{"pos":"PHRASE 短语","cn":"出卖灵魂(或良心)","en":"If you talk about someone selling their soul in order to get something, you are criticizing them for abandoning their principles.","ex":{"en":"...a man who would sell his soul for political viability.","cn":"为了升官晋爵甘愿出卖良心的人"}},{"pos":"","cn":"","en":"to sell like hot cakes→see: ;"},{"pos":"","cn":"","en":"相关词组：sell off sell on sell out sell up"}]},"examples":[{"en":"He's a talented screenwriter who has sold out to TV soap operas.","cn":"他是个有才华的电影编剧，却改行写起电视肥皂剧来了。"},{"en":"I sold my car to James for £800.","cn":"我把我的汽车转让给了詹姆斯，获得 800 英镑。"}]},"sexes":{"oxford":{"phon":"seks","pos":"noun","senses":[{"en":"the state of being male or female","cn":"性别；性"},{"en":"either of the two groups that people, animals and plants are divided into according to their function of producing young","cn":"男性；女性；雄性；雌性"}]}},"serve":{"media":{"uk":"media/uk/serve__gb_1.mp3","us":"media/us/serve__us_1.mp3"},"oxford":{"phon":"sɜːv","pos":"verb","senses":[{"en":"to give somebody food or drink, for example at a restaurant or during a meal","cn":"（给某人）提供；端上","g":"[transitive, intransitive]","sc":"food/drink","ex":{"en":"Breakfast is served between 7 and 10 a.m.","cn":"早餐供应时间从上午 7 点到 10 点。"}},{"en":"to be enough for somebody/something","cn":"足够；足以","g":"[transitive]","sc":"food/drink","ex":{"en":"This dish will serve four hungry people.","cn":"这饭够四个饥饿的人吃。"}},{"en":"to help a customer or sell them something in a shop","cn":"接待；服务","g":"[transitive, intransitive]","lab":"especially British English","sc":"customers","ex":{"en":"Are you being served?","cn":"有人接待您吗？"}},{"en":"to be useful to somebody in achieving or satisfying something","cn":"对…有用；能满足…的需要","g":"[transitive]","sc":"be useful","ex":{"en":"These experiments serve no useful purpose.","cn":"这些实验没有任何实际意义。"}},{"en":"to provide an area or a group of people with a product or service","cn":"（向某地或某群体）供应，提供","g":"[transitive]","sc":"provide something","ex":{"en":"The centre will serve the whole community.","cn":"这个中心将为整个社区提供服务。"}},{"en":"to work or perform duties for a person, an organization, a country, etc.; to spend a period of time in a particular job","cn":"（为…）工作，服务，尽职责；任职（一段时间）","g":"[intransitive, transitive]","sc":"work","ex":{"en":"He served as a captain in the army.","cn":"他曾是一名陆军上尉。"}},{"en":"to be suitable for a particular use, especially when nothing else is available","cn":"可用作，可当…使（尤指别无选择时）","g":"[intransitive]","sc":"be suitable","ex":{"en":"The sofa will serve as a bed for a night or two.","cn":"沙发可以当床凑合一两夜。"}},{"en":"to have a particular effect or result","cn":"产生…的效果（或结果）","g":"[intransitive, transitive]","sc":"have particular result","ex":{"en":"The judge said the punishment would serve as a warning to others.","cn":"法官说这种惩罚将对其他人起到杀一儆百的作用。"}},{"en":"to spend a period of time in prison","cn":"服（刑）","g":"[transitive]","sc":"time in prison","ex":{"en":"prisoners serving life sentences","cn":"服无期徒刑的囚犯"}},{"en":"to give or send somebody an official document, especially one that orders them to appear in court","cn":"把…送达；向（某人）送交","g":"[transitive]","lab":"law","sc":"official document","ex":{"en":"to serve a writ/summons on somebody","cn":"把令状／传票送达某人"}},{"en":"to start playing by throwing the ball into the air and hitting it","cn":"发（球）","g":"[intransitive, transitive]","sc":"in sport","ex":{"en":"Who's serving?","cn":"谁发球？"}},{"en":"the action of serving the ball to your opponent","cn":"发球","ex":{"en":"He has not lost his serve (= lost a game in which it was his turn to serve) in three matches.","cn":"他在三场比赛中没有丢掉一个发球局（=输掉一场轮到他发球的比赛）。"},"pos":"noun"}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"为…服务;为…效力;为…效忠","en":"If you serve your country, an organization, or a person, you do useful work for them.","ex":{"en":"It is unfair to soldiers who have served their country well for many years","cn":"这对那些为国效忠多年的士兵们来说是不公平的。"}},{"pos":"VERB 动词","cn":"(尤指在部队)服役;(在政府部门)任职","en":"If you serve in a particular place or as a particular official, you perform official duties, especially in the armed forces, as a civil servant, or as a politician.","ex":{"en":"During the second world war he served with RAF Coastal Command","cn":"二战期间他在英国皇家空军海防总队服役。"}},{"pos":"VERB 动词","cn":"用作;可当…使用;充作","en":"If something serves as a particular thing or serves a particular purpose, it performs a particular function, which is often not its intended function.","ex":{"en":"She ushered me into the front room, which served as her office","cn":"她把我领进了她用作办公室的前厅。"}},{"pos":"VERB 动词","cn":"供应(某地或某人);为…提供服务","en":"If something serves people or an area, it provides them with something that they need.","ex":{"en":"This could mean the closure of thousands of small businesses which serve the community","cn":"这可能意味着成千上万家服务社会的小企业将要倒闭。"}},{"pos":"VERB 动词","cn":"对…有用;能满足…的需要;符合…的利益","en":"Something that serves someone's interests benefits them.","ex":{"en":"The economy should be organized to serve the interests of all the people","cn":"经济的组织运行应符合所有人的利益。"}},{"pos":"VERB 动词","cn":"(给…)提供，端上(食物);上(菜);开(饭)","en":"When you serve food and drink, you give people food and drink.","ex":{"en":"Serve it with French bread","cn":"把它和法式面包一起端上去。"}},{"pos":"VERB 动词","cn":"(食物的量)足够…吃","en":"Serve is used to indicate how much food a recipe produces. For example, a recipe that serves six provides enough food for six people.","ex":{"en":"Garnish with fresh herbs. Serves 4.","cn":"配以新鲜香草，4 人份。"}},{"pos":"VERB 动词","cn":"接待，服务，招待(顾客)","en":"Someone who serves customers in a shop or a bar helps them and provides them with what they want to buy.","ex":{"en":"They wouldn't serve me in any pubs 'cos I looked too young","cn":"这些酒吧都不让我进，因为我看上去太小了。"}},{"pos":"VERB 动词","cn":"送交(令状等);把…送达","en":"When the police or other officials serve someone with a legal order or serve an order on them, they give or send the legal order to them.","ex":{"en":"Immigration officers tried to serve her with a deportation order","cn":"移民局官员试图向她下达驱逐令。"}},{"pos":"VERB 动词","cn":"服(刑);当(学徒)","en":"If you serve something such as a prison sentence or an apprenticeship, you spend a period of time doing it.","ex":{"en":"...Leo, who is currently serving a life sentence for murder","cn":"因谋杀罪正在服无期徒刑的利奥"}},{"pos":"VERB 动词","cn":"(在网球、羽毛球等比赛中)发球","en":"When you serve in games such as tennis and badminton, you throw up the ball or shuttlecock and hit it to start play.","ex":{"en":"He served 17 double faults","cn":"他有 17 次双发失误。"}},{"pos":"N-COUNT 可数名词","cn":"(某些球类比赛中的)发球","en":"When you describe someone's serve, you are indicating how well or how fast they serve a ball or shuttlecock.","ex":{"en":"His powerful serve was too much for the defending champion.","cn":"他的大力发球让卫冕冠军难以招架。"}},{"pos":"PHRASE 短语","cn":"咎由自取;罪有应得;活该","en":"If you say it serves someone right when something unpleasant happens to them, you mean that it is their own fault and you have no sympathy for them.","ex":{"en":"Serves her right for being so stubborn.","cn":"她太固执了，活该。"}},{"pos":"","cn":"","en":"相关词组：serve out serve up"}]},"examples":[{"en":"He served under Edward Heath in the 1970s.","cn":"他曾于 20 世纪 70 年代在爱德华 · 希思手下任职。"},{"en":"The town is well served with buses and major road links.","cn":"这座城市乘坐公共汽车很方便，与干线公路的连接也很发达。"}]},"sexually":{"oxford":{"phon":"ˈsekʃəli","pos":"adverb","senses":[{"en":"in a way that is connected with the physical activity of sex","cn":"性行为的；性的","ex":{"en":"sexually abused children","cn":"遭受性虐待的儿童"}},{"en":"in a way that is connected with the process of producing young","cn":"生殖的；有性繁殖的","ex":{"en":"sexually reproducing organisms","cn":"有性生殖生物"}}]},"media":{"uk":"media/uk/sexually__gb_1.mp3","us":"media/us/sexually__us_1.mp3"},"examples":[{"en":"She finds him sexually attractive.","cn":"她觉得他富有性魅力。"},{"en":"Girls become sexually mature earlier than boys.","cn":"女孩比男孩性成熟早。"}]},"self-esteem":{"oxford":{"phon":"ˌself ɪˈstiːm","pos":"noun","senses":[{"en":"a feeling of being happy with your own character and abilities","cn":"自尊（心）","ex":{"en":"to have high/low self-esteem","cn":"自尊心强／弱"}}]},"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"自尊(心)","en":"Your self-esteem is how you feel about yourself. For example, if you have low self-esteem, you do not like yourself, you do not think that you are a valuable person, and therefore you do not behave confidently.","ex":{"en":"Poor self-esteem is at the centre of many of the difficulties we experience in our relationships.","cn":"缺乏自尊心是我们之间关系所遭遇的重重困难中的核心问题。"}}]},"media":{"uk":"media/uk/self_esteem_1_gb_1.mp3","us":"media/us/self_esteem_1_us_1.mp3"},"examples":[{"en":"You need to build your self-esteem.","cn":"你需要树立自尊心。"},{"en":"to have high/low self-esteem","cn":"自尊心强/弱"}]},"selector":{"oxford":{"phon":"sɪˈlektə(r)","pos":"noun","senses":[{"en":"a person who chooses the members of a particular sports team","cn":"（运动队队员的）选拔人","lab":"British English","ex":{"en":"The Welsh selectors have named the team for next week’s international.","cn":"威尔士选拔者已经指定了参加下周国际比赛的球队。"}},{"en":"a device in an engine, a machine, etc. that allows you to choose a particular function","cn":"选择器；转换器","ex":{"en":"a gear selector","cn":"变速器"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"(挑选运动队员或参赛运动员的)选拔委员，选拔人","en":"A selector is someone whose job is to choose which people will be in a particular sports team or will take part in a particular sports contest.","ex":{"en":"...the England cricket selectors.","cn":"英格兰板球队的选拔委员"}}]},"media":{"uk":"media/uk/selector__gb_1.mp3","us":"media/us/selector__us_1.mp3"}},"seldom":{"media":{"uk":"media/uk/seldom__gb_1.mp3","us":"media/us/seldom__us_1.mp3"},"oxford":{"phon":"ˈseldəm","pos":"adverb","senses":[{"en":"not often","cn":"不常；很少；难得","lab":"literary","ex":{"en":"He had seldom seen a child with so much talent.","cn":"有如此天赋的孩子他以往没见过几个。"}}]},"collins":{"senses":[{"pos":"ADV-BRD-NEG 广义否定结构副词","cn":"不常;很少;难得","en":"If something seldom happens, it happens only occasionally.","ex":{"en":"They seldom speak","cn":"他们很少发言。"}}]},"examples":[{"en":"He had seldom seen a child with so much talent.","cn":"有如此天赋的孩子他以往没见过几个。"},{"en":"( literary ) Seldom had he seen such beauty.","cn":"他以前很少见过这样的美景。"}]},"seventies":{"oxford":{"phon":"ˈsevnti","pos":"number","senses":[{"en":"70","cn":"七十"},{"en":"numbers, years or temperatures from 70 to 79","cn":"七十几；七十年代"}]}},"self-":{"oxford":{"phon":"self","pos":"combining form","senses":[{"en":"( in nouns and adjectives","cn":"构成名词和形容词 ) of, to or by yourself or itself 自身的；对自身；由自身"}]},"collins":{"senses":[{"pos":"COMB in ADJ and N与形容词，名词构成的词","cn":"(用于构词)表示“靠自身的”，“由自身的”，“对自身的”","en":"Self- is used to form words which indicate that you do something to yourself or by yourself.","ex":{"en":"He is a self-proclaimed racist.","cn":"他自称是种族主义者。"}},{"pos":"COMB in ADJ and N与形容词，名词构成的词","cn":"(用于构词)表示“自动的”，“自行的”","en":"Self- is used to form words which describe something such as a device that does something automatically by itself.","ex":{"en":"...a self-loading pistol.","cn":"自动上膛的手枪"}}]},"media":{"uk":"media/uk/self__1_gb_1.mp3","us":"media/us/self__1_us_1.mp3"},"examples":[{"en":"self-addressed","cn":"写有自己姓名地址的"},{"en":"self-control","cn":"自我控制"}]},"sensible":{"media":{"uk":"media/uk/sensible__gb_1.mp3","us":"media/us/sensible__us_1.mp3"},"oxford":{"phon":"ˈsensəbl","pos":"adjective","senses":[{"en":"able to make good judgements based on reason and experience rather than emotion; practical","cn":"明智的；理智的；合理的；切合实际的","ex":{"en":"She's a sensible sort of person.","cn":"她属于那种通情达理的人。"}},{"en":"useful rather than fashionable","cn":"朴素而实用的","ex":{"en":"sensible shoes","cn":"朴实而舒适的鞋"}},{"en":"aware of something","cn":"意识到；认识到","lab":"formal or literary","ex":{"en":"I am sensible of the fact that mathematics is not a popular subject.","cn":"我知道数学课不受欢迎。"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"(行为或决定)明智的，理智的，合理的","en":"Sensible actions or decisions are good because they are based on reasons rather than emotions.","ex":{"en":"It might be sensible to get a solicitor","cn":"也许应该请一个诉状律师。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"(人)明智的，理智的，通情达理的","en":"Sensible people behave in a sensible way.","ex":{"en":"She was a sensible girl and did not panic","cn":"她是一个理智的女孩，没有惊慌失措。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"(衣服、鞋子)耐用的，朴素而实用的","en":"Sensible shoes or clothes are practical and strong rather than fashionable and attractive.","ex":{"en":"Wear loose clothing and sensible footwear.","cn":"穿上宽松的衣服和舒服的鞋子。"}}]},"examples":[{"en":"He decided, very sensibly, not to drive when he was so tired.","cn":"他很累，所以决定不开车，这是很明智的。"},{"en":"It wasn’t very sensible to go out on your own so late at night.","cn":"这么晚一个人单独外出是不太明智的。"}]},"september":{"media":{"uk":"media/uk/september__gb_1.mp3","us":"media/us/september__us_1.mp3"},"oxford":{"phon":"sepˈtembə(r)","pos":"noun","senses":[{"en":"the 9th month of the year, between August and October","cn":"九月","lab":"British English","ex":{"en":"She was born in September.","cn":"她出生在九月。"}}]},"collins":{"senses":[{"pos":"N-VAR 可变名词","cn":"九月","en":"September is the ninth month of the year in the Western calendar.","ex":{"en":"Her son, Jerome, was born in September","cn":"她儿子杰尔姆生于 9 月。"}}]}},"selves":{"media":{"uk":"media/uk/selves__gb_1.mp3","us":"media/us/selves__us_1.mp3"},"collins":{"senses":[{"pos":"","cn":"(self的复数)","en":"Selves is the plural of self ."}]}},"segment":{"oxford":{"phon":"ˈseɡmənt","pos":"noun","senses":[{"en":"a part of something that is separate from the other parts or can be considered separately","cn":"部分；份；片；段","ex":{"en":"She cleaned a small segment of the painting.","cn":"她擦干净了这幅画的一小部分。"}},{"en":"one of the sections of an orange, a lemon, etc.","cn":"（柑橘、柠檬等的）瓣"},{"en":"a part of a circle separated from the rest by a single line","cn":"弓形；圆缺","lab":"geometry"},{"en":"the smallest speech sound that a word can be divided into","cn":"音段","lab":"phonetics"},{"en":"to divide something into different parts","cn":"分割；划分","ex":{"en":"Market researchers often segment the population on the basis of age and social class.","cn":"市场研究人员常常按年龄和社会阶层划分人口。"},"pos":"verb"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"部分;片段","en":"A segment of something is one part of it, considered separately from the rest.","ex":{"en":"...the poorer segments of society.","cn":"社会中的较贫穷阶层"}},{"pos":"N-COUNT 可数名词","cn":"(橘子、葡萄柚等水果的)瓣","en":"A segment of fruit such as an orange or grapefruit is one of the sections into which it is easily divided."},{"pos":"N-COUNT 可数名词","cn":"圆缺;弓形","en":"A segment of a circle is one of the two parts into which it is divided when you draw a straight line through it."},{"pos":"N-COUNT 可数名词","cn":"(市场)细分的部分","en":"A segment of a market is one part of it, considered separately from the rest.","ex":{"en":"Three-to-five day cruises are the fastest-growing segment of the market","cn":"3 至 5 天的乘船游览是该市场中发展最快的部分。"}},{"pos":"VERB 动词","cn":"细分，划分(市场)","en":"If a company segments a market, it divides it into separate parts, usually in order to improve marketing opportunities.","ex":{"en":"The big six record companies are multinational, and thus can segment the world market into national ones.","cn":"六大唱片公司都是跨国经营，因此能够将世界市场按国家划分。"}}]},"media":{"img":["media/pic/circles_comp.jpg","media/thumb/circles2.jpg","media/ldoce/img/oranges.jpg"],"uk":"media/uk/segment__gb_1.mp3","us":"media/us/segment__us_1.mp3"},"examples":[{"en":"Market researchers often segment the population on the basis of age and social class.","cn":"市场研究人员常常按年龄和社会阶层划分人口。"},{"en":"Lines divided the area into segments.","cn":"这一地区用线条分成了若干部分。"}]},"select":{"media":{"uk":"media/uk/select__gb_1.mp3","us":"media/us/select__us_1.mp3"},"oxford":{"phon":"sɪˈlekt","pos":"verb","senses":[{"en":"to choose somebody/something from a group of people or things, usually according to a system","cn":"选择；挑选；选拔","g":"[transitive, intransitive]","ex":{"en":"He hasn't been selected for the team.","cn":"他未能入选该队。"}},{"en":"to mark something on a computer screen; to choose something, especially from a menu","cn":"（在电脑屏幕上）选定；（从菜单中）选择，选取","lab":"computing","ex":{"en":"Select the text you want to format by holding down the left button on your mouse.","cn":"按住鼠标左键选取你想要安排版式的文本。"}},{"en":"carefully chosen as the best out of a larger group of people or things","cn":"精选的；作为…精华的；优等的","g":"[only before noun]","ex":{"en":"a select wine list","cn":"名优葡萄酒目录"},"pos":"adjective"},{"en":"used by people who have a lot of money or a high social position","cn":"有钱、有社会地位的人使用的","ex":{"en":"They live in a very select area.","cn":"他们住在一个上层人士住宅区。"},"pos":"adjective"}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"选择;挑选;选拔","en":"If you select something, you choose it from a number of things of the same kind.","ex":{"en":"Voters are selecting candidates for both US Senate seats and for 52 congressional seats","cn":"选民正在为美国参议院议席和 52 个众议院议席挑选候选人。"}},{"pos":"VERB 动词","cn":"(在屏幕上)选定(某文件或某段文本以作特别处理)","en":"If you select a file or a piece of text on a computer screen, you click on it so that it is marked in a different colour, usually in order for you to give the computer an instruction relating to that file or piece of text.","ex":{"en":"I selected a file and pressed the Delete key.","cn":"我选定了一个文件，按下了删除键。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"精选的;作为…精华的;优等的","en":"A select group is a small group of some of the best people or things of their kind.","ex":{"en":"He was one of the small select group assembled by Penney, at the High Explosive Research centre.","cn":"他是彭尼在烈性炸药研究中心召集的精英小组的一员。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"第一流的;只为富人(或上层人士)而设的;高级的","en":"If you describe something as select, you mean it has many desirable features, but is available only to people who have a lot of money or who belong to a high social class.","ex":{"en":"Christian Lacroix is throwing a very lavish and very select party.","cn":"克里斯汀·拉克鲁瓦正在举办一个非常豪华的上流聚会。"}}]},"examples":[{"en":"All our hotels have been carefully selected for the excellent value they provide.","cn":"我们的所有旅馆都是精心挑选的，最为合算。"},{"en":"Select the text you want to format by holding down the left button on your mouse.","cn":"按住鼠标左键选取你想要格式化的文本。"}]},"seem":{"media":{"uk":"media/uk/seem__gb_1.mp3","us":"media/us/seem__us_1.mp3"},"oxford":{"phon":"siːm","pos":"linking verb","senses":[{"en":"to give the impression of being or doing something","cn":"（给人印象）好像，似乎，看来","ex":{"en":"You seem happy.","cn":"你好像挺高兴。"}},{"en":"used to make what you say about your thoughts, feelings or actions less strong","cn":"（用以缓和语气）感到好像，觉得似乎","ex":{"en":"I seem to have left my book at home.","cn":"我大概是把书忘在家里了。"}},{"en":"used to suggest that something is true when you are not certain or when you want to be polite","cn":"（表示不确切或客气）看来好像，似乎","ex":{"en":"It would seem that we all agree.","cn":"我们大家似乎都同意。"}}]},"collins":{"senses":[{"pos":"V-LINK 连系动词","cn":"好像;似乎;看来","en":"You use seem to say that someone or something gives the impression of having a particular quality, or of happening in the way you describe.","ex":{"en":"We heard a series of explosions. They seemed quite close by","cn":"我们听到一连串的爆炸声，似乎就在附近。"}},{"pos":"V-LINK 连系动词","cn":"(在描述自己的感觉、想法、经历时用于缓和语气)好像，似乎","en":"You use seem when you are describing your own feelings or thoughts, or describing something that has happened to you, in order to make your statement less forceful.","ex":{"en":"I seem to have lost all my self-confidence","cn":"我好像已经自信全无。"}},{"pos":"PHRASE 短语","cn":"似乎不能;好像无法","en":"If you say that you cannot seem or could not seem to do something, you mean that you have tried to do it and were unable to.","ex":{"en":"No matter how hard I try I cannot seem to catch up on all the bills","cn":"无论怎么努力，我好像就是无法付清所有的账单。"}}]},"examples":[{"en":"‘He'll be there, then?’ ‘ So it seems (= people say so). ’ “","cn":"这么说，他要去那儿了？” “似乎是这样。”"},{"en":"It seems only reasonable to ask students to buy a dictionary.","cn":"要学生买一本词典似乎挺合情合理的。"}]},"several":{"media":{"uk":"media/uk/several__gb_1.mp3","us":"media/us/several__us_1.mp3"},"oxford":{"phon":"ˈsevrəl","pos":"determiner, pronoun","senses":[{"en":"more than two but not very many","cn":"几个；数个；一些","ex":{"en":"Several letters arrived this morning.","cn":"今天上午来了几封信。"}},{"en":"separate","cn":"各自的；分别的","ex":{"en":"They said goodbye and went their several ways.","cn":"他们道别后，便各自走了。"},"pos":"adjective"}]},"collins":{"senses":[{"pos":"DET 限定词","cn":"几个;数个;一些","en":"Several is used to refer to an imprecise number of people or things that is not large but is greater than two.","ex":{"en":"I had lived two doors away from this family for several years","cn":"我和这家人是好几年的邻居了，中间就隔着两家。"}}]},"examples":[{"en":"If you're looking for a photo of Alice you'll find several in here.","cn":"你要是想找艾丽斯的照片的话，这儿有几张。"},{"en":"Several of the paintings were destroyed in the fire.","cn":"那些画有好几幅被大火烧毁了。"}]},"self-contradictory":{"oxford":{"phon":"ˌself kɒntrəˈdɪktəri","pos":"adjective","senses":[{"en":"containing two ideas or statements that cannot both be true","cn":"自相矛盾的"}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"自相矛盾的","en":"If you say or write something that is self-contradictory, you make two statements which cannot both be true.","ex":{"en":"He is notorious for making unexpected, often self-contradictory, comments.","cn":"他发表的那些出人意料而且经常自相矛盾的评论令他臭名昭著。"}}]},"media":{"uk":"media/uk/self_contradictory_1_gb_1.mp3","us":"media/us/self_contradictory_1_us_1.mp3"}},"seek":{"oxford":{"phon":"siːk","pos":"verb","senses":[{"en":"to look for something/somebody","cn":"寻找","g":"[transitive, intransitive]","lab":"British English","ex":{"en":"Drivers are advised to seek alternative routes.","cn":"建议驾车者另寻其他路线。"}},{"en":"to ask somebody for something; to try to obtain or achieve something","cn":"要求；寻求；谋求；争取","g":"[transitive]","lab":"British English","ex":{"en":"I think it's time we sought legal advice.","cn":"我想我们现在该咨询一下律师了。"}},{"en":"to try to do something","cn":"试图；设法","g":"[intransitive]","ex":{"en":"He sought to establish himself as a writer.","cn":"他试图成为一名作家。"}},{"en":"looking for or trying to get the thing mentioned; the activity of doing this","cn":"寻求（或追求）…的；对…的寻求（或追求）","ex":{"en":"attention-seeking behaviour","cn":"为引起他人的注意而作出的行为"}}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"寻找;物色","en":"If you seek something such as a job or a place to live, you try to find one.","ex":{"en":"They have had to seek work as labourers","cn":"他们只好找体力活儿干。"}},{"pos":"VERB 动词","cn":"谋求;谋取;寻求","en":"When someone seeks something, they try to obtain it.","ex":{"en":"The prosecutors have warned they will seek the death penalty","cn":"检控方律师已警告说他们会努力争取判处死刑。"}},{"pos":"VERB 动词","cn":"请求(帮助);征求(意见)","en":"If you seek someone's help or advice, you contact them in order to ask for it.","ex":{"en":"Always seek professional legal advice before entering into any agreement","cn":"在签订任何协定之前一定要先征求法律专业人士的意见。"}},{"pos":"VERB 动词","cn":"力图;想方设法","en":"If you seek to do something, you try to do it.","ex":{"en":"He also denied that he would seek to annex the country","cn":"他还否认会试图吞并该国。"}},{"pos":"","cn":"","en":"相关词组：seek out"}]},"media":{"uk":"media/uk/seek__gb_1.mp3","us":"media/us/seek__us_1.mp3"},"examples":[{"en":"She managed to calm him down and seek help from a neighbour.","cn":"她设法使他平静下来，然后向一位邻居求助。"},{"en":"We are currently seeking new ways of expanding our membership.","cn":"目前，我们正探索扩招会员的新途径。"}]},"settled":{"media":{"uk":"media/uk/settled__gb_1.mp3","us":"media/us/settled__us_1.mp3"},"oxford":{"phon":"ˈsetld","pos":"adjective","senses":[{"en":"not likely to change or move","cn":"不大可能变动的；稳定的","ex":{"en":"settled weather","cn":"持续不变的天气"}},{"en":"comfortable and happy with your home, job, way of life, etc.","cn":"舒适自在的；（对住所、工作、生活方式等）习惯的","ex":{"en":"You’ll feel more settled when you’ve been here a few weeks.","cn":"当你来这里几周后，你会感觉更加安定。"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"稳定的;固定的;定居的","en":"If you have a settled way of life, you stay in one place, in one job, or with one person, rather than moving around or changing.","ex":{"en":"He decided to lead a more settled life with his partner","cn":"他决定和爱人一起过一种更加安定的生活。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"(情况、制度等)固定不变的，无变化的","en":"A settled situation or system stays the same all the time.","ex":{"en":"Cats are creatures of habit — they seem to appreciate a settled routine","cn":"猫是一种有固定习性的动物，它们似乎喜欢过一种有规律的生活。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"(因长期在某地生活或工作)舒适自在的，适应的,习惯的","en":"If you feel settled, you have been living or working in a place long enough to feel comfortable there.","ex":{"en":"After a few years of being a diplomat, she still didn't feel settled.","cn":"做了几年外交官后，她还是没有适应。"}}]},"examples":[{"en":"settled weather","cn":"持续不变的天气"},{"en":"a settled way of life","cn":"安定的生活方式"}]},"secondly":{"media":{"uk":"media/uk/secondly__gb_1.mp3","us":"media/us/secondly__us_1.mp3"},"oxford":{"phon":"ˈsekəndli","pos":"adverb","senses":[{"en":"used to introduce the second of a list of points you want to make in a speech or piece of writing","cn":"（用于列举）第二，其次","ex":{"en":"Firstly, it's expensive, and secondly, it's too slow.","cn":"首先是价格贵，其次，速度太慢。"}}]},"collins":{"senses":[{"pos":"ADV 副词","cn":"(用于列举观点或给出原因)第二，其次","en":"You say secondly when you want to make a second point or give a second reason for something.","ex":{"en":"You need, firstly, a strong independent board of directors and secondly, an experienced and dedicated staff.","cn":"你首先需要一个强大的独立董事会，其次需要一批富有经验并且爱岗敬业的员工。"}}]},"examples":[{"en":"Firstly, it's expensive, and secondly, it's too slow.","cn":"首先是价格贵，其次，速度太慢。"},{"en":"Firstly, they are not efficient, and secondly, they are expensive to make.","cn":"首先﹐它们效率不高﹐其次﹐它们的制作成本很高。"}]},"sent":{"collins":{"senses":[{"pos":"","cn":"","en":"Sent is the past tense and past participle of send."}]},"media":{"uk":"media/uk/sent__gb_1.mp3","us":"media/us/sent__us_1.mp3"}},"seamlessly":{"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"done or made so smoothly that you cannot tell where one thing stops and another begins","cn":""},{"en":"without any seam s","cn":""}]},"examples":[{"en":"the seamless integration of data, text, images, and sound","cn":"","src":"ld"}],"media":{"uk":"media/uk/seamlessly__gb_1.mp3","us":"media/us/seamlessly__us_1.mp3"},"oxford":{"phon":"ˈsiːmləsli","pos":"adverb","senses":[{"en":"smoothly, so that you do not notice any change between one part and the next","cn":"无缝地","ex":{"en":"The computer animation blends seamlessly with the rest of the film.","cn":"电脑动画与电影的其余部分无缝融合。"}}]}},"selection":{"oxford":{"phon":"sɪˈlekʃn","pos":"noun","senses":[{"en":"the process of choosing somebody/something from a group of people or things, usually according to a system","cn":"选择；挑选；选拔","g":"[uncountable]","ex":{"en":"She took a long time to make her selection.","cn":"她花了好长时间才作出选择。"}},{"en":"a number of people or things that have been chosen from a larger group","cn":"被挑选的人（或物）；被选中者；入选者","g":"[countable]","ex":{"en":"A selection of readers' comments is published below.","cn":"下面选登了部分读者的评论。"}},{"en":"a collection of things from which something can be chosen","cn":"可供选择的事物","g":"[countable]","ex":{"en":"The showroom has a wide selection of kitchens.","cn":"展厅里有多种式样的厨房可供选择。"}}]},"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"选拔;挑选;选择","en":"Selection is the act of selecting one or more people or things from a group.","ex":{"en":"...Darwin's principles of natural selection","cn":"达尔文的自然选择理论"}},{"pos":"N-COUNT 可数名词","cn":"挑选出来的一批人(或事物)","en":"A selection of people or things is a set of them that have been selected from a larger group.","ex":{"en":"...this selection of popular songs.","cn":"这张流行歌曲选集"}},{"pos":"N-COUNT 可数名词","cn":"(商店内)可供挑选的某类商品","en":"The selection of goods in a shop is the particular range of goods that it has available and from which you can choose what you want.","ex":{"en":"It offers the widest selection of antiques of every description in a one day market.","cn":"它在为期一天的集市上出售应有尽有的各种古董。"}}]},"media":{"uk":"media/uk/selection__gb_1.mp3","us":"media/us/selection__us_1.mp3","img":["media/ldoce/img/selection.jpg"]},"examples":[{"en":"The showroom has a wide selection of kitchens.","cn":"展厅里有多种式样的厨房可供选择。"},{"en":"The final team selection will be made tomorrow.","cn":"明天将确定队伍的最后人选。"}]},"servant":{"oxford":{"phon":"ˈsɜːvənt","pos":"noun","senses":[{"en":"a person who works in another person’s house, and cooks, cleans, etc. for them","cn":"仆人；佣人","ex":{"en":"a domestic servant","cn":"家仆"}},{"en":"a person who works for a company or an organization","cn":"（公司或机构的）雇员，职员","ex":{"en":"Mr Bennet said his client was a loyal servant to the council.","cn":"班纳特先生表示，他的委托人是该委员会的忠实仆人。"}},{"en":"a person or thing that is controlled by something","cn":"奴仆般受制（或献身）于…的人；服务于…的事物","ex":{"en":"He was willing to make himself a servant of his art.","cn":"他甘愿献身于自己的艺术。"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"仆人;用人","en":"A servant is someone who is employed to work at another person's home, for example as a cleaner or a gardener."},{"pos":"N-COUNT 可数名词","cn":"提供服务的人(或事物);可以利用的人(或事物)","en":"You can use servant to refer to someone or something that provides a service for people or can be used by them.","ex":{"en":"Like any other public servants, police must respond to public demand","cn":"和其他所有公务员一样，警察必须服务于公众的需求。"}}]},"media":{"uk":"media/uk/servant__gb_1.mp3","us":"media/us/servant__us_1.mp3"},"examples":[{"en":"They treat their mother like a servant.","cn":"他们像对待佣人一样对待自己的母亲。"},{"en":"He was willing to make himself a servant of his art.","cn":"他甘愿献身于自己的艺术。"}]},"secretarial":{"media":{"uk":"media/uk/secretarial__gb_1.mp3","us":"media/us/secretarial__us_1.mp3"},"oxford":{"phon":"ˌsekrəˈteəriəl","pos":"adjective","senses":[{"en":"involving or connected with the work of a secretary","cn":"秘书的；文秘工作的","ex":{"en":"secretarial work","cn":"文秘工作"}}]},"collins":{"senses":[{"pos":"ADJ 形容词","cn":"秘书工作的","en":"Secretarial work is the work done by a secretary in an office.","ex":{"en":"I was doing temporary secretarial work","cn":"我在做临时的秘书工作。"}}]},"examples":[{"en":"secretarial work","cn":"文秘工作"},{"en":"a secretarial course","cn":"秘书课程"}]},"separated":{"media":{"uk":"media/uk/separated__gb_1.mp3","us":"media/us/separated__us_1.mp3"},"oxford":{"phon":"ˈsepəreɪtɪd","pos":"adjective","senses":[{"en":"no longer living with your husband, wife or partner","cn":"（和某人）分居的","lab":"especially North American English","ex":{"en":"Her parents are separated but not divorced.","cn":"她父母分居但没离婚。"}}]},"collins":{"senses":[{"pos":"ADJ 形容词","cn":"分居的","en":"Someone who is separated from their wife or husband lives apart from them, but is not divorced.","ex":{"en":"Most single parents are either divorced or separated","cn":"大多数单身父母要么离婚了要么分居了。"}},{"pos":"ADJ 形容词","cn":"(与家人等)分离的，不在一起的","en":"If you are separated from someone, for example your family, you are not able to be with them.","ex":{"en":"The idea of being separated from him, even for a few hours, was torture","cn":"一想到要和他分开，即便是短短几小时，都感到备受煎熬。"}}]},"examples":[{"en":"Her parents are separated but not divorced.","cn":"她父母分居但没离婚。"},{"en":"He's been separated from his wife for a year.","cn":"他和妻子分居一年了。"}]},"settles":{"oxford":{"phon":"ˈsetl","pos":"verb","senses":[{"en":"to put an end to an argument or a disagreement","cn":"结束（争论、争端等）；解决（分歧、纠纷等）"},{"en":"to decide or arrange sth finally （","cn":"最终）决定，确定，安排好"}]},"media":{"uk":"media/uk/settle__gb_1.mp3","us":"media/us/settle__us_1.mp3"}},"seeking":{"oxford":{"phon":"siːk","pos":"verb","senses":[{"en":"to look for sth/sb","cn":"寻找"},{"en":"to try to obtain or achieve sth","cn":"寻求；谋求；争取"}]}},"set":{"media":{"uk":"media/uk/set__gb_1.mp3","us":"media/us/set__us_1.mp3"},"oxford":{"phon":"set","pos":"verb","senses":[{"en":"to prepare or arrange something so that it is ready for use or in position","cn":"设置；调整好；安排就绪","g":"[transitive]","sc":"clock/machine","ex":{"en":"Have you set the alarm clock?","cn":"你给闹钟定好时间了吗?"}},{"en":"to arrange knives, forks, etc. on a table for a meal","cn":"摆放餐具","g":"[transitive]","sc":"table","ex":{"en":"Can you help me set the table?","cn":"你能帮我摆桌子吗？"}},{"en":"to fix something so that others copy it or try to achieve it","cn":"树立；创立；开创","g":"[transitive]","sc":"example/standard, etc.","ex":{"en":"This could set a new fashion.","cn":"这或许会开创一种新时尚。"}},{"en":"to give somebody a piece of work to do or a task or target to achieve","cn":"布置；分配；指派","g":"[transitive]","sc":"work/task","ex":{"en":"Who will be setting (= writing the questions for) the French exam?","cn":"谁出法语试题？"}},{"en":"to arrange or fix something; to decide on something","cn":"安排；确定；决定","g":"[transitive]","sc":"arrange","ex":{"en":"They haven't set a date for their wedding yet.","cn":"他们还没有确定婚礼日期。"}},{"en":"to place the action of a play, novel or film in a particular place, time, etc.","cn":"把故事情节安排在；为…设置背景于","g":"[transitive, usually passive]","sc":"play/book/film","ex":{"en":"The novel is set in London in the 1960s.","cn":"这部小说以 20 世纪 60 年代的伦敦为背景。"}},{"en":"to be located in a particular place","cn":"位于；坐落在","g":"[transitive, usually passive]","sc":"be located","ex":{"en":"The house is set in fifty acres of parkland.","cn":"房子四周是五十英亩开阔的绿地。"}},{"en":"to put something/somebody in a particular place or position","cn":"放；置；使处于","g":"[transitive]","sc":"put/start","ex":{"en":"She set a tray down on the table.","cn":"她把托盘放到桌上。"}},{"en":"to cause somebody/something to be in a particular state; to start something happening","cn":"使处于某种状况；使开始","g":"[transitive]","sc":"put/start","ex":{"en":"Her manner immediately set everyone at their ease.","cn":"她的态度立刻使大家感到轻松了。"}},{"en":"to go down below the horizon","cn":"落（下）","g":"[intransitive]","sc":"of sun/moon","ex":{"en":"We sat and watched the sun setting.","cn":"我们坐着看太阳渐渐落下去。"}},{"en":"to put a precious stone into a piece of jewellery","cn":"镶嵌","g":"[transitive, usually passive]","sc":"jewellery","ex":{"en":"She had the sapphire set in a gold ring.","cn":"她请人把蓝宝石镶嵌到一枚金戒指上。"}},{"en":"to become solid or hard","cn":"凝固；凝结","g":"[intransitive]","sc":"become hard","ex":{"en":"Leave the concrete to set for a few hours.","cn":"让混凝土凝固几小时。"}},{"en":"to fix your face into a determined expression","cn":"使现出坚定的表情","g":"[transitive, usually passive]","sc":"face","ex":{"en":"Her jaw was set in a determined manner.","cn":"她下巴紧绷着，一副决不动摇的样子。"}},{"en":"to arrange somebody’s hair while it is wet so that it dries in a particular style","cn":"固定发型；做头发","g":"[transitive]","sc":"hair","ex":{"en":"She had her hair washed and set.","cn":"她去洗了头，做了发型。"}},{"en":"to put a broken bone into a fixed position and hold it there, so that it will join together again and get better; to get better in this way","cn":"把（断骨）复位；接（骨）","g":"[transitive, intransitive]","sc":"bone","ex":{"en":"The surgeon set her broken arm.","cn":"医生给她接上了手臂上的断骨。"}},{"en":"to use a machine or computer to arrange writing and images on pages in order to prepare a book, newspaper, etc. for printing","cn":"排版","g":"[transitive]","lab":"specialist","sc":"for printing"},{"en":"to write music to go with words","cn":"为…谱曲；给…配乐","g":"[transitive]","sc":"words to music","ex":{"en":"Schubert set many poems to music.","cn":"舒伯特为许多诗歌谱了曲。"}},{"en":"a group of similar things that belong together in some way","cn":"一套，一副，一组（类似的东西）","g":"[countable]","sc":"group","ex":{"en":"a set of six chairs","cn":"六把成套的椅子"},"pos":"noun"},{"en":"a group of objects used together, for example for playing a game","cn":"一套，一副，一组（配套使用的东西）","g":"[countable]","sc":"group","ex":{"en":"a chess set","cn":"一副国际象棋"},"pos":"noun"},{"en":"a group of people who have similar interests and spend a lot of time together socially","cn":"一伙（或一帮、一群）人；阶层；团伙","g":"[countable + singular or plural verb]","lab":"sometimes disapproving","sc":"group","ex":{"en":"the smart set (= rich, fashionable people)","cn":"富裕时尚一族"},"pos":"noun"},{"en":"a piece of equipment for receiving television or radio signals","cn":"电视机；收音机","g":"[countable]","sc":"TV/radio","ex":{"en":"a television/TV set","cn":"电视机"},"pos":"noun"},{"en":"the scenery used for a play, film, etc.","cn":"布景","g":"[countable]","sc":"for play/movie","ex":{"en":"We need volunteers to help build and paint the set.","cn":"我们需要一些自愿帮忙搭建和粉刷布景的人。"},"pos":"noun"},{"en":"a place where a play is performed or part of a film is filmed","cn":"舞台；片场","g":"[countable, uncountable]","sc":"for play/movie","ex":{"en":"The cast must all be on (the) set by 7 in the morning.","cn":"全体演员必须在早上 7 点钟到场。"},"pos":"noun"},{"en":"one section of a match in games such as tennis or volleyball","cn":"（网球的）盘；（排球比赛等的）局","g":"[countable]","sc":"in sport","ex":{"en":"She won in straight sets (= without losing a set).","cn":"她一盘未失，连连得胜。"},"pos":"noun"},{"en":"a group of things regarded as a unit because they all have particular qualities in common","cn":"集；集合","g":"[countable]","sc":"mathematics","ex":{"en":"the set of all square numbers less than 50","cn":"50 以下的所有平方数集"},"pos":"noun"},{"en":"a series of songs or pieces of music that a musician or group performs at a concert","cn":"一组歌曲（或乐曲）","g":"[countable]","sc":"pop music","ex":{"en":"a stunning solo set of ten songs","cn":"令人惊叹的十首独奏歌曲"},"pos":"noun"},{"en":"a group of school students with a similar ability in a particular subject","cn":"（在某学科上能力相当的）一批学生","g":"[countable]","lab":"British English","sc":"class","ex":{"en":"She's in the top set for French.","cn":"她的法语成绩名列前茅。"},"pos":"noun"},{"en":"the way in which somebody’s face or body is fixed in a particular expression, especially one showing a feeling of being determined","cn":"（尤指坚定的）姿势，姿态，神情","g":"[singular]","sc":"of face/body","ex":{"en":"She admired the firm set of his jaw.","cn":"她喜欢他那副紧绷着下巴的刚毅神态。"},"pos":"noun"},{"en":"an act of arranging hair in a particular style while it is wet","cn":"头发的定型；做头发","g":"[singular]","sc":"hair","ex":{"en":"A shampoo and set costs £15.","cn":"洗头并做发型共 15 英镑。"},"pos":"noun"},{"en":"the state of becoming solid or hard","cn":"凝固；凝结","g":"[singular]","sc":"becoming solid","ex":{"en":"To be sure of a good set when making the jam, use preserving sugar with added pectin.","cn":"为了确保制作果酱时效果良好，请使用添加果胶的保鲜糖。"},"pos":"noun"},{"en":"a hole in the ground where a badger lives","cn":"獾穴","g":"[countable]","sc":"animal’s home","pos":"noun"},{"en":"a young plant, shoot etc. for planting","cn":"（供移植的）秧苗，插枝，球茎","g":"[countable]","sc":"plant","ex":{"en":"onion sets","cn":"洋葱苗"},"pos":"noun"},{"en":"in a particular position","cn":"位于（或处于）…的","sc":"in position","ex":{"en":"a house set in 40 acres of parkland","cn":"一所坐落在一片 40 英亩开阔绿地上的房子"},"pos":"adjective"},{"en":"planned or fixed","cn":"安排好的；确定的；固定的","g":"[usually before noun]","sc":"planned","ex":{"en":"Each person was given set jobs to do.","cn":"给每个人分配了预先定好的工作。"},"pos":"adjective"},{"en":"not likely to change","cn":"固定的；顽固的；固执的","sc":"opinions/ideas","ex":{"en":"set ideas/opinions/views on how to teach","cn":"不变的教学思想／主张／观点"},"pos":"adjective"},{"en":"having a fixed price and a limited choice of dishes","cn":"套（餐）的","g":"[only before noun]","sc":"meal","ex":{"en":"a set dinner/lunch/meal","cn":"一份晚餐／午餐套餐；一份套餐"},"pos":"adjective"},{"en":"likely to do something; ready for something or to do something","cn":"有可能的；做好准备的","sc":"likely/ready","ex":{"en":"The team looks set for victory.","cn":"看来这个队能赢。"},"pos":"adjective"},{"en":"fixed; not natural","cn":"呆板的；不自然的","g":"[usually before noun]","sc":"face","ex":{"en":"a set smile","cn":"僵硬的笑容"},"pos":"adjective"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"一套;一组;一系列","en":"A set of things is a number of things that belong together or that are thought of as a group.","ex":{"en":"There must be one set of laws for the whole of the country","cn":"整个国家必须要有一套统一的法律。"}},{"pos":"N-COUNT 可数名词","cn":"(网球比赛中的)盘","en":"In tennis, a set is one of the groups of six or more games that form part of a match.","ex":{"en":"Graf was leading 5-1 in the first set.","cn":"格拉芙第一盘以 5 比 1 领先。"}},{"pos":"N-COUNT 可数名词","cn":"(数学中的)集，集合","en":"In mathematics, a set is a group of mathematical quantities that have some characteristic in common."},{"pos":"N-COUNT 可数名词","cn":"(一场音乐会中所演唱或演奏的)一组歌曲(或乐曲)","en":"A band's or musician's set is the group of songs or tunes that they perform at a concert.","ex":{"en":"The band continued with their set after a short break","cn":"短暂的休息后，乐队继续演奏他们的曲目。"}},{"pos":"N-SING 单数名词","cn":"(经常碰面或趣味相同的)一伙(或一帮、一群)人","en":"You can refer to a group of people as a set if they meet together socially or have the same interests and lifestyle.","ex":{"en":"He belonged to what the press called 'The Chelsea Set'.","cn":"他属于媒体所称的“切尔西圈子”里的人。"}},{"pos":"N-COUNT 可数名词","cn":"(话剧的)布景;(电影的)摄影棚，拍片现场","en":"The set for a play, film, or television show is the furniture and scenery that is on the stage when the play is being performed or in the studio where filming takes place.","ex":{"en":"From the first moment he got on the set, he wanted to be a director too","cn":"自从进入摄影棚的第一刻起，他就希望自己也能成为一名导演。"}},{"pos":"N-SING 单数名词","cn":"(尤指坚定的)神情，姿态，姿势","en":"The set of someone's face or part of their body is the way that it is fixed in a particular expression or position, especially one that shows determination.","ex":{"en":"Matt looked at Hugh and saw the stubbornness in the set of his shoulders","cn":"马特看着休，从他坚挺的肩膀中看出了他的倔强。"}},{"pos":"N-COUNT 可数名词","cn":"(电视机等)家用电器","en":"A set is an appliance. For example, a television set is a television.","ex":{"en":"Children spend so much time in front of the television set","cn":"孩子们花在看电视上的时间太多了。"}},{"pos":"VERB 动词","cn":"(尤指小心翼翼地)放，置","en":"If you set something somewhere, you put it there, especially in a careful or deliberate way.","ex":{"en":"He took the case out of her hand and set it on the floor","cn":"他从她手中拿过箱子，将它小心地放在地板上。"}},{"pos":"ADJ 形容词","cn":"位于…的;坐落在…的","en":"If something is set in a particular place or position, it is in that place or position.","ex":{"en":"The castle is set in 25 acres of beautiful grounds","cn":"这座城堡坐落于一片方圆 25 英亩、风景秀丽的土地上。"}},{"pos":"ADJ 形容词","cn":"镶于…上的;嵌在…上的","en":"If something is set into a surface, it is fixed there and does not stick out.","ex":{"en":"The man unlocked a gate set in a high wall and let me through","cn":"那名男子打开了高墙中一面大门上的锁让我进去。"}},{"pos":"VERB 动词","cn":"使处于(某种状态或情况)","en":"You can use set to say that a person or thing causes another person or thing to be in a particular condition or situation. For example, to set someone free means to cause them to be free, and to set something going means to cause it to start working.","ex":{"en":"Set the kitchen timer going","cn":"让厨房计时器开始计时。"}},{"pos":"VERB 动词","cn":"设置，调整好，调准(钟表等)","en":"When you set a clock or control, you adjust it to a particular point or level.","ex":{"en":"Set the volume as high as possible","cn":"将音量尽量调大。"}},{"pos":"VERB 动词","cn":"决定，确定(日期、价格、目标或水准)","en":"If you set a date, price, goal, or level, you decide what it will be.","ex":{"en":"The conference chairman has set a deadline of noon tomorrow","cn":"会议主席将明天中午定为截止日期。"}},{"pos":"VERB 动词","cn":"估定(价值);认为有（…价值)","en":"If you set a certain value on something, you think it has that value.","ex":{"en":"She sets a high value on autonomy","cn":"她对自主权看得很重。"}},{"pos":"VERB 动词","cn":"树立(榜样);创造(纪录);开创(先例)","en":"If you set something such as a record, an example, or a precedent, you do something that people will want to copy or try to achieve.","ex":{"en":"Legal experts said her case would not set a precedent because it was an out-of-court settlement","cn":"法律专家说她的案子不会成为判例，因为它是庭外和解的。"}},{"pos":"VERB 动词","cn":"分配;布置;指派","en":"If someone sets you a task or aim or if you set yourself a task or aim, you need to succeed in doing it.","ex":{"en":"I have to plan my academic work very rigidly and set myself clear objectives","cn":"我必须严格地规划我的学业，同时给自己定下明确的目标。"}},{"pos":"VERB 动词","cn":"出(试题、试卷)","en":"To set an examination or a question paper means to decide what questions will be asked in it.","ex":{"en":"He broke with the tradition of setting examinations in Latin.","cn":"他打破了用拉丁语出试卷的传统。"}},{"pos":"ADJ 形容词","cn":"安排好的;确定的;固定的","en":"You use set to describe something which is fixed and cannot be changed.","ex":{"en":"Investors can apply for a package of shares at a set price","cn":"投资者可以申购固定价格的股票组合。"}},{"pos":"ADJ 形容词","cn":"(学习书目)指定的","en":"A set book must be studied by students taking a particular course.","ex":{"en":"One of the set books is Jane Austen's Emma.","cn":"指定阅读书目之一是简·奥斯汀的《爱玛》。"}},{"pos":"ADJ 形容词","cn":"(戏剧、电影、小说等)以(某时或某地)为背景的","en":"If a play, film, or story is set in a particular place or period of time, the events in it take place in that place or period.","ex":{"en":"The play is set in a small Midwestern town.","cn":"这出戏以中西部的一个小镇为背景。"}},{"pos":"ADJ 形容词","cn":"做好准备的;可能的","en":"If you are set to do something, you are ready to do it or are likely to do it. If something is set to happen, it is about to happen or likely to happen.","ex":{"en":"Roberto Baggio was set to become one of the greatest players of all time","cn":"罗伯特·巴乔注定会成为迄今为止最伟大的球员之一。"}},{"pos":"ADJ 形容词","cn":"下定决心的;坚决的","en":"If you are set on something, you are strongly determined to do or have it. If you are set against something, you are strongly determined not to do or have it.","ex":{"en":"She was set on going to an all-girls school","cn":"她执意要去女子学校上学。"}},{"pos":"VERB 动词","cn":"使表现出，显出(坚定的表情)","en":"If you set your face or jaw, you put on a fixed expression of determination.","ex":{"en":"Instead, she set her jaw grimly and waited in silence","cn":"相反，她一脸严肃，面部紧绷，一声不吭地等着。"}},{"pos":"VERB 动词","cn":"凝固;凝结;变硬","en":"When something such as jelly, melted plastic, or cement sets, it becomes firm or hard.","ex":{"en":"You can add ingredients to these desserts as they begin to set","cn":"这些甜点开始凝固时就可以加入辅料了。"}},{"pos":"VERB 动词","cn":"(太阳)落山，落下","en":"When the sun sets, it goes below the horizon.","ex":{"en":"They watched the sun set behind the distant dales.","cn":"他们望着夕阳没入远处的山谷。"}},{"pos":"VERB 动词","cn":"设置，安排，设计(陷阱)","en":"To set a trap means to prepare it to catch someone or something.","ex":{"en":"He seemed to think I was setting some sort of trap for him","cn":"他似乎认为我在给他设什么套儿。"}},{"pos":"VERB 动词","cn":"在(桌)上摆放餐具","en":"When someone sets the table, they prepare it for a meal by putting plates and cutlery on it."},{"pos":"VERB 动词","cn":"为…谱(曲);为…配(乐)","en":"If someone sets a poem or a piece of writing to music, they write music for the words to be sung to.","ex":{"en":"He has attracted much interest by setting ancient religious texts to music.","cn":"他因为给古老的宗教经书谱曲配乐而备受关注。"}},{"pos":"PHRASE 短语","cn":"为…做准备;为…铺平了道路","en":"If someone sets the scene or sets the stage for an event to take place, they make preparations so that it can take place.","ex":{"en":"The Democrat convention has set the scene for a ferocious election campaign this autumn","cn":"民主党代表大会已经为今年秋季激烈的大选作好了准备。"}},{"pos":"PHRASE 短语","cn":"守旧的;一成不变的;固执的","en":"If you say that someone is set in their ways, you are being critical of the fact that they have fixed habits and ideas which they will not easily change, even though they may be old-fashioned."},{"pos":"","cn":"","en":"to set eyes on something→see: ; to set fire to something→see: ; to set foot somewhere→see: ; to set your heart on something→see: ; to set sail→see: ; to set great store by or on something→see: ; to set to work→see: ;"},{"pos":"PHRASAL VERB 短语动词","cn":"建起;设立;设置","en":"If you set up a temporary structure, you place it or build it somewhere.","ex":{"en":"They took to the streets, setting up roadblocks of burning tyres","cn":"他们走上街头，用点燃的轮胎设置路障。"}},{"pos":"PHRASAL VERB 短语动词","cn":"安装，装配，调试(设备或机器)","en":"If you set up a device or piece of machinery, you do the things that are necessary for it to be able to start working.","ex":{"en":"Setting up the camera can be tricky","cn":"调试相机可能会很费事。"}},{"pos":"PHRASAL VERB 短语动词","cn":"立业;开业;创业","en":"If you set up somewhere or set yourself up somewhere, you establish yourself in a new business or new area.","ex":{"en":"The mayor's scheme offers incentives to firms setting up in lower Manhattan","cn":"市长的方案激励了打算在曼哈顿下城开业的公司。"}},{"pos":"PHRASAL VERB 短语动词","cn":"安(家);开(店)","en":"If you set up home or set up shop, you buy a house or business of your own and start living or working there.","ex":{"en":"They married, and set up home in Ramsgate.","cn":"他们结婚了，在拉姆斯盖特安家定居。"}},{"pos":"PHRASAL VERB 短语动词","cn":"引起;引发;产生","en":"If something sets up something such as a process, it creates it or causes it to begin.","ex":{"en":"The secondary current sets up a magnetic field inside the tube","cn":"二次电流在管子内部会产生磁场。"}},{"pos":"PHRASAL VERB 短语动词","cn":"使更健康;使更有活力;使状态更好","en":"If something sets you up for something, it puts you in a good condition or position to deal with it, for example by making you feel healthy and energetic.","ex":{"en":"I have my cornflakes and smell the fresh air and the grass and it sets me up for the day","cn":"我吃了些脆玉米片，呼吸着充满青草气息的新鲜空气，这让我一天都充满活力。"}},{"pos":"PHRASAL VERB 短语动词","cn":"诬陷;陷害;冤枉","en":"If you are set up by someone, they make it seem that you have done something wrong when you have not.","ex":{"en":"He claimed he had been set up after drugs were discovered at his home","cn":"在他家里发现毒品后，他声称自己是被人陷害的。"}},{"pos":"","cn":"","en":"相关词组：set against set apart set aside set back set down set forth set in set off set on set out set up set upon"}]},"examples":[{"en":"Set against the benefits of the new technology, there is also a strong possibility that jobs will be lost.","cn":"权衡利弊，新技术的确有种种好处，但也很可能使一些人失去工作。"},{"en":"The break from work really set me up for the new year.","cn":"放下工作稍事休息，的确使我更有精力在新的一年大干一场了。"}]},"self-satisfaction":{"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"自鸣得意;沾沾自喜","en":"Self-satisfaction is the feeling you have when you are self-satisfied.","ex":{"en":"He tried hard not to smile in smug self-satisfaction.","cn":"他强忍住沾沾自喜的笑容。"}}]},"media":{"uk":"media/uk/self_satisfaction_1_gb_1.mp3","us":"media/us/self_satisfaction_1_us_1.mp3"},"examples":[{"en":"a look of self-satisfaction","cn":"沾沾自喜的神态"},{"en":"A self-satisfied smile settled on his face.","cn":""}],"oxford":{"phon":"ˌself sætɪsˈfækʃn","pos":"noun","senses":[{"en":"the fact of being too pleased with yourself or your own achievements","cn":"自鸣得意的；沾沾自喜的","ex":{"en":"a look of self-satisfaction","cn":"自鸣得意的样子"}}]}},"servitude":{"media":{"uk":"media/uk/servitude__gb_1.mp3","us":"media/us/servitude__us_1.mp3"},"oxford":{"phon":"ˈsɜːvɪtjuːd","pos":"noun","senses":[{"en":"the condition of being a slave or being forced to obey another person","cn":"奴役（状况）；任人差遣（的状况）","ex":{"en":"a life of poverty and servitude","cn":"贫穷和奴役的生活"}}]},"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"奴役;苦役;完全受人支配","en":"Servitude is the condition of being a slave or of being completely under the control of someone else.","ex":{"en":"...a life of servitude.","cn":"受奴役的一生"}}]}},"seating":{"media":{"uk":"media/uk/seating__gb_1.mp3","us":"media/us/seating__us_1.mp3"},"oxford":{"phon":"ˈsiːtɪŋ","pos":"noun","senses":[{"en":"places to sit; seats","cn":"可坐的地方；座位","ex":{"en":"The theatre has seating for about 500 people.","cn":"这家剧院可坐 500 人左右。"}}]},"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"(总称)座椅，座位","en":"You can refer to the seats in a place as the seating .","ex":{"en":"The stadium has been fitted with seating for over eighty thousand spectators.","cn":"这个体育场配备了8万多个观众座席。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"(公共场所、正式场合的)座位安排(或设置)","en":"The seating at a public place or a formal occasion is the arrangement of where people will sit.","ex":{"en":"She checked the seating arrangements before the guests filed into the dining-room.","cn":"在客人们鱼贯进入餐厅之前，她核实了一遍座位安排。"}}]},"examples":[{"en":"The room had a seating capacity of over 200.","cn":"这个房间能容 200 多人就座。"},{"en":"The theatre has seating for about 500 people.","cn":"这家剧院可坐 500 人左右。"}]},"semitone":{"oxford":{"phon":"ˈsemitəʊn","pos":"noun","senses":[{"en":"half a tone on a musical scale, for example the interval between C and C♯ or between E and F","cn":"半音"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"（西方音乐中的）半音","en":"In Western music, a semitone is the smallest interval between two musical notes. Two semitones are equal to one tone."}]},"media":{"uk":"media/uk/semitone__gb_1.mp3","us":"media/us/semitone__us_1.mp3"}},"see":{"media":{"uk":"media/uk/see__gb_1.mp3","us":"media/us/see__us_1.mp3"},"oxford":{"phon":"siː","pos":"verb","senses":[{"en":"to become aware of somebody/something by using your eyes","cn":"看见；见到；看出","g":"[transitive, intransitive]","lab":"figurative","sc":"use eyes","ex":{"en":"She looked for him but couldn't see him in the crowd.","cn":"她在人群里找来找去，但没看见他。"}},{"en":"to have or use the power of sight","cn":"看得见；看；有视力","g":"[intransitive]","sc":"use eyes","ex":{"en":"She will never see again (= she has become blind).","cn":"她再也看不见东西了。"}},{"en":"to watch a game, television programme, performance, etc.","cn":"观看（比赛、电视节目、演出等）","g":"[transitive]","sc":"watch","ex":{"en":"Did you see that programme on Brazil last night?","cn":"昨晚你有没有看那个介绍巴西的节目？"}},{"en":"to look at something in order to find information; to go to somebody in order to ask for help or information","cn":"见；参见；咨询","g":"[transitive, intransitive]","sc":"look up/ask for information","ex":{"en":"See page 158.","cn":"参见第 158 页。"}},{"en":"to be near and recognize somebody; to meet somebody by chance","cn":"遇见；碰到；邂逅","g":"[transitive]","sc":"meet by chance","ex":{"en":"Guess who I saw at the party last night!","cn":"猜猜昨天我在晚会上碰见谁了！"}},{"en":"to visit somebody/something","cn":"拜访；看望；探视","g":"[transitive]","sc":"visit","ex":{"en":"Come and see us again soon.","cn":"早点再来看我们。"}},{"en":"to have a meeting with somebody","cn":"会见；会晤","g":"[transitive]","sc":"have meeting","ex":{"en":"You ought to see a doctor about that cough.","cn":"你得找个大夫看看你的咳嗽。"}},{"en":"to spend time with somebody","cn":"与（某人）待在一起；交往","g":"[transitive]","sc":"spend time","ex":{"en":"Are you seeing anyone (= having a romantic relationship with anyone)?","cn":"你是不是跟什么人好上了？"}},{"en":"to understand something","cn":"理解；明白；领会","g":"[intransitive, transitive]","sc":"understand","ex":{"en":"‘It opens like this.’ ‘Oh, I see.’","cn":"“这样就打开了。”“哦，我明白了。”"}},{"en":"to have an opinion of something","cn":"认为；看待","g":"[transitive]","sc":"have opinion","ex":{"en":"I see things differently now.","cn":"现在，我看问题的方式不一样了。"}},{"en":"to consider something as a future possibility; to imagine somebody/something as something","cn":"设想；想象","g":"[transitive]","lab":"especially British English","sc":"imagine","ex":{"en":"I can't see her changing her mind.","cn":"我无法想象她会改变主意。"}},{"en":"to find out something by looking, asking or waiting","cn":"（通过查看、打听、等待）弄清，了解","g":"[intransitive, transitive]","sc":"find out","ex":{"en":"‘Has the mail come yet?’ ‘I'll just go and see.’","cn":"“邮件来了没有？”“我去看看。”"}},{"en":"to find out or decide something by thinking or considering","cn":"考虑；定夺","g":"[intransitive, transitive]","sc":"find out","ex":{"en":"‘Will you be able to help us?’ ‘I don't know, I'll have to see.’","cn":"“你能帮助我们吗？”“不好说，我得考虑一下。”"}},{"en":"to make sure that you do something or that something is done","cn":"确保；务必（做到）","g":"[transitive]","sc":"make sure","ex":{"en":"See that all the doors are locked before you leave.","cn":"一定要把所有的门都锁好了再走。"}},{"en":"to experience or suffer something","cn":"经历；遭受","g":"[transitive]","sc":"experience","ex":{"en":"He has seen a great deal in his long life.","cn":"他在漫长的一生中经历了许多事情。"}},{"en":"to be the time when an event happens","cn":"为…发生的时间","g":"[transitive]","sc":"witness event","ex":{"en":"Next year sees the centenary of Saint-Saëns' death.","cn":"明年是圣桑逝世一百周年。"}},{"en":"to be the place where an event happens","cn":"为…发生的地点","g":"[transitive]","sc":"witness event","ex":{"en":"This stadium has seen many thrilling football games.","cn":"在这座体育场里举办过许多激动人心的足球比赛。"}},{"en":"to go with somebody to help or protect them","cn":"送；护送","g":"[transitive]","sc":"help","ex":{"en":"I saw the old lady across (= helped her cross) the road.","cn":"我护送老太太过马路。"}},{"en":"the district or office of a bishop or an archbishop","cn":"主教（或大主教）教区；主教（或大主教）权限；牧座","ex":{"en":"the Holy See (= the office of the Pope)","cn":"（罗马）宗座"},"pos":"noun"}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"看见;看到","en":"When you see something, you notice it using your eyes.","ex":{"en":"You can't see colours at night","cn":"晚上看不见颜色。"}},{"pos":"VERB 动词","cn":"与…见面;看望;会见","en":"If you see someone, you visit them or meet them.","ex":{"en":"I saw him yesterday","cn":"我昨天见到他了。"}},{"pos":"VERB 动词","cn":"观看，看(娱乐节目等)","en":"If you see an entertainment such as a play, film, concert, or sports game, you watch it.","ex":{"en":"He had been to see a Semi-Final of the FA Cup","cn":"他看过一场足总杯半决赛。"}},{"pos":"VERB 动词","cn":"看出;意识到","en":"If you see that something is true or exists, you realize by observing it that it is true or exists.","ex":{"en":"I could see she was lonely.","cn":"我能看出她很寂寞。"}},{"pos":"VERB 动词","cn":"明白;领会;理解","en":"If you see what someone means or see why something happened, you understand what they mean or understand why it happened.","ex":{"en":"Oh, I see what you're saying","cn":"哦，我明白你的意思了。"}},{"pos":"VERB 动词","cn":"认为;把…看作","en":"If you see someone or something as a certain thing, you have the opinion that they are that thing.","ex":{"en":"She saw him as a visionary, but her father saw him as a man who couldn't make a living","cn":"她认为他是一个有眼光的人，但是她父亲却认为他没有谋生的能力。"}},{"pos":"VERB 动词","cn":"看出;看上，欣赏(某种特质)","en":"If you see a particular quality in someone, you believe they have that quality. If you ask what someone sees in a particular person or thing, you want to know what they find attractive about that person or thing.","ex":{"en":"Frankly, I don't know what Paul sees in her","cn":"坦白地说，我不知道保罗看上她什么了。"}},{"pos":"VERB 动词","cn":"想象;预测","en":"If you see something happening in the future, you imagine it, or predict that it will happen.","ex":{"en":"A good idea, but can you see Taylor trying it?","cn":"主意不错，不过你认为泰勒会尝试它吗？"}},{"pos":"VERB 动词","cn":"目睹;经历;见证","en":"If a period of time or a person sees a particular change or event, it takes place during that period of time or while that person is alive.","ex":{"en":"Yesterday saw the resignation of the acting Interior Minister","cn":"昨天代理内政部长辞职了。"}},{"pos":"VERB 动词","cn":"察看;弄清;了解","en":"You can use see in expressions to do with finding out information. For example, if you say 'I'll see what's happening', you mean that you intend to find out what is happening.","ex":{"en":"Let me just see what the next song is","cn":"我来看看下一首歌是什么。"}},{"pos":"VERB 动词","cn":"想办法，尽力(帮忙)","en":"You can use see to promise to try and help someone. For example, if you say 'I'll see if I can do it', you mean that you will try to do the thing concerned.","ex":{"en":"I'll see if I can call her for you","cn":"我会尽力帮你把她叫来。"}},{"pos":"VERB 动词","cn":"确保;保证","en":"If you see that something is done or if you see to it that it is done, you make sure that it is done.","ex":{"en":"See that you take care of him","cn":"一定要照顾好他。"}},{"pos":"VERB 动词","cn":"护送;陪伴","en":"If you see someone to a particular place, you accompany them to make sure that they get there safely, or to show politeness.","ex":{"en":"He didn't offer to see her to her car","cn":"他没有提出要陪她去取车。"}},{"pos":"VERB 动词","cn":"遇到;拜访","en":"If you see a lot of someone, you often meet each other or visit each other.","ex":{"en":"We used to see quite a lot of his wife, Carolyn","cn":"我们以前经常见到他的妻子卡罗琳。"}},{"pos":"VERB 动词","cn":"与…交往;与…谈恋爱","en":"If you are seeing someone, you spend time with them socially, and are having a romantic or sexual relationship.","ex":{"en":"My husband was still seeing her and he was having an affair with her.","cn":"我的丈夫仍在和她来往，而且两人还搞婚外情。"}},{"pos":"VERB 动词","cn":"(我们)知道，了解","en":"Some writers use see in expressions such as we saw and as we have seen to refer to something that has already been explained or described.","ex":{"en":"We saw in Chapter 16 how annual cash budgets are produced","cn":"在第 16 章我们了解了年度现金预算是怎样制订的。"}},{"pos":"VERB 动词","cn":"(书中)见，参见","en":"See is used in books to indicate to readers that they should look at another part of the book, or at another book, because more information is given there.","ex":{"en":"Surveys consistently find that men report feeling safe on the street after dark. See, for example, Hindelang and Garofalo (1978)","cn":"多项调查一致显示，男性认为天黑后在大街上行走是安全的。比如，参见欣德朗和加罗法洛(1978)。"}},{"pos":"PHRASE 短语","cn":"既然;因为;鉴于","en":"You can use seeing that or seeing as to introduce a reason for what you are saying.","ex":{"en":"He is in the marriage bureau business, which is mildly ironic seeing that his dearest wish is to get married himself","cn":"他从事婚姻介绍工作，这多少有点讽刺意味，因为他最大的愿望就是自己能结婚。"}},{"pos":"CONVENTION 惯用语","cn":"我明白;原来如此","en":"You can say 'I see' to indicate that you understand what someone is telling you.","ex":{"en":"'He came home in my car.' — 'I see.'","cn":"“他坐我的车回家来的。”——“哦，是这样。”"}},{"pos":"CONVENTION 惯用语","cn":"(表示暂不作决定)看看吧，再说吧","en":"People say 'I'll see' or 'We'll see' to indicate that they do not intend to make a decision immediately, and will decide later.","ex":{"en":"We'll see. It's a possibility.","cn":"再说吧，可能会的。"}},{"pos":"CONVENTION 惯用语","cn":"(表示试图记起某事或找到某物)让我想一想，让我看看","en":"People say 'let me see' or 'let's see' when they are trying to remember something, or are trying to find something.","ex":{"en":"Let's see, they're six — no, make that five hours ahead of us","cn":"让我想一想，他们比我们早 6 个——不，就算是早 5 个小时完成。"}},{"pos":"PHRASE 短语","cn":"意识到错误;明白事理","en":"If you try to make someone see sense or see reason, you try to make them realize that they are wrong or are being stupid.","ex":{"en":"He was hopeful that by sitting together they could both see sense and live as good neighbours","cn":"他希望他们坐到一起，彼此能清醒理智，和睦为邻。"}},{"pos":"CONVENTION 惯用语","cn":"(用于向某人解释某事物并鼓励其倾听和理解)你瞧，你知道，看吧","en":"You can say 'you see' when you are explaining something to someone, to encourage them to listen and understand.","ex":{"en":"Well, you see, you shouldn't really feel that way about it","cn":"好了，知道吗，对那件事你真的不应该那么想。"}},{"pos":"CONVENTION 惯用语","cn":"再见;回头见;呆会儿见","en":"'See you', 'be seeing you', and 'see you later' are ways of saying goodbye to someone when you expect to meet them again soon.","ex":{"en":"'Talk to you later.' — 'All right. See you love.'","cn":"“ 回头再跟你谈。”——“好的。再见，亲爱的。”"}},{"pos":"CONVENTION 惯用语","cn":"到时候你就知道了;你等着瞧吧","en":"You can say 'You'll see' to someone if they do not agree with you about what you think will happen in the future, and you believe that you will be proved right.","ex":{"en":"The thrill wears off after a few years of marriage. You'll see.","cn":"婚后几年这种兴奋感就会逐渐消逝。你等着瞧吧。"}},{"pos":"","cn":"","en":"to see the back of someone→see: ; to have n better days→see: ; to be n dead→see: ; as far as the eye can→see: ; to eye to eye→see: ; as far as I can→see: ; to fit→see: ; to the light→see: ; to the light of day→see: ; to red→see: ; it remains to be n→see: ; wait and→see: ;"},{"pos":"","cn":"","en":"相关词组：see about see off see through see to"}]},"examples":[{"en":"The government not only has to do something, it must be seen to be doing something (= people must be aware that it is doing sth).","cn":"政府不仅必须采取措施，而且必须让人们知道它在采取措施。"},{"en":"We should have seen it coming. There was no way he could keep going under all that pressure.","cn":"我们本该料到的。承受着那么大的压力，他不可能坚持下去。"}]},"seriously":{"media":{"uk":"media/uk/seriously__gb_1.mp3","us":"media/us/seriously__us_1.mp3"},"oxford":{"phon":"ˈsɪəriəsli","pos":"adverb","senses":[{"en":"in a serious way","cn":"严重地；严肃地；认真地","ex":{"en":"to be seriously ill/injured/wounded/hurt","cn":"重病；重伤"}},{"en":"used at the beginning of a sentence to show a change from joking to being more serious","cn":"（用于句首，表示转为谈正事）说正经的，说实在的","ex":{"en":"Seriously though, it could be really dangerous.","cn":"不过说实在的，这事说不好真的很危险。"}},{"en":"very; extremely","cn":"非常；极其","lab":"informal","ex":{"en":"They're seriously rich.","cn":"他们极为富有。"}}]},"collins":{"senses":[{"pos":"ADV 副词","cn":"严肃地;认真地;正经地","en":"You use seriously to indicate that you are not joking and that you really mean what you say.","ex":{"en":"Seriously, I only smoke in the evenings.","cn":"真的，我只在晚上抽烟。"}},{"pos":"CONVENTION 惯用语","cn":"(用以询问对方的话是否是认真的)当真,真的.","en":"You say 'seriously' when you are surprised by what someone has said, as a way of asking them if they really mean it.","ex":{"en":"'I tried to chat him up at the general store.' He laughed. 'Seriously?'","cn":"“我在杂货店里试图跟他搭讪来着。”他笑着说。“真的?”"}},{"pos":"PHRASE 短语","cn":"认真对待;把…看得很重要","en":"If you take someone or something seriously, you believe that they are important and deserve attention.","ex":{"en":"It's hard to take them seriously in their pretty grey uniforms","cn":"他们穿着帅气的灰色制服时，很难对他们郑重其事起来。"}}]},"examples":[{"en":"Seriously though, it could be really dangerous.","cn":"不过说实在的，这事说不好真的很危险。"},{"en":"You're not seriously expecting me to believe that?","cn":"你不是真的以为我会相信那样的话吧？"}]},"sensitive":{"media":{"uk":"media/uk/sensitive__gb_1.mp3","us":"media/us/sensitive__us_1.mp3"},"oxford":{"phon":"ˈsensətɪv","pos":"adjective","senses":[{"en":"aware of and able to understand other people and their feelings","cn":"体贴的；体恤的；善解人意的","sc":"to people’s feelings","ex":{"en":"a sensitive and caring man","cn":"体贴的男人"}},{"en":"reacting quickly or more than usual to something","cn":"敏感的；过敏的","sc":"to cold/light/food, etc.","ex":{"en":"sensitive areas of the body","cn":"身体的敏感区"}},{"en":"able to understand art, music and literature and to express yourself through them","cn":"感觉敏锐的；艺术感觉好的；有悟性的","sc":"to art/music/literature","ex":{"en":"an actor’s sensitive reading of the poem","cn":"演员对那首诗富有表现力的朗诵"}},{"en":"easily offended or upset","cn":"易生气的；易被惹恼的；神经过敏的","sc":"easily upset","ex":{"en":"You're far too sensitive.","cn":"你也太敏感了。"}},{"en":"that you have to treat with great care because it may offend people or make them angry or embarrassed","cn":"须谨慎对待的；敏感的","sc":"information/subject","ex":{"en":"sensitive information/data","cn":"敏感信息／资料"}},{"en":"able to measure very small changes","cn":"灵敏的","lab":"figurative","sc":"to small changes","ex":{"en":"a sensitive instrument","cn":"灵敏的仪器"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"体恤的;体贴的;善解人意的","en":"If you are sensitive to other people's needs, problems, or feelings, you show understanding and awareness of them.","ex":{"en":"The classroom teacher must be sensitive to a child's needs","cn":"班主任必须对小学生的需求体察入微。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"易生气的;易担忧的;敏感的","en":"If you are sensitive about something, you are easily worried and offended when people talk about it.","ex":{"en":"Young people are very sensitive about their appearance","cn":"年轻人对外表很在意。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"(问题、话题)敏感的，棘手的，易引起纷争的，须谨慎对待的","en":"A sensitive subject or issue needs to be dealt with carefully because it is likely to cause disagreement or make people angry or upset.","ex":{"en":"Employment is a very sensitive issue.","cn":"就业是一个非常棘手的问题。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"(文件、报告)机密的，须小心对待的，须妥善保管的","en":"Sensitive documents or reports contain information that needs to be kept secret and dealt with carefully.","ex":{"en":"He instructed staff to shred sensitive documents.","cn":"他吩咐员工将机密文件用碎纸机销毁。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"过敏的;易受影响的;敏感的","en":"Something that is sensitive to a physical force, substance, or treatment is easily affected by it and often harmed by it.","ex":{"en":"...a chemical which is sensitive to light.","cn":"对光敏感的化学品"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"(科学仪器)灵敏的，灵敏度高的","en":"A sensitive piece of scientific equipment is capable of measuring or recording very small changes.","ex":{"en":"...an extremely sensitive microscope.","cn":"高灵敏度的显微镜"}}]},"examples":[{"en":"an actor's sensitive reading of the poem","cn":"演员对那首诗富有表现力的朗诵"},{"en":"Health care is a politically sensitive issue.","cn":"医疗卫生是一个政治敏感问题。"}]},"security":{"media":{"uk":"media/uk/security__gb_1.mp3","us":"media/us/security__us_1.mp3"},"oxford":{"phon":"sɪˈkjʊərəti","pos":"noun","senses":[{"en":"the activities involved in protecting a country, building or person against attack, danger, etc.","cn":"保护措施；安全工作","g":"[uncountable]","sc":"protection","ex":{"en":"national/homeland security (= the defence of a country)","cn":"国家／国土安全"}},{"en":"a place at an airport where you go after your passport has been checked so that officials can find out if you are carrying illegal drugs or weapons","cn":"机场安检区","g":"[uncountable]","sc":"protection","ex":{"en":"My bag was emptied and searched when I went through security.","cn":"通过安检时我的包被清空搜查。"}},{"en":"the department of a large company or organization that deals with the protection of its buildings, equipment and staff","cn":"保卫部门；保安部门","g":"[uncountable + singular or plural verb]","sc":"protection","ex":{"en":"Security was/were called to the incident.","cn":"保安人员被叫到事发现场。"}},{"en":"protection against something bad that might happen in the future","cn":"担保；保证","g":"[uncountable]","sc":"protection","ex":{"en":"financial security","cn":"财务担保"}},{"en":"the state of feeling happy and safe from danger or worry","cn":"安全；平安","g":"[uncountable]","sc":"feeling happy/safe","ex":{"en":"the security of a loving family life","cn":"安享天伦之乐"}},{"en":"a valuable item, such as a house, that you agree to give to somebody if you are unable to pay back the money that you have borrowed from them","cn":"抵押品","g":"[uncountable, countable]","sc":"for a loan","ex":{"en":"His home and business are being held as security for the loan.","cn":"他是以房子和店铺为抵押得到这笔贷款的。"}},{"en":"documents proving that somebody is the owner of shares, etc. in a particular company","cn":"证券","g":"[plural]","lab":"finance","sc":"shares in company","ex":{"en":"government securities","cn":"政府证券"}}]},"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"防卫;保安措施;安全工作","en":"Security refers to all the measures that are taken to protect a place, or to ensure that only people with permission enter it or leave it.","ex":{"en":"They are now under a great deal of pressure to tighten their airport security","cn":"他们现在承受着加强机场安保措施的巨大压力。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"安全感;无忧无虑","en":"A feeling of security is a feeling of being safe and free from worry.","ex":{"en":"He loves the security of a happy home life","cn":"他喜欢幸福家庭生活所带来的安全感。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"抵押品","en":"If something is security for a loan, you promise to give that thing to the person who lends you money, if you fail to pay the money back.","ex":{"en":"The central bank will provide special loans, and the banks will pledge the land as security.","cn":"中央银行会提供特殊贷款，而这些银行会以土地作为抵押。"}},{"pos":"N-PLURAL 复数名词","cn":"证券","en":"Securities are stocks, shares, bonds, or other certificates that you buy in order to earn regular interest from them or to sell them later for a profit.","ex":{"en":"National banks can package their own mortgages and underwrite them as securities.","cn":"国家银行能够合并自己的抵押贷款并以证券形式包销。"}}]},"examples":[{"en":"She'd allowed herself to be lulled into a false sense of security (= a feeling that she was safe when in fact she was in danger).","cn":"她不自觉地陷入了一种虚假的安全感之中。"},{"en":"His home and business are being held as security for the loan.","cn":"他是以房子和店铺为抵押得到这笔贷款的。"}]},"self-sacrifice":{"oxford":{"phon":"ˌself ˈsækrɪfaɪs","pos":"noun","senses":[{"en":"the act of not allowing yourself to have or do something in order to help other people","cn":"自我牺牲","ex":{"en":"the courage and self-sacrifice of those who fought in the war","cn":"投身战争的人的勇气和自我牺牲精神"}}]},"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"自我牺牲","en":"Self-sacrifice is the giving up of what you want so that other people can have what they need or want.","ex":{"en":"I thanked my parents for all their self-sacrifice on my behalf.","cn":"我感谢父母为我做出的所有自我牺牲。"}}]},"media":{"uk":"media/uk/self_sacrifice_1_gb_1.mp3","us":"media/us/self_sacrifice_1_us_1.mp3"},"examples":[{"en":"the courage and self-sacrifice of those who fought in the war","cn":"投身战争的人的勇气和自我牺牲精神"},{"en":"several years of hard work and self-sacrifice","cn":"几年的辛苦工作和自我牺牲"}]},"seized":{"oxford":{"phon":"siːz","pos":"verb","senses":[{"en":"to take sb/sth in your hand suddenly and using force","cn":"抓住；捉住；夺"},{"en":"to take control of a place or situation, often suddenly and violently （","cn":"常指通过暴力突然）夺取，攻占，控制"}]}},"seats":{"oxford":{"phon":"siːt","pos":"noun","senses":[{"en":"a place where you can sit, for example a chair","cn":"座位，坐处（如椅子等）"},{"en":"( in nouns and adjectives","cn":"构成名词和形容词 ) with the number of seats mentioned 有 … 座位的；有 … 座的"}]}},"seems":{"oxford":{"phon":"siːm","pos":"linking verb","senses":[{"en":"( not used in the progressive tenses","cn":"不用于进行时 ) to give the impression of being or doing sth （给人印象）好像，似乎，看来"},{"en":"used to make what you say about your thoughts, feelings or actions less strong （","cn":"用以缓和语气）感到好像，觉得似乎"}]}},"seconds":{"oxford":{"phon":"ˈsekənd","pos":"determiner","senses":[{"en":"happening or coming next after the first in a series of similar things or people; 2nd","cn":"第二（的）"},{"en":"next in order of importance, size, quality, etc. to one other person or thing （","cn":"重要性、规模、质量等）居第二位的"}]}},"seminars":{"oxford":{"phon":"ˈsemɪnɑː(r)","pos":"noun","senses":[{"en":"a class at a university or college when a small group of students and a teacher discuss or study a particular topic （","cn":"大学教师带领学生作专题讨论的）研讨班"},{"en":"a meeting for discussion or training","cn":"研讨会；培训会"}]}},"seeing":{"oxford":{"phon":"siː","pos":"verb","senses":[{"en":"( not used in the progressive tenses","cn":"不用于进行时 ) to become aware of sb/sth by using your eyes 看见；见到；看出"},{"en":"( not usually used in the progressive tenses","cn":"通常不用于进行时 ) to have or use the power of sight 看得见；看；有视力"}]},"media":{"uk":"media/ldoce/hwd/bre/2/seeing0205.mp3","us":"media/ldoce/hwd/ame/2/seeing.mp3"},"examples":[{"en":"I won’t stay long, seeing as you’re busy.","cn":"我不会待久﹐看你挺忙的。"},{"en":"Oh, all right, seeing as it’s you (= used to agree humorously to someone’s request ) .","cn":"噢﹐没问题﹐因为是你呀。"}]},"secrets":{"oxford":{"phon":"ˈsiːkrət","pos":"adjective","senses":[{"en":"known about by only a few people; kept hidden from others","cn":"秘密的；保密的；外人不得而知的"},{"en":"used to describe actions and behaviour that you do not tell other people about （","cn":"指行为与习惯）暗中进行的，未公开的，隐秘的"}]}},"selecting":{"oxford":{"phon":"sɪˈlekt","pos":"verb","senses":[{"en":"to choose sb/sth from a group of people or things, usually according to a system","cn":"选择；挑选；选拔"},{"en":"( computing","cn":"计 ) to mark sth on a computer screen; to choose sth, especially from a menu （在计算机屏幕上）选定；（从菜单中）选择，选取"}]}},"sends":{"oxford":{"phon":"send","pos":"verb","senses":[{"en":"to make sth go or be taken to a place, especially by post/mail, email, radio, etc.","cn":"邮寄；发送"},{"en":"to tell sb sth by sending them a message","cn":"传达；转致；告知"}]}},"selected":{"oxford":{"phon":"sɪˈlekt","pos":"verb","senses":[{"en":"to choose sb/sth from a group of people or things, usually according to a system","cn":"选择；挑选；选拔"},{"en":"( computing","cn":"计 ) to mark sth on a computer screen; to choose sth, especially from a menu （在计算机屏幕上）选定；（从菜单中）选择，选取"}]}},"sections":{"oxford":{"phon":"ˈsekʃn","pos":"noun","senses":[{"en":"any of the parts into which sth is divided","cn":"部分；部门"},{"en":"a separate part of a structure from which the whole can be put together","cn":"部件；散件"}]}},"senses":{"oxford":{"phon":"sens","pos":"noun","senses":[{"en":"one of the five powers (sight, hearing, smell, taste and touch) that your body uses to get information about the world around you","cn":"感觉官能（即视、听、嗅、味、触五觉）"},{"en":"a feeling about sth important （","cn":"对重大事情的）感觉，意识"}]}},"sectors":{"oxford":{"phon":"ˈsektə(r)","pos":"noun","senses":[{"en":"a part of an area of activity, especially of a country's economy （","cn":"尤指一国经济的）部门，领域，行业"},{"en":"a part of a particular area, especially an area under military control （","cn":"尤指军事管制的）区域，地带"}]}},"settings":{"oxford":{"phon":"ˈsetɪŋ","pos":"noun","senses":[{"en":"a set of surroundings; the place at which sth happens","cn":"环境；背景"},{"en":"the place and time at which the action of a play, novel, etc. takes place （","cn":"戏剧、小说等的）情节背景"}]}},"services":{"oxford":{"phon":"ˈsɜːvɪs","pos":"noun","senses":[{"en":"a system that provides sth that the public needs, organized by the government or a private company","cn":"公共服务系统；公共事业"},{"en":"an organization or a company that provides sth for the public or does sth for the government","cn":"公共事业机构（或公司）"}]}},"selling":{"oxford":{"phon":"sel","pos":"verb","senses":[{"en":"to give sth to sb in exchange for money","cn":"出让；转让"},{"en":"to offer sth for people to buy","cn":"出售；售卖"}]},"media":{"uk":"media/ldoce/hwd/bre/f/ld44selling.mp3","us":"media/ldoce/hwd/ame/f/ld44selling.mp3"},"examples":[{"en":"a career in selling","cn":"推销工作"}]},"serfs":{"oxford":{"phon":"sɜːf","pos":"noun","senses":[{"en":"(in the past) a person who was forced to live and work on land that belonged to a landowner whom they had to obey （","cn":"旧时的）农奴"}]}},"senators":{"oxford":{"phon":"ˈsenətə(r)","pos":"noun","senses":[{"en":"a member of a senate","cn":"参议员"}]}},"searched":{"oxford":{"phon":"sɜːtʃ","pos":"noun","senses":[{"en":"an attempt to find sb/sth, especially by looking carefully for them/it","cn":"搜索；搜寻；搜查；查找"},{"en":"( computing","cn":"计 ) an act of looking for information in a computer database or network 搜索；检索"}]}},"seas":{"oxford":{"phon":"siː","pos":"noun","senses":[{"en":"( especially BrE ) the salt water that covers most of the earth's surface and surrounds its continents and islands","cn":"海；海洋"},{"en":"( often Sea , especially as part of a name","cn":"常作 Sea，尤作名称的一部分 ) a large area of salt water that is part of an ocean or surrounded by land 海"}]}},"served":{"oxford":{"phon":"sɜːv","pos":"verb","senses":[{"en":"to give sb food or drink, for example at a restaurant or during a meal （","cn":"给某人）提供；端上"},{"en":"to be enough for sb/sth","cn":"够 … 吃（或用）"}]}},"sees":{"oxford":{"phon":"siː","pos":"verb","senses":[{"en":"( not used in the progressive tenses","cn":"不用于进行时 ) to become aware of sb/sth by using your eyes 看见；见到；看出"},{"en":"( not usually used in the progressive tenses","cn":"通常不用于进行时 ) to have or use the power of sight 看得见；看；有视力"}]}},"sentences":{"oxford":{"phon":"ˈsentəns","pos":"noun","senses":[{"en":"( grammar","cn":"语法 ) a set of words expressing a statement, a question or an order, usually containing a subject and a verb. In written "},{"en":"the punishment given by a court","cn":"判决；宣判；判刑"}]}},"securing":{"oxford":{"phon":"sɪˈkjʊə(r)","pos":"adjective","senses":[{"en":"feeling happy and confident about yourself or a particular situation","cn":"安心的；有把握的"},{"en":"likely to continue or be successful for a long time","cn":"可靠的；牢靠的；稳固的"}]}},"seasons":{"oxford":{"phon":"ˈsiːzn","pos":"noun","senses":[{"en":"any of the four main periods of the year: spring, summer, autumn/fall and winter","cn":"季；季节"},{"en":"a period of the year in tropical countries when it is either very dry or it rains a lot （","cn":"热带地区的）旱/雨季"}]}},"serves":{"oxford":{"phon":"sɜːv","pos":"verb","senses":[{"en":"to give sb food or drink, for example at a restaurant or during a meal （","cn":"给某人）提供；端上"},{"en":"to be enough for sb/sth","cn":"够 … 吃（或用）"}]}},"seizes":{"oxford":{"phon":"siːz","pos":"verb","senses":[{"en":"to take sb/sth in your hand suddenly and using force","cn":"抓住；捉住；夺"},{"en":"to take control of a place or situation, often suddenly and violently （","cn":"常指通过暴力突然）夺取，攻占，控制"}]}},"sets":{"oxford":{"phon":"set","pos":"verb","senses":[{"en":"to put sth/sb in a particular place or position","cn":"放；置；使处于"},{"en":"to cause sb/sth to be in a particular state; to start sth happening","cn":"使处于某种状况；使开始"}]}},"seals":{"oxford":{"phon":"siːl","pos":"verb","senses":[{"en":"to close an envelope, etc. by sticking the edges of the opening together","cn":"封上（信封）"},{"en":"to close a container tightly or fill a crack, etc., especially so that air, liquid, etc. cannot get in or out","cn":"密封（容器）"}]}},"seething":{"oxford":{"phon":"siːð","pos":"verb","senses":[{"en":"to be extremely angry about sth but try not to show other people how angry you are","cn":"强压怒火；生闷气"},{"en":"to be full of a lot of people or animals, especially when they are all moving around","cn":"充满，遍布，到处都是（人、动物）"}]}},"sessions":{"oxford":{"phon":"ˈseʃn","pos":"noun","senses":[{"en":"a period of time that is spent doing a particular activity","cn":"一场；一节；一段时间"},{"en":"a formal meeting or series of meetings of a court, a parliament, etc; a period of time when such meetings are held （","cn":"法庭的）开庭，开庭期；（议会等的）会议，会期"}]}},"seemed":{"oxford":{"phon":"siːm","pos":"linking verb","senses":[{"en":"( not used in the progressive tenses","cn":"不用于进行时 ) to give the impression of being or doing sth （给人印象）好像，似乎，看来"},{"en":"used to make what you say about your thoughts, feelings or actions less strong （","cn":"用以缓和语气）感到好像，觉得似乎"}]}},"sensed":{"oxford":{"phon":"sens","pos":"noun","senses":[{"en":"one of the five powers (sight, hearing, smell, taste and touch) that your body uses to get information about the world around you","cn":"感觉官能（即视、听、嗅、味、触五觉）"},{"en":"a feeling about sth important （","cn":"对重大事情的）感觉，意识"}]}},"secretaries":{"oxford":{"phon":"ˈsekrətri","pos":"noun","senses":[{"en":"a person who works in an office, working for another person, dealing with letters and telephone calls, typing, keeping records, arranging meetings with people, etc.","cn":"秘书"},{"en":"an official of a club, society, etc. who deals with writing letters, keeping records, and making business arrangements （","cn":"俱乐部、社团等的）干事，文书"}]}},"sectarian":{"collins":{"senses":[{"pos":"ADJ 形容词","cn":"宗派的;教派的","en":"Sectarian means resulting from the differences between different religions.","ex":{"en":"He was the fifth person to be killed in sectarian violence","cn":"他是宗派暴力中的第 5 个罹难者。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"violence etc that is related to the strong feelings of people who belong to different religious groups","cn":"教派之间的暴力/冲突/谋杀等"},{"en":"supporting a particular religious group and its beliefs","cn":"宗派的﹐教派的"}]},"vocab":{"pos":"adj n","senses":[{"en":"Sectarian is a word to describe something having to do with smaller groups or sects. Sectarian violence, for example, would describe violence that has erupted between conflicting groups or sects."}]},"media":{"uk":"media/ldoce/hwd/bre/7/sectarian0205.mp3","us":"media/ldoce/hwd/ame/b/sectarian.mp3"},"examples":[{"en":"attempts to break down the sectarian divide in Northern Ireland","cn":"旨在消除北爱尔兰的宗教派系分歧的努力"},{"en":"sectarian attacks/violence","cn":"教派攻击/暴力活动"}],"oxford":{"phon":"sekˈteəriən","pos":"adjective","senses":[{"en":"connected with the differences that exist between groups of people who have different religious views","cn":"（宗教）教派的，派性的","ex":{"en":"sectarian attacks/violence","cn":"教派攻击／暴力活动"}}]}},"serfdom":{"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"农奴制度","en":"The system of serfdom was the social and economic system by which the owners of land had serfs."},{"pos":"N-UNCOUNT 不可数名词","cn":"农奴身份;农奴地位","en":"If someone was in a state of serfdom, they were a serf."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"the system of using serfs, or the state of being a serf","cn":"农奴制﹔农奴身份"}]},"media":{"uk":"media/ldoce/hwd/bre/2/ld41serfdom.mp3","us":"media/ldoce/hwd/ame/9/serfdom.mp3"},"examples":[{"en":"the abolition of serfdom in Russia in 1861 * 1861","cn":"年农奴制在俄国的废除"},{"en":"the abolition of serfdom in Russia in 1861","cn":""}],"oxford":{"phon":"ˈsɜːfdəm","pos":"noun","senses":[{"en":"the system under which crops were grown by serfs; the state of being a serf","cn":"农奴制；农奴身份","ex":{"en":"the abolition of serfdom in Russia in 1861","cn":"1861 年农奴制在俄国的废除"}}]}},"separatist":{"collins":{"senses":[{"pos":"ADJ 形容词","cn":"分裂主义的;独立主义的","en":"Separatist organizations and activities within a country involve members of a group of people who want to establish their own separate government or are trying to do so.","ex":{"en":"...the Basque separatist movement","cn":"巴斯克分裂主义运动"}},{"pos":"N-COUNT 可数名词","cn":"分裂主义者;独立主义者","en":"Separatists are people who want their own separate government or are involved in separatist activities.","ex":{"en":"The army has come under attack by separatists.","cn":"军队一直遭到分裂主义者的袭击。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"someone who belongs to a group that wants to start a new country with its own government, by separating from the country that they belong to now","cn":"分离主义者﹐独立主义者"}]},"media":{"uk":"media/ldoce/hwd/bre/9/separatist0205.mp3","us":"media/ldoce/hwd/ame/7/laadseparatist.mp3"},"examples":[{"en":"Basque separatists","cn":"巴斯克分裂主义者"},{"en":"a separatist movement","cn":"分离主义运动"}],"oxford":{"phon":"ˈseprətɪst","pos":"adjective","senses":[{"en":"connected with separatism","cn":"分离主义的；分离主义者的","ex":{"en":"a separatist movement","cn":"分离主义运动"}},{"en":"a member of a group of people within a country who want to separate from the rest of the country and form their own government","cn":"分离主义者；独立主义者","ex":{"en":"Basque separatists","cn":"巴斯克分裂主义者"},"pos":"noun"}]}},"self-effacing":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"自我谦避的;不求闻达的","en":"Someone who is self-effacing does not like talking about themselves or drawing attention to themselves.","ex":{"en":"As women we tend to be self-effacing and make light of what we have achieved.","cn":"作为女性我们往往不喜夸耀，对自己获得的成功轻描淡写。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"not wanting to talk about your abilities or achievements and to say that you are good at something, even when you are – used to show approval","cn":""},{"en":"not wanting to talk about yourself or to attract attention","cn":""},{"en":"not wanting to be noticed and not expecting to be treated in a special way","cn":""}]},"vocab":{"pos":"adj","senses":[{"en":"Someone who's self-effacing is shy and likes to stay out of the spotlight, shunning attention and praise."}]},"media":{"uk":"media/ldoce/hwd/bre/e/self_effacing0205.mp3","us":"media/ldoce/hwd/ame/2/self-effacing.mp3"},"examples":[{"en":"He was a shy, self-effacing man.","cn":"他是个腼腆谦逊的人。"},{"en":"a quiet self-effacing man","cn":"一个沉默寡言﹑谦虚持重的人"}],"oxford":{"phon":"ˌself ɪˈfeɪsɪŋ","pos":"adjective","senses":[{"en":"not wanting to attract attention to yourself or your abilities","cn":"谦逊的；不求闻达的","ex":{"en":"He was a shy, self-effacing man.","cn":"他是个腼腆谦逊的人。"}}]}},"self-examination":{"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"自省;自察","en":"Self-examination is thought that you give to your own character and actions, for example in order to judge whether you have been behaving in a way that is acceptable to your own set of values.","ex":{"en":"The events in Los Angeles have sparked a new national self-examination","cn":"发生在洛杉矶的事件再次引发了全国范围的反思。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"(对身体的)自我检查","en":"Self-examination is the act of examining your own body to check whether or not you have any signs of a particular disease or illness.","ex":{"en":"Breast self-examination is invaluable for detecting cancer in its very early stages.","cn":"乳房自检对早期癌症的发现是极为重要的。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"careful thought about whether your actions and your reasons for them are right or wrong","cn":"自省﹐〔对自己行为等的〕反省"},{"en":"the practice of checking parts of your body for early signs of some illnesses 〔","cn":"对身体的〕自我检查"}]},"media":{"uk":"media/ldoce/hwd/bre/1/ld41self-examinati.mp3","us":"media/ldoce/hwd/ame/5/self-examination.mp3"},"oxford":{"phon":"ˌself ɪɡˌzæmɪˈneɪʃn","pos":"noun","senses":[{"en":"the study of your own behaviour and beliefs to find out if they are right or wrong","cn":"自省；反省","ex":{"en":"spiritual self-examination","cn":"精神上的自我审视"}},{"en":"the act of checking your body for any signs of illness","cn":"（对身体的）自我检查"}]}},"seedy":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"邋遢的;脏乱的;声名狼藉的","en":"If you describe a person or place as seedy, you disapprove of them because they look dirty and untidy, or they have a bad reputation.","ex":{"en":"Frank ran dodgy errands for a seedy local villain","cn":"弗兰克为当地一个臭名远扬的恶棍跑腿，干些骗人勾当。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"a seedy person or place looks dirty or poor, and is often connected with illegal or immoral activities 〔","cn":"人〕肮脏的﹔〔地方〕乌烟瘴气的﹔不正派的"}]},"vocab":{"pos":"adj","senses":[{"en":"When a place is seedy , it's sleazy, run-down — not the kind of place you'd take your mom. The East Village of New York was once known for being seedy , but now it's safe for children of all ages."}]},"media":{"uk":"media/ldoce/hwd/bre/4/seedy0205.mp3","us":"media/ldoce/hwd/ame/b/seedy.mp3"},"examples":[{"en":"the seedy world of prostitution","cn":"乌烟瘴气的卖淫圈子"},{"en":"a seedy bar","cn":"污七八糟的酒吧"}],"oxford":{"phon":"ˈsiːdi","pos":"adjective","senses":[{"en":"dirty and unpleasant, possibly connected with bad or illegal activities","cn":"肮脏的；污七八糟的；乌烟瘴气的；下流的","ex":{"en":"a seedy bar","cn":"污七八糟的酒吧"}}]}},"second-class":{"collins":{"senses":[{"pos":"ADJ 形容词","cn":"二等的;无足轻重的;地位低下的","en":"If someone treats you as a second-class citizen, they treat you as if you are less valuable and less important than other people.","ex":{"en":"Too many airlines treat our children as second-class citizens.","cn":"太多的航空公司把我们的孩子当作二等公民对待。"}},{"pos":"ADJ 形容词","cn":"次等的;劣质的","en":"If you describe something as second-class, you mean that it is of poor quality.","ex":{"en":"I am not prepared to see children in some parts of this country having to settle for a second-class education.","cn":"我没有料到会发现在这个国家的一些地区孩子们只能接受二流的教育。"}},{"pos":"ADJ 形容词","cn":"(车厢、舱位)二等的,普通的","en":"The second-class accommodation on a train or ship is the ordinary accommodation, which is cheaper and less comfortable than the first-class accommodation.","ex":{"en":"He sat in the corner of a second-class carriage","cn":"他坐在一节二等车厢的角落里。"}},{"pos":"ADJ 形容词","cn":"(邮件)第二类的,(英国)廉价慢递的,(美国)投递报刊的","en":"In Britain, second-class postage is the slower and cheaper type of postage. In the United States, second-class postage is the type of postage that is used for sending newspapers and magazines.","ex":{"en":"...a second-class stamp.","cn":"第二类邮件所贴的邮票"}},{"pos":"ADJ 形容词","cn":"(英国的大学学位)二级优等的","en":"In Britain, a second-class degree is a good university degree, but not as good as a first-class degree.","ex":{"en":"A second-class honours degree is the minimum requirement.","cn":"至少须获得二级优等荣誉学位。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"considered to be less important and less valuable than other people","cn":"二等的﹐次等的﹐较差的"},{"en":"of a lower standard or quality than the best 〔","cn":"标准﹑质量〕次等的﹐二流的"},{"en":"tickets etc that are for cheaper, less comfortable seats on a train or ship","cn":"二等票/票价/车厢/舱等"}]},"media":{"uk":"media/ldoce/hwd/bre/a/brelasdesecond-class.mp3","us":"media/ldoce/hwd/ame/e/second-class.mp3"},"examples":[{"en":"Older people should not be treated as second-class citizens.","cn":"不应把老年人当二等公民对待。"},{"en":"Applicants should have at least a second-class honours degree.","cn":"申请者须有二级优等以上学位。"}],"oxford":{"phon":"ˌsekənd ˈklɑːs","pos":"noun","senses":[{"en":"a way of travelling on a train or ship that costs less and is less comfortable than first class. In the UK this is now usually called standard class.","cn":"（火车的）二等车厢；（船的）二等舱","g":"[uncountable]"},{"en":"(in the UK) the class of mail that costs less and takes longer to arrive than first class","cn":"第二类邮件（在英国投递较第一类邮件慢，邮资也较低）","g":"[uncountable]","ex":{"en":"Second class is cheaper.","cn":"二等舱比较便宜。"}},{"en":"(in the US) the system of sending newspapers and magazines by mail","cn":"第二类邮件（美国报刊投递类别）","g":"[uncountable]"},{"en":"the second highest standard of degree given by a British university, often divided into upper second class and lower second class","cn":"二等学位（英国大学学位等级）","g":"[uncountable, singular]"},{"en":"using the cheaper, second-class service","cn":"第二类邮件（美国报刊投递类别）","ex":{"en":"to send a letter second class","cn":"按第二类邮件投递信件"},"pos":"adverb"},{"en":"less important than other people","cn":"次要的；无足轻重的","lab":"disapproving","ex":{"en":"Older people should not be treated as second-class citizens.","cn":"不应把老年人当二等公民对待。"},"pos":"adjective"},{"en":"of a lower standard or quality than the best","cn":"（质量、标准等）二流的，次等的","ex":{"en":"a second-class education","cn":"二流的教育"},"pos":"adjective"},{"en":"connected with the less expensive way of travelling on a train, ship, etc.","cn":"（车厢、船舱等）二等的","g":"[only before noun]","ex":{"en":"second-class carriages/compartments/passengers","cn":"二等车厢／隔间／车厢乘客"},"pos":"adjective"},{"en":"(in the UK) connected with letters, packages, etc. that you pay less to send and that are delivered less quickly","cn":"第二类的（英国邮件等级，投递较第一类慢，邮资也较低）","g":"[only before noun]","ex":{"en":"second-class letters/stamps","cn":"第二类信件；第二类邮件所贴的邮票"},"pos":"adjective"},{"en":"(in the US) connected with the system of sending newspapers and magazines by mail","cn":"第二类的（美国邮件等级，用于投递报刊）","pos":"adjective"},{"en":"used to describe a British university degree which is good but not of the highest class","cn":"二等的（英国大学学位）","g":"[only before noun]","ex":{"en":"Applicants should have at least a second-class honours degree.","cn":"申请者须有二等以上学位。"},"pos":"adjective"}]}},"serenity":{"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"very calm or peaceful","cn":""}]},"vocab":{"pos":"n","senses":[{"en":"The goal of meditation is to reach a state of serenity , when you mind is still and perfectly calm. Use serenity to mean the quality or state of being calm and peaceful."}]},"collocations":{"phrases":["ADJ. absolute Her face had an expression of absolute serenity. | comparative She escaped to the comparative serenity of the kitchen.","VERB + SERENITY achieve, find","PREP. with ~ She was able to face death with serenity. | ~ of older people who have achieved a serenity of understanding","PHRASES a feeling of serenity"]},"media":{"uk":"media/ldoce/hwd/bre/c/serene0205.mp3","us":"media/ldoce/hwd/ame/b/serene.mp3"},"examples":[{"en":"The hotel offers a haven of peace and serenity away from the bustle of the city.","cn":"那家旅馆远离闹市，是一个幽静安谧的好去处。"},{"en":"The child’s face was serene and beautiful.","cn":""}],"oxford":{"phon":"səˈrenəti","pos":"noun","senses":[{"en":"the quality of being calm and peaceful","cn":"安详，宁静，平静","ex":{"en":"The hotel offers a haven of peace and serenity away from the bustle of the city.","cn":"那家旅馆远离闹市，是一个幽静安谧的好去处。"}}]}},"sequin":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"(装饰衣服的)闪光小圆片,小亮片","en":"Sequins are small, shiny discs that are sewn on clothes to decorate them.","ex":{"en":"The frocks were covered in sequins, thousands of them.","cn":"裙子上点缀着无数亮闪闪的小圆片。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a small shiny flat piece of metal, sewn onto clothes for decoration 〔","cn":"装饰衣服用的〕闪光金属小圆片"}]},"media":{"uk":"media/ldoce/hwd/bre/7/sequin0205.mp3","us":"media/ldoce/hwd/ame/3/sequin.mp3"},"oxford":{"phon":"ˈsiːkwɪn","pos":"noun","senses":[{"en":"a small round shiny disc sewn onto clothing as decoration","cn":"（装饰衣服的）闪光小圆片","ex":{"en":"a dress covered in gold sequins","cn":"布满金色亮片的连衣裙"}}]}},"self-contained":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"自给的;独立自足的","en":"You can describe someone or something as self-contained when they are complete and separate and do not need help or resources from outside.","ex":{"en":"He seems completely self-contained and he doesn't miss you when you're not there","cn":"他似乎十分独立，你不在的时候也并不想念你。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"(住宿场所)设施齐全的，独门独户的","en":"Self-contained accommodation such as a flat has all its own facilities, so that a person living there does not have to share rooms such as a kitchen or bathroom with other people."}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"complete and not needing other things or help from somewhere else to work","cn":"配套齐全的﹐自成体系的"},{"en":"someone who is self-contained does not seem to need other people or show their feelings 〔","cn":"人〕独立自主的﹐感情不外露的"},{"en":"a self-contained apartment has its own kitchen and bathroom 〔","cn":"公寓〕有独立设备的﹔设备齐全的〔指有独立的厨房和卫生间〕"}]},"collocations":{"phrases":["VERBS be, seem | become","ADV. extremely, very | completely, entirely, quite, totally, wholly The flat is completely self-contained. | largely a largely self-containe"]},"media":{"uk":"media/ldoce/hwd/bre/1/self_contained0205.mp3","us":"media/ldoce/hwd/ame/e/self-contained.mp3"},"examples":[{"en":"Her father was a quiet self-contained man.","cn":"她父亲生前是个好静而独立自主的人。"},{"en":"Each chapter is self-contained and can be studied in isolation.","cn":"每一章均自成一篇，可单独学习。"}],"oxford":{"phon":"ˌself kənˈteɪnd","pos":"adjective","senses":[{"en":"not needing or depending on other people","cn":"（指人）独立的，自立的","ex":{"en":"Her father was a quiet, self-contained man.","cn":"她父亲生前是个沉默寡言而独立自主的人。"}},{"en":"able to operate or exist without outside help or influence","cn":"（指事物）自给的，独立的","ex":{"en":"a self-contained community","cn":"自给自足的社会"}},{"en":"having its own kitchen, bathroom and entrance","cn":"独门独户的；设施齐全的","g":"[usually before noun]","lab":"British English","ex":{"en":"self-contained accommodation","cn":"独门独户、设施齐全的住处"}}]}},"seesaw":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"跷跷板","en":"A seesaw is a long board which is balanced on a fixed part in the middle. To play on it, a child sits on each end, and when one end goes up, the other goes down.","ex":{"en":"There was a sandpit, a seesaw and a swing in the playground.","cn":"游乐场上有一处沙坑、一块跷跷板和一个秋千架。"}},{"pos":"ADJ 形容词","cn":"来回往复的;拉锯式的","en":"In a seesaw situation, something continually changes from one state to another and back again.","ex":{"en":"...a seesaw price situation.","cn":"价格来回波动"}},{"pos":"VERB 动词","cn":"(感情或某种局面)摇摆不定，不断反复，来回波动","en":"If someone's emotions see-saw, or a particular situation seesaws, they continually change from one state to another and back again.","ex":{"en":"The Tokyo stock market seesawed up and down.","cn":"东京股市涨落不定。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a piece of equipment that children play on, made of a board that is balanced in the middle, so that when one end goes up the other goes down","cn":"跷跷板"},{"en":"a repeated movement from one state or condition to another and back again","cn":"拉锯局面﹐不断起伏的状态"},{"en":"to keep changing from one state or condition to another and back again","cn":"摇摆不定﹐时起时落"}]},"media":{"img":["media/ldoce/img/seesaw.jpg"],"uk":"media/ldoce/hwd/bre/6/seesaw_v0205.mp3","us":"media/ldoce/hwd/ame/3/seesaw1.mp3"},"examples":[{"en":"Before the election, the president seesawed in the polls.","cn":"大选之前﹐总统在民意测验中的情况时好时坏。"}]},"sewerage":{"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"排水系统;下水道系统;污水处理系统","en":"Sewerage is the system by which waste matter is carried away in sewers and made harmless.","ex":{"en":"The town has already put in a proper sewerage system.","cn":"小镇已经安装了合理的污水处理系统。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"the system by which waste material and used water are carried away in sewers and then treated to stop them being harmful","cn":"污水处理系统，下水道系统"}]},"media":{"uk":"media/ldoce/hwd/bre/e/ld41sewerage.mp3","us":"media/ldoce/hwd/ame/c/sewerage.mp3"},"oxford":{"phon":"ˈsuːərɪdʒ","pos":"noun","senses":[{"en":"the system by which sewage is carried away from houses, factories, etc. and is cleaned and made safe by adding chemicals to it","cn":"排水系统；污水处理","ex":{"en":"an increase in water and sewerage charges","cn":"水费和排污费增加"}}]}},"self-confessed":{"collins":{"senses":[{"pos":"ADJ 形容词","cn":"自己承认的;自己坦白的","en":"If you describe someone as a self-confessed murderer or a self-confessed romantic, for example, you mean that they admit openly that they are a murderer or a romantic.","ex":{"en":"The self-confessed drug addict was arrested 13 months ago","cn":"那个自己坦白的瘾君子在 13 个月前被逮捕。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"admitting that you have a particular quality, especially one that is bad 〔","cn":"尤指对坏事〕自己承认的﹐自动坦白的"}]},"media":{"uk":"media/ldoce/hwd/bre/0/ld41self-confessed.mp3","us":"media/ldoce/hwd/ame/d/self-confessed.mp3"},"examples":[{"en":"a self-confessed thief","cn":"自首的窃贼"},{"en":"a self-confessed drug addict","cn":"自己坦白的吸毒者"}],"oxford":{"phon":"ˌself kənˈfest","pos":"adjective","senses":[{"en":"admitting that you are a particular type of person or have a particular problem, especially a bad one","cn":"自己承认的；自己坦白的","ex":{"en":"a self-confessed thief","cn":"自首的窃贼"}}]}},"serviceman":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"男军人","en":"A serviceman is a man who is in the army, navy, or air force."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"someone who is in the army, especially someone who is not an officer","cn":""},{"en":"soldiers, especially those who are taking part in a military attack","cn":""},{"en":"a man or woman who is in the army, air force, or navy","cn":""}]},"media":{"uk":"media/ldoce/hwd/bre/f/serviceman0205.mp3","us":"media/ldoce/hwd/ame/f/serviceman.mp3"},"oxford":{"phon":"ˈsɜːvɪsmən","pos":"noun","senses":[{"en":"a man who is a member of the armed forces","cn":"（男、女）军人","lab":"British English"}]}},"sear":{"collins":{"senses":[{"pos":"VERB 动词","cn":"烧掉…的表面;烧焦","en":"To sear something means to burn its surface with a sudden intense heat.","ex":{"en":"Grass fires have seared the land near the farming village of Basekhai.","cn":"草地野火烧焦了巴斯克亥农庄附近的土地。"}},{"pos":"VERB 动词","cn":"烧灼;灼伤;灼痛","en":"If something sears a part of your body, it causes a painful burning feeling there.","ex":{"en":"I distinctly felt the heat start to sear my throat.","cn":"我分明感觉到嗓子开始烧得难受。"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to burn something with a sudden powerful heat","cn":"烙﹐烧灼"},{"en":"to have a very strong sudden and unpleasant effect on you","cn":"给…留下极不愉快的感觉﹐铭刻"},{"en":"to cook the outside of a piece of meat quickly at a high temperature, in order to keep its juices in","cn":"把〔肉〕用高温快煎〔以锁住肉汁〕"}]},"vocab":{"pos":"v adj","senses":[{"en":"To sear something is to quickly cook or burn its surface by applying intense heat. When making beef stew, the color and flavor are usually better if you sear the meat first."}]},"media":{"uk":"media/ldoce/hwd/bre/e/sear0205.mp3","us":"media/ldoce/hwd/ame/a/sear1.mp3"},"examples":[{"en":"Sear the meat first (= cook the outside of it quickly at a high temperature) to retain its juices.","cn":"先把肉稍煎一下以保持肉汁。"},{"en":"The heat of the sun seared their faces.","cn":"烈日把他们的脸都晒伤了。"}],"oxford":{"phon":"sɪə(r)","pos":"verb","senses":[{"en":"to burn the surface of something in a way that is sudden and powerful","cn":"烧灼；灼伤；烤焦；轻煎","g":"[transitive]","ex":{"en":"The heat of the sun seared their faces.","cn":"烈日把他们的脸都晒伤了。"}},{"en":"to cause somebody to feel sudden and great pain","cn":"使骤然感到剧痛","g":"[intransitive, transitive]","lab":"formal","ex":{"en":"The pain seared along her arm.","cn":"她的胳膊一阵剧痛。"}}]}},"segregate":{"collins":{"senses":[{"pos":"VERB 动词","cn":"使隔离;使分开;使分离","en":"To segregate two groups of people or things means to keep them physically apart from each other.","ex":{"en":"Police segregated the two rival camps of protesters","cn":"警察把两个敌对阵营的抗议人群隔离开来。"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to divide something into two or more parts or groups, or to divide one type of thing from another. You use separate especially when saying that the parts are different from each other","cn":""},{"en":"to make something become two or more parts or groups","cn":""},{"en":"to separate something into two or more groups, parts etc – used especially when each part is equal in size","cn":""}]},"vocab":{"pos":"v n","senses":[{"en":"To separate people by race or religion is to segregate them. In general, the word segregate means to separate one type of thing from another."}]},"collocations":{"phrases":["ADV. strictly","PREP. according to, by Jobs were strictly segregated by gender. | from The women were segregated from the male workers in the factory. | int","PHRASES highly segregated Women's work has always been highly segregated. | racially/socially segregated"]},"media":{"uk":"media/ldoce/hwd/bre/1/segregate0205.mp3","us":"media/ldoce/hwd/ame/f/segregate.mp3"},"examples":[{"en":"In all our restaurants, smoking and non-smoking areas are segregated from each other.","cn":"在我们所有的餐馆中，吸烟区和非吸烟区都是分开的。"},{"en":"a segregated school (= one for students of one race or religion only)","cn":"单一种族（或信仰）的学校"}],"oxford":{"phon":"ˈseɡrɪɡeɪt","pos":"verb","senses":[{"en":"to separate people of different races, religions or sexes and treat them in a different way","cn":"隔离并区别对待（不同种族、宗教或性别的人）","ex":{"en":"a culture in which women are segregated from men","cn":"妇女受到隔离歧视的文化"}},{"en":"to keep one thing separate from another","cn":"（使）分开，分离，隔离","ex":{"en":"Pedestrians are segregated from the traffic by a metal barrier.","cn":"铁栅栏把行人与来往车辆隔开。"}}]}},"seedless":{"collins":{"senses":[{"pos":"ADJ 形容词","cn":"(水果)无籽的，无核的","en":"A seedless fruit has no seeds in it.","ex":{"en":"...seedless grapes.","cn":"无籽儿葡萄"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"seedless fruit has no seeds in it 〔","cn":"水果〕无籽的﹐无核的"}]},"media":{"uk":"media/ldoce/hwd/bre/0/seedless0205.mp3","us":"media/ldoce/hwd/ame/2/amelasdeseedless.mp3"},"examples":[{"en":"seedless grapes","cn":"无籽葡萄"}],"oxford":{"phon":"ˈsiːdləs","pos":"adjective","senses":[{"en":"having no seeds","cn":"无籽的；无核的","ex":{"en":"seedless grapes","cn":"无籽葡萄"}}]}},"sesame":{"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"芝麻","en":"Sesame is a plant grown for its seeds and oil, which are used in cooking.","ex":{"en":"...sesame seeds","cn":"芝麻籽"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a tropical plant grown for its seeds and oil and used in cooking","cn":"芝麻"}]},"media":{"uk":"media/ldoce/hwd/bre/c/ld41sesame.mp3","us":"media/ldoce/hwd/ame/2/sesame.mp3"},"examples":[{"en":"sesame seeds","cn":"芝麻粒儿"}],"oxford":{"phon":"ˈsesəmi","pos":"noun","senses":[{"en":"a tropical plant grown for its seeds and their oil, which are used in cooking","cn":"芝麻；脂麻","ex":{"en":"sesame seeds","cn":"芝麻粒儿"}}]}},"serbo-croat":{"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"(前南斯拉夫使用的)塞尔维亚－克罗地亚语","en":"Serbo-Croat is one of the languages spoken in the former Yugoslavia."}]}},"seize":{"collins":{"senses":[{"pos":"VERB 动词","cn":"(迅速有力地)抓住，捉住","en":"If you seize something, you take hold of it quickly, firmly, and forcefully.","ex":{"en":"'Leigh,' he said seizing my arm to hold me back.","cn":"“莉，”他说着一把抓住我的胳膊把我拉了回来。"}},{"pos":"VERB 动词","cn":"(通过暴力突然迅速地)夺取，攻占，控制","en":"When a group of people seize a place or seize control of it, they take control of it quickly and suddenly, using force.","ex":{"en":"Troops have seized the airport and railroad terminals","cn":"军队已控制了机场和火车站。"}},{"pos":"VERB 动词","cn":"(通常指通过武力)起获，没收，扣押","en":"If a government or other authority seize someone's property, they take it from them, often by force.","ex":{"en":"Police were reported to have seized all copies of this morning's edition of the newspaper","cn":"据说警方已经将该报纸今天的早间版全部没收。"}},{"pos":"VERB 动词","cn":"逮捕;捉拿;俘获","en":"When someone is seized, they are arrested or captured.","ex":{"en":"UN officials say two military observers were seized by the Khmer Rouge yesterday","cn":"联合国官员称昨天有两名军事观察员被红色高棉逮捕。"}},{"pos":"VERB 动词","cn":"抓住，把握(机会)","en":"When you seize an opportunity, you take advantage of it and do something that you want to do.","ex":{"en":"During the riots hundreds of people seized the opportunity to steal property","cn":"在暴乱中成百上千的人纷纷趁机偷窃财物。"}},{"pos":"","cn":"","en":"相关词组：seize on seize up"}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to have something in your hand, hands, or arms","cn":""},{"en":"to hold something very tightly and not let it go","cn":""},{"en":"to hold something tightly, especially because you do not want to drop or lose it","cn":""}]},"vocab":{"pos":"v","senses":[{"en":"Infomercial salesmen constantly tell you to seize the opportunity to buy their product while you still can. Supplies are limited! After all, everyone will want that solar-powered puppy petter, so you'd better grab the opportunity and buy two!"}]},"collocations":{"phrases":["ADV. immediately, suddenly He was immediately seized and thrown into prison.","PREP. by She seized him by the arm. | from He seized the book from her hand.","PHRASES seize hold of sb/sth The wrestlers try to seize hold of each other. 2 take sth","ADV. immediately, promptly She promptly seized the opportunity his absence gave her. | eagerly, gratefully","VERB + SEIZE be quick to, be ready to He was quick to seize on this idea. | be determined to | attempt to, try to | fail to He had failed to","PREP. on/upon The rumours were eagerly seized on by the local press.","PHRASES an attempt to seize sth"]},"media":{"uk":"media/ldoce/hwd/bre/e/seize0205.mp3","us":"media/ldoce/hwd/ame/2/seize.mp3"},"examples":[{"en":"The rumours were eagerly seized upon by the local press.","cn":"当地报章迫不及待地对这些传闻加以炒作。"},{"en":"A large quantity of drugs was seized during the raid.","cn":"在这次突击行动中起获了大量毒品。"}],"oxford":{"phon":"siːz","pos":"verb","senses":[{"en":"to take somebody/something in your hand suddenly and using force","cn":"抓住；捉住；夺","g":"[transitive]","ex":{"en":"She tried to seize the gun from him.","cn":"她试图夺他的枪。"}},{"en":"to take control of a place or situation, often suddenly and violently","cn":"（常指通过暴力突然）夺取，攻占，控制","g":"[transitive]","ex":{"en":"They seized the airport in a surprise attack.","cn":"他们突袭攻占了机场。"}},{"en":"to arrest or capture somebody","cn":"逮捕；捉拿；俘获","g":"[transitive]","ex":{"en":"The men were seized as they left the building.","cn":"这些人在离开那栋房子时被抓获。"}},{"en":"to take illegal or stolen goods away from somebody","cn":"起获；没收；扣押","g":"[transitive]","ex":{"en":"A large quantity of drugs was seized during the raid.","cn":"在这次突击行动中起获了大量毒品。"}},{"en":"to be quick to make use of a chance, an opportunity, etc.","cn":"抓住，把握（机会、时机、主动等）","g":"[transitive]","ex":{"en":"The party seized the initiative with both hands (= quickly and with enthusiasm).","cn":"该党迅速掌握主动。"}},{"en":"to affect somebody suddenly and deeply","cn":"突然侵袭；突然控制","g":"[transitive]","ex":{"en":"Panic seized her.","cn":"她突然惊慌失措。"}},{"en":"if a machine seizes, it no longer works because the parts are stuck and cannot move","cn":"抓住：如果机器抓住了，它就不再工作，因为零件被卡住并且无法移动","g":"[intransitive]","lab":"North American English"},{"en":"if a part of your body seizes, you are unable to move it easily and it is often painful","cn":"（身体）发僵","lab":"North American English"}]}},"sew":{"collins":{"senses":[{"pos":"VERB 动词","cn":"缝制;缝合;缝补","en":"When you sew something such as clothes, you make them or repair them by joining pieces of cloth together by passing thread through them with a needle.","ex":{"en":"She sewed the dresses on the sewing machine","cn":"她在缝纫机上缝制衣服。"}},{"pos":"VERB 动词","cn":"(医生)缝合(手、手指等)","en":"When something such as a hand or finger is sewn back by a doctor, it is joined with the patient's body using a needle and thread.","ex":{"en":"The hand was preserved in ice by neighbours and sewn back on in hospital","cn":"手被邻居用冰块保存起来了，在医院又被缝合好了。"}},{"pos":"","cn":"","en":"相关词组：sew up"}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"successfully finish an agreement, especially one that is important and involves a large number of people","cn":""},{"en":"to finish a meeting, a business agreement, or a plan by settling everything quickly in a satisfactory way","cn":""},{"en":"to settle a business agreement or plan in a satisfactory way, especially in a way that is favourable to you","cn":""}]},"vocab":{"pos":"v","senses":[{"en":"Sew describes stitching something together. If you sew up the holes in your socks, you use thread and a needle to close them."}]},"collocations":{"phrases":["ADV. carefully, neatly The squares of fabric were all sewn neatly together. | on, together, up I sewed on three buttons. He sewed up the tea","PREP. onto He sewed the patch onto the back of his trousers."]},"media":{"uk":"media/ldoce/hwd/bre/1/brelasdesew.mp3","us":"media/ldoce/hwd/ame/4/sew.mp3"},"examples":[{"en":"It didn't take me long to sew up the deal.","cn":"我没费多大工夫就把那桩生意做成了。"},{"en":"They think they have the election sewn up (= they think they are definitely going to win).","cn":"他们认为这次选举他们已万无一失。"}],"oxford":{"phon":"səʊ","pos":"verb","senses":[{"en":"to use a needle and thread to make stitches in cloth","cn":"缝；做针线活","g":"[intransitive, transitive]","ex":{"en":"My mother taught me how to sew.","cn":"我母亲教我做针线。"}},{"en":"to make, repair or attach something using a needle and thread","cn":"缝制；缝补；缝上","g":"[transitive]","ex":{"en":"She sews all her own clothes.","cn":"她所有的衣服都是自己缝的。"}}]}},"self-interest":{"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"自私自利;利己主义","en":"If you accuse someone of self-interest, you disapprove of them because they always want to do what is best for themselves rather than for anyone else.","ex":{"en":"Their current protests are motivated purely by self-interest.","cn":"他们当前的抗议完全是受一己之利驱使的。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a selfish attitude that makes you do things only for selfish reasons, especially in business or politics","cn":""},{"en":"someone with an I'm all right, Jack attitude is only concerned that their own life is satisfactory, and does not care about other people - used especially in newspapers","cn":""},{"en":"when you only care about what is best for you, and do not care about what is best for other people","cn":"自私自利﹐利己之心"}]},"collocations":{"phrases":["ADJ. enlightened | pure VERB + SELF-INTEREST be motivated by | pursue your own","PHRASES in your own self-interest Directors may be tempted to act in their own self-interest."]},"media":{"uk":"media/ldoce/hwd/bre/7/self_interest0205.mp3","us":"media/ldoce/hwd/ame/b/self-interest.mp3"},"examples":[{"en":"Not all of them were acting out of self-interest.","cn":"他们当中，并非所有人的行动都是出于利己的目的。"},{"en":"His offer was motivated solely by self-interest.","cn":"他的提议完全是出于私利。"}],"oxford":{"phon":"ˌself ˈɪntrəst","pos":"noun","senses":[{"en":"the fact of somebody only considering their own interests and of not caring about things that would help other people","cn":"自私自利","ex":{"en":"Not all of them were acting out of self-interest.","cn":"他们当中，并非所有人的行动都是出于利己的目的。"}}]}},"searchlight":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"探照灯","en":"A searchlight is a large powerful light that can be turned to shine a long way in any direction."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a very bright electric light that turns in any direction, used for finding people, guarding places etc","cn":"探照灯"}]},"media":{"uk":"media/ldoce/hwd/bre/0/searchlight0205.mp3","us":"media/ldoce/hwd/ame/2/searchlight.mp3"},"oxford":{"phon":"ˈsɜːtʃlaɪt","pos":"noun","senses":[{"en":"a powerful lamp that can be turned in any direction, used, for example, for finding people or vehicles at night","cn":"探照灯","ex":{"en":"Enemy searchlights swept through the sky.","cn":"敌人的探照灯扫过天空。"}}]}},"sewer":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"污水管;下水道;阴沟","en":"A sewer is a large underground channel that carries waste matter and rain water away, usually to a place where it is treated and made harmless.","ex":{"en":"...the city's sewer system.","cn":"城市排水系统"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a pipe or passage under the ground that carries away waste material and used water from houses, factories etc","cn":"下水道﹔阴沟﹔污水管"}]},"media":{"uk":"media/ldoce/hwd/bre/7/sewer_las3_br.mp3","us":"media/ldoce/hwd/ame/1/sewer.mp3"},"oxford":{"phon":"ˈsuːə(r)","pos":"noun","senses":[{"en":"an underground pipe that is used to carry sewage away from houses, factories, etc.","cn":"污水管；下水道；阴沟","ex":{"en":"a sewer pipe/system","cn":"下水道管道/系统"}}]}},"seminar":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"专题讨论会;研讨会","en":"A seminar is a meeting where a group of people discuss a problem or topic.","ex":{"en":"...a series of half-day seminars to help businessmen get the best value from investing in information technology.","cn":"旨在帮助商界人士从投资信息技术中获得最大价值的一系列半日研讨会"}},{"pos":"N-COUNT 可数名词","cn":"(大学里由教师指导一小组学生参加的)研讨班，研讨课","en":"A seminar is a class at a college or university in which the teacher and a small group of students discuss a topic.","ex":{"en":"Students are asked to prepare material in advance of each weekly seminar.","cn":"学生要在上每星期的研讨课前备好材料。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a period of time, usually about 30 minutes to one hour, in which a teacher teaches a group of students","cn":""},{"en":"a period in which someone teaches one person or a group of people - use this especially about practical skills such as music, swimming, or driving, or in British English about a class in a school","cn":""},{"en":"one of the periods of time that a school day is divided into","cn":""}]},"vocab":{"pos":"n","senses":[{"en":"A seminar means a class or meeting, but it carries with it extra weight. An educational seminar indicates a small, advanced study, while a meeting labeled as such means an intense exchange of ideas."}]},"collocations":{"phrases":["ADJ. termly, weekly, etc. | graduate","QUANT. series","VERB + SEMINAR conduct, give | attend, go to","SEMINAR + NOUN group | discussion, paper | room | programme, series","PREP. at/in a/the ~ There was some lively debate at this week's seminar. | ~ on Professor Mackay will give a seminar on musical settings of ","ADJ. all-day, half-day, weekend | one-day, two-day, etc. | business, economic | training","VERB + SEMINAR organize, hold, run | attend, go to","SEMINAR + VERB take place"]},"media":{"uk":"media/ldoce/hwd/bre/2/seminar0205.mp3","us":"media/ldoce/hwd/ame/5/seminar.mp3"},"examples":[{"en":"Teaching is by lectures and seminars.","cn":"教学形式为讲座和研讨班。"},{"en":"a one-day management seminar","cn":"为期一天的管理研讨会"}],"oxford":{"phon":"ˈsemɪnɑː(r)","pos":"noun","senses":[{"en":"a class at a university or college when a small group of students and a teacher discuss or study a particular topic","cn":"（大学教师带领学生作专题讨论的）研讨课","lab":"British English","ex":{"en":"Teaching is by lectures and seminars.","cn":"教学形式为讲座和研讨课。"}},{"en":"a meeting for discussion or training","cn":"研讨会；培训会","ex":{"en":"a one-day management seminar","cn":"为期一天的管理研讨会"}}]}},"septic":{"collins":{"senses":[{"pos":"ADJ 形容词","cn":"(伤口或身体部位)受感染的，感染病菌的","en":"If a wound or a part of your body becomes septic, it becomes infected.","ex":{"en":"A flake of plaster from the ceiling fell into his eye, which became septic.","cn":"天花板上的一小片熟石膏掉到他眼里，致使他的眼睛感染了。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"a wound or part of your body that is septic is infected with bacteria 〔","cn":"伤口等〕脓毒性的﹐受感染的"}]},"vocab":{"pos":"adj","senses":[{"en":"Septic is connected to dangerous waste products. If your house is not connected to your town or city's sewer, your waste from drains and toilets goes into a septic tank."}]},"media":{"uk":"media/ldoce/hwd/bre/7/brelasdeseptic.mp3","us":"media/ldoce/hwd/ame/b/septic.mp3"},"examples":[{"en":"A dirty cut may go septic.","cn":"伤口不干净容易受感染。"},{"en":"a septic finger","cn":"被感染的手指"}],"oxford":{"phon":"ˈseptɪk","pos":"adjective","senses":[{"en":"containing harmful bacteria that cause infection","cn":"感染病菌的；脓毒性的；受感染的","ex":{"en":"a septic finger","cn":"被感染的手指"}}]}},"self-educated":{"collins":{"senses":[{"pos":"ADJ 形容词","cn":"自我教育的;自学的;自修的","en":"People who are self-educated have acquired knowledge or a skill by themselves, rather than being taught it by someone else such as a teacher at school.","ex":{"en":"...a self-educated man from a working class background.","cn":"来自工薪阶级、自学成才的男子"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"having taught yourself by reading books, thinking about ideas etc, rather than learning things in school","cn":"自学的﹐自修的"}]},"media":{"uk":"media/ldoce/hwd/bre/c/ld41self-educated.mp3","us":"media/ldoce/hwd/ame/8/self-educated.mp3"},"oxford":{"phon":"ˌself ˈedʒukeɪtɪd","pos":"adjective","senses":[{"en":"having learned things by reading books, etc. rather than at school or college","cn":"自我教育的；自学的；自修的"}]}},"sensationalist":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"(新闻报道、电视广播节目)耸人听闻的，追求轰动效应的","en":"Sensationalist news reports and television and radio programmes present the facts in a way that makes them seem worse or more shocking than they really are.","ex":{"en":"...sensationalist headlines","cn":"耸人听闻的新闻标题"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a way of reporting events or stories that makes them seem as strange, exciting, or shocking as possible – used to show disapproval","cn":""}]},"media":{"uk":"media/ldoce/hwd/bre/3/brelasdesensationalism.mp3","us":"media/ldoce/hwd/ame/c/sensationalism.mp3"},"examples":[{"en":"sensationalist headlines","cn":"耸人听闻的标题"}],"oxford":{"phon":"senˈseɪʃənəlɪst","pos":"adjective","senses":[{"en":"getting people's interest by using words that are intended to shock or by presenting facts and events as worse or more shocking than they really are","cn":"（指行文或报道）耸人听闻，哗众取宠","ex":{"en":"sensationalist headlines","cn":"博人眼球的标题"}}]}},"sewage":{"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"(下水道的)污水，污物，废水","en":"Sewage is waste matter such as faeces or dirty water from homes and factories, which flows away through sewers.","ex":{"en":"...the MPs' call for more treatment of raw sewage.","cn":"议员们关于对未经净化的污水加强处理的呼吁"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"the mixture of waste from the human body and used water, that is carried away from houses by pipes under the ground （","cn":"下水道的）污水﹐污物"}]},"collocations":{"phrases":["ADJ. raw, untreated | treated","VERB + SEWAGE dump, pump In some parts of the country raw sewage is pumped straight in the sea. | treat Sewage should be treated in a proper","SEWAGE + NOUN farm, plant, works | disposal, treatment | discharge, effluent, sludge | pollution"]},"media":{"uk":"media/ldoce/hwd/bre/0/brelasdesewage.mp3","us":"media/ldoce/hwd/ame/3/sewage.mp3"},"examples":[{"en":"a ban on the dumping of raw sewage (= that has not been treated with chemicals) at sea","cn":"禁止把未经处理的污水排入海中"},{"en":"sewage disposal","cn":"污水处理"}],"oxford":{"phon":"ˈsuːɪdʒ","pos":"noun","senses":[{"en":"used water and waste substances that are produced by human bodies, that are carried away from houses and factories through special pipes (= sewers)","cn":"（下水道的）污水，污物","ex":{"en":"a ban on the dumping of raw sewage (= that has not been treated with chemicals) at sea","cn":"禁止把未经处理的污水排入海中"}}]}},"segregated":{"collins":{"senses":[{"pos":"ADJ 形容词","cn":"(因种族、性别、宗教不同而)隔离的，分开的","en":"Segregated buildings or areas are kept for the use of one group of people who are the same race, sex, or religion, and no other group is allowed to use them.","ex":{"en":"...racially segregated schools","cn":"实行种族隔离制度的学校"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"a segregated school or other institution can only be attended by members of one sex, race, religion etc 〔","cn":"男女〕分开的﹔〔种族〕隔离的"}]},"vocab":{"pos":"adj","senses":[{"en":"Segregated means separated. Some people think it’s a good idea to keep boys and girls segregated — or separated from each other — at school. Others believe that boys and girls should learn in the same classrooms."}]},"media":{"uk":"media/ldoce/hwd/bre/a/brelasdesegregated.mp3","us":"media/ldoce/hwd/ame/b/segregated.mp3"},"examples":[{"en":"a racially segregated education system","cn":"实行种族隔离的教育制度"}]},"serrated":{"collins":{"senses":[{"pos":"ADJ 形容词","cn":"(刀、刀片等)呈锯齿状的,呈蛇尖状的","en":"A serrated object such as a knife or blade has a row of V-shaped points along the edge.","ex":{"en":"Bread knives should have a serrated edge.","cn":"面包刀的刀刃应该有波浪齿。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"having a very thin edge or point that can cut things easily","cn":""},{"en":"having an irregular edge with a lot of sharp points","cn":""},{"en":"having a lot of thin sharp points","cn":""}]},"vocab":{"pos":"adj","senses":[{"en":"A serrated edge is jagged. When a knife is described as having a serrated blade, its edge is lined with small teeth, similar to a saw's. It will cut tomatoes, bread, and meat more effectively than a smooth-edged blade."}]},"media":{"uk":"media/ldoce/hwd/bre/a/serrated0205.mp3","us":"media/ldoce/hwd/ame/f/serrated.mp3"},"examples":[{"en":"a knife with a serrated edge","cn":"带锯齿刃的刀"},{"en":"Use a knife with a serrated edge .","cn":"使用带锯齿刃的刀。"}],"oxford":{"phon":"səˈreɪtɪd","pos":"adjective","senses":[{"en":"having a series of sharp points on the edge like a saw","cn":"锯齿状的","ex":{"en":"a knife with a serrated edge","cn":"带锯齿刃的刀"}}]}},"sealer":{"collins":{"senses":[{"pos":"N-MASS 物质名词","cn":"同 sealant","en":"A sealer is the same as a sealant ."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a substance that is put on the surface of something to protect it from air, water etc","cn":"密封胶﹐密封剂﹐防渗漏剂"},{"en":"a person or ship that hunts seal s","cn":"捕猎海豹者﹔猎海豹船"}]},"media":{"uk":"media/ldoce/hwd/bre/2/ld41sealer.mp3","us":"media/ldoce/hwd/ame/8/sealer1.mp3"},"oxford":{"phon":"ˈsiːlə(r)","pos":"noun","senses":[{"en":"a substance that is put onto a surface to stop air, water, etc. from entering or escaping from it","cn":"密封剂；密封胶；防渗漏剂","g":"[uncountable, countable]"},{"en":"a person who hunts seals","cn":"捕猎海豹者","g":"[countable]"},{"en":"a ship used for hunting seals","cn":"海豹捕猎船","g":"[countable]"}]}},"self-absorbed":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"只顾自己的;自我专注的","en":"Someone who is self-absorbed thinks so much about things concerning themselves that they do not notice other people or the things around them."}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"interested only in yourself and the things that affect you","cn":"只顾自己的﹐专注于自我的"}]},"media":{"uk":"media/ldoce/hwd/bre/d/ld41self-absorbed.mp3","us":"media/ldoce/hwd/ame/b/self-absorbed.mp3"},"examples":[{"en":"Teenagers always seem so self-absorbed.","cn":"青少年似乎总是只关心自己。"}],"oxford":{"phon":"ˌself əbˈzɔːbd","pos":"adjective","senses":[{"en":"only thinking about or interested in yourself","cn":"只顾自己的；只关心自己的","ex":{"en":"He watched the joggers with their self-absorbed faces.","cn":"他看着那些慢跑者，他们一脸自私。"}}]}},"serendipitous":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"偶然发生的;有意外收获的","en":"A serendipitous event is one that is not planned but has a good result.","ex":{"en":"...a serendipitous discovery.","cn":"一个偶然幸运的发现"}}]},"vocab":{"pos":"adj","senses":[{"en":"Serendipitous is an adjective that describes accidentally being in the right place at the right time, like bumping into a good friend in some unusual location, or finding a hundred dollar bill on the ground."}]},"examples":[{"en":"serendipitous discoveries","cn":"偶然的幸运发现"}],"oxford":{"phon":"ˌserənˈdɪpətəs","pos":"adjective","senses":[{"en":"happening by chance in an interesting or pleasant way","cn":"机缘凑巧的","ex":{"en":"serendipitous discoveries","cn":"机缘巧合的发现"}}]}},"self-portrait":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"自画像;自我描述","en":"A self-portrait is a drawing, painting, or written description that you do of yourself."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a drawing, painting, or description that you do of yourself","cn":"自画像﹔自我描述"}]},"media":{"uk":"media/ldoce/hwd/bre/8/brelasdeself-portrait.mp3","us":"media/ldoce/hwd/ame/d/self-portrait.mp3"},"oxford":{"phon":"ˌself ˈpɔːtreɪt","pos":"noun","senses":[{"en":"a painting, etc. that you do of yourself","cn":"自画像","ex":{"en":"a self-portrait in pen and ink","cn":"用钢笔和墨水画的自画像"}}]}},"seethe":{"collins":{"senses":[{"pos":"VERB 动词","cn":"强压怒火;生闷气","en":"When you are seething, you are very angry about something but do not express your feelings about it.","ex":{"en":"She took it calmly at first but under the surface was seething","cn":"她起初平静地接受了，但内心却气呼呼的。"}},{"pos":"VERB 动词","cn":"充满，遍布，到处都是(人或物)","en":"If you say that a place is seething with people or things, you are emphasizing that it is very full of them and that they are all moving about.","ex":{"en":"The forest below him seethed and teemed with life","cn":"他下面的森林里处处生机勃勃。"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to feel an emotion, especially anger, so strongly that you are almost shaking","cn":"气得发抖﹐怒火中烧"},{"en":"if a place is seething with people, insects etc, there are a lot of them all moving quickly in different directions 〔","cn":"某地方〕充满（四处移动的某物）"}]},"vocab":{"pos":"v","senses":[{"en":"If a liquid seethes , it is boiling, but if it's a person who's seething , watch out! He or she is really angry!"}]},"collocations":{"phrases":["ADV. inwardly, privately Inwardly she was seething, and vowed to get her own back. | quietly, silently","PREP. at She was seething at the insult. | with He clenched his fists, seething with anger."]},"media":{"uk":"media/ldoce/hwd/bre/a/seethe0205.mp3","us":"media/ldoce/hwd/ame/6/seethe.mp3"},"examples":[{"en":"Inwardly he was seething at this challenge to his authority.","cn":"他在心里因权威受到挑战而闷闷不乐。"},{"en":"He marched off, seething with frustration.","cn":"他大为失望，气呼呼地走开了。"}],"oxford":{"phon":"siːð","pos":"verb","senses":[{"en":"to be extremely angry about something but to try not to show other people how angry you are","cn":"怒火中烧；强压怒火","ex":{"en":"She seethed silently in the corner.","cn":"她在角落里默默地生闷气。"}},{"en":"to be full of a lot of people or animals, especially when they are all moving around","cn":"充满，遍布，到处都是（人、动物）","ex":{"en":"The resort is seething with tourists all year round.","cn":"这处名胜一年四季游人如织。"}},{"en":"to move around quickly and violently","cn":"翻滚；翻腾；涌动","lab":"literary","ex":{"en":"The grey ocean seethed beneath them.","cn":"灰蒙蒙的大海在他们下面翻滚。"}}]}},"seamless":{"collins":{"senses":[{"pos":"ADJ 形容词","cn":"无缝的;无停顿的;衔接完美的","en":"You use seamless to describe something that has no breaks or gaps in it or which continues without stopping.","ex":{"en":"It was a seamless procession of wonderful electronic music.","cn":"这是一曲优美流畅的电子乐曲。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"done or made so smoothly that you cannot tell where one thing stops and another begins","cn":"流畅的﹐浑然一体的"},{"en":"without any seam s","cn":"无缝的"}]},"vocab":{"pos":"adj","senses":[{"en":"Something seamless could literally be a piece of clothing without seams, but it's usually something else that's smooth or unbroken, like a seamless transition."}]},"media":{"uk":"media/ldoce/hwd/bre/2/seamless0205.mp3","us":"media/ldoce/hwd/ame/f/laadseamless.mp3"},"examples":[{"en":"a seamless flow of talk","cn":"连贯流畅的谈话"},{"en":"a seamless garment","cn":"无缝衣服"}],"oxford":{"phon":"ˈsiːmləs","pos":"adjective","senses":[{"en":"without a seam","cn":"无（接）缝的","ex":{"en":"seamless underwear","cn":"无缝内衣"}},{"en":"with no spaces or breaks between one part and the next","cn":"（两部分之间）无空隙的，不间断的，不停顿的","ex":{"en":"a seamless flow of talk","cn":"连贯流畅的谈话"}}]}},"sequel":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"(书或电影的)续篇，续集","en":"A book or film which is a sequel to an earlier one continues the story of the earlier one.","ex":{"en":"She is currently writing a sequel to Daphne du Maurier's 'Rebecca'","cn":"她现在正在续写达夫妮·杜穆里埃的小说《蝴蝶梦》。"}},{"pos":"N-COUNT 可数名词","cn":"后续的事;随之而来的事;结果;余波","en":"The sequel to something that has happened is an event or situation that happens after it or as a result of it.","ex":{"en":"The police said the clash was a sequel to yesterday's nationwide strike","cn":"警方说这场冲突是昨天全国大罢工的余波。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a book, play or film that continues the story of an earlier book, play or film, usually by the same writer, film-maker etc","cn":""},{"en":"a book, film, play etc that continues the story of an earlier one, usually written or made by the same person 〔","cn":"书﹑电影﹑戏剧等的〕续集﹐续篇"},{"en":"an event that happens as a result of something that happened before","cn":"随之而来的事﹔后果﹔后续的事﹔余波"}]},"vocab":{"pos":"n","senses":[{"en":"A sequel is a part two. The Empire Strikes Back and Toy Story 2 are sequels . Many successful movies and have sequels ."}]},"collocations":{"phrases":["VERB + SEQUEL do, make, write He's been asked to make a sequel to &lsquo;Peter Pan&rsquo;.","PREP. in a/the~ Some important new characters appear in the sequel. | ~ to 2 sth that happens after sth else","ADJ. immediate | strange, unexpected","VERB + SEQUEL have The affair had a strange sequel.","PREP. ~ to The immediate sequel to the price rises was uprisings across the country."]},"media":{"uk":"media/ldoce/hwd/bre/c/sequel0205.mp3","us":"media/ldoce/hwd/ame/7/sequel.mp3"},"examples":[{"en":"There was an interesting sequel to these events later in the year.","cn":"这几件事发生以后，当年就出现了一种有趣的结果。"},{"en":"a sequel to the hit movie ‘Madagascar’","cn":"热门影片《马达加斯加》的续集"}],"oxford":{"phon":"ˈsiːkwəl","pos":"noun","senses":[{"en":"a book, film, play, etc. that continues the story of an earlier one","cn":"（书、电影、戏剧等的）续篇，续集","ex":{"en":"a sequel to the hit movie ‘Madagascar’","cn":"热门影片《马达加斯加》的续集"}},{"en":"something that happens after an earlier event or as a result of an earlier event","cn":"后续的事；随之而来的事；结果","g":"[usually singular]","ex":{"en":"There was an interesting sequel to these events later in the year.","cn":"这几件事发生以后，当年就出现了一种有趣的结果。"}}]}},"self-defeating":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"适得其反的;弄巧成拙的;事与愿违的","en":"A plan or action that is self-defeating is likely to cause problems or difficulties instead of producing useful results.","ex":{"en":"Dishonesty is ultimately self-defeating.","cn":"弄虚作假最终会自食其果。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"if a plan or action backfires , it is intended to do one thing but instead does the opposite","cn":""},{"en":"an action or plan that is self-defeating is not well planned or is badly done, so that it produces the opposite effect from the one intended","cn":""},{"en":"intended to make something better, but actually making it worse","cn":""}]},"media":{"uk":"media/ldoce/hwd/bre/2/ld41self-defeating.mp3","us":"media/ldoce/hwd/ame/6/self-defeating.mp3"},"examples":[{"en":"Paying children too much attention when they misbehave can be self-defeating.","cn":"孩子有不良行为时，小题大做可能适得其反。"},{"en":"Constant dieting can be self-defeating.","cn":"一直节食结果可能适得其反。"}],"oxford":{"phon":"ˌself dɪˈfiːtɪŋ","pos":"adjective","senses":[{"en":"causing more problems and difficulties instead of solving them; not achieving what you wanted to achieve but having an opposite effect","cn":"事与愿违的；适得其反的；弄巧成拙的","ex":{"en":"Paying children too much attention when they misbehave can be self-defeating.","cn":"孩子有不良行为时，过分关注可能适得其反。"}}]}},"sexless":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"无性行为的;性冷淡的;无性欲的","en":"If you describe a person as sexless, you mean that they have no sexual feelings or that they are not sexually active. A sexless relationship does not involve sex.","ex":{"en":"Malcolm is a brilliant but frustrated surgeon who is married to a neurotic and sexless woman.","cn":"马尔科姆是一位才华横溢却又生活失意的外科医生，他妻子有些神经质而且性冷淡。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"to be not at all sexually attractive","cn":""},{"en":"not sexually attractive, because of not having any strong male or female qualities","cn":""},{"en":"not involving sexual activity, in a way that does not seem normal or usual","cn":"无性行为的﹐性冷淡的"}]},"media":{"uk":"media/ldoce/hwd/bre/3/ld41sexless.mp3","us":"media/ldoce/hwd/ame/a/sexless.mp3"},"examples":[{"en":"a sexless figure","cn":"无性别特征的体形"},{"en":"a sexless marriage","cn":"无性婚姻"}],"oxford":{"phon":"ˈseksləs","pos":"adjective","senses":[{"en":"that is neither male nor female, or does not seem to be either male or female","cn":"无性（别）的","ex":{"en":"a sexless figure","cn":"无性别特征的体形"}},{"en":"in which there is no sexual desire or activity","cn":"性冷淡的；无性行为的"}]}},"self-seeking":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"追逐私利的;只顾自己的","en":"If you describe someone as self-seeking, you disapprove of them because they are interested only in doing things which give them an advantage over other people.","ex":{"en":"He said that democracy would open the way for self-seeking politicians to abuse the situation.","cn":"他说民主会为追逐私利的政客大开方便之门，使他们趁机以公谋私。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"doing things only because they will give you an advantage that other people do not have – used to show disapproval","cn":"追逐私利的﹐为自己打算的〔含贬义〕"}]},"media":{"uk":"media/ldoce/hwd/bre/3/self_seeking0205.mp3","us":"media/ldoce/hwd/ame/b/self-seeking.mp3"},"examples":[{"en":"a self-seeking politician","cn":"追求私利的政客"}],"oxford":{"phon":"ˌself ˈsiːkɪŋ","pos":"adjective","senses":[{"en":"interested only in your own needs and interests rather than thinking about the needs of other people","cn":"追逐私利的"},{"en":"concern only for your own needs and interests rather than the needs of other people","cn":"追逐私利的","ex":{"en":"They were accused of self-seeking and corruption.","cn":"他们被指控谋取私利和腐败。"},"pos":"noun"}]}},"sequester":{"collins":{"senses":[{"pos":"VERB 动词","cn":"同 sequestrate","en":"Sequester means the same as sequestrate .","ex":{"en":"Everything he owned was sequestered.","cn":"他的所有财产都被扣押了。"}},{"pos":"VERB 动词","cn":"使隔离;使与他人隔绝","en":"If someone is sequestered somewhere, they are isolated from other people.","ex":{"en":"This jury is expected to be sequestered for at least two months.","cn":"预计这个陪审团将至少被隔离两个月。"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to keep a person or a group of people away from other people","cn":"使与他人隔离﹔使隔绝"},{"en":"to sequestrate","cn":"扣押〔债务人的财产〕"}]},"vocab":{"pos":"v","senses":[{"en":"The word sequester describes being kept away from others. If your sister tells you to stay out of the way so she can cook dinner for her new boyfriend, you might sequester yourself in your room."}]},"media":{"uk":"media/ldoce/hwd/bre/c/sequester0205.mp3","us":"media/ldoce/hwd/ame/c/sequester.mp3"},"examples":[{"en":"The jury were sequestered during the trial.","cn":"审判期间﹐陪审团被隔离开来。"}],"oxford":{"phon":"sɪˈkwestə(r)","pos":"verb","senses":[{"en":"to take control of somebody’s property or assets until a debt has been paid","cn":"强制管理，扣押（债务人资产）"},{"en":"to keep a jury together in a place, in order to prevent them from talking to other people about a court case, or learning about it in the newspapers, on television, etc.","cn":"隔离（避免陪审团与公众接触）"}]}},"self-confident":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"自信的","en":"Someone who is self-confident behaves confidently because they feel sure of their abilities or value.","ex":{"en":"She'd blossomed into a self-confident young woman.","cn":"她已长大成为了一个自信的年轻女性。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"sure that you have the ability to do something well or deal with situations successfully","cn":""},{"en":"confident, and not shy or nervous in social situations","cn":""},{"en":"confident, calm, and in control of your feelings even in a difficult situation","cn":""}]},"vocab":{"pos":"adj","senses":[{"en":"To be self-confident is to be secure in yourself and your abilities. When you are giving a presentation or a speech, it helps to be self-confident –- or at least to pretend that you are."}]},"media":{"uk":"media/ldoce/hwd/bre/d/brelasdeself-confident.mp3","us":"media/ldoce/hwd/ame/2/self-confident.mp3"},"examples":[{"en":"He has no self-confidence.","cn":"他毫无自信。"},{"en":"a self-confident child","cn":"自信的孩子"}],"oxford":{"phon":"ˌself ˈkɒnfɪdənt","pos":"adjective","senses":[{"en":"having confidence in yourself and your abilities","cn":"自信的","ex":{"en":"a self-confident child","cn":"自信的孩子"}}]}},"seafront":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"(城镇的)滨海区，临海地区","en":"The seafront is the part of a seaside town that is nearest to the sea. It usually consists of a road with buildings that face the sea.","ex":{"en":"They decided to meet on the seafront.","cn":"他们决定在滨海区会面。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"the part of a town where the shops, houses etc are next to the beach 〔","cn":"城镇的〕滨海区"}]},"media":{"uk":"media/ldoce/hwd/bre/0/seafront0205.mp3","us":"media/ldoce/hwd/ame/d/seafront.mp3"},"examples":[{"en":"the grand houses along the seafront","cn":"滨海区的豪宅"},{"en":"a hotel right on the seafront","cn":"就在海滩边的一家宾馆"}],"oxford":{"phon":"ˈsiːfrʌnt","pos":"noun","senses":[{"en":"the part of a town facing the sea","cn":"（城镇的）滨海区，面海地区","ex":{"en":"the grand houses along the seafront","cn":"滨海区的豪宅"}}]}},"secrete":{"collins":{"senses":[{"pos":"VERB 动词","cn":"分泌","en":"If part of a plant, animal, or human secretes a liquid, it produces it.","ex":{"en":"The sweat glands secrete water.","cn":"汗腺分泌汗液。"}},{"pos":"VERB 动词","cn":"隐藏;藏匿","en":"If you secrete something somewhere, you hide it there so that nobody will find it.","ex":{"en":"She secreted the gun in the kitchen cabinet.","cn":"她把枪藏在橱柜里。"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to make something difficult to see or find, for example by putting it somewhere secret, or by covering it","cn":""},{"en":"to hide something carefully, especially by covering it","cn":""},{"en":"to hide money or something that you should not have","cn":""}]},"vocab":{"pos":"1 v 2 v","senses":[{"en":"Secrete is all about secrets. It means both \"to hide\" and \"to release.\" When you squeeze a lemon, it secretes juice. When you stuff your money in a mattress, you secrete it there."}]},"media":{"uk":"media/ldoce/hwd/bre/e/secrete0205.mp3","us":"media/ldoce/hwd/ame/8/secrete1.mp3"},"examples":[{"en":"The drugs were secreted in the lining of his case.","cn":"毒品藏在他的皮箱内衬中。"},{"en":"Insulin is secreted by the pancreas.","cn":"胰岛素是胰腺分泌的。"}],"oxford":{"phon":"sɪˈkriːt","pos":"verb","senses":[{"en":"to produce a liquid substance","cn":"分泌","ex":{"en":"Insulin is secreted by the pancreas.","cn":"胰岛素是胰腺分泌的。"}},{"en":"to hide something, especially something small","cn":"隐藏，藏匿（小物件）","lab":"formal","ex":{"en":"The drugs were secreted in the lining of his case.","cn":"毒品藏在他的皮箱内衬中。"}}]}},"seagoing":{"collins":{"senses":[{"pos":"ADJ 形容词","cn":"(船只)适于航海的，远洋航行的","en":"Seagoing boats and ships are designed for travelling on the sea, rather than on lakes, rivers, or canals."}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"built to travel on the sea 〔","cn":"船〕适于航海的﹐远洋航行的"}]},"media":{"uk":"media/ldoce/hwd/bre/2/ld41seagoing.mp3","us":"media/ldoce/hwd/ame/3/seagoing.mp3"},"examples":[{"en":"a seagoing ship","cn":"远洋轮"}],"oxford":{"phon":"ˈsiːɡəʊɪŋ","pos":"adjective","senses":[{"en":"built for crossing the sea","cn":"远洋航行的","ex":{"en":"a seagoing vessel","cn":"一条适合航海的船"}}]}},"segmentation":{"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"分割;分段;划分","en":"Segmentation is the dividing of something into parts which are loosely connected."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"when something divides or is divided into smaller parts","cn":"分割[划分]（成部分）"}]},"media":{"uk":"media/ldoce/hwd/bre/d/ld41segmentation.mp3","us":"media/ldoce/hwd/ame/6/segmentation.mp3"},"examples":[{"en":"the segmentation of society","cn":"社会的划分"}],"oxford":{"phon":"ˌseɡmenˈteɪʃn","pos":"noun","senses":[{"en":"the act of dividing something into different parts; one of these parts","cn":"分割；划分；分割成（或划分成）的部分","ex":{"en":"the segmentation of social classes","cn":"社会阶级的分化"}}]}},"second-in-command":{"collins":{"senses":[{"pos":"N-SING 单数名词","cn":"副指挥;二把手","en":"A second-in-command is someone who is next in rank to the leader of a group, and who has authority to give orders when the leader is not there.","ex":{"en":"He was posted to Hong Kong as second-in-command of C Squadron","cn":"他被派遣到香港任C中队的副队长。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"someone who is immediately below the rank of another manager, and who is officially in charge when that other person is away or ill","cn":""},{"en":"a manager who is in charge of an organization or department when a more senior manager is not there","cn":""},{"en":"the person who has the next highest rank to the leader of a group, especially in a military organization 〔","cn":"尤指军事组织的〕副司令员﹐副指挥官"}]},"media":{"uk":"media/ldoce/hwd/bre/3/ld41second-in-comm.mp3","us":"media/ldoce/hwd/ame/4/second-in-command.mp3"},"oxford":{"phon":"ˌsekənd ɪn kəˈmɑːnd","pos":"noun","senses":[{"en":"a person who has the second highest rank in a group and takes charge when the leader is not there","cn":"副指挥官；二号人物","ex":{"en":"For twenty years he served the business as second in command to his father.","cn":"二十年来，他一直担任父亲的二把手，为公司服务。"}}]}},"self-sufficiency":{"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"自给自足;自立","en":"Self-sufficiency is the state of being self-sufficient."}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"political freedom from control by the government of another country","cn":""},{"en":"not controlled by any other country - used especially in an official or political contexts","cn":""},{"en":"part of a country or organization that is autonomous is partly independent and has the right to organize most of its own activities, business etc","cn":""}]},"media":{"uk":"media/ldoce/hwd/bre/2/brelasdeself-sufficient.mp3","us":"media/ldoce/hwd/ame/1/self-sufficient.mp3"},"examples":[{"en":"Australia is 65% self-sufficient in oil.","cn":""}],"oxford":{"phon":"ˌself səˈfɪʃnsi","pos":"noun","senses":[{"en":"the ability to do or produce everything that you need without the help of other people","cn":"自给自足的；自立的","ex":{"en":"economic self-sufficiency","cn":"半年刊/报告"}}]}},"self-preservation":{"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"自我保全;自我保护","en":"Self-preservation is the action of keeping yourself safe or alive in a dangerous situation, often without thinking about what you are doing.","ex":{"en":"The police have the same human urge for self-preservation as the rest of us.","cn":"警察和我们其他人一样，都有自我保护的人类本能。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"protection of yourself and your own life in a threatening or dangerous situation","cn":"自我保存﹐自我保护"}]},"media":{"uk":"media/ldoce/hwd/bre/2/ld41self-preservat.mp3","us":"media/ldoce/hwd/ame/e/self-preservation.mp3"},"examples":[{"en":"She was held back by some sense of self-preservation.","cn":"一种自我保护意识使她没有贸然行动。"},{"en":"the instinct for self-preservation","cn":"自我保护的本能"}],"oxford":{"phon":"ˌself prezəˈveɪʃn","pos":"noun","senses":[{"en":"the fact of protecting yourself in a dangerous or difficult situation","cn":"自我保存；自我保护","ex":{"en":"She was held back by some sense of self-preservation.","cn":"一种自我保护意识使她没有贸然行动。"}}]}},"semaphore":{"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"旗语","en":"Semaphore is a system of sending messages by using two flags. You hold a flag in each hand and move your arms to various positions representing different letters of the alphabet."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a system of sending messages using two flags, which you hold in different positions to represent letters and numbers","cn":"旗语"}]},"vocab":{"pos":"n v","senses":[{"en":"A semaphore is a gadget used for conveying signals. Semaphores have either lights or mechanical arms that move."}]},"media":{"uk":"media/ldoce/hwd/bre/3/ld41semaphore.mp3","us":"media/ldoce/hwd/ame/6/semaphore.mp3"},"oxford":{"phon":"ˈseməfɔː(r)","pos":"noun","senses":[{"en":"a system for sending signals in which you hold your arms or two flags in particular positions to represent different letters of the alphabet","cn":"信号标；旗语"},{"en":"to send a message to somebody by semaphore or a similar system of signals","cn":"打旗语；（用其他类似的信号系统）发信号","pos":"verb"}]}},"self-proclaimed":{"collins":{"senses":[{"pos":"ADJ 形容词","cn":"自称的;自命的;自封的","en":"Self-proclaimed is used to show that someone has given themselves a particular title or status rather than being given it by other people.","ex":{"en":"...a self-proclaimed expert","cn":"自封的专家"}},{"pos":"ADJ 形容词","cn":"不吝承认的;无耻自称的","en":"Self-proclaimed is used to show that someone says themselves that they are a type of person which most people would be embarrassed or ashamed to be.","ex":{"en":"One of the prisoners is a self-proclaimed racist who opened fire on a crowd four years ago.","cn":"其中一名囚犯恬不知耻地自称是种族主义者，他曾在四年前向一群人开枪射击。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"having given yourself a position or title without the approval or agreement of other people – used to show disapproval","cn":"自称的﹐自封的〔含贬义〕"}]},"media":{"uk":"media/ldoce/hwd/bre/9/self_proclaime0205.mp3","us":"media/ldoce/hwd/ame/9/self-proclaimed.mp3"},"examples":[{"en":"a self-proclaimed champion of the working class","cn":"自封的工人阶级斗士"}],"oxford":{"phon":"ˌself prəˈkleɪmd","pos":"adjective","senses":[{"en":"giving yourself a particular title, job, etc. without the agreement or permission of other people","cn":"自称的；自命的"}]}},"serge":{"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"哔叽(一种结实的羊毛布)","en":"Serge is a type of strong woollen cloth used to make clothes such as skirts, coats, and trousers.","ex":{"en":"He wore a blue serge suit.","cn":"他穿着一套蓝色哔叽西服。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"strong woollen cloth used for making suits, trousers etc","cn":"哔叽〔衣料〕"}]},"media":{"uk":"media/ldoce/hwd/bre/f/ld41serge.mp3","us":"media/ldoce/hwd/ame/6/serge.mp3"},"examples":[{"en":"a blue serge suit","cn":"一套蓝色哔叽西服"}],"oxford":{"phon":"sɜːdʒ","pos":"noun","senses":[{"en":"a type of strong cloth made of wool, used for making clothes","cn":"哔叽","ex":{"en":"a blue serge suit","cn":"一套蓝色哔叽西服"}}]}},"senatorial":{"collins":{"senses":[{"pos":"ADJ 形容词","cn":"参议院的;与参议院有关的","en":"Senatorial means belonging to or relating to a Senate.","ex":{"en":"He has senatorial experience in defence and foreign policy.","cn":"他在参议院期间有过国防和外交政策方面的经验。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"someone who works in politics, especially an elected member of the government","cn":""},{"en":"a political or government leader, especially one who is well-respected","cn":""},{"en":"in Britain, someone who has been elected to a parliament to represent people from a particular area of the country","cn":""}]},"vocab":{"pos":"adj","senses":[{"en":"Anything senatorial relates to senators, who are members of a legislative body. If you are a senatorial candidate, guess what? You are running for the Senate."}]},"media":{"uk":"media/ldoce/hwd/bre/0/senator0205.mp3","us":"media/ldoce/hwd/ame/8/senator.mp3"},"examples":[{"en":"a senatorial candidate","cn":"参议员候选人"}],"oxford":{"phon":"ˌsenəˈtɔːriəl","pos":"adjective","senses":[{"en":"connected with a senate or members of a senate","cn":"参议员","ex":{"en":"a senatorial candidate","cn":"参议员候选人"}}]}},"semiconductor":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"半导体","en":"A semiconductor is a substance used in electronics whose ability to conduct electricity increases with greater heat."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a substance, such as silicon , that allows some electric currents to pass through it, and is used in electronic equipment","cn":"半导体"}]},"media":{"uk":"media/ldoce/hwd/bre/9/ld41semiconductor.mp3","us":"media/ldoce/hwd/ame/f/semiconductor.mp3"},"oxford":{"phon":"ˌsemikənˈdʌktə(r)","pos":"noun","senses":[{"en":"a solid substance that conducts electricity in particular conditions, better than insulators but not as well as conductors","cn":"半导体"},{"en":"a device containing a semiconductor used in electronics","cn":"半导体装置"}]}},"sectarianism":{"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"宗派主义;教派主义;党派主义","en":"Sectarianism is strong support for the religious or political group you belong to, and often involves conflict with other groups.","ex":{"en":"...political rivalry and sectarianism within our movement.","cn":"我们这场运动内部的政治对立和宗派主义"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"violence etc that is related to the strong feelings of people who belong to different religious groups","cn":""},{"en":"supporting a particular religious group and its beliefs","cn":""}]},"media":{"uk":"media/ldoce/hwd/bre/7/sectarian0205.mp3","us":"media/ldoce/hwd/ame/b/sectarian.mp3"},"examples":[{"en":"people on both sides of the sectarian divide in Northern Ireland","cn":""}],"oxford":{"phon":"sekˈteəriənɪzəm","pos":"noun","senses":[{"en":"strong support for one particular religious or political group, especially when this leads to violence between different groups","cn":"宗派主义","ex":{"en":"reports of a rise in religious and ethnic sectarianism","cn":"关于宗教和种族派别暴力事件增加的报告"}}]}},"seaward":{"collins":{"senses":[{"pos":"ADV 副词","cn":"朝海地;向海地;临海地","en":"Something that moves or faces seaward or seawards moves or faces in the direction of the sea or further out to sea.","ex":{"en":"A barge was about a hundred yards away, waiting to return seaward","cn":"一艘驳船停在大约 100 码开外，等待着返海回航。"}},{"pos":"ADJ 形容词","cn":"朝海的;向海的;临海的","en":"The seaward side of something faces in the direction of the sea or further out to sea.","ex":{"en":"The houses on the seaward side of the road were all in ruins.","cn":"马路临海一侧的房子全部沦为废墟。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"facing towards the sea","cn":"向海的﹐朝海的"}]},"media":{"uk":"media/ldoce/hwd/bre/0/ld41seaward.mp3","us":"media/ldoce/hwd/ame/b/seaward.mp3"},"examples":[{"en":"the seaward side of the coastal road","cn":"海滨公路临海的一侧"},{"en":"Her gaze was fixed seawards.","cn":"她凝望大海。"}],"oxford":{"phon":"ˈsiːwəd","pos":"adjective","senses":[{"en":"towards the sea; in the direction of the sea","cn":"向海的；朝海的","ex":{"en":"the seaward side of the coastal road","cn":"海滨公路临海的一侧"}},{"en":"towards the sea; in the direction of the sea","cn":"向海的；朝海的","ex":{"en":"Her gaze was fixed seawards.","cn":"她凝望着大海。"},"pos":"adverb"}]}},"self-control":{"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"自制力;自我克制","en":"Self-control is the ability to not show your feelings or not do the things that your feelings make you want to do.","ex":{"en":"His self-control, reserve and aloofness were almost inhuman","cn":"他自制、矜持和冷漠得几乎有些不近人情。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"if you control yourself or control your feelings, you continue to behave calmly and sensibly and do not become too angry, excited, or upset","cn":""},{"en":"the ability to behave calmly and sensibly and not become too angry, excited, or upset, even when you have a good reason to","cn":""},{"en":"to manage to stay calm and not become angry, especially when someone is trying to make you angry","cn":""}]},"vocab":{"pos":"n","senses":[{"en":"Self-control is the quality that allows you to stop yourself from doing things you want to do but that might not be in your best interest. For example, without self-control , you might burp and curse nonstop."}]},"collocations":{"phrases":["PHRASES a lack/loss of self-control"]},"media":{"uk":"media/ldoce/hwd/bre/d/self_control0205.mp3","us":"media/ldoce/hwd/ame/0/self-control.mp3"},"examples":[{"en":"It took all his self-control not to shout at them.","cn":"他强压怒火，没有冲他们叫嚷。"},{"en":"to lose/regain your self-control","cn":"失去/恢复自制"}],"oxford":{"phon":"ˌself kənˈtrəʊl","pos":"noun","senses":[{"en":"the ability to remain calm and not show your emotions even though you are feeling angry, excited, etc.","cn":"自制力；自我控制","ex":{"en":"to lose/regain your self-control","cn":"失去／恢复自制"}}]}},"self-governing":{"collins":{"senses":[{"pos":"ADJ 形容词","cn":"(国家、组织)自治的，自己管理自己的","en":"A self-governing region or organization is governed or run by its own people rather than by the people of another region or organization.","ex":{"en":"...a self-governing province","cn":"自治省"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"political freedom from control by the government of another country","cn":""},{"en":"not controlled by any other country - used especially in an official or political contexts","cn":""},{"en":"part of a country or organization that is autonomous is partly independent and has the right to organize most of its own activities, business etc","cn":""}]},"media":{"uk":"media/ldoce/hwd/bre/6/self_governing0205.mp3","us":"media/ldoce/hwd/ame/d/self-governing.mp3"},"examples":[{"en":"self-governing states","cn":"自治州"}],"oxford":{"phon":"ˌself ˈɡʌvənɪŋ","pos":"adjective","senses":[{"en":"governed or controlled by its own people or members, not by others","cn":"自治","ex":{"en":"a self-governing community","cn":"自治社区"}}]}},"seedbed":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"苗床;苗圃","en":"A seedbed is an area of ground, usually with specially prepared earth, where young plants are grown from seed."},{"pos":"N-COUNT 可数名词","cn":"(人或事物发展的)有利环境，温床","en":"You can refer to a place or a situation as a seedbed when it seems likely that a particular type of thing or person will develop in that place or situation.","ex":{"en":"TV is using radio as a seedbed for ideas","cn":"电视正从广播节目中汲取灵感。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a place or condition that encourages something to develop","cn":"温床"},{"en":"an area of ground where young plants are grown from seeds before they are planted somewhere else","cn":"苗床"}]},"media":{"uk":"media/ldoce/hwd/bre/0/ld41seedbed.mp3","us":"media/ldoce/hwd/ame/8/seedbed.mp3"},"examples":[{"en":"Strong personal beliefs can become a seedbed for conflicts.","cn":"强烈的个人信仰有可能成为产生冲突的温床。"}],"oxford":{"phon":"ˈsiːdbed","pos":"noun","senses":[{"en":"an area of soil which has been specially prepared for planting seeds in","cn":"苗床"},{"en":"a place or situation in which something can develop","cn":"（某事物发展的）有利环境；温床","g":"[usually singular]","ex":{"en":"a seedbed for ideas","cn":"思想的温床"}}]}},"self-assertive":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"有主见的","en":"Someone who is self-assertive acts in a confident way, speaking firmly about their opinions and demanding the rights that they believe they should have.","ex":{"en":"If you want good relationships, you must have the confidence to be self-assertive when required.","cn":"如果想要发展成功的关系，在需要的时候必须有自信拿出主见。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"very confident about saying what you think or want","cn":"非常自信的﹐极有主见的"}]},"media":{"uk":"media/ldoce/hwd/bre/1/ld41self-assertive.mp3","us":"media/ldoce/hwd/ame/1/ld41self-assertive.mp3"},"oxford":{"phon":"ˌself əˈsɜːtɪv","pos":"adjective","senses":[{"en":"very confident and not afraid to express your opinions","cn":"非常自信的；有主见的"}]}},"self-addressed":{"collins":{"senses":[{"pos":"ADJ 形容词","cn":"(信封)写明发信人地址的，回邮的","en":"A self-addressed envelope is an envelope which you have written your address on and which you send to someone in another envelope so that they can send something back to you.","ex":{"en":"Please enclose a stamped self-addressed envelope.","cn":"请随信寄来一个贴好邮票的回信信封。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"a self-addressed envelope has the sender’s address on it, so that information can be put in it and sent back to them 〔","cn":"信封〕写有发信人地址的"}]},"media":{"uk":"media/ldoce/hwd/bre/b/ld41self-addressed.mp3","us":"media/ldoce/hwd/ame/c/self-addressed.mp3"},"oxford":{"phon":"ˌself əˈdrest","pos":"adjective","senses":[{"en":"if an envelope is self-addressed, somebody has written their own address on it","cn":"（信封）写明回邮地址的"}]}},"self-supporting":{"collins":{"senses":[{"pos":"ADJ 形容词","cn":"资金自给的;经济独立的","en":"Self-supporting is used to describe organizations, schemes, and people who earn enough money to not need financial help from anyone else.","ex":{"en":"The income from visitors makes the museum self-supporting","cn":"参观者带来的收入使得这个博物馆能够独立运营。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"able to earn enough money to support yourself","cn":"自食其力的﹐自立的"},{"en":"able to stand or stay upright without support","cn":"自承的﹐自撑的"}]},"media":{"uk":"media/ldoce/hwd/bre/f/ld41self-supportin.mp3","us":"media/ldoce/hwd/ame/e/self-supporting.mp3"},"examples":[{"en":"The business will soon become self-supporting.","cn":"这家公司很快就能独立经营了。"},{"en":"self-supporting fencing","cn":"自撑的篱笆"}],"oxford":{"phon":"ˌself səˈpɔːtɪŋ","pos":"adjective","senses":[{"en":"having enough money to be able to operate without financial help from other people","cn":"资金自给的；经济独立的"}]}},"sentimentalist":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"好感伤者;多愁善感者","en":"If you describe someone as a sentimentalist, you believe that they are sentimental about things."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"someone who behaves or writes in a sentimental way","cn":"多愁善感的人﹔感伤主义者"}]},"media":{"uk":"media/ldoce/hwd/bre/1/sentimentalist0205.mp3","us":"media/ldoce/hwd/ame/6/laadsentimentalist.mp3"},"oxford":{"phon":"ˌsentɪˈmentəlɪst","pos":"noun","senses":[{"en":"a person who is sentimental about things","cn":"好感伤者；多愁善感的人"}]}},"seer":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"预言者;先知","en":"A seer is a person who tells people what will happen in the future.","ex":{"en":"...the writings of the 16th century French seer, Nostradamus.","cn":"16世纪法国预言家诺斯特拉达穆斯的作品"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"someone who can see into the future and say what will happen","cn":"预言者﹐先知"}]},"vocab":{"pos":"n","senses":[{"en":"A seer is someone who can see the future. Nostradamus is considered a seer because he predicted everything from the Great Fire of London to the French Revolution. Oh, and the end of the world."}]},"media":{"uk":"media/ldoce/hwd/bre/b/ld41seer.mp3","us":"media/ldoce/hwd/ame/8/seer.mp3"},"oxford":{"phon":"sɪə(r)","pos":"noun","senses":[{"en":"(especially in the past) a person who claims that they can see what is going to happen in the future","cn":"（尤指旧时）预言家，先知"}]}},"seditious":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"煽动叛乱的;煽动反政府的;反动性的","en":"A seditious act, speech, or piece of writing encourages people to fight against or oppose the government.","ex":{"en":"He fell under suspicion for distributing seditious pamphlets.","cn":"他因散发反政府传单而遭到怀疑。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"actions, speeches etc that are intended to encourage people to oppose the government or to take part in a rebellion","cn":""},{"en":"secret activities that are intended to encourage people to oppose the government or to take part in a rebellion","cn":""},{"en":"speech, writing, or actions intended to encourage people to disobey a government","cn":""}]},"vocab":{"pos":"adj","senses":[{"en":"Something seditious works against a government. When countries overthrow authoritarian dictators, often the people engage in seditious protests until the dictator has to leave."}]},"media":{"uk":"media/ldoce/hwd/bre/a/sedition0205.mp3","us":"media/ldoce/hwd/ame/8/sedition.mp3"},"examples":[{"en":"seditious activity","cn":"煽动叛乱的活动"},{"en":"Trade union leaders were charged with sedition.","cn":""}],"oxford":{"phon":"sɪˈdɪʃəs","pos":"adjective","senses":[{"en":"intended to encourage people to oppose a government","cn":"煽动叛乱的言论（或行动）","ex":{"en":"seditious activity","cn":"煽动叛乱的活动"}}]}},"sedation":{"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"(服镇静剂后的)镇静(状态)","en":"If someone is under sedation, they have been given medicine or drugs in order to calm them or make them sleep.","ex":{"en":"His mother was under sedation after the boy's body was brought back from Germany.","cn":"男孩的尸体从德国运回后，他的母亲一直靠服药保持镇静。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"the use of drugs to make someone calm or go to sleep 〔","cn":"服镇静剂后的〕镇静（状态）"}]},"vocab":{"pos":"n","senses":[{"en":"Sedation is either the state of being relaxed or sleepy because of a drug, or the act of drugging someone with a sedative."}]},"collocations":{"phrases":["ADJ. heavy | light","PREP. under ~ The attack victim is currently in hospital, under heavy sedation."]},"media":{"uk":"media/ldoce/hwd/bre/3/ld41sedation.mp3","us":"media/ldoce/hwd/ame/8/sedation.mp3"},"examples":[{"en":"The victim's wife was last night being kept under sedation in the local hospital.","cn":"昨晚，受害人的妻子在当地医院用药后处于镇静状态。"},{"en":"The patient was still under heavy sedation .","cn":"这个病人用药后仍处于深度镇静状态。"}],"oxford":{"phon":"sɪˈdeɪʃn","pos":"noun","senses":[{"en":"the act of giving somebody drugs in order to make them calm or to make them sleep; the state that results from this","cn":"药物镇静；镇静状态","ex":{"en":"The victim's wife was last night being kept under sedation in the local hospital.","cn":"昨晚，受害人的妻子在当地医院用药后处于镇静状态。"}}]}},"separatism":{"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"分离主义;独立主义","en":"Separatism is the beliefs and activities of separatists."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"someone who belongs to a group that wants to start a new country with its own government, by separating from the country that they belong to now","cn":""}]},"media":{"uk":"media/ldoce/hwd/bre/9/separatist0205.mp3","us":"media/ldoce/hwd/ame/7/laadseparatist.mp3"},"oxford":{"phon":"ˈseprətɪzəm","pos":"noun","senses":[{"en":"the desire by a group of people within a country to separate from the rest of the country and form their own government","cn":"分离主义者；独立主义者","ex":{"en":"regional separatism","cn":"地区分裂主义"}}]}},"second-guess":{"collins":{"senses":[{"pos":"VERB 动词","cn":"预测;预言","en":"If you try to second-guess something, you try to guess in advance what someone will do or what will happen.","ex":{"en":"Editors and contributors are trying to second-guess the future.","cn":"编辑们和撰稿者们在试图预测未来。"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to say what you think will happen in the future","cn":""},{"en":"to publicly say what will happen in the future with the weather or the economic or political situation, especially when you have special or technical knowledge","cn":""},{"en":"to say that something will happen, especially because you have religious or magical powers","cn":""}]},"media":{"uk":"media/ldoce/hwd/bre/a/second_guess0205.mp3","us":"media/ldoce/hwd/ame/8/second-guess.mp3"},"examples":[{"en":"It was impossible to second-guess the decision of the jury.","cn":"陪审团的决定不可能预测。"},{"en":"I’m not going to try and second-guess the committee’s decisions.","cn":"我不想去猜测委员会的决定。"}],"oxford":{"phon":"ˌsekənd ˈɡes","pos":"verb","senses":[{"en":"to guess what somebody will do before they do it; to guess how you will feel in the future","cn":"猜测；预言；预感","g":"[transitive]","ex":{"en":"It was impossible to second-guess the decision of the jury.","cn":"陪审团的决定不可能预测。"}},{"en":"to criticize somebody after a decision has been made; to criticize something after it has happened","cn":"事后批评（或品评）；耍事后聪明","g":"[transitive, intransitive]","lab":"especially North American English"}]}},"selfless":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"无私的;忘我的","en":"If you say that someone is selfless, you approve of them because they care about other people more than themselves.","ex":{"en":"She was a wonderful companion and her generosity to me was entirely selfless","cn":"她是一个极好的伴侣，她对我慷慨大方，一心只为我着想。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"caring only about other people's needs, not your own, and never behaving selfishly","cn":""},{"en":"sincerely concerned about other people and willing to help them or give money to them if they need it, without trying to get any advantage for yourself","cn":""},{"en":"caring about other people more than about yourself – used to show approval","cn":"忘我的﹐无私的〔含褒义〕"}]},"vocab":{"pos":"adj","senses":[{"en":"When you're being selfless , you're thinking of other people before yourself. Selfless is the opposite of selfish."}]},"media":{"uk":"media/ldoce/hwd/bre/5/selfless0205.mp3","us":"media/ldoce/hwd/ame/f/selfless.mp3"},"examples":[{"en":"a life of selfless service to the community","cn":"无私服务于社会的一生"},{"en":"selfless devotion to their work","cn":"他们对工作的无私奉献"}],"oxford":{"phon":"ˈselfləs","pos":"adjective","senses":[{"en":"thinking more about the needs, happiness, etc. of other people than about your own","cn":"无私的","ex":{"en":"a life of selfless service to the community","cn":"无私服务于社会的一生"}}]}},"secretive":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"深藏不露的;讳莫如深的","en":"If you are secretive, you like to have secrets and to keep your knowledge, feelings, or intentions hidden.","ex":{"en":"Billionaires are usually fairly secretive about the exact amount that they're worth.","cn":"亿万富翁通常对自己身家的确切数目讳莫如深。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"unwilling to let other people know what you are doing, or to give them information about yourself","cn":""},{"en":"unwilling to tell people definitely what your plans, intentions, or opinions are - use this especially when you cannot think of a good reason for someone doing this","cn":""},{"en":"if someone plays their cards close to their chest or vest , they do not allow other people to know what they are planning to do next","cn":""}]},"collocations":{"phrases":["VERBS be | become","ADV. extremely, highly, unusually, very his highly secretive nature | almost | rather, slightly, somewhat","PREP. about They were very secretive about their plans."]},"media":{"uk":"media/ldoce/hwd/bre/4/secretive0205.mp3","us":"media/ldoce/hwd/ame/c/secretive.mp3"},"examples":[{"en":"He's very secretive about his work.","cn":"他对自己的工作讳莫如深。"},{"en":"The government has been accused of being secretive and undemocratic.","cn":"该政府被指责政务不公开﹑缺乏民主。"}],"oxford":{"phon":"ˈsiːkrətɪv","pos":"adjective","senses":[{"en":"tending or liking to hide your thoughts, feelings, actions, etc. from other people","cn":"惯于掩藏自己的；不外露的","ex":{"en":"He's very secretive about his work.","cn":"他对自己的工作讳莫如深。"}}]}},"septuagenarian":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"70 至 79 岁的人;古稀之年的人","en":"A septuagenarian is a person between 70 and 79 years old.","ex":{"en":"...septuagenarian author Mary Wesley.","cn":"已步入古稀之年的作家玛丽·韦斯利"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"someone who is between 70 and 79 years old","cn":"七十多岁的人"}]},"media":{"uk":"media/ldoce/hwd/bre/9/ld41septuagenarian.mp3","us":"media/ldoce/hwd/ame/6/septuagenarian.mp3"},"oxford":{"phon":"ˌseptjuədʒəˈneəriən","pos":"noun","senses":[{"en":"a person between 70 and 79 years old","cn":"70 至 79 岁的人"}]}},"seaport":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"海港市镇;港口城市","en":"A seaport is a town with a large harbour that is used by ships.","ex":{"en":"...the Baltic seaport of Rostock.","cn":"波罗的海沿岸的海港城市罗斯托克"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a large town on or near a coast, with a harbour that big ships can use","cn":"海港﹐海港市镇"}]},"media":{"uk":"media/ldoce/hwd/bre/b/ld41seaport.mp3","us":"media/ldoce/hwd/ame/8/seaport.mp3"},"examples":[{"en":"the Baltic seaports","cn":"波罗的海港口城市"}],"oxford":{"phon":"ˈsiːpɔːt","pos":"noun","senses":[{"en":"a town with a harbour used by large ships","cn":"海港城市","ex":{"en":"the Baltic seaports","cn":"波罗的海港口城市"}}]}},"serpent":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"蛇","en":"A serpent is a snake.","ex":{"en":"...the serpent in the Garden of Eden.","cn":"伊甸园里的那条蛇"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a snake, especially a large one","cn":"蛇〔尤指大蛇〕"}]},"media":{"uk":"media/ldoce/hwd/bre/9/serpent0205.mp3","us":"media/ldoce/hwd/ame/e/serpent.mp3"},"oxford":{"phon":"ˈsɜːpənt","pos":"noun","senses":[{"en":"a snake, especially a large one","cn":"蛇；（尤指）大蛇"}]}},"self-explanatory":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"无需解释的;明白易懂的;显而易见的","en":"Something that is self-explanatory is clear and easy to understand without needing any extra information or explanation.","ex":{"en":"I hope the graphs on the following pages are self-explanatory.","cn":"我希望后面几页的图表能一目了然。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"clear and easy to understand without needing any more explanation","cn":"无须解释的﹐明白易懂的﹐一目了然的"}]},"media":{"uk":"media/ldoce/hwd/bre/1/self_explanato0205.mp3","us":"media/ldoce/hwd/ame/5/self-explanatory.mp3"},"examples":[{"en":"The video controls are pretty self-explanatory.","cn":"录像机的这些控制键都是一看就懂的。"}],"oxford":{"phon":"ˌself ɪkˈsplænətri","pos":"adjective","senses":[{"en":"easy to understand and not needing any more explanation","cn":"无须解释的；明白易晓的；一目了然的","ex":{"en":"I think the title is self-explanatory.","cn":"我觉得这个标题一目了然。"}}]}},"self-aware":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"自知的;自明的;自觉的","en":"Someone who is self-aware knows and judges their own character well.","ex":{"en":"Doing a degree has increased my confidence and I feel much more self-aware.","cn":"攻读学位增强了我的自信，使我更加了解自己。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"knowledge and understanding of yourself","cn":""}]},"media":{"uk":"media/ldoce/hwd/bre/6/self_awareness0205.mp3","us":"media/ldoce/hwd/ame/0/laadself-awareness.mp3"},"oxford":{"phon":"ˌself əˈweə(r)","pos":"adjective","senses":[{"en":"having or showing knowledge and understanding of your own character","cn":"自知；自明；自觉","ex":{"en":"She was sufficiently self-aware to recognize the cause of her problems.","cn":"她有足够的自我意识，能够认识到问题的原因。"}}]}},"self-assertion":{"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"主见;自我主张","en":"Self-assertion is confidence that you have in speaking firmly about your opinions and demanding the rights that you believe you should have.","ex":{"en":"...her silence and lack of self-assertion","cn":"她的沉默和缺乏主见"}}]},"vocab":{"pos":"n","senses":[{"en":"A self-assertion is a boastful statement. \"I am the greatest!\" is a self-assertion . Self-assertion is great if you’re a boxer like Muhammad Ali, but usually annoying if you’re not."}]},"oxford":{"phon":"ˌself əˈsɜːʃn","pos":"noun","senses":[{"en":"the quality of being very confident and not afraid to express your opinions","cn":"自信且勇于表达；自我肯定"}]}},"seafarer":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"水手;海员;经常乘船旅行的人","en":"Seafarers are people who work on ships or people who travel regularly on the sea.","ex":{"en":"The Estonians have always been seafarers.","cn":"爱沙尼亚人总是在海上漂泊。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a sailor or someone who travels regularly by ship","cn":"水手﹐海员﹔经常乘船旅行的人"}]},"media":{"uk":"media/ldoce/hwd/bre/f/ld41seafarer.mp3","us":"media/ldoce/hwd/ame/f/ld41seafarer.mp3"},"oxford":{"phon":"ˈsiːfeərə(r)","pos":"noun","senses":[{"en":"a sailor","cn":"水手；海员"}]}},"seashore":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"海岸;海滨;海滩","en":"The seashore is the part of a coast where the land slopes down into the sea.","ex":{"en":"She takes her inspiration from shells and stones she finds on the seashore.","cn":"她从在海滩上捡到的贝壳和石子中汲取灵感。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"the land at the edge of the sea, consisting of sand and rocks","cn":"海滨﹐海岸"}]},"media":{"uk":"media/ldoce/hwd/bre/2/seashore0205.mp3","us":"media/ldoce/hwd/ame/3/seashore.mp3"},"oxford":{"phon":"ˈsiːʃɔː(r)","pos":"noun","senses":[{"en":"the land along the edge of the sea or ocean, usually where there is sand and rocks","cn":"海岸；海滨","lab":"especially British English","ex":{"en":"He liked to look for shells on the seashore.","cn":"他喜欢在海滨捡贝壳。"}}]}},"self-service":{"collins":{"senses":[{"pos":"ADJ 形容词","cn":"自我服务的;(商店)自选的;(饭店)自助的","en":"A self-service shop, restaurant, or garage is one where you get things for yourself rather than being served by another person."}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"a self-service restaurant, shop etc is one in which you get things for yourself and then pay for them 〔","cn":"餐馆﹑商店等〕自助（式）的"}]},"media":{"uk":"media/ldoce/hwd/bre/2/self_service0205.mp3","us":"media/ldoce/hwd/ame/f/self-service.mp3"},"examples":[{"en":"The cafe provides quick self-service at low prices.","cn":"那家小餐馆提供价格低廉、方便快捷的自助餐。"}],"oxford":{"phon":"ˌself ˈsɜːvɪs","pos":"adjective","senses":[{"en":"a self-service shop, restaurant, etc. is one in which customers serve themselves and then pay for the goods","cn":"自我服务的；（商店）自选的；（餐厅）自助的"},{"en":"the system in which customers serve themselves and then pay for the goods in a shop, restaurant, etc.","cn":"自我服务的；（商店）自选的；（餐厅）自助的","ex":{"en":"The cafe provides quick self-service at low prices.","cn":"这家咖啡店低价提供便捷自助服务。"},"pos":"noun"}]}},"seep":{"collins":{"senses":[{"pos":"VERB 动词","cn":"渗透;渗漏","en":"If something such as liquid or gas seeps somewhere, it flows slowly and in small amounts into a place where it should not go.","ex":{"en":"Radioactive water had seeped into underground reservoirs","cn":"放射性水已经渗入地下蓄水层中。"}},{"pos":"VERB 动词","cn":"(秘密)逐渐外泄;(不快的情感)逐渐释放","en":"If something such as secret information or an unpleasant emotion seeps somewhere, it comes out gradually.","ex":{"en":"...the tide of racism which is sweeping Europe seeps into Britain.","cn":"正席卷欧洲的种族主义浪潮逐渐渗透到英国。"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"if something penetrates an object or substance, it fully enters it, or goes through it","cn":""},{"en":"if liquid seeps in , it gradually enters a substance or a place","cn":""},{"en":"if a liquid or gas permeates an object or substance it enters it and spreads through it","cn":""}]},"vocab":{"pos":"v","senses":[{"en":"Seep means to leak slowly. When you see the word, imagine water coming in through your sneakers on a rainy day. It's not a lot of water, but your feet still get pretty wet."}]},"collocations":{"phrases":["ADV. gradually, slowly | away, out, through The power had gradually seeped away.","VERB + SEEP begin to","PREP. from Blood was seeping slowly from the wound. | into, out of Water was seeping out of the tank. | through The damp seeped through her "]},"media":{"uk":"media/ldoce/hwd/bre/5/seep0205.mp3","us":"media/ldoce/hwd/ame/7/seep.mp3"},"examples":[{"en":"Water seeped from a crack in the pipe.","cn":"水从管道的一个裂缝中渗出。"},{"en":"Blood was beginning to seep through the bandages.","cn":"血开始从绷带渗出来。"}],"oxford":{"phon":"siːp","pos":"verb","senses":[{"en":"to flow slowly and in small quantities through something or into something","cn":"渗；渗透","lab":"figurative","ex":{"en":"Blood was beginning to seep through the bandages.","cn":"血开始从绷带渗出来。"}}]}},"seller":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"卖者;销售者;销售商","en":"A seller of a type of thing is a person or company that sells that type of thing.","ex":{"en":"...a flower seller.","cn":"卖花人"}},{"pos":"N-COUNT 可数名词","cn":"(交易的)卖方","en":"In a business deal, the seller is the person who is selling something to someone else.","ex":{"en":"In theory, the buyer could ask the seller to have a test carried out","cn":"理论上，买方可以要求卖方进行一次测试。"}},{"pos":"N-COUNT 可数名词","cn":"(畅销或滞销的)商品","en":"If you describe a product as, for example, a big seller, you mean that large numbers of it are being sold.","ex":{"en":"The gift shop's biggest seller is a photo of Nixon meeting Presley.","cn":"这家礼品店最畅销的商品是尼克松会见猫王普雷斯利的照片。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a company or person that sells goods to the public in a shop - used especially in business contexts","cn":""},{"en":"a person or company that sells goods in large quantities and at low prices, especially to other companies that then sell the goods to the public","cn":""},{"en":"a person or company that buys and sells large quantities of goods such as wine, or basic materials such as coal and wood","cn":""}]},"media":{"uk":"media/ldoce/hwd/bre/d/brelasdeseller.mp3","us":"media/ldoce/hwd/ame/6/cellar.mp3"},"examples":[{"en":"This particular model is one of our biggest sellers.","cn":"这种型号是我们销路最好的产品之一。"},{"en":"The law is intended to protect both the buyer and the seller.","cn":"这项法律旨在保护买卖双方。"}],"oxford":{"phon":"ˈselə(r)","pos":"noun","senses":[{"en":"a person who sells something","cn":"卖者；销售者；卖方","ex":{"en":"a flower seller","cn":"卖花人"}},{"en":"a product that has been sold in the amounts or way mentioned","cn":"（畅销、滞销等的）商品","ex":{"en":"This particular model is one of our biggest sellers.","cn":"这种型号是我们销路最好的产品之一。"}}]}},"self-effacement":{"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"自我谦避;自我轻视","en":"Someone's self-effacement is their unwillingness to talk about themselves or draw attention to themselves.","ex":{"en":"He was modest to the point of self-effacement.","cn":"他过于谦虚，甚至到了自我轻视的程度。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"not wanting to talk about your abilities or achievements and to say that you are good at something, even when you are – used to show approval","cn":""},{"en":"not wanting to talk about yourself or to attract attention","cn":""},{"en":"not wanting to be noticed and not expecting to be treated in a special way","cn":""}]},"media":{"uk":"media/ldoce/hwd/bre/e/self_effacing0205.mp3","us":"media/ldoce/hwd/ame/2/self-effacing.mp3"},"examples":[{"en":"a quiet self-effacing man","cn":""}],"oxford":{"phon":"ˌself ɪˈfeɪsmənt","pos":"noun","senses":[{"en":"the fact of trying not to attract attention to yourself or your abilities","cn":"谦逊的；不求闻达的"}]}},"sexism":{"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"(通常指对女性的)性别歧视，性别偏见","en":"Sexism is the belief that the members of one sex, usually women, are less intelligent or less capable than those of the other sex and need not be treated equally. It is also the behaviour which is the result of this belief.","ex":{"en":"Groups like ours are committed to eradicating homophobia, racism and sexism.","cn":"一些像我们这样的团体致力于消除对同性恋的憎恶、种族歧视和性别歧视。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"an unreasonable dislike and distrust of people who are different from you in some way, especially because of their race, sex, religion etc","cn":""},{"en":"the practice of treating one group of people differently from another in an unfair way","cn":""},{"en":"an unreasonable refusal to accept beliefs, customs, and ways of thinking that are different from your own","cn":""}]},"vocab":{"pos":"n","senses":[{"en":"Sexism means discrimination against people because of their sex: anything unfair to males or females, because they're males or females, is an example of sexism ."}]},"collocations":{"phrases":["ADJ. blatant, rampant She was shocked by his blatant sexism. Sexism is rampant in many institutions.","VERB + SEXISM combat, fight (against) efforts to combat sexism in the workplace"]},"media":{"uk":"media/ldoce/hwd/bre/c/sexism0205.mp3","us":"media/ldoce/hwd/ame/4/sexism.mp3"},"examples":[{"en":"legislation designed to combat sexism in the work place","cn":"旨在抵制工作场所的性别歧视的法规"},{"en":"a study of sexism in language","cn":"对语言中存在的性别歧视的研究"}],"oxford":{"phon":"ˈseksɪzəm","pos":"noun","senses":[{"en":"the unfair treatment of people, especially women, because of their sex; the attitude that causes this","cn":"（尤指对女性的）性别歧视，性别偏见","ex":{"en":"legislation designed to combat sexism in the workplace","cn":"旨在抵制工作场所的性别歧视的法规"}}]}},"sentient":{"collins":{"senses":[{"pos":"ADJ 形容词","cn":"有感知能力的;有知觉力的","en":"A sentient being is capable of experiencing things through its senses.","ex":{"en":"...sentient creatures human and nonhuman alike.","cn":"有知觉能力的人类和非人类生物"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"able to experience things through your senses","cn":"有感知力的﹐有知觉力的"}]},"vocab":{"pos":"adj","senses":[{"en":"Someone sentient is able to feel things, or sense them. Sentient usually occurs in phrases like \" sentient beings\" and \" sentient creatures,\" making it clear that things that don’t have life don’t have feelings. Explain that to a pet rock."}]},"media":{"uk":"media/ldoce/hwd/bre/3/ld41sentient.mp3","us":"media/ldoce/hwd/ame/0/sentient.mp3"},"examples":[{"en":"Man is a sentient being.","cn":"人是有感觉的生物。"}],"oxford":{"phon":"ˈsentiənt","pos":"adjective","senses":[{"en":"able to see or feel things through the senses","cn":"有感觉能力的；有知觉力的","ex":{"en":"Man is a sentient being.","cn":"人是有感觉的生物。"}}]}},"self-determination":{"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"(国家的)自立，自主权","en":"Self-determination is the right of a country to be independent, instead of being controlled by a foreign country, and to choose its own form of government."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"the right of the people of a particular country to govern themselves and to choose the type of government they will have 〔","cn":"民族的〕自决权﹐自决"}]},"media":{"uk":"media/ldoce/hwd/bre/9/ld41self-determina.mp3","us":"media/ldoce/hwd/ame/0/self-determination.mp3"},"oxford":{"phon":"ˌself dɪˌtɜːmɪˈneɪʃn","pos":"noun","senses":[{"en":"the right of a country or a region and its people to be independent and to choose their own government and political system","cn":"（国家或地区及其人民的）自决权","ex":{"en":"All nations have the right to self-determination.","cn":"所有国家都享有自决权。"}},{"en":"the right or ability of a person to control their own fate","cn":"（个人）自主权，自主能力","ex":{"en":"There were many influences which limited girls' ideas about their independence and self-determination.","cn":"有许多影响限制了女孩关于独立和自决的想法。"}}]}},"searcher":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"搜寻者","en":"Searchers are people who are looking for someone or something that is missing.","ex":{"en":"Searchers have found three mountain climbers missing since Saturday.","cn":"搜救人员已经找到了周六失踪的3名登山者。"}},{"pos":"N-COUNT 可数名词","cn":"探索者;探求者","en":"A searcher is someone who is trying to find something such as the truth or the answer to a problem.","ex":{"en":"He's not a real searcher after truth.","cn":"他不是一个真正探求真理的人。"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to look carefully for someone or something","cn":""},{"en":"to try to get someone or something you want or need","cn":""},{"en":"used especially when someone or something is difficult to find","cn":""}]},"media":{"uk":"media/ldoce/hwd/bre/5/brelasdesearch.mp3","us":"media/ldoce/hwd/ame/7/search1.mp3"},"examples":[{"en":"It was too dark to search further.","cn":""},{"en":"The area was thoroughly searched .","cn":""}],"oxford":{"phon":"ˈsɜːtʃə(r)","pos":"noun","senses":[{"en":"a person who is trying to find something/somebody","cn":"搜索者；查找者"}]}},"serpentine":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"弯弯曲曲的;蜿蜒的;盘旋的","en":"Something that is serpentine is curving and winding in shape, like a snake when it moves.","ex":{"en":"...serpentine woodland pathways.","cn":"蜿蜒的林间小路"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"winding like a snake","cn":"曲折的﹐蜿蜒的"},{"en":"complicated and difficult to understand","cn":"错综复杂的﹔难以理解的"}]},"vocab":{"pos":"adj","senses":[{"en":"You can use the adjective serpentine to describe things that look like a serpent or are snakelike. Looking down at the carved riverbeds in the Grand Canyon is like looking into a basket of snakes: the serpentine twists curve throughout the canyon floor."}]},"media":{"uk":"media/ldoce/hwd/bre/8/ld41serpentine.mp3","us":"media/ldoce/hwd/ame/3/serpentine1.mp3"},"examples":[{"en":"the serpentine course of the river","cn":"蜿蜒曲折的河道"},{"en":"a serpentine plot","cn":"曲折的情节"}],"oxford":{"phon":"ˈsɜːpəntaɪn","pos":"adjective","senses":[{"en":"bending and twisting like a snake","cn":"弯弯曲曲的；蜿蜒的；盘旋的；迂回的","ex":{"en":"the serpentine course of the river","cn":"蜿蜒曲折的河道"}}]}},"segue":{"collins":{"senses":[{"pos":"VERB 动词","cn":"(直接)转到，接入(另一首曲子、另一段对话)","en":"If something such as a piece of music or conversation segues into another piece of music or conversation, it changes into it or is followed by it without a break.","ex":{"en":"The piece segues into his solo with the strings.","cn":"曲终后紧接着就是他的弦乐独奏。"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to move smoothly from one song, idea, activity, condition etc to another 〔","cn":"顺畅地〕转到﹐接入〔另一首歌﹑另一个主意﹑另一种情形等〕"}]},"vocab":{"pos":"v n","senses":[{"en":"A segue is a smooth transition. When you segue in conversation, you change the topic so smoothly that people might not even notice."}]},"media":{"uk":"media/ldoce/hwd/bre/4/ld41segue.mp3","us":"media/ldoce/hwd/ame/e/laadsegue.mp3"},"examples":[{"en":"a spiritual that segued into a singalong chorus","cn":"一首转为会众集体跟唱的灵歌"},{"en":"He then segued into a discussion of atheism.","cn":"然后他转入对无神论的论述。"}],"oxford":{"phon":"ˈseɡweɪ","pos":"verb","senses":[{"en":"to move smoothly from one song, subject, place, etc. to another","cn":"（顺利）转到，接入（另一首歌、话题、地方等）","ex":{"en":"a spiritual that segued into a singalong chorus","cn":"一首转为会众集体跟唱的灵歌"}},{"en":"a smooth movement from one song, subject, place, etc. to another","cn":"（顺利）转到，接入（另一首歌、话题、地方等）","ex":{"en":"His comments offered the perfect segue to the questions she wanted to ask him.","cn":"他的评论为她想问他的问题提供了完美的衔接。"},"pos":"noun"}]}},"semibreve":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"全音符","en":"A semibreve is a musical note that has a time value equal to two half notes."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a musical note which continues for four beat s","cn":"全音符"}]},"media":{"uk":"media/ldoce/hwd/bre/f/ld41semibreve.mp3","us":"media/ldoce/hwd/ame/f/ld41semibreve.mp3","img":["media/thumb/semibreve.jpg"]},"oxford":{"phon":"ˈsemibriːv","pos":"noun","senses":[{"en":"a note that lasts as long as four crotchets","cn":"全音符"}]}},"sensational":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"(结果、事件、局势)轰动性的，引起哗然的","en":"A sensational result, event, or situation is so remarkable that it causes great excitement and interest.","ex":{"en":"The world champions suffered a sensational defeat.","cn":"世界冠军遭遇惨败，引起了一片哗然。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"(故事、报道)耸人听闻的，哗众取宠的","en":"You can describe stories or reports as sensational if you disapprove of them because they present facts in a way that is intended to cause feelings of shock, anger, or excitement.","ex":{"en":"...sensational tabloid newspaper reports.","cn":"哗众取宠的小报报道"}},{"pos":"ADJ 形容词","cn":"极好的;绝妙的","en":"You can describe something as sensational when you think that it is extremely good.","ex":{"en":"Her voice is sensational","cn":"她的嗓音非常动听。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"very interesting, exciting, and surprising","cn":"令人极度兴奋的﹐轰动的"},{"en":"intended to interest, excite, or shock people – used to show disapproval","cn":"大肆渲染的，耸人听闻的"},{"en":"very good","cn":"极棒的﹐极好的"}]},"vocab":{"pos":"adj","senses":[{"en":"Something sensational gets your attention. It's either amazing or a little trashy — like a sensational tabloid story."}]},"media":{"uk":"media/ldoce/hwd/bre/d/sensational0205.mp3","us":"media/ldoce/hwd/ame/5/sensational.mp3"},"examples":[{"en":"The result was a sensational 4–1 victory.","cn":"比赛结果是轰动性的，以 4:1 狂胜对手。"},{"en":"They won sensationally against the top team.","cn":"他们战胜了那支顶级球队，引起了轰动。"}],"oxford":{"phon":"senˈseɪʃənl","pos":"adjective","senses":[{"en":"causing great surprise, excitement, or interest","cn":"轰动的；引起哗然的","ex":{"en":"The result was a sensational 4–1 victory.","cn":"比赛结果是轰动性的，以 4:1 狂胜对手。"}},{"en":"trying to get your interest by presenting facts or events as worse or more shocking than they really are","cn":"哗众取宠的；耸人听闻的","lab":"disapproving","ex":{"en":"sensational news stories","cn":"引起轰动的新闻报道"}},{"en":"extremely good; wonderful","cn":"极好的；绝妙的","lab":"informal","ex":{"en":"You look sensational in that dress!","cn":"你穿这件连衣裙漂亮极了！"}}]}},"sepulchre":{"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a small room or building in which the bodies of dead people were put","cn":"墓室﹐冢"}]},"vocab":{"pos":"n","senses":[{"en":"There are many possible resting places for your body once you die, and a sepulcher is the best option if you want a fancy room made entirely from stone. Think it over, because you can only choose once."}]},"media":{"uk":"media/ldoce/hwd/bre/e/sepulchre0205.mp3","us":"media/ldoce/hwd/ame/8/amelasdesepulchre.mp3"},"oxford":{"phon":"ˈseplkə(r)","pos":"noun","senses":[{"en":"a place for a dead body, either cut in rock or built of stone","cn":"（在岩石上凿出或用石头砌成的）坟墓，墓穴"}]}},"self-centred":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"自我中心的;只顾自己的;自私自利的","en":"Someone who is self-centred is only concerned with their own wants and needs and never thinks about other people.","ex":{"en":"He was self-centred, but he wasn't cruel.","cn":"他很自私，但是并非无情。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"someone who is selfish only thinks about what they need or want, and never thinks about how other people feel or what other people want","cn":""},{"en":"paying so much attention to yourself that you do not notice what is happening to other people","cn":"自我中心的﹐只顾自己的﹐自私的"},{"en":"someone who is egocentric believes that what they do and think is much more important than what anyone else thinks or does","cn":""}]},"media":{"uk":"media/ldoce/hwd/bre/e/brelasdeself-centred.mp3","us":"media/ldoce/hwd/ame/b/self-centered.mp3"},"oxford":{"phon":"ˌself ˈsentəd","pos":"adjective","senses":[{"en":"tending to think only about yourself and not thinking about the needs or feelings of other people","cn":"自我中心的；只考虑自己的","ex":{"en":"She's completely self-centred.","cn":"她完全以自我为中心。"}}]}},"seemly":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"得体的;适当的;合乎礼仪的","en":"Seemly behaviour or dress is appropriate in the particular circumstances.","ex":{"en":"Self-assertion was not thought seemly in a woman.","cn":"人们认为女性不应该过于自信。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"suitable for a particular situation or social occasion, according to accepted standards of behaviour","cn":"适宜的﹐得体的﹐合乎行为规范的"}]},"vocab":{"pos":"adj","senses":[{"en":"You don't want to seem anything less than seemly , especially in the presence of the Queen. Only seemly behavior is allowed when she's around."}]},"media":{"uk":"media/ldoce/hwd/bre/3/ld41seemly.mp3","us":"media/ldoce/hwd/ame/e/seemly.mp3"},"examples":[{"en":"It was not seemly for ladies to talk about money.","cn":"女士谈论钱的事似乎不大得体。"}],"oxford":{"phon":"ˈsiːmli","pos":"adjective","senses":[{"en":"appropriate for a particular social situation","cn":"合适的；得体的；合乎礼仪的","ex":{"en":"It was not considered seemly to talk in such a way in front of the children.","cn":"在孩子们面前这样说话被认为不太合适。"}}]}},"sedimentary":{"collins":{"senses":[{"pos":"ADJ 形容词","cn":"由沉淀物形成的;沉积而成的","en":"Sedimentary rocks are formed from sediment left by water, ice, or wind."}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"made of the solid substances that settle at the bottom of the sea, rivers, lakes etc 〔","cn":"在海﹑河﹑湖等的底部〕沉积的﹐沉积形成的"}]},"vocab":{"pos":"adj","senses":[{"en":"Anything sedimentary is formed by or resembles sediment, which consists of little particles of earth that collect in natural bodies of water."}]},"media":{"uk":"media/ldoce/hwd/bre/2/ld41sedimentary.mp3","us":"media/ldoce/hwd/ame/e/sedimentary.mp3"},"examples":[{"en":"sedimentary rocks","cn":"沉积岩"},{"en":"sedimentary rock","cn":"沉积岩"}],"oxford":{"phon":"ˌsedɪˈmentri","pos":"adjective","senses":[{"en":"connected with or formed from the sand, stones, mud, etc. that settle at the bottom of lakes, etc.","cn":"沉积的；沉积形成的","ex":{"en":"sedimentary rocks","cn":"沉积岩"}}]}},"semitropical":{"collins":{"senses":[{"pos":"ADJ 形容词","cn":"副热带的;亚热带的","en":"Semi-tropical places have warm, wet air.","ex":{"en":"...a semi-tropical island.","cn":"一个亚热带的岛屿"}},{"pos":"ADJ 形容词","cn":"(花草、树木)副热带的，亚热带的","en":"Semi-tropical plants and trees grow in places where the air is warm and wet.","ex":{"en":"The inn has a garden of semi-tropical vegetation.","cn":"这家小酒店的花园里种着亚热带植物。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"subtropical","cn":"副热带的﹐亚热带的"}]},"media":{"uk":"media/ldoce/hwd/bre/9/ld41semitropical.mp3","us":"media/ldoce/hwd/ame/e/semitropical.mp3"}},"semicircle":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"半圆;半圆弧;半圆形","en":"A semi-circle is one half of a circle, or something having the shape of half a circle.","ex":{"en":"They stood in a semi-circle round the teacher's chair and answered questions.","cn":"他们围着老师的椅子站成半圆形回答问题。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a shape with four straight sides that are equal in length and four angles of 90 degrees","cn":""},{"en":"a round shape that is like an O","cn":""},{"en":"half a circle","cn":"半圆"}]},"media":{"uk":"media/ldoce/hwd/bre/1/semicircle0205.mp3","us":"media/ldoce/hwd/ame/1/semicircle.mp3"},"examples":[{"en":"We sat in a semicircle round the fire.","cn":"我们坐在炉火前，围成一个半圆形。"},{"en":"a semicircle of chairs","cn":"摆成半圆形的椅子"}],"oxford":{"phon":"ˈsemisɜːkl","pos":"noun","senses":[{"en":"one half of a circle","cn":"半圆","lab":"geometry"},{"en":"a thing, or a group of people or things, like a semicircle in shape","cn":"半圆形","ex":{"en":"a semicircle of chairs","cn":"摆成半圆形的椅子"}}]}},"seraglio":{"vocab":{"pos":"n","senses":[{"en":"A seraglio refers to the apartments or rooms where a group of Turkish Muslim women live together, especially if they are a man's wives and concubines. In other words, a seraglio is a harem."}]}},"sensual":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"喜欢感官享受的;耽于肉欲的","en":"Someone or something that is sensual shows or suggests a great liking for physical pleasures, especially sexual pleasures.","ex":{"en":"He was a very sensual person","cn":"他是个登徒子。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"肉欲的;愉悦感官的","en":"Something that is sensual gives pleasure to your physical senses rather than to your mind.","ex":{"en":"It was an opera, very glamorous and very sensual.","cn":"这场歌剧美轮美奂，声色俱佳,给感官以极大享受。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"sexually attractive","cn":""},{"en":"seeming to show strong sexual feelings and a desire for sexual pleasure","cn":""},{"en":"intended to make someone feel sexually excited","cn":""}]},"vocab":{"pos":"adj","senses":[{"en":"Sensual means physically pleasing. It often is used in a sexual context, but is not exclusively sexual in meaning."}]},"media":{"uk":"media/ldoce/hwd/bre/b/sensual0205.mp3","us":"media/ldoce/hwd/ame/e/sensual.mp3"},"examples":[{"en":"He was darkly sensual and mysterious.","cn":"他耽于肉欲，而且让人捉摸不透。"},{"en":"the sensuality of his poetry","cn":"他的诗专注于感官享受"}],"oxford":{"phon":"ˈsenʃuəl","pos":"adjective","senses":[{"en":"connected with your physical feelings; giving pleasure to your physical senses, especially sexual pleasure","cn":"感官的；肉欲的；愉悦感官的","ex":{"en":"sensual pleasure","cn":"感官之乐"}},{"en":"suggesting an interest in physical pleasure, especially sexual pleasure","cn":"喜欢感官享受的；耽于肉欲的","ex":{"en":"sensual lips","cn":"性感的嘴唇"}}]}},"seasoned":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"富有经验的;老练的","en":"You can use seasoned to describe a person who has a lot of experience of something. For example, a seasoned traveller is a person who has travelled a lot.","ex":{"en":"The author is a seasoned academic","cn":"作者是一位经验丰富的学者。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"someone who is experienced knows a lot about a job or activity because they have done it for a long time","cn":""},{"en":"someone who has done something regularly for a long time and knows all the problems involved","cn":""},{"en":"someone who is practised in a particular job or skill has become good at it through experience","cn":""}]},"vocab":{"pos":"adj","senses":[{"en":"Seasoned describes a person who has been around forever, doing what they do, and doing it well — throughout the seasons. They have lots of experience, and they can handle just about anything that comes their way."}]},"media":{"uk":"media/ldoce/hwd/bre/d/brelasdeseasoned.mp3","us":"media/ldoce/hwd/ame/b/seasoned.mp3"},"examples":[{"en":"a seasoned campaigner/performer/traveller, etc.","cn":"经验丰富的社会运动家、表演者、旅行家等"},{"en":"The sausage was very highly seasoned.","cn":"这香肠调味很浓。"}],"oxford":{"phon":"ˈsiːznd","pos":"adjective","senses":[{"en":"having a lot of experience of a particular activity","cn":"富有经验的；老于此道的","g":"[usually before noun]","ex":{"en":"a seasoned campaigner/performer/traveller, etc.","cn":"经验丰富的社会运动家、表演者、旅行家等"}},{"en":"with salt, pepper, etc. added to it","cn":"调好味的；加了作料的","ex":{"en":"Toss the meat in seasoned flour.","cn":"将肉拌入调味面粉中。"}},{"en":"made suitable for use by being left outside","cn":"风干的，晾干的（可加工使用）","ex":{"en":"seasoned timber","cn":"干燥可用的木料"}}]}},"serum":{"collins":{"senses":[{"pos":"N-VAR 可变名词","cn":"免疫血清","en":"A serum is a liquid that is injected into someone's blood to protect them against a poison or disease."},{"pos":"N-UNCOUNT 不可数名词","cn":"血清","en":"Serum is the watery, pale yellow part of blood."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a liquid containing substances that fight infection or poison, that is put into a sick person’s blood 〔","cn":"用于治疗的〕免疫血清"},{"en":"the thin part of blood or the liquid from a plant","cn":"血清﹔〔植物的〕浆液﹐树液"}]},"media":{"uk":"media/ldoce/hwd/bre/9/serum0205.mp3","us":"media/ldoce/hwd/ame/0/serum.mp3"},"examples":[{"en":"snakebite serum","cn":"抗蛇毒血清"}],"oxford":{"phon":"ˈsɪərəm","pos":"noun","senses":[{"en":"the thin liquid that remains from blood when the rest has clotted","cn":"血清","g":"[uncountable]","lab":"biology"},{"en":"serum taken from the blood of an animal and given to people to protect them from disease, poison, etc.","cn":"免疫血清","g":"[uncountable, countable]","lab":"medical","ex":{"en":"snakebite serum","cn":"抗蛇毒血清"}},{"en":"any liquid like water in body tissue","cn":"浆液（体液的水样部分）","g":"[uncountable]"}]}},"see-through":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"(衣服)薄得透明的，透视的","en":"See-through clothes are made of thin cloth, so that you can see a person's body or underwear through them."}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"easy to see through, rather than coloured or dirty","cn":""},{"en":"clear – used especially about materials and solid things. Transparent is a little more formal than clear","cn":""},{"en":"made of a very thin material that you can see through – used especially about women’s clothes","cn":""}]},"media":{"uk":"media/ldoce/hwd/bre/3/ld41see-through.mp3","us":"media/ldoce/hwd/ame/7/see-through.mp3"},"examples":[{"en":"a see-through blouse","cn":"透明的女式衬衫"}],"oxford":{"phon":"ˈsiː θruː","pos":"adjective","senses":[{"en":"very thin so that you can see through it","cn":"薄至透明的；可透视的","ex":{"en":"a see-through blouse","cn":"透明的女式衬衫"}}]}},"seasonal":{"collins":{"senses":[{"pos":"ADJ 形容词","cn":"季节的;季节性的;随季节变化的","en":"A seasonal factor, event, or change occurs during one particular time of the year.","ex":{"en":"...blaming seasonal factors for the unemployment increase in the west","cn":"把西部失业率的上升归咎于季节性因素"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"happening, expected, or needed during a particular season","cn":"季节性的﹐时令的﹐当令的"}]},"media":{"uk":"media/ldoce/hwd/bre/3/seasonal0205.mp3","us":"media/ldoce/hwd/ame/f/seasonal.mp3"},"examples":[{"en":"seasonal workers brought in to cope with the Christmas period","cn":"为应付圣诞节期间的业务而招聘的临时工"},{"en":"seasonally adjusted unemployment figures (= not including the changes that always happen in different seasons)","cn":"经季节因素调整的失业统计数字"}],"oxford":{"phon":"ˈsiːzənl","pos":"adjective","senses":[{"en":"happening or needed during a particular season; varying with the seasons","cn":"季节性的；随季节变化的","ex":{"en":"seasonal workers brought in to cope with the Christmas period","cn":"为应付圣诞节期间的业务而招聘的临时工"}},{"en":"typical of or suitable for the time of year, especially Christmas","cn":"节令性的；适应节日需要的；（尤指）圣诞节的","ex":{"en":"seasonal decorations","cn":"圣诞节装饰品"}}]}},"self-rule":{"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"同 self-government","en":"Self-rule is the same as self-government .","ex":{"en":"The agreement gives the territory limited self-rule.","cn":"这个协议规定该地区享有有限的自治权。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"when a country or part of a country is governed by its own citizens","cn":"自治"}]},"media":{"uk":"media/ldoce/hwd/bre/1/ld41self-rule.mp3","us":"media/ldoce/hwd/ame/c/self-rule.mp3"},"oxford":{"phon":"ˌself ˈruːl","pos":"noun","senses":[{"en":"the governing of a country or an area by its own people","cn":"自治","ex":{"en":"Protesters demanding self-rule clashed with police.","cn":"要求自治的抗议者与警察发生冲突。"}}]}},"seaside":{"collins":{"senses":[{"pos":"N-SING 单数名词","cn":"(尤指作为度假地的)海边，海滨","en":"You can refer to an area that is close to the sea, especially one where people go for their holidays, as the seaside .","ex":{"en":"I went to spend a few days at the seaside","cn":"我去海滨玩了几天。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"the part of a country that is close to the sea - use this when you are talking about a country or a large part of a country","cn":""},{"en":"the land along the edge of the sea or along the edge of a lake","cn":""},{"en":"an area of sand at the edge of the sea - use this especially to talk about a place where you go to relax and enjoy yourself","cn":""}]},"collocations":{"phrases":["VERB + SEASIDE go to Every summer we went to the seaside for two months.","SEASIDE + NOUN resort, town, village","PREP. at the ~ a holiday at the seaside | by the ~ They have a cottage by the seaside."]},"media":{"uk":"media/ldoce/hwd/bre/1/seaside_n0205.mp3","us":"media/ldoce/hwd/ame/a/seaside.mp3"},"examples":[{"en":"a seaside vacation home","cn":"海滨度假别墅"},{"en":"a trip to the seaside","cn":"去海滨旅行"}],"oxford":{"phon":"ˈsiːsaɪd","pos":"noun","senses":[{"en":"an area that is by the sea, especially one where people go for a day or a holiday","cn":"（尤指人们游玩、度假的）海边，海滨","lab":"especially British English","ex":{"en":"a trip to the seaside","cn":"去海滨旅行"}},{"en":"connected with an area that is by the sea, especially one where people go for a day or a holiday","cn":"（尤指人们游玩、度假的）海边，海滨","ex":{"en":"a seaside resort","cn":"海滨度假区"},"pos":"adjective"}]}},"sequestered":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"偏僻的;幽静的;与世隔绝的","en":"A sequestered place is quiet and far away from busy places."}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"a sequestered place is quiet and far away from people 〔","cn":"地方〕僻静的﹐与世隔绝的"}]},"media":{"uk":"media/ldoce/hwd/bre/d/sequestered0205.mp3","us":"media/ldoce/hwd/ame/d/sequestered.mp3"},"oxford":{"phon":"sɪˈkwestəd","pos":"adjective","senses":[{"en":"quiet and far away from people","cn":"僻静的；隐蔽幽静的","ex":{"en":"a sequestered valley","cn":"一个偏僻的山谷"}}]}},"seducer":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"(通常指男性)诱奸者，勾引者","en":"A seducer is someone, usually a man, who seduces someone else.","ex":{"en":"He is proud of his reputation as a seducer of young women.","cn":"他很得意自己“芳心猎手”这一名声。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a man who persuades someone to have sex with him","cn":"诱奸者"}]},"media":{"uk":"media/ldoce/hwd/bre/0/ld41seducer.mp3","us":"media/ldoce/hwd/ame/0/ld41seducer.mp3"},"oxford":{"phon":"sɪˈdjuːsə(r)","pos":"noun","senses":[{"en":"a person who seduces somebody","cn":"诱奸者"}]}},"sever":{"collins":{"senses":[{"pos":"VERB 动词","cn":"切开;割断;切下;割下","en":"To sever something means to cut completely through it or to cut it completely off.","ex":{"en":"Richardson severed his right foot in a motorbike accident.","cn":"理查森在一次摩托车事故中失去了他的右脚。"}},{"pos":"VERB 动词","cn":"(突然)断绝，中断(关系)","en":"If you sever a relationship or connection that you have with someone, you end it suddenly and completely.","ex":{"en":"She severed her ties with England","cn":"她断绝了和英国的往来。"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to cut part of something away from the rest of it","cn":""},{"en":"to cut something off by hitting it hard or cutting it with a sharp tool","cn":""},{"en":"to quickly remove something using scissors","cn":""}]},"vocab":{"pos":"v","senses":[{"en":"To sever something is to cut it off from the whole. If your girlfriend breaks up with you on your anniversary, you might respond by severing the blossoms off the roses you were planning to give her. (Just an idea.)"}]},"media":{"uk":"media/ldoce/hwd/bre/a/sever0205.mp3","us":"media/ldoce/hwd/ame/f/sever.mp3"},"examples":[{"en":"The two countries have severed all diplomatic links.","cn":"两国断绝了一切外交关系。"},{"en":"His hand was severed from his arm.","cn":"他的手从胳膊上截断了。"}],"oxford":{"phon":"ˈsevə(r)","pos":"verb","senses":[{"en":"to cut something into two pieces; to cut something off something","cn":"切开；割断；切下；割下","ex":{"en":"to sever a rope","cn":"割断绳子"}},{"en":"to completely end a relationship or all communication with somebody","cn":"断绝；中断","ex":{"en":"The two countries have severed all diplomatic links.","cn":"两国断绝了一切外交关系。"}}]}},"seniority":{"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"资历;地位;级别","en":"A person's seniority in an organization is the importance and power that they have compared with others, or the fact that they have worked there for a long time.","ex":{"en":"He has said he will fire editorial employees without regard to seniority.","cn":"他说过不管资历如何,任何编辑人员他都有可能解雇。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"if you have seniority in a company or organization, you have worked there a long time and have some official advantages 〔","cn":"在某一公司或组织供职的〕年资﹐资历"},{"en":"when you are older or higher in rank than someone else","cn":"年长﹔职位[级别]高"}]},"vocab":{"pos":"n","senses":[{"en":"Seniority refers to being ranked higher in an organization since you have been there longer. Who has seniority in a high school? The seniors of course!"}]},"collocations":{"phrases":["VERB + SENIORITY attain, gain","PREP. by ~ Promotion in the job was by seniority.","PHRASES in order of seniority, a level of seniority, next in seniority On the death of the captain, the officer next in seniority assumed co"]},"media":{"uk":"media/ldoce/hwd/bre/8/seniority0205.mp3","us":"media/ldoce/hwd/ame/e/seniority.mp3"},"examples":[{"en":"Should promotion be based on merit or seniority?","cn":"提拔一个人应当看业绩，还是看资历？"},{"en":"a lawyer with five years' seniority","cn":"有五年从业经验的律师"}],"oxford":{"phon":"ˌsiːniˈɒrəti","pos":"noun","senses":[{"en":"the fact of being older or of a higher rank than others","cn":"年长；级别高","ex":{"en":"a position of seniority","cn":"高级职位"}},{"en":"the rank that you have in a company because of the length of time you have worked there","cn":"资历","ex":{"en":"a lawyer with five years’ seniority","cn":"有五年从业经验的律师"}}]}},"self-deprecating":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"自我贬低的;过分谦虚的","en":"If you describe someone's behaviour as self-deprecating, you mean that they criticize themselves or represent themselves as foolish in a light-hearted way.","ex":{"en":"Sharon tells the story of that night with self-deprecating humour.","cn":"沙伦以幽默自嘲的口吻讲述那一夜的故事。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"not wanting to talk about your abilities or achievements and to say that you are good at something, even when you are – used to show approval","cn":""},{"en":"not wanting to talk about yourself or to attract attention","cn":""},{"en":"not wanting to be noticed and not expecting to be treated in a special way","cn":""}]},"vocab":{"pos":"adj","senses":[{"en":"A self-deprecating person knows her own weaknesses and shortcomings and isn't afraid to point them out, often in a humorous way."}]},"media":{"uk":"media/ldoce/hwd/bre/9/self_deprecati0205.mp3","us":"media/ldoce/hwd/ame/5/laadself-deprecating.mp3"},"examples":[{"en":"He gave a self-deprecating shrug.","cn":"他自谦地耸耸肩。"},{"en":"self-deprecating humour","cn":"自嘲"}],"oxford":{"phon":"ˌself ˈdeprəkeɪtɪŋ","pos":"adjective","senses":[{"en":"done in a way that makes your own achievements or abilities seem unimportant","cn":"自我贬低的；自谦的","ex":{"en":"He gave a self-deprecating shrug.","cn":"他自谦地耸耸肩。"}}]}},"sedan":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"大轿车;厢式轿车","en":"A sedan is a car with seats for four or more people, a fixed roof, and a boot that is separate from the part of the car that you sit in."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a car that has four doors, seats for at least four people, and a boot","cn":"大轿车﹐厢式轿车"}]},"media":{"uk":"media/ldoce/hwd/bre/5/ld41sedan.mp3","us":"media/ldoce/hwd/ame/4/sedan.mp3"},"oxford":{"phon":"sɪˈdæn","pos":"noun","senses":[{"en":"a car with four doors and a boot (= space at the back for carrying things) which is separated from the part where the driver and passengers sit","cn":"小轿车；（三厢四门）轿车"}]}},"seaman":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"水手;海员;水兵","en":"A seaman is a sailor, especially one who is not an officer.","ex":{"en":"The men emigrate to work as seamen.","cn":"男人们移居国外当海员。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a sailor on a ship or in the navy who is not an officer","cn":"水手﹐海员﹔水兵"},{"en":"someone who has a lot of experience of ships and the sea","cn":"航海老手"}]},"media":{"uk":"media/ldoce/hwd/bre/e/seaman0205.mp3","us":"media/ldoce/hwd/ame/1/seaman.mp3"},"examples":[{"en":"Seaman Bates 《","cn":"水手贝茨》"},{"en":"a merchant seaman","cn":"商船船员"}],"oxford":{"phon":"ˈsiːmən","pos":"noun","senses":[{"en":"a member of the navy or a sailor on a ship below the rank of an officer","cn":"水兵；水手；海员","ex":{"en":"Seaman Bates","cn":"《水手贝茨》"}}]}},"sensibility":{"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"感受力;感悟力;鉴赏力","en":"Sensibility is the ability to experience deep feelings.","ex":{"en":"Everything he writes demonstrates the depth of his sensibility.","cn":"他笔下的一切都显示出他深深的感悟。"}},{"pos":"N-VAR 可变名词","cn":"敏感;善感;感情","en":"Someone's sensibility is their tendency to be influenced or offended by things.","ex":{"en":"He was unable to control his sensibility","cn":"他不能控制自己的过分敏感。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"the way that someone reacts to particular subjects or types of behaviour","cn":"感情〔人对某些话题或行为作出的反应〕"},{"en":"the ability to understand feelings, especially those expressed in literature or art 〔","cn":"尤指对文学﹑艺术的〕感受力﹐鉴赏力﹐敏感性"}]},"vocab":{"pos":"n","senses":[{"en":"Sensibility is your ability to feel or be aware of something. Your artistic sensibility might allow you to understand even the most complex work of art."}]},"media":{"uk":"media/ldoce/hwd/bre/c/sensibility0205.mp3","us":"media/ldoce/hwd/ame/4/sensibility.mp3"},"examples":[{"en":"a man of impeccable manners, charm and sensibility","cn":"一个有魅力、懂感情、举止无可挑剔的男人"},{"en":"The article offended her religious sensibilities.","cn":"那篇文章伤害了她的宗教感情。"}],"oxford":{"phon":"ˌsensəˈbɪləti","pos":"noun","senses":[{"en":"the ability to experience and understand deep feelings, especially in art and literature","cn":"（尤指文艺方面的）感受能力，鉴赏力，敏感性","g":"[uncountable, countable]","ex":{"en":"a man of impeccable manners, charm and sensibility","cn":"一个有魅力、懂感情、举止无可挑剔的男人"}},{"en":"a person’s feelings, especially when the person is easily offended or influenced by something","cn":"（尤指易受伤害或影响的）感情","g":"[plural]","ex":{"en":"The article offended her religious sensibilities.","cn":"那篇文章伤害了她的宗教感情。"}}]}},"sensory":{"collins":{"senses":[{"pos":"ADJ 形容词","cn":"感官的;感觉的","en":"Sensory means relating to the physical senses.","ex":{"en":"...sensory information passing through the spinal cord.","cn":"经过脊髓传送的感官信息"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"relating to or using your senses of sight, hearing, smell, taste, or touch","cn":"感官的﹔感觉上的"}]},"vocab":{"pos":"adj","senses":[{"en":"The adjective sensory describes something relating to sensation — something that you feel with your physical senses. Sticking a knife into a toaster will give you a sensory experience, but so will smelling a rose. Stick with the rose."}]},"media":{"uk":"media/ldoce/hwd/bre/1/sensory0205.mp3","us":"media/ldoce/hwd/ame/6/sensory.mp3"},"examples":[{"en":"sensory organs","cn":"感觉器官"},{"en":"sensory deprivation","cn":"感觉丧失"}],"oxford":{"phon":"ˈsensəri","pos":"adjective","senses":[{"en":"connected with your physical senses","cn":"感觉的；感官的","ex":{"en":"sensory organs","cn":"感觉器官"}}]}},"semitic":{"collins":{"senses":[{"pos":"ADJ 形容词","cn":"闪米特语族的，闪语的(包括阿拉伯语和希伯来语)","en":"Semitic languages are a group of languages that include Arabic and Hebrew."},{"pos":"ADJ 形容词","cn":"闪米特人的;闪族的","en":"Semitic people belong to one of the groups of people who speak a Semitic language.","ex":{"en":"...the Semitic races.","cn":"闪米特人"}},{"pos":"ADJ 形容词","cn":"(有时指)犹太人的","en":"Semitic is sometimes used to mean Jewish."}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"belonging to the race of people that includes Jews, Arabs, and, in ancient times, Babylonians and Assyrians","cn":"闪米特人〔包括犹太人﹑阿拉伯人﹑古巴比伦人和古亚述人等〕的"},{"en":"relating to any of the languages of these people","cn":"闪米特语族的"},{"en":"another word for Jewish Jewish","cn":"的另一种说法"}]},"media":{"uk":"media/ldoce/hwd/bre/1/semitic0205.mp3","us":"media/ldoce/hwd/ame/b/semitic.mp3"},"oxford":{"phon":"səˈmɪtɪk","pos":"adjective","senses":[{"en":"of or connected with the language group that includes Hebrew and Arabic","cn":"闪米特语族的，闪语的（包括希伯来语和阿拉伯语）"},{"en":"of or connected with the people who speak Semitic languages, especially Hebrew and Arabic","cn":"闪米特人（尤指操希伯来语和阿拉伯语的人）的；闪族的"}]}},"seismograph":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"地震仪;测震仪","en":"A seismograph is an instrument for recording and measuring the strength of earthquakes."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"an instrument that measures and records the movement of the earth during an earthquake","cn":"地震仪"}]},"vocab":{"pos":"n","senses":[{"en":"A seismograph is an instrument scientists use to measure the strength of an earthquake."}]},"media":{"uk":"media/ldoce/hwd/bre/6/ld41seismograph.mp3","us":"media/ldoce/hwd/ame/8/seismograph.mp3"},"oxford":{"phon":"ˈsaɪzməɡrɑːf","pos":"noun","senses":[{"en":"an instrument that measures and records information about earthquakes","cn":"地震仪；测震仪"}]}},"self-drive":{"collins":{"senses":[{"pos":"ADJ 形容词","cn":"租车人自己驾驶的","en":"A self-drive car is one which you hire and drive yourself.","ex":{"en":"Any holiday in the USA and Canada is enhanced by renting a self-drive car.","cn":"租车自驾绝对会使在美国和加拿大的度假更加愉快。"}},{"pos":"ADJ 形容词","cn":"(度假)自己驾车的,自驾游的","en":"A self-drive holiday is one where you drive yourself to the place where you are staying, rather than being taken there by plane or coach.","ex":{"en":"...the growth in popularity of self-drive camping holidays.","cn":"自驾车野营度假的日益盛行"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"a self-drive car is one that you have hire d to drive yourself","cn":"租车人自己驾驶的"},{"en":"a self-drive holiday is one in which you use your own car to visit the holiday area 〔","cn":"度假〕自驾游的"}]},"media":{"uk":"media/ldoce/hwd/bre/9/ld41self-drive.mp3","us":"media/ldoce/hwd/ame/9/ld41self-drive.mp3"},"oxford":{"phon":"ˌself ˈdraɪv","pos":"adjective","senses":[{"en":"a self-drive car is one that you hire and drive yourself","cn":"租车人自行驾驶的"},{"en":"a self-drive holiday is one on which you use your own car or a car you hire to travel to the holiday area","cn":"自驾（游）的"}]}},"seabed":{"collins":{"senses":[{"pos":"N-SING 单数名词","cn":"海底;海床","en":"The seabed is the ground under the sea."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"the land at the bottom of the sea","cn":"海床﹐海底"}]},"media":{"uk":"media/ldoce/hwd/bre/4/seabed0205.mp3","us":"media/ldoce/hwd/ame/9/amelasdeseabed.mp3"}},"self-imposed":{"collins":{"senses":[{"pos":"ADJ 形容词","cn":"自己强加的;自愿承担的;自己规定的","en":"A self-imposed restriction, task, or situation is one that you have deliberately created or accepted for yourself.","ex":{"en":"He returned home in the summer of 1974 after eleven years of self-imposed exile","cn":"经历了 11 年的自我流放后，他于1974 年夏回归故里。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"a self-imposed rule, duty etc is one that you have made for yourself, and which no one has asked you to accept","cn":"自己规定的﹐自愿承担的"}]},"media":{"uk":"media/ldoce/hwd/bre/c/brelasdeself-imposed.mp3","us":"media/ldoce/hwd/ame/8/self-imposed.mp3"},"examples":[{"en":"She spent five years in self-imposed exile in Bolivia.","cn":"她在玻利维亚度过了五年的自我流放生活。"}],"oxford":{"phon":"ˌself ɪmˈpəʊzd","pos":"adjective","senses":[{"en":"a self-imposed task, duty, etc. is one that you force yourself to do rather than one that somebody else forces you to do","cn":"自己强加的；自愿负担的；自己规定的"}]}},"self-righteous":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"以正人君子自居的;自以为是的","en":"If you describe someone as self-righteous, you disapprove of them because they are convinced that they are right in their beliefs, attitudes, and behaviour and that other people are wrong.","ex":{"en":"He is critical of the monks, whom he considers narrow-minded and self-righteous.","cn":"他对僧侣们颇有微词，认为他们思想偏狭，自视清高。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"feeling very confident about how good you are and about your high moral standards, in a way that annoys other people","cn":""},{"en":"behaving as if you are morally better than other people, especially in telling them what you think is right and wrong","cn":""},{"en":"showing other people very clearly that you think you are morally better than they are","cn":""}]},"vocab":{"pos":"adj","senses":[{"en":"A self-righteous person thinks their beliefs and morals are better than everyone else's. If you're quite sure the charity of others pales in comparison with yours, you might be self-righteous ."}]},"media":{"uk":"media/ldoce/hwd/bre/a/self_righteous0205.mp3","us":"media/ldoce/hwd/ame/4/self-righteous.mp3"},"examples":[{"en":"She’s a vegetarian, but she’s not at all self-righteous about it.","cn":"她是个素食者﹐但她并不以此来标榜自己。"}],"oxford":{"phon":"ˌself ˈraɪtʃəs","pos":"adjective","senses":[{"en":"feeling or behaving as if what you say or do is always morally right, and other people are wrong","cn":"以正人君子自居的；自以为正直的","ex":{"en":"He was in one of his self-righteous moods.","cn":"他又以正人君子自居了。"}}]}},"self-assured":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"自信的;胸有成竹的","en":"Someone who is self-assured shows confidence in what they say and do because they are sure of their own abilities.","ex":{"en":"He's a self-assured, confident negotiator.","cn":"他是一个胸有成竹、充满信心的谈判者。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"sure that you have the ability to do something well or deal with situations successfully","cn":""},{"en":"confident, and not shy or nervous in social situations","cn":""},{"en":"confident, calm, and in control of your feelings even in a difficult situation","cn":""}]},"media":{"uk":"media/ldoce/hwd/bre/d/self_assured0205.mp3","us":"media/ldoce/hwd/ame/b/self-assured.mp3"},"oxford":{"phon":"ˌself əˈʃʊəd","pos":"adjective","senses":[{"en":"having a lot of confidence in yourself and your abilities","cn":"自信的；胸有成竹的","ex":{"en":"He grew more self-assured as he got older.","cn":"随着年龄的增长，他变得更加自信。"}}]}},"self-restraint":{"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"自我克制;自我约束","en":"If you show self-restraint, you do not do something even though you would like to do it, because you think it would be better not to."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"the ability to stop yourself doing or saying something, even though you want to, because it is more sensible not to do or say it","cn":"自我克制﹐自我约束"},{"en":"exercise/practise self-restraint The UN appealed for both sides to exercise self-restraint.","cn":"联合国呼吁双方要自我克制。"}]},"media":{"uk":"media/ldoce/hwd/bre/f/self_restraint0205.mp3","us":"media/ldoce/hwd/ame/b/self-restraint.mp3"},"examples":[{"en":"She exercised all her self-restraint and kept quiet.","cn":"她好不容易才忍住没说话。"}],"oxford":{"phon":"ˌself rɪˈstreɪnt","pos":"noun","senses":[{"en":"the ability to stop yourself doing or saying something that you want to because you know it is better not to","cn":"自我克制","ex":{"en":"She exercised all her self-restraint and kept quiet.","cn":"她好不容易才忍住没说话。"}}]}},"sextet":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"六重奏乐队;六重唱组合","en":"A sextet is a group of six musicians or singers who play or sing together.","ex":{"en":"...the Paul Rogers Sextet.","cn":"保罗·罗杰斯六人乐队"}},{"pos":"N-COUNT 可数名词","cn":"六重奏乐曲;六重唱乐曲","en":"A sextet is a piece of music written for six performers."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a group of six singers or musicians performing together","cn":"六重唱组﹔六重奏团"},{"en":"a piece of music for six performers","cn":"六重唱[奏]曲"}]},"media":{"uk":"media/ldoce/hwd/bre/9/ld41sextet.mp3","us":"media/ldoce/hwd/ame/7/sextet.mp3"},"examples":[{"en":"Mozart’s sextet in B flat","cn":"莫扎特的降B调六重奏曲"}],"oxford":{"phon":"seksˈtet","pos":"noun","senses":[{"en":"a group of six musicians or singers who play or sing together","cn":"六重奏乐团；六重唱组合","g":"[countable + singular or plural verb]"},{"en":"a piece of music for six musicians or singers","cn":"六重奏（曲）；六重唱（曲）","g":"[countable]"}]}},"seclusion":{"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"隔绝;隐退;隐居","en":"If you are living in seclusion, you are in a quiet place away from other people.","ex":{"en":"She lived in seclusion with her husband on their farm in Panama","cn":"她与丈夫隐居在他们在巴拿马的农场。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"the state of being private and away from other people","cn":"与世隔绝﹐隐居"}]},"vocab":{"pos":"n","senses":[{"en":"Seclusion means being separate, and apart from others, in a quiet kind of way. If you want seclusion , try a private island."}]},"collocations":{"phrases":["ADJ. complete, total, utter | relative For holidays, I prefer the relative seclusion of the countryside.","PREP. in (the ~ of) I live very much in seclusion these days. She liked to sunbathe in the seclusion of her own garden."]},"media":{"uk":"media/ldoce/hwd/bre/e/seclusion0205.mp3","us":"media/ldoce/hwd/ame/a/seclusion.mp3"},"examples":[{"en":"the seclusion and peace of the island","cn":"岛上的幽僻宁静"},{"en":"They enjoyed ten days of peace and seclusion.","cn":"他们享受了十天与世隔绝的宁静生活。"}],"oxford":{"phon":"sɪˈkluːʒn","pos":"noun","senses":[{"en":"the state of being private or of having little contact with other people","cn":"清静；隐居；与世隔绝","ex":{"en":"the seclusion and peace of the island","cn":"岛上的幽僻宁静"}}]}},"senseless":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"无意义的;无目的的;没有益处的","en":"If you describe an action as senseless, you think it is wrong because it has no purpose and produces no benefit.","ex":{"en":"...people whose lives have been destroyed by acts of senseless violence","cn":"生活被那些无谓的暴力行为所毁的人们"}},{"pos":"ADJ 形容词","cn":"失去知觉的;不省人事的","en":"If someone is senseless, they are unconscious.","ex":{"en":"They were knocked to the ground, beaten senseless and robbed of their wallets","cn":"他们遭重拳击倒在地，被打得不省人事，钱包也被抢走了。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"something that is pointless has no purpose and makes you angry or sad","cn":""},{"en":"not having any purpose or plan and therefore boring or sad","cn":""},{"en":"a crime or something bad that is senseless seems to have no meaning or purpose and you cannot understand why someone would do it","cn":""}]},"collocations":{"phrases":["VERBS be, seem","ADV. absolutely, quite It was an absolutely senseless act of violence. 2 unconscious","VERBS be, lie He lay senseless out in the rain. | beat sb, kick sb, knock sb The thugs beat him senseless with a baseball bat. The branch of"]},"media":{"uk":"media/ldoce/hwd/bre/8/senseless0205.mp3","us":"media/ldoce/hwd/ame/b/senseless.mp3"},"examples":[{"en":"His death was a senseless waste of life.","cn":"他白浪费了性命，死得毫无意义。"},{"en":"The police blamed senseless drivers who went too fast.","cn":"警察责怪莽撞司机开快车。"}],"oxford":{"phon":"ˈsensləs","pos":"adjective","senses":[{"en":"having no meaning or purpose","cn":"无意义的；无目的的","lab":"disapproving","ex":{"en":"senseless violence","cn":"无谓的暴力"}},{"en":"unconscious","cn":"失去知觉","g":"[not before noun]","ex":{"en":"He was beaten senseless.","cn":"他被打昏了。"}},{"en":"not using good judgement","cn":"不明智的；愚蠢的","ex":{"en":"The police blamed senseless drivers who went too fast.","cn":"警察责怪莽撞司机开快车。"}}]}},"self-indulgence":{"collins":{"senses":[{"pos":"N-VAR 可变名词","cn":"自我放纵;自我纵容","en":"Self-indulgence is the act of allowing yourself to have or do the things that you enjoy very much.","ex":{"en":"He prayed to be saved from self-indulgence","cn":"他祈祷自己能从自我放纵中摆脱出来。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"allowing yourself to have or do things that you enjoy but do not need, especially if you do this too often – used to show disapproval","cn":""}]},"media":{"uk":"media/ldoce/hwd/bre/f/brelasdeself-indulgent.mp3","us":"media/ldoce/hwd/ame/b/laadself-indulgent.mp3"},"examples":[{"en":"It feels self-indulgent spending so much on a pair of shoes.","cn":""}],"oxford":{"phon":"ˌself ɪnˈdʌldʒəns","pos":"noun","senses":[{"en":"the fact of allowing yourself to have or do things that you like, especially when you do this too much or too often","cn":"放纵自己的；任性的","ex":{"en":"the self-indulgence of the wealthy middle classes","cn":"富裕中产阶级的自我放纵"}}]}},"secretion":{"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"分泌","en":"Secretion is the process by which certain liquid substances are produced by parts of plants or from the bodies of people or animals.","ex":{"en":"...the secretion of adrenaline.","cn":"肾上腺素的分泌"}},{"pos":"N-PLURAL 复数名词","cn":"分泌物","en":"Secretions are liquid substances produced by parts of plants or bodies.","ex":{"en":"...gastric secretions.","cn":"胃分泌物"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a substance, usually liquid, produced by part of a plant or animal 〔","cn":"动植物的〕分泌物"},{"en":"the production of this substance","cn":"分泌"}]},"vocab":{"pos":"n","senses":[{"en":"A secretion is a substance made and released by a living thing, like when your skin sweats."}]},"media":{"uk":"media/ldoce/hwd/bre/f/ld41secretion.mp3","us":"media/ldoce/hwd/ame/f/secretion.mp3"},"examples":[{"en":"the secretion of bile by the liver","cn":"肝脏分泌胆汁的过程"},{"en":"bodily secretions","cn":"人体分泌物"}],"oxford":{"phon":"sɪˈkriːʃn","pos":"noun","senses":[{"en":"the process by which liquid substances are produced by parts of the body or plants","cn":"分泌","g":"[uncountable]","ex":{"en":"the secretion of bile by the liver","cn":"肝脏分泌胆汁的过程"}},{"en":"a liquid substance produced by parts of the body or plants","cn":"分泌物","g":"[countable, usually plural]","ex":{"en":"bodily secretions","cn":"人体分泌物"}}]}},"seawater":{"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"salty water from the sea","cn":"海水"}]},"media":{"uk":"media/ldoce/hwd/bre/2/ld41seawater.mp3","us":"media/ldoce/hwd/ame/6/laadseawater.mp3"},"oxford":{"phon":"ˈsiːwɔːtə(r)","pos":"noun","senses":[{"en":"water from the sea, which contains salt","cn":"海水"}]}},"secondment":{"collins":{"senses":[{"pos":"N-VAR 可变名词","cn":"临时调任;暂调","en":"Someone who is on secondment from their normal employer has been sent somewhere else temporarily in order to do special duties.","ex":{"en":"We have two full-time secretaries, one of whom is on secondment from the Royal Navy.","cn":"我们有两个全职秘书，其中一人是临时从皇家海军调来的。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a period of time that you spend away from your usual job, either doing another job or studying","cn":"临时调任﹐暂调﹐借调"}]},"media":{"uk":"media/ldoce/hwd/bre/f/secondment0205.mp3","us":"media/ldoce/hwd/ame/8/ld41secondment.mp3"},"examples":[{"en":"They met while she was on secondment from the Foreign Office.","cn":"两人是在她从外交部调来短期任职时认识的。"},{"en":"a government adviser, on secondment from the Metropolitan Police","cn":"一名借调自伦敦警察厅的政府顾问"}],"oxford":{"phon":"sɪˈkɒndmənt","pos":"noun","senses":[{"en":"a short period of time when an employee is sent to another department, office, etc. in order to do a different job","cn":"临时调派；短期调任","ex":{"en":"They met while she was on secondment from the Foreign Office.","cn":"两人是在她从外交部调来短期任职时认识的。"}}]}},"sexist":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"(通常指对女性)性别歧视的","en":"If you describe people or their behaviour as sexist, you mean that they are influenced by the belief that the members of one sex, usually women, are less intelligent or less capable than those of the other sex and need not be treated equally.","ex":{"en":"Old-fashioned sexist attitudes are still common","cn":"陈旧的性别歧视态度仍然常见。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"someone who treats people of other races unfairly or badly","cn":""},{"en":"someone who has strong unreasonable opinions, especially about race or religion","cn":""},{"en":"someone, especially a man, who believes that their sex is better, more intelligent, more important etc than the other","cn":""}]},"vocab":{"pos":"adj n","senses":[{"en":"A sexist is someone who discriminates on the basis of gender. Sexist people and laws are unfair."}]},"media":{"uk":"media/ldoce/hwd/bre/9/ld41sexist.mp3","us":"media/ldoce/hwd/ame/9/ld41sexist.mp3"},"examples":[{"en":"sexist language","cn":"有性别歧视的语言"},{"en":"a sexist attitude","cn":"性别歧视的态度"}],"oxford":{"phon":"ˈseksɪst","pos":"adjective","senses":[{"en":"treating other people, especially women, unfairly because of their sex or making offensive remarks about them","cn":"性别歧视者","ex":{"en":"a sexist attitude","cn":"性别歧视的态度"}},{"en":"a person who treats other people, especially women, unfairly because of their sex or who makes offensive remarks about them","cn":"性别歧视者","pos":"noun"}]}},"sensation":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"(身体上的)感觉，知觉","en":"A sensation is a physical feeling.","ex":{"en":"Floating can be a very pleasant sensation","cn":"漂浮会是一种非常惬意的感觉。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"(尤指)触觉;感觉能力;知觉","en":"Sensation is your ability to feel things physically, especially through your sense of touch.","ex":{"en":"The pain was so bad that she lost all sensation.","cn":"太疼了，疼得她都失去了知觉。"}},{"pos":"N-COUNT 可数名词","cn":"(某种经历所产生的)整体感觉，总体印象","en":"You can use sensation to refer to the general feeling or impression caused by a particular experience.","ex":{"en":"It's a funny sensation to know someone's talking about you in a language you don't understand.","cn":"知道有人正用一种你听不懂的语言谈论你，这种感觉很奇怪。"}},{"pos":"N-COUNT 可数名词","cn":"引起轰动的人(或事件、情况)","en":"If a person, event, or situation is a sensation, it causes great excitement or interest.","ex":{"en":"...the film that turned her into an overnight sensation.","cn":"使她一夜间名声大噪的影片"}},{"pos":"N-SING 单数名词","cn":"轰动;哗然","en":"If a person, event, or situation causes a sensation, they cause great interest or excitement.","ex":{"en":"She was just 14 when she caused a sensation at the Montreal Olympics.","cn":"她在蒙特利尔奥运会上引起轰动时才 14 岁。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a physical feeling of heat, cold, tiredness etc","cn":""},{"en":"a physical feeling, especially one that is unclear or difficult to describe","cn":""},{"en":"a feeling that you get from one of your five senses, especially the sense of touch 〔","cn":"感官的〕感觉﹔〔尤指〕触觉"}]},"vocab":{"pos":"n","senses":[{"en":"A sensation is a type of feeling, picked up by one of the five senses. Peppercorns will give you the sensation of a million tiny pinpricks on your tongue."}]},"collocations":{"phrases":["ADJ. delicious, exquisite, pleasant, pleasurable, wonderful | unpleasant | curious, odd, strange | burning, choking, prickling, tingling | b","VERB + SENSATION experience, feel, have He felt a tingling sensation down his side. | produce | enjoy Most people enjoy the sensation of eat","PREP. ~ of the sensation of sand between your toes 2 ability to feel","ADJ. pure He gave way to pure sensation.","VERB + SENSATION have She had no sensation in her hands. | lose","SENSATION + VERB come back 3 feeling/impression","ADJ. curious, eerie, odd, strange","VERB + SENSATION have I had the eerie sensation that I was not alone."]},"media":{"uk":"media/ldoce/hwd/bre/5/sensation0205.mp3","us":"media/ldoce/hwd/ame/6/sensation.mp3"},"examples":[{"en":"I had a sensation of falling, as if in a dream.","cn":"我有一种坠落的感觉，像在梦中似的。"},{"en":"When I arrived, I had the sensation that she had been expecting me.","cn":"我到那儿后，感觉到她一直在盼着我。"}],"oxford":{"phon":"senˈseɪʃn","pos":"noun","senses":[{"en":"a feeling that you get when something affects your body","cn":"感觉；知觉","g":"[countable]","ex":{"en":"a tingling/burning sensation","cn":"刺痛／烧灼的感觉"}},{"en":"the ability to feel through your sense of touch","cn":"感觉能力；知觉能力","g":"[uncountable]","ex":{"en":"She seemed to have lost all sensation in her arms.","cn":"她的两条胳膊好像完全失去知觉了。"}},{"en":"a general feeling or impression that is difficult to explain; an experience or a memory","cn":"直觉；莫名其妙的感觉；经历；回忆","g":"[countable, usually singular]","ex":{"en":"He had the eerie sensation of being watched.","cn":"他不安地感到有人在监视他。"}},{"en":"very great surprise, excitement, or interest among a lot of people; the person or the thing that causes this surprise","cn":"轰动；哗然；引起轰动的人（或事物）","g":"[countable, usually singular]","ex":{"en":"News of his arrest caused a sensation.","cn":"他被捕的消息引起了轰动。"}}]}},"seductress":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"勾引男子的女人","en":"A seductress is a woman who seduces someone.","ex":{"en":"Few males can resist a self-confident seductress.","cn":"很少有男人能抵挡住志在必得的女人的勾引。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a woman who persuades someone to have sex with her","cn":"勾引男子的女人"}]},"media":{"uk":"media/ldoce/hwd/bre/9/ld41seductress.mp3","us":"media/ldoce/hwd/ame/0/laadseductress.mp3"},"oxford":{"phon":"sɪˈdʌktrəs","pos":"noun","senses":[{"en":"a woman who seduces somebody; a female seducer","cn":"勾引男人的女人"}]}},"serried":{"collins":{"senses":[{"pos":"ADJ 形容词","cn":"(人或事物)密排的，密集的，排紧的","en":"Serried things or people are closely crowded together in rows.","ex":{"en":"...serried rows of law books and law reports.","cn":"排得密密匝匝的几排法律书籍和判例汇编"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"standing or arranged closely together in rows","cn":"排紧的﹐靠拢的﹐密集的"}]},"media":{"uk":"media/ldoce/hwd/bre/9/ld41serried.mp3","us":"media/ldoce/hwd/ame/f/serried.mp3"},"examples":[{"en":"serried ranks of soldiers","cn":"密集排列的士兵"},{"en":"the serried ranks of reporters waiting outside","cn":"密密麻麻地排在外面等待的记者"}],"oxford":{"phon":"ˈserid","pos":"adjective","senses":[{"en":"standing or arranged closely together in rows or lines","cn":"（行列）密排的，密集的，靠拢的","ex":{"en":"serried ranks of soldiers","cn":"密集排列的士兵"}}]}},"self-expression":{"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"(对性格、情感、意见的)自我表现，自我抒发","en":"Self-expression is the expression of your personality, feelings, or opinions, for example through an artistic activity such as drawing or dancing.","ex":{"en":"The conflict between the urge for self-expression and the pressure to conform is a central one for her","cn":"想要表现自我的欲望和被迫从众的压力对她来说是一个最主要的冲突。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"the expression of your feelings or thoughts, especially through activities such as painting, writing, or acting","cn":"自我表现〔尤指通过绘画﹑写作﹑演戏等实现〕"}]},"media":{"uk":"media/ldoce/hwd/bre/5/ld41self-expressio.mp3","us":"media/ldoce/hwd/ame/e/self-expression.mp3"},"examples":[{"en":"You should encourage your child's attempts at self-expression.","cn":"你应当鼓励孩子尝试表达自我。"},{"en":"Corporate dress codes don’t give workers much room for self-expression.","cn":"公司的着装规定没有给员工多少自我表现的余地。"}],"oxford":{"phon":"ˌself ɪkˈspreʃn","pos":"noun","senses":[{"en":"the expression of your thoughts or feelings, especially through activities such as writing, painting, dancing, etc.","cn":"自我表现，自我表达（尤指通过写作、绘画、舞蹈等活动）","ex":{"en":"You should encourage your child's attempts at self-expression.","cn":"你应当鼓励孩子尝试表达自我。"}}]}},"seizure":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"(尤指心脏病或脑部疾病的)突然发作，侵袭","en":"If someone has a seizure, they have a sudden violent attack of an illness, especially one that affects their heart or brain.","ex":{"en":"...a mild cardiac seizure","cn":"轻度的心脏病发作"}},{"pos":"N-COUNT 可数名词","cn":"(对权力、土地的)夺取;(突然的)占领，控制","en":"If there is a seizure of power or a seizure of an area of land, a group of people suddenly take control of the place, using force.","ex":{"en":"...the seizure of territory through force.","cn":"对领土的武装占领"}},{"pos":"N-COUNT 可数名词","cn":"(对非法物品的)起获，查封","en":"When an organization such as the police or customs service makes a seizure of illegal goods, they find them and take them away.","ex":{"en":"Police have made one of the biggest seizures of heroin there's ever been in Britain.","cn":"警方这次缴获的海洛因是英国迄今为止数量最大的几宗之一。"}},{"pos":"N-COUNT 可数名词","cn":"(因欠款未还而采取的)没收，充公","en":"If a financial institution or a government makes a seizure of someone's assets, they take their money or property from them because they have not paid money that they owe.","ex":{"en":"A court ordered the seizure of two ships for non-payment of the debt.","cn":"因未付债款，法庭下令没收两艘船。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"the act of suddenly taking control of something, especially by force","cn":"夺取﹔占领﹐控制"},{"en":"when the police or government officers take away illegal goods such as drugs or guns 〔","cn":"警方或政府官员对毒品﹑枪支等的〕查获﹐没收"},{"en":"a sudden condition in which someone cannot control the movements of their body, which continues for a short time 〔","cn":"疾病的〕突然发作"}]},"vocab":{"pos":"n","senses":[{"en":"A seizure is the act of taking by legal process or force, such as the seizure of evidence found at the scene of a crime."}]},"collocations":{"phrases":["ADJ. biggest | drugs, land | cocaine, heroin, etc.","VERB + SEIZURE make Customs have made their biggest ever seizure of heroin.","PHRASES search and seizure The Act confers powers of entry, search and seizure on the police."]},"media":{"uk":"media/ldoce/hwd/bre/5/seizure0205.mp3","us":"media/ldoce/hwd/ame/e/seizure.mp3"},"examples":[{"en":"the largest ever seizure of cocaine at a British port","cn":"在英国口岸起获的历来数量最大的一批可卡因"},{"en":"The court ordered the seizure of his assets.","cn":"法庭下令没收他的财产。"}],"oxford":{"phon":"ˈsiːʒə(r)","pos":"noun","senses":[{"en":"the use of legal authority to take something from somebody; an amount of something that is taken in this way","cn":"起获；没收；起获的赃物；没收的财产","g":"[uncountable, countable]","ex":{"en":"The court ordered the seizure of his assets.","cn":"法庭下令没收他的财产。"}},{"en":"the act of using force to take control of a country, town, etc.","cn":"夺取；占领；控制","g":"[uncountable]","ex":{"en":"the army’s seizure of power","cn":"军队对政权的夺取"}},{"en":"a sudden attack of an illness, especially one that affects the brain","cn":"（疾病，尤指脑病的）突然侵袭，发作","g":"[countable]","lab":"old-fashioned","ex":{"en":"to have/suffer an epileptic seizure","cn":"癫痫发作"}}]}},"secession":{"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"(从国家、大集团的)退出，脱离，分离","en":"The secession of a region or group from the country or larger group to which it belongs is the action of formally becoming separate.","ex":{"en":"...the Ukraine's secession from the Soviet Union.","cn":"乌克兰之退出苏联"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"when a country or state officially stops being part of another country and becomes independent","cn":"退出﹐脱离"}]},"vocab":{"pos":"1 n 2 n","senses":[{"en":"The noun secession refers to a big break-up — a formal split, an official “Good-bye to you!” — among political entities. If France has really, truly had it with the European Union, then a French secession movement may be in order."}]},"media":{"uk":"media/ldoce/hwd/bre/2/ld41secession.mp3","us":"media/ldoce/hwd/ame/2/ld41secession.mp3"},"examples":[{"en":"a vote in favor of secession","cn":"赞成独立的一票"},{"en":"Croatia’s secession from Yugoslavia","cn":"克罗地亚脱离南斯拉夫"}],"oxford":{"phon":"sɪˈseʃn","pos":"noun","senses":[{"en":"the fact of an area or group becoming independent from the country or larger group that it belongs to","cn":"（地区或集团从所属的国家或上级集团的）退出，脱离"}]}},"self-doubt":{"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"自我怀疑;不自信","en":"Self-doubt is a lack of confidence in yourself and your abilities."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"the feeling that you and your abilities are not good enough","cn":"自我怀疑"}]},"media":{"uk":"media/ldoce/hwd/bre/8/ld41self-doubt.mp3","us":"media/ldoce/hwd/ame/0/self-doubt.mp3"},"examples":[{"en":"a moment of self-doubt","cn":"片刻的自我怀疑"}],"oxford":{"phon":"ˌself ˈdaʊt","pos":"noun","senses":[{"en":"the feeling that you are not good enough","cn":"自我怀疑","ex":{"en":"His life was plagued by fear and self-doubt.","cn":"他一生担惊受怕，自我怀疑。"}}]}},"selfsame":{"collins":{"senses":[{"pos":"ADJ 形容词","cn":"(用于强调)同一的，完全相同的","en":"You use self-same when you want to emphasize that the person or thing mentioned is exactly the same as the one mentioned previously.","ex":{"en":"You find yourself worshipped by the self-same people who beat you up at school.","cn":"你发现原来在学校里痛扁你的同一群人现在成了你的崇拜者。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"the same place, person, or thing, not a different one","cn":""},{"en":"two or more people who have common aims, interests, beliefs etc have the same interests, aims, or beliefs","cn":""},{"en":"use this to emphasize that someone or something is the same person or thing, not a different one, when this is interesting or surprising","cn":""}]},"media":{"uk":"media/ldoce/hwd/bre/6/ld41selfsame.mp3","us":"media/ldoce/hwd/ame/f/selfsame.mp3"},"examples":[{"en":"Jane had been wondering that selfsame thing.","cn":"简一直在为同一件事纳闷。"},{"en":"two great victories on the selfsame day","cn":"同一天内的两大胜利"}],"oxford":{"phon":"ˈselfseɪm","pos":"adjective","senses":[{"en":"used to emphasize that two people or things are the same","cn":"（强调两者完全相同）同一的","ex":{"en":"Jane had been wondering that selfsame thing.","cn":"简也一直在为同一件事纳闷。"}}]}},"self-made":{"collins":{"senses":[{"pos":"ADJ 形容词","cn":"靠自己奋斗成功的;(尤指)白手起家的","en":"Self-made is used to describe people who have become successful and rich through their own efforts, especially if they started life without money, education, or high social status.","ex":{"en":"He is a self-made man.","cn":"他白手起家。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"without help from anyone else","cn":""},{"en":"without any help from anyone else. Alone is more formal and less common than on your own or by yourself","cn":""},{"en":"without asking for help or advice from anyone","cn":""}]},"media":{"uk":"media/ldoce/hwd/bre/7/brelasdeself-made.mp3","us":"media/ldoce/hwd/ame/0/self-made.mp3"},"examples":[{"en":"He was proud of the fact that he was a self-made man.","cn":"他为自己白手起家而自豪。"}],"oxford":{"phon":"ˌself ˈmeɪd","pos":"adjective","senses":[{"en":"having become rich and successful through your own hard work rather than having had money given to you","cn":"靠自己奋斗成功的；白手起家的","ex":{"en":"He was proud of the fact that he was a self-made man.","cn":"他为自己白手起家而自豪。"}}]}},"separable":{"collins":{"senses":[{"pos":"ADJ 形容词","cn":"可分开的;可分离的;可分隔的","en":"If things are separable, they can be separated from each other.","ex":{"en":"Character is not separable from physical form but is governed by it.","cn":"性格和外表是分不开的，而且观其形知其性。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"two things that are separable can be separated or considered separately","cn":"可分开[分隔﹐分离]的"}]},"collocations":{"phrases":["VERBS be","ADV. easily, readily Church and State were not easily separable in this period. | completely","PREP. from The two things were never identical, but never separable from each other."]},"media":{"uk":"media/ldoce/hwd/bre/4/separable0205.mp3","us":"media/ldoce/hwd/ame/c/separable.mp3"},"examples":[{"en":"The phrasal verb ‘tear up’ is separable because you can say ‘She tore the letter up’ or ‘She tore up the letter’. * tear up","cn":"是可以分开的短语动词，因为既可以说 She tore the letter up ，又可以说 She tore up the letter。"},{"en":"The moral question is not entirely separable from the financial one.","cn":"道德问题和财政问题不能截然分开。"}],"oxford":{"phon":"ˈsepərəbl","pos":"adjective","senses":[{"en":"that can be separated from something, or considered separately","cn":"可分开的；可分隔的；可分离的","ex":{"en":"The moral question is not entirely separable from the financial one.","cn":"道德问题和财政问题不能截然分开。"}},{"en":"that can be used with the object going either between the verb and the particle or after the particle","cn":"可分的；可分离的；可分开的","lab":"grammar","ex":{"en":"The phrasal verb ‘tear up’ is separable because you can say ‘She tore the letter up’ or ‘She tore up the letter’.","cn":"tear up 是可以分开的短语动词，因为既可以说 She tore the letter up，又可以说 She tore up the letter。"}}]}},"sedative":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"镇静剂","en":"A sedative is a medicine or drug that calms you or makes you sleep.","ex":{"en":"They use opium as a sedative, rather than as a narcotic.","cn":"他们把鸦片用作镇静剂而不是毒品。"}},{"pos":"ADJ 形容词","cn":"有镇静作用的;有催眠作用的","en":"Something that has a sedative effect calms you or makes you sleep.","ex":{"en":"Amber bath oil has a sedative effect.","cn":"琥珀沐浴油有镇静安神效用。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a drug used to make someone calm or go to sleep","cn":"镇静药﹐镇静剂"}]},"vocab":{"pos":"adj n","senses":[{"en":"A sedative is a drug that calms you down. If a patient is freaking out about getting an MRI or minor surgery, the doctor might prescribe a sedative to chill them out."}]},"collocations":{"phrases":["ADJ. powerful, strong | mild The doctor gave her a mild sedative to help her sleep.","VERB + SEDATIVE give sb, prescribe (sb)"]},"media":{"uk":"media/ldoce/hwd/bre/8/sedative0205.mp3","us":"media/ldoce/hwd/ame/a/sedative.mp3"},"examples":[{"en":"the sedative effect of the drug","cn":"这药物的镇静效果"}],"oxford":{"phon":"ˈsedətɪv","pos":"noun","senses":[{"en":"a drug that makes somebody go to sleep or makes them feel calm and relaxed","cn":"镇静药","ex":{"en":"The doctor gave her a mild sedative to help her sleep.","cn":"医生给了她一种药性平和的镇静剂来帮她入睡。"}},{"en":"having the effect of making somebody go to sleep or feel calm and relaxed","cn":"镇静药","ex":{"en":"the sedative effect of the drug","cn":"该药物的镇静作用"},"pos":"adjective"}]}},"seminarian":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"研讨班学员","en":"A seminarian is a student at a seminary."}]},"oxford":{"phon":"ˌsemɪˈneəriən","pos":"noun","senses":[{"en":"a student in a seminary","cn":"神学院学生；修生"}]}},"seepage":{"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"渗;渗透;渗入","en":"Seepage is the slow flow of a liquid through something.","ex":{"en":"Chemical seepage has caused untold damage.","cn":"化学品泄漏已造成不可估量的损失。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a gradual flow of liquid or gas through small spaces or holes 〔","cn":"液体或气体的〕渗漏"}]},"media":{"uk":"media/ldoce/hwd/bre/3/ld41seepage.mp3","us":"media/ldoce/hwd/ame/0/seepage.mp3"},"examples":[{"en":"Water gradually escapes by seepage through the ground.","cn":"水逐渐从地上渗走了。"},{"en":"oil seepages","cn":"油渗"}],"oxford":{"phon":"ˈsiːpɪdʒ","pos":"noun","senses":[{"en":"the process by which a liquid flows slowly and in small quantities through something; the result of this process","cn":"渗；渗透；渗液","lab":"figurative","ex":{"en":"Water gradually escapes by seepage through the ground.","cn":"水逐渐从地上渗走了。"}}]}},"seminary":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"神学院","en":"A seminary is a college where priests, ministers, or rabbis are trained."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a college for training priests or ministers 〔","cn":"培养神父﹑牧师的〕神学院"},{"en":"a school","cn":"学校"}]},"vocab":{"pos":"n","senses":[{"en":"What do ministers, priests, rabbis, and children have in common? They all might attend a school that has the word seminary in its name. A seminary is a school, especially one where people train to be religious leaders."}]},"media":{"uk":"media/ldoce/hwd/bre/5/seminary0205.mp3","us":"media/ldoce/hwd/ame/f/seminary.mp3"},"oxford":{"phon":"ˈsemɪnəri","pos":"noun","senses":[{"en":"a college where priests, ministers or rabbis are trained","cn":"神学院；修院","ex":{"en":"He went to the Northern Catholic Seminary to train for the ministry.","cn":"他到北方天主教神学院去接受牧师培训。"}}]}},"seventh":{"collins":{"senses":[{"pos":"ORD 序数词","cn":"第七","en":"The seventh item in a series is the one that you count as number seven.","ex":{"en":"I was the seventh child in a family of 11.","cn":"我在家里的 11 个孩子中排行老七。"}},{"pos":"FRACTION 分数词","cn":"七分之一","en":"A seventh is one of seven equal parts of something.","ex":{"en":"A million people died, a seventh of the population.","cn":"共有 100 万人丧生，占总人口的七分之一。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"coming after six other things in a series","cn":"第七（个）的"},{"en":"to be extremely happy","cn":"非常快活﹐极为幸福"},{"en":"one of seven equal parts of something","cn":"七分之一"}]},"media":{"uk":"media/ldoce/hwd/bre/f/ld44seventh.mp3","us":"media/ldoce/hwd/ame/d/laadseventh.mp3"},"examples":[{"en":"Now that he's been promoted he's in seventh heaven.","cn":"他得到擢升，简直乐上天了。"},{"en":"in the seventh century","cn":"在七世纪"}],"oxford":{"phon":"ˈsevnθ","pos":"ordinal number","senses":[{"en":"7th","cn":"第七","ex":{"en":"Today is the seventh (of May).","cn":"今天是五月七日。"}},{"en":"each of seven equal parts of something","cn":"七分之一","pos":"noun"}]}},"secular":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"世俗的;现世的;非宗教的","en":"You use secular to describe things that have no connection with religion.","ex":{"en":"He spoke about preserving the country as a secular state.","cn":"他谈及了保持该国世俗化的问题。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"relating to religion","cn":""},{"en":"relating to matters of the human spirit, rather than the physical world","cn":""},{"en":"connected with God and religion, and therefore treated in a special way – used especially in the following phrases","cn":""}]},"vocab":{"pos":"n adj","senses":[{"en":"Secular things are not religious. Anything not affiliated with a church or faith can be called secular ."}]},"collocations":{"phrases":["VERBS be","ADV. completely, purely It began as a religious organization, but these days it is purely secular. | essentially, largely We live in a large"]},"media":{"uk":"media/ldoce/hwd/bre/e/secular0205.mp3","us":"media/ldoce/hwd/ame/e/secular.mp3"},"examples":[{"en":"Ours is a secular society.","cn":"我们的社会是个世俗社会。"},{"en":"secular music","cn":"世俗音乐"}],"oxford":{"phon":"ˈsekjələ(r)","pos":"adjective","senses":[{"en":"not connected with spiritual or religious matters","cn":"现世的；世俗的；非宗教的","ex":{"en":"secular music","cn":"世俗音乐"}},{"en":"living among ordinary people rather than in a religious community","cn":"教区的；在俗的"}]}},"second-string":{"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"not regularly part of a team, group etc, but sometimes taking someone else’s place in it 〔","cn":"队﹑组等成员〕替补的﹐二线的"}]},"media":{"uk":"media/ldoce/hwd/bre/5/ld41second-string.mp3","us":"media/ldoce/hwd/ame/7/second-string.mp3"},"examples":[{"en":"Wilson was a second string for New Zealand in last week's match.","cn":"在上周的比赛中，威尔逊是新西兰队的替补队员。"},{"en":"a second-string quarterback","cn":"替补四分卫"}],"oxford":{"phon":"ˌsekənd ˈstrɪŋ","pos":"noun","senses":[{"en":"the players in a sports team who are available to replace those who start a game; one of these players","cn":"替补队员","ex":{"en":"United's second string were in Reserve Cup action last night.","cn":"曼联第二阵容昨晚参加了储备杯比赛。"}},{"en":"only used occasionally where somebody/something else is not available","cn":"替补的","ex":{"en":"a second-string quarterback","cn":"替补四分卫"},"pos":"adjective"}]}},"serendipity":{"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"(意外发现或发明新奇或有价值事物的)运气,走运,机缘凑巧","en":"Serendipity is the luck some people have in finding or creating interesting or valuable things by chance.","ex":{"en":"Some of the best effects in my garden have been the result of serendipity.","cn":"我园子里最珍贵的几件物品是机缘巧合之下意外所得。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"when interesting or valuable discoveries are made by accident 〔","cn":"有趣或有价值事物的〕碰巧发现﹐机缘巧合"}]},"vocab":{"pos":"n","senses":[{"en":"If you find good things without looking for them, serendipity — unexpected good luck — has brought them to you."}]},"media":{"uk":"media/ldoce/hwd/bre/9/ld41serendipity.mp3","us":"media/ldoce/hwd/ame/3/serendipity.mp3"},"examples":[{"en":"serendipitous discoveries","cn":"偶然的幸运发现"}],"oxford":{"phon":"ˌserənˈdɪpəti","pos":"noun","senses":[{"en":"the fact of something interesting or pleasant happening by chance","cn":"巧事；机缘凑巧","ex":{"en":"Meeting her like that, and there of all places, was true serendipity!","cn":"就这样遇见她，而且是在任何地方，真是机缘巧合！"}}]}},"secluded":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"僻静的;隐蔽的","en":"A secluded place is quiet and private.","ex":{"en":"We were tucked away in a secluded corner of the room","cn":"我们被藏匿到房间里一个隐蔽的角落。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"a distant or far-off town or country is a long way from where you are","cn":""},{"en":"a faraway country, especially one that you have been told about or have read about, is very far away, and different from your own country","cn":""},{"en":"remote places are far away from other places or people, and very few people go there","cn":""}]},"vocab":{"pos":"adj","senses":[{"en":"A secluded place is isolated, away from other people. It's quiet, and there's not a lot going on."}]},"collocations":{"phrases":["VERBS be, look","ADV. very, wonderfully | fairly, pretty We managed to find a fairly secluded spot for our picnic."]},"media":{"uk":"media/ldoce/hwd/bre/f/brelasdesecluded.mp3","us":"media/ldoce/hwd/ame/f/secluded.mp3"},"examples":[{"en":"a secluded garden/beach/spot, etc.","cn":"僻静的花园、海滩、地点等"},{"en":"to lead a secluded life","cn":"过隐居生活"}],"oxford":{"phon":"sɪˈkluːdɪd","pos":"adjective","senses":[{"en":"quiet and private","cn":"僻静的；清静的；隐蔽的","ex":{"en":"a secluded garden/beach/corner","cn":"僻静的花园/海滩/角落"}}]}},"seduce":{"collins":{"senses":[{"pos":"VERB 动词","cn":"引诱;吸引;诱惑","en":"If something seduces you, it is so attractive that it makes you do something that you would not otherwise do.","ex":{"en":"The view of lake and plunging cliffs seduces visitors","cn":"湖光旖旎、峭壁峥嵘，游客们被深深吸引了。"}},{"pos":"VERB 动词","cn":"勾引;诱奸","en":"If someone seduces another person, they use their charm to persuade that person to have sex with them.","ex":{"en":"She has set out to seduce Stephen.","cn":"她已经开始勾引斯蒂芬了。"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to make someone want to have or do something, even though they know they really should not","cn":""},{"en":"to attract someone to buy a particular product, support a particular political party etc, by making it seem very attractive - used especially in order to show disapproval","cn":""},{"en":"to persuade someone to have sex with you, especially someone who is younger than you or has less sexual experience","cn":""}]},"vocab":{"pos":"v","senses":[{"en":"To seduce is to lure or entice, particularly away from obligations or proper behavior. Often, seducing leads to sex."}]},"media":{"uk":"media/ldoce/hwd/bre/6/seduce0205.mp3","us":"media/ldoce/hwd/ame/2/seduce.mp3"},"examples":[{"en":"The promise of huge profits seduced him into parting with his money.","cn":"高额利润的许诺诱使他把钱交了出来。"},{"en":"The professor was sacked for seducing female students.","cn":"这个教授因诱奸女学生而被解雇。"}],"oxford":{"phon":"sɪˈdjuːs","pos":"verb","senses":[{"en":"to persuade somebody to have sex with you, especially somebody who is younger or who has less experience than you","cn":"诱奸"},{"en":"to persuade somebody to do something that they would not usually agree to do by making it seem very attractive","cn":"诱骗；唆使","ex":{"en":"The promise of huge profits seduced him into parting with his money.","cn":"高额利润的许诺诱使他把钱交了出来。"}}]}},"secretariat":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"(负责管理国际政治组织的)秘书处，书记处","en":"A secretariat is a department that is responsible for the administration of an international political organization.","ex":{"en":"...the UN secretariat.","cn":"联合国秘书处"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a government office or the office of a large international organization, especially one that has a secretary general in charge of it","cn":"秘书处﹐书记处"}]},"media":{"uk":"media/ldoce/hwd/bre/8/ld41secretariat.mp3","us":"media/ldoce/hwd/ame/0/secretariat1.mp3"},"examples":[{"en":"the United Nations Secretariat in New York","cn":"设在纽约的联合国秘书处"}],"oxford":{"phon":"ˌsekrəˈteəriət","pos":"noun","senses":[{"en":"the department of a large international or political organization which is responsible for running it, especially the office of a secretary general","cn":"（大型国际组织、政治组织的）秘书处，书记处"}]}},"seventieth":{"collins":{"senses":[{"pos":"ORD 序数词","cn":"第七十","en":"The seventieth item in a series is the one that you count as number seventy.","ex":{"en":"...the seventieth anniversary of the discovery of Tutankhamun's tomb.","cn":"图坦卡蒙墓发现 70 周年纪念日"}},{"pos":"FRACTION 分数词","cn":"七十分之一","en":"A seventieth is one of seventy equal parts of something."}]},"ldoce":{"phon":"hwd","pos":"","senses":[{"en":"the number 70","cn":""},{"en":"the years from 1970 to 1979","cn":""},{"en":"to be aged between 70 and 79","cn":""}]},"media":{"uk":"media/ldoce/hwd/bre/8/ld41seventy.mp3","us":"media/ldoce/hwd/ame/5/seventy.mp3"},"examples":[{"en":"We lost touch during the seventies.","cn":""},{"en":"In the early seventies, Sag Harbor was still a peaceful village.","cn":""}],"oxford":{"phon":"ˈsevntiəθ","pos":"ordinal number","senses":[{"en":"70th","cn":"第七"},{"en":"each of 70 equal parts of something","cn":"七分之一","pos":"noun"}]}},"seamanship":{"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"航海技能;船舶驾驶术;航海术","en":"Seamanship is skill in managing a boat and controlling its movement through the sea.","ex":{"en":"...the art of seamanship and navigation.","cn":"驾船和航海的技术"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"the skills and knowledge that an experienced sailor has","cn":"航海术﹐航海技能﹐船舶驾驶术"}]},"media":{"uk":"media/ldoce/hwd/bre/7/seamanship0205.mp3","us":"media/ldoce/hwd/ame/a/seamanship.mp3"},"oxford":{"phon":"ˈsiːmənʃɪp","pos":"noun","senses":[{"en":"skill in sailing a boat or ship","cn":"航海技术；船艺"}]}},"seriousness":{"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"say this to emphasize that something surprising is really true, or to ask whether something surprising is really true","cn":""},{"en":"say this when you think other people will not believe that you are telling the truth, or to ask if someone is joking because what they say does not seem true","cn":""},{"en":"say this when you are telling someone about something that will be hard for them to believe","cn":""}]},"vocab":{"pos":"n","senses":[{"en":"Seriousness is a quality of being calmly intent, or serious. Your seriousness will serve you well when you're studying for an important test."}]},"collocations":{"phrases":["ADJ. deadly, deep, full, great, high He maintained an attitude of high seriousness. | mock | underlying The joke did not obscure the underly","VERB + SERIOUSNESS appreciate, realize, recognize, understand Only later did he realize the full seriousness of his offence. | exaggerate | ","PREP. with ~ She spoke with great seriousness of the hardships she had endured.","PHRASES in all seriousness You can't in all seriousness think they'll give you the job! | take, treat, etc. sth with the utmost seriousness"]},"media":{"uk":"media/ldoce/hwd/bre/e/ld41seriousness.mp3","us":"media/ldoce/hwd/ame/e/ld41seriousness.mp3"},"examples":[{"en":"He spoke with a seriousness that was unusual in him.","cn":"他说话时神情少有地认真。"},{"en":"In all seriousness, if Tom does resign, a lot of other people will start leaving too.","cn":"说正经的﹐如果汤姆真的辞职﹐其他许多人也会走的。"}],"oxford":{"phon":"ˈsɪəriəsnəs","pos":"noun","senses":[{"en":"the state of being serious","cn":"严重；认真；严肃","ex":{"en":"He spoke with a seriousness that was unusual in him.","cn":"他说话时神情少有地认真。"}}]}},"semantics":{"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"语义学","en":"Semantics is the branch of linguistics that deals with the meanings of words and sentences."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"the study of the meaning of words and phrases","cn":"语义学"},{"en":"the meaning of a word or expression 〔","cn":"词或词组的〕含义﹐语义"}]},"vocab":{"pos":"n","senses":[{"en":"Semantics is the study of meaning in language. It can be applied to entire texts or to single words. For example, \"destination\" and \"last stop\" technically mean the same thing, but students of semantics analyze their subtle shades of meaning."}]},"media":{"uk":"media/ldoce/hwd/bre/4/semantics0205.mp3","us":"media/ldoce/hwd/ame/0/semantics.mp3"},"oxford":{"phon":"sɪˈmæntɪks","pos":"noun","senses":[{"en":"the study of the meanings of words and phrases","cn":"语义学"},{"en":"the meaning of words, phrases or systems","cn":"（单词、短语或其他符号系统的）含义","ex":{"en":"the semantics of the language","cn":"语言的语义学"}}]}},"sedge":{"collins":{"senses":[{"pos":"N-MASS 物质名词","cn":"(生长于湿地的)苔草，苔","en":"Sedge is a plant that looks like grass and grows in wet ground."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a plant similar to grass that grows in wet ground and on the edge of rivers and lakes 〔","cn":"生长于潮湿处的〕苔草"}]},"media":{"uk":"media/ldoce/hwd/bre/4/ld41sedge.mp3","us":"media/ldoce/hwd/ame/f/sedge.mp3"},"oxford":{"phon":"sedʒ","pos":"noun","senses":[{"en":"a plant like grass that grows in wet ground or near water","cn":"莎草；苔"}]}},"seagull":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"海鸥","en":"A seagull is a common kind of bird with white or grey feathers."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a large common grey or white bird that lives near the sea","cn":"海鸥"}]},"collocations":{"phrases":["QUANT. flock","SEAGULL + VERB circle, fly, wheel | dive-bomb, swoop | cry, scream, screech, shriek"]},"media":{"img":["media/ldoce/img/seagull.jpg"],"uk":"media/ldoce/hwd/bre/c/seagull0205.mp3","us":"media/ldoce/hwd/ame/d/seagull.mp3"},"examples":[{"en":"a flock of seagulls","cn":"一群海鸥"}],"oxford":{"phon":"ˈsiːɡʌl","pos":"noun","senses":[{"en":"a seabird with long wings and usually white and grey or black feathers. There are several types of seagull.","cn":"海鸥","ex":{"en":"a flock of seagulls","cn":"一群海鸥"}}]}},"self-denying":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"自我剥夺的;自我牺牲的;克己忘我的","en":"Someone who is self-denying refuses to do or have things that they would like, either because they cannot afford them, or because they believe it is morally good for them not to do them or have them.","ex":{"en":"They believed that good parents should be self-sacrificing and self-denying","cn":"他们认为好的父母应该牺牲自我，一心为孩子着想。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"when you do not do or have the things you enjoy, for moral or religious reasons","cn":""}]},"media":{"uk":"media/ldoce/hwd/bre/a/ld41self-denial.mp3","us":"media/ldoce/hwd/ame/3/self-denial.mp3"}},"sellotape":{"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"塞勒塔普胶黏带;透明胶带","en":"Sellotape is a clear sticky tape that you use to stick paper or card together or onto a wall."},{"pos":"VERB 动词","cn":"用透明胶带粘贴","en":"If you Sellotape one thing to another, you stick them together using Sellotape.","ex":{"en":"I sellotaped the note to his door.","cn":"我用透明胶带把便条贴在他的门上。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"thin clear plastic tape that is sticky on one side, used for sticking things together Sellotape","cn":"透明胶带"}]},"media":{"uk":"media/ldoce/hwd/bre/7/brelasdesellotape.mp3","us":"media/ldoce/hwd/ame/d/ld41sellotape.mp3"},"examples":[{"en":"The envelope was stuck down with Sellotape.","cn":"信封是用胶黏带封口的。"},{"en":"a roll of Sellotape","cn":"一卷胶黏带"}],"oxford":{"phon":"ˈseləteɪp","pos":"verb","senses":[{"en":"to join or stick things together with Sellotape","cn":"用透明胶带粘贴","ex":{"en":"We found a note sellotaped to the front door.","cn":"我们看见正门上有一张用透明胶带贴的字条。"}},{"en":"clear plastic tape that is sticky on one side, used for sticking things together","cn":"赛勒塔普胶粘带；透明胶带","ex":{"en":"a roll of Sellotape","cn":"一卷胶粘带"},"pos":"noun"}]}},"self-satisfied":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"自鸣得意的;沾沾自喜的","en":"If you describe someone as self-satisfied, you mean that they are too pleased with themselves about their achievements or their situation and they think that nothing better is possible.","ex":{"en":"You're so bloody self-satisfied","cn":"你也太自鸣得意了。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"very pleased with what you, your family, or your country have achieved, or of something you own","cn":""},{"en":"feeling pleased because something good has happened, especially because you think you have been very clever, skilful etc","cn":""},{"en":"behaving in an unpleasant and annoying way, because you think you are better or know more than other people, and that your opinions are always right","cn":""}]},"media":{"uk":"media/ldoce/hwd/bre/c/self_satisfied0205.mp3","us":"media/ldoce/hwd/ame/1/self-satisfied.mp3"},"examples":[{"en":"He had a self-satisfied smirk on his face.","cn":"他脸上挂着得意扬扬的笑容。"},{"en":"a look of self-satisfaction","cn":"沾沾自喜的神态"}],"oxford":{"phon":"ˌself ˈsætɪsfaɪd","pos":"adjective","senses":[{"en":"too pleased with yourself or your own achievements","cn":"自鸣得意的；沾沾自喜的","ex":{"en":"He had a self-satisfied smirk on his face.","cn":"他脸上挂着得意扬扬的笑容。"}}]}},"self-destructive":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"自毁的","en":"Self-destructive behaviour is harmful to the person who behaves in that way.","ex":{"en":"He had a reckless, self-destructive streak.","cn":"他生性鲁莽草率，会做出自毁行为。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"deliberately doing things that are likely to seriously harm or kill yourself","cn":"自毁的﹐自残的"}]},"media":{"uk":"media/ldoce/hwd/bre/4/self_destructi0205.mp3","us":"media/ldoce/hwd/ame/8/laadself-destructive.mp3"},"examples":[{"en":"a self-destructive alcoholic","cn":"一个自暴自弃的酗酒者"}],"oxford":{"phon":"ˌself dɪˈstrʌktɪv","pos":"adjective","senses":[{"en":"doing things to deliberately harm yourself","cn":"自毁","ex":{"en":"These young people became involved in crime and other self-destructive behaviour.","cn":"这些年轻人参与犯罪和其他自毁行为。"}}]}},"self-possessed":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"沉着的;镇静的;泰然自若的","en":"Someone who is self-possessed is calm and confident and in control of their emotions.","ex":{"en":"She is clearly the most articulate and self-possessed member of her family.","cn":"显然，她是全家口才最好、最沉着冷静的人。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"sure that you have the ability to do something well or deal with situations successfully","cn":""},{"en":"confident, and not shy or nervous in social situations","cn":""},{"en":"confident, calm, and in control of your feelings even in a difficult situation","cn":""}]},"media":{"uk":"media/ldoce/hwd/bre/2/self_possessed0205.mp3","us":"media/ldoce/hwd/ame/1/self-possessed.mp3"},"examples":[{"en":"He soon recovered his usual self-possession.","cn":"他很快恢复了平时沉着冷静的样子。"},{"en":"She’s a confident self-possessed public speaker.","cn":"她是个自信﹑镇定的演说家。"}],"oxford":{"phon":"ˌself pəˈzest","pos":"adjective","senses":[{"en":"able to remain calm and confident in a difficult situation","cn":"沉着的；镇定的；泰然自若的","ex":{"en":"She always seems so calm and self-possessed.","cn":"她总是显得那么镇静自若。"}}]}},"self-reliance":{"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"自主;自立;自力更生","en":"Self-reliance is the ability to do things and make decisions by yourself, without needing other people to help you.","ex":{"en":"People learned self-reliance because they had to","cn":"人们被迫学会了自力更生。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"able to make your own decisions, organize your own life, and do things in your own way, without wanting help or advice from other people","cn":""},{"en":"able to do things for yourself and solve problems by yourself, and able to live without depending on anyone else","cn":""},{"en":"able to live happily on your own, without needing a lot of friends or spending a lot of time with other people","cn":""}]},"media":{"uk":"media/ldoce/hwd/bre/e/brelasdeself-reliant.mp3","us":"media/ldoce/hwd/ame/d/self-reliant.mp3"},"examples":[{"en":"Our aim is to teach our son to become an independent self-reliant adult.","cn":""}],"oxford":{"phon":"ˌself rɪˈlaɪəns","pos":"noun","senses":[{"en":"the ability to do or decide things by yourself, rather than depending on other people for help","cn":"自立的；自力更生的；自主的","ex":{"en":"economic self-reliance","cn":"经济自力更生"}}]}},"set-to":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"打架;冲突;争吵","en":"A set-to is a dispute or fight.","ex":{"en":"This was the subject of a bit of a set-to between Smith and his record company.","cn":"这就是史密斯和他的唱片公司发生小摩擦的原因。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a short fight or quarrel 〔","cn":"短时间的〕打斗﹐争吵"}]},"media":{"uk":"media/ldoce/hwd/bre/d/ld41set-to.mp3","us":"media/ldoce/hwd/ame/d/ld41set-to.mp3"},"examples":[{"en":"Tom and I had a bit of a set-to last night.","cn":"昨晚汤姆和我起了小冲突。"}],"oxford":{"phon":"ˌset ˈtuː","pos":"noun","senses":[{"en":"a small fight or an argument","cn":"打架；争吵","ex":{"en":"We had a bit of a set-to with the neighbours.","cn":"我们和邻居发生了一些争执。"}}]}},"selloff":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"(国有企业等的)出售;(公司股票的)抛售","en":"The sell-off of something, for example an industry owned by the state or a company's shares, is the selling of it.","ex":{"en":"The privatisation of the electricity industry — the biggest sell-off of them all","cn":"电力行业的私有化——其中最大的一笔出售"}}]}},"serviette":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"餐巾;餐巾纸","en":"A serviette is a square of cloth or paper that you use to protect your clothes or to wipe your mouth when you are eating."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a napkin","cn":"餐巾"}]},"media":{"uk":"media/ldoce/hwd/bre/f/serviette0205.mp3","us":"media/ldoce/hwd/ame/4/serviette.mp3"},"oxford":{"phon":"ˌsɜːviˈet","pos":"noun","senses":[{"en":"a piece of cloth or paper used at meals for protecting your clothes and cleaning your lips and fingers","cn":"餐巾；餐巾纸"}]}},"searing":{"collins":{"senses":[{"pos":"ADJ 形容词","cn":"灼热的;强烈的","en":"Searing is used to indicate that something such as pain or heat is very intense.","ex":{"en":"She woke to feel a searing pain in her feet.","cn":"她醒来感到脚上火辣辣地痛。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"(言谈、文章)吹毛求疵的，尖刻的,苛责的","en":"A searing speech or piece of writing is very critical.","ex":{"en":"...searing criticism.","cn":"尖刻的批评"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"extremely hot","cn":"炽热的"},{"en":"searing pain is severe and feels like a burn","cn":"灼痛的"},{"en":"searing words or attitudes criticize someone or something very strongly 〔","cn":"言语﹑态度〕严厉的﹐苛刻的"}]},"media":{"uk":"media/ldoce/hwd/bre/5/brelasdesearing.mp3","us":"media/ldoce/hwd/ame/6/searing.mp3"},"examples":[{"en":"the searing heat of a tropical summer","cn":"热带夏季灼人的热浪"},{"en":"a searing attack on the government","cn":"对政府的猛烈抨击"}],"oxford":{"phon":"ˈsɪərɪŋ","pos":"adjective","senses":[{"en":"so strong that it seems to burn you","cn":"灼人的；火辣辣的","ex":{"en":"the searing heat of a tropical summer","cn":"热带夏季灼人的热浪"}},{"en":"powerful and critical","cn":"猛烈批评的","ex":{"en":"a searing attack on the government","cn":"对政府的猛烈抨击"}}]}},"sedition":{"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"煽动反政府的言论(或文章、行为）","en":"Sedition is speech, writing, or behaviour intended to encourage people to fight against or oppose the government.","ex":{"en":"Government officials charged him with sedition.","cn":"政府官员指控他煽动人们造反。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"actions, speeches etc that are intended to encourage people to oppose the government or to take part in a rebellion","cn":""},{"en":"secret activities that are intended to encourage people to oppose the government or to take part in a rebellion","cn":""},{"en":"speech, writing, or actions intended to encourage people to disobey a government","cn":"煽动反政府行为的言论[文章﹐行动]"}]},"vocab":{"pos":"n","senses":[{"en":"Sedition is the illegal act of inciting people to resist or rebel against the government in power. It's what the southern states did at the start of the Civil War."}]},"media":{"uk":"media/ldoce/hwd/bre/a/sedition0205.mp3","us":"media/ldoce/hwd/ame/8/sedition.mp3"},"examples":[{"en":"seditious activity","cn":"煽动叛乱的活动"},{"en":"Trade union leaders were charged with sedition.","cn":"工会领导人被控犯有煽动罪。"}],"oxford":{"phon":"sɪˈdɪʃn","pos":"noun","senses":[{"en":"the use of words or actions that are intended to encourage people to oppose a government","cn":"煽动叛乱的言论（或行动）","ex":{"en":"to be charged with sedition","cn":"被控煽动罪"}}]}},"serial":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"(电视或广播的)连续剧;(报纸或杂志上的)连载小说","en":"A serial is a story which is broadcast on television or radio or is published in a magazine or newspaper in a number of parts over a period of time.","ex":{"en":"...one of BBC television's most popular serials, Eastenders","cn":"英国广播公司最受欢迎的电视连续剧之一——《伦敦东区》"}},{"pos":"ADJ 形容词","cn":"连续的;连环的","en":"Serial killings or attacks are a series of killings or attacks committed by the same person. This person is known as a serial killer or attacker.","ex":{"en":"...serial murders","cn":"连环凶杀案"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a regular series of television programmes, books etc that tell the same story or are the same kind of programme, book etc","cn":""},{"en":"a story that is broadcast in several separate parts on television or radio, or printed in separate parts in a magazine or newspaper","cn":""},{"en":"a story that is broadcast or printed in several separate parts on television, in a magazine etc","cn":"电视连续剧﹔〔杂志等上的〕连载小说"}]},"vocab":{"pos":"adj n","senses":[{"en":"Serial means arranged in a series. If you get a serial number with your new phone, that's a number assigned to the phone when it was made, to distinguish it from all the other phones."}]},"media":{"uk":"media/ldoce/hwd/bre/e/brelasdeserial.mp3","us":"media/ldoce/hwd/ame/f/l2serial.mp3"},"examples":[{"en":"tasks carried out in the same serial order","cn":"按同样顺序完成的任务"},{"en":"a serial rapist","cn":"一个连续作案的强奸犯"}],"oxford":{"phon":"ˈsɪəriəl","pos":"adjective","senses":[{"en":"doing the same thing in the same way several times; done in the same way several times","cn":"连续的；多次的","g":"[only before noun]","ex":{"en":"a serial rapist","cn":"一个连续作案的强奸犯"}},{"en":"broadcast or published in several separate parts","cn":"以连续剧形式播出的；连载的","g":"[only before noun]","ex":{"en":"a novel in serial form","cn":"一部连载小说"}},{"en":"arranged in a series","cn":"顺序排列的；排成系列的","g":"[usually before noun]","lab":"specialist","ex":{"en":"tasks carried out in the same serial order","cn":"按同样顺序完成的任务"}},{"en":"a story that is broadcast or published in several separate parts on television, on the radio, on the internet, in a magazine, etc.","cn":"（电视、网络等的）连续剧；（广播、杂志等的）连载小说","ex":{"en":"a classic drama serial","cn":"经典连续剧"},"pos":"noun"}]}},"self-important":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"妄自尊大的;高傲的;自负的","en":"If you say that someone is self-important, you disapprove of them because they behave as if they are more important than they really are.","ex":{"en":"He was self-important, vain and ignorant.","cn":"他傲慢自负，虚荣无知。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"someone who thinks that they are better than people from a lower social class","cn":""},{"en":"someone who is snobbish thinks that they are better than people from a lower class, so that they will not be friendly with them or do the things they do","cn":""},{"en":"someone who is stuck-up thinks that they are better than other people, and behaves in a proud, unfriendly way","cn":""}]},"media":{"uk":"media/ldoce/hwd/bre/c/self_important0205.mp3","us":"media/ldoce/hwd/ame/0/laadself-important.mp3"},"examples":[{"en":"a self-important pompous little man","cn":"一个妄自尊大﹑自命不凡的平庸之辈"}],"oxford":{"phon":"ˌself ɪmˈpɔːtnt","pos":"adjective","senses":[{"en":"thinking that you are more important than other people","cn":"自大的；妄自尊大的；自负的","ex":{"en":"He was a self-important little man.","cn":"他是个讨厌的自命不凡的家伙。"}}]}},"self-destruct":{"collins":{"senses":[{"pos":"VERB 动词","cn":"自毁","en":"If someone self-destructs, they do something that seriously damages their chances of success.","ex":{"en":"They're going to be famous, but unless something happens, they're going to self-destruct","cn":"他们将会出名，但如果照现在这样发展下去，他们会自毁前程。"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"if something such as a bomb self-destructs, it destroys itself, usually by exploding 〔","cn":"炸弹等〕自爆﹐自毁"}]},"media":{"uk":"media/ldoce/hwd/bre/8/ld41self-destruct.mp3","us":"media/ldoce/hwd/ame/b/self-destruct.mp3"},"examples":[{"en":"( figurative ) In the last half-hour of the movie the plot rapidly self-destructs.","cn":"在电影的最后半个小时里，故事情节迅速了结。"},{"en":"This tape will self-destruct in 30 seconds.","cn":"这盘磁带将在 30 秒后自毁。"}],"oxford":{"phon":"ˌself dɪˈstrʌkt","pos":"verb","senses":[{"en":"to destroy itself, usually by exploding","cn":"自毁；自爆","lab":"figurative","ex":{"en":"This tape will self-destruct in 30 seconds.","cn":"这盘磁带将在 30 秒后自毁。"}}]}},"self-employed":{"collins":{"senses":[{"pos":"ADJ 形容词","cn":"自雇的;个体经营的;自由职业的","en":"If you are self-employed, you organize your own work and taxes and are paid by people for a service you provide, rather than being paid a regular salary by a person or a firm.","ex":{"en":"There are no paid holidays or sick leave if you are self-employed.","cn":"如果你是个体户，就没有带薪休假或病假。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"to have a job - used especially in official contexts or in writing","cn":""},{"en":"someone who is self-employed works for a business that they own or gets paid for work by various companies or people, and is not directly employed by a single company or organization","cn":""},{"en":"to have a job, especially one that is for a particular period of time, or when it is difficult to keep working","cn":""}]},"media":{"uk":"media/ldoce/hwd/bre/9/self_employed0205.mp3","us":"media/ldoce/hwd/ame/5/self-employed.mp3"},"examples":[{"en":"retirement plans for the self-employed (= people who are self-employed)","cn":"自由职业者退休计划"},{"en":"a self-employed musician","cn":"自己单干的乐师"}],"oxford":{"phon":"ˌself ɪmˈplɔɪd","pos":"adjective","senses":[{"en":"working for yourself and not employed by a company, etc.","cn":"个体经营的；单干的；自雇的","ex":{"en":"a self-employed musician","cn":"自己单干的乐师"}}]}},"serf":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"(旧时的)农奴","en":"In former times, serfs were a class of people who had to work on a particular person's land and could not leave without that person's permission."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"someone in the past who lived and worked on land that they did not own and who had to obey the owner of the land 〔","cn":"旧时的〕农奴"}]},"vocab":{"pos":"n","senses":[{"en":"A serf is a person who is forced to work on a plot of land, especially during the medieval period when Europe practiced feudalism, when a few lords owned all the land and everyone else had to toil on it."}]},"media":{"uk":"media/ldoce/hwd/bre/0/ld41serf.mp3","us":"media/ldoce/hwd/ame/b/serf.mp3"},"oxford":{"phon":"sɜːf","pos":"noun","senses":[{"en":"(in the past) a person who was forced to live and work on land that belonged to a landowner whom they had to obey","cn":"（旧时的）农奴"}]}},"seasoning":{"collins":{"senses":[{"pos":"N-MASS 物质名词","cn":"调味品;佐料","en":"Seasoning is salt, pepper, or other spices that are added to food to improve its flavour.","ex":{"en":"Mix the meat with the onion, carrot, and some seasoning.","cn":"把肉和洋葱、胡萝卜及一些佐料搅拌在一起。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"salt, pepper, spices etc that give food a more interesting taste","cn":"调味品﹐佐料"}]},"media":{"uk":"media/ldoce/hwd/bre/0/brelasdeseasoning.mp3","us":"media/ldoce/hwd/ame/8/seasoning.mp3"},"oxford":{"phon":"ˈsiːzənɪŋ","pos":"noun","senses":[{"en":"a substance used to add taste to food, especially salt and pepper","cn":"调味品；作料","ex":{"en":"Stir in the lemon rind and seasoning.","cn":"加入柠檬皮和调味料。"}}]}},"seamstress":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"女裁缝;女缝纫工","en":"A seamstress is a woman who sews and makes clothes as her job."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a woman whose job is sewing and making clothes","cn":"女缝纫工﹐女裁缝"},{"en":"a woman who is good at sewing","cn":"精于缝纫的妇女﹔缝纫女工"}]},"media":{"uk":"media/ldoce/hwd/bre/7/ld41seamstress.mp3","us":"media/ldoce/hwd/ame/e/seamstress.mp3"},"oxford":{"phon":"ˈsiːmstrəs","pos":"noun","senses":[{"en":"a woman who can sew and make clothes or whose job is sewing and making clothes","cn":"会缝纫的女人；女裁缝","lab":"British English"}]}},"sedate":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"安静的;庄重的;不苟言笑的;平淡无奇的","en":"If you describe someone or something as sedate, you mean that they are quiet and rather dignified, though perhaps a bit dull.","ex":{"en":"She took them to visit her sedate, elderly cousins","cn":"她带他们去拜访她那些不苟言笑的表兄表姐们。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"不慌不忙的;慢悠悠的;从容的","en":"If you move along at a sedate pace, you move slowly, in a controlled way.","ex":{"en":"We set off again at a more sedate pace.","cn":"我们重新上路了，步调更加从容。"}},{"pos":"VERB 动词","cn":"给…施用镇静剂","en":"If someone is sedated, they are given a drug to calm them or to make them sleep.","ex":{"en":"The patient is sedated with intravenous use of sedative drugs","cn":"静脉注射了镇静剂后病人安然入睡。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"calm, serious, and formal","cn":"安静的﹐安详的﹔庄重的"},{"en":"moving slowly and calmly 〔","cn":"行进〕慢悠悠的"},{"en":"to give someone drugs to make them calm or to make them sleep","cn":"给…服镇静剂"}]},"vocab":{"pos":"adj v","senses":[{"en":"Sedate means to be calm, but if a doctor sedates you it means you've been administered a tranquilizing drug. Most surgeries require some form of sedation, but to be sedate in day-to-day life means composed, quiet, and serene. Not necessarily unconscious."}]},"media":{"uk":"media/ldoce/hwd/bre/3/sedate_adj0205.mp3","us":"media/ldoce/hwd/ame/a/sedate1.mp3"},"examples":[{"en":"We followed the youngsters at a more sedate pace.","cn":"我们跟在年轻人后面，步子稍慢一点。"},{"en":"Most of the patients are heavily sedated.","cn":"多数病人服了大剂量镇静药。"}],"oxford":{"phon":"sɪˈdeɪt","pos":"adjective","senses":[{"en":"slow, calm and relaxed","cn":"镇定的；泰然的；不慌不忙的","ex":{"en":"We followed the youngsters at a more sedate pace.","cn":"我们跟在年轻人后面，步子稍慢一点。"}},{"en":"quiet, especially in a way that lacks excitement","cn":"宁静的；不热闹的","ex":{"en":"a sedate country town","cn":"宁静的乡间小镇"}},{"en":"to give somebody drugs in order to make them calm and/or to make them sleep","cn":"给…服镇静剂","ex":{"en":"Most of the patients are heavily sedated.","cn":"多数病人服了大剂量镇静药。"},"pos":"verb"}]}},"seraph":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"(《圣经》中的)六翼天使，撒拉弗","en":"In the Bible, a seraph is a kind of angel."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"one of the angel s that protect the seat of God, according to the Bible","cn":"撒拉弗〔《圣经》中守护上帝宝座的天使〕"}]},"vocab":{"pos":"n","senses":[{"en":"A seraph is an angel — a heavenly, human-like creature with wings."}]},"media":{"uk":"media/ldoce/hwd/bre/7/ld41seraph.mp3","us":"media/ldoce/hwd/ame/c/seraph.mp3"},"oxford":{"phon":"ˈserəf","pos":"noun","senses":[{"en":"an angel of the highest rank","cn":"撒拉弗，色辣芬（基督教中级别最高的天使）"}]}},"self-worth":{"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"自我价值感","en":"Self-worth is the feeling that you have good qualities and have achieved good things.","ex":{"en":"Try not to link your sense of self-worth to the opinions of others.","cn":"尽量不要把你的自我价值感和别人的意见联系起来。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"the feeling that you deserve to be liked and respected","cn":"自我价值感"}]},"media":{"uk":"media/ldoce/hwd/bre/a/ld41self-worth.mp3","us":"media/ldoce/hwd/ame/c/laadself-worth.mp3"},"examples":[{"en":"Work gave me a sense of dignity and self-worth.","cn":"工作给了我自尊﹐使我认识到了自己的价值。"}],"oxford":{"phon":"ˌself ˈwɜːθ","pos":"noun","senses":[{"en":"a feeling of confidence in yourself that you are a good and useful person","cn":"自我价值感","ex":{"en":"Praise your child to increase her sense of self-worth.","cn":"要多表扬你的孩子，以提高她的自信心。"}}]}},"semblance":{"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"假象;表象;外观","en":"If there is a semblance of a particular condition or quality, it appears to exist, even though this may be a false impression.","ex":{"en":"At least a semblance of normality has been restored to parts of the country","cn":"该国的部分地区至少已经恢复了表面的常态。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"if someone or something has the appearance of being a particular kind of person or thing, they seem to be like that, but in fact they may not be","cn":""},{"en":"your impression of someone or something is the way they seem to you","cn":""},{"en":"when something seems to be true, normal etc - use this especially in negative sentences when something seems only very slightly true, normal etc, or to say that it does not seem this at all","cn":""}]},"vocab":{"pos":"n","senses":[{"en":"Semblance is all about illusion. Cramming all of your dirty clothes into the closet gives the semblance, or false appearance, that you've done your laundry — but the stench might give you away."}]},"collocations":{"phrases":["VERB + SEMBLANCE have | lack The film lacks any semblance of realism. | gain | drop, lose He dropped all semblance of dignity and rushed dow","PREP. in/into a/the ~ of She bared her teeth in a semblance of a smile. | ~ of He tried to restore some semblance of normality to their home","PHRASES a/some semblance of order"]},"media":{"uk":"media/ldoce/hwd/bre/7/semblance0205.mp3","us":"media/ldoce/hwd/ame/f/semblance.mp3"},"examples":[{"en":"The ceasefire brought about a semblance of peace.","cn":"停火协定带来了表面的和平。"},{"en":"Life at last returned to some semblance of normality.","cn":"生活似乎终于恢复了正常。"}],"oxford":{"phon":"ˈsembləns","pos":"noun","senses":[{"en":"a situation in which something seems to exist although this may not, in fact, be the case","cn":"表象；假象；外观；外貌","ex":{"en":"The ceasefire brought about a semblance of order.","cn":"停火协定带来了表面的秩序。"}}]}},"sentiment":{"collins":{"senses":[{"pos":"N-VAR 可变名词","cn":"(基于思想或情感的)态度，情绪","en":"A sentiment that people have is an attitude which is based on their thoughts and feelings.","ex":{"en":"Public sentiment rapidly turned anti-American","cn":"公众情绪迅速转变，开始反对美国。"}},{"pos":"N-COUNT 可数名词","cn":"(用言辞表达的)见解，感想","en":"A sentiment is an idea or feeling that someone expresses in words.","ex":{"en":"I must agree with the sentiments expressed by John Prescott","cn":"我不得不对约翰·普雷斯科特的见解表示赞同。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"(尤指对过去的事过度而无谓的)感伤，眷恋","en":"Sentiment is feelings such as pity or love, especially for things in the past, and may be considered exaggerated and foolish.","ex":{"en":"Laura kept that letter out of sentiment","cn":"劳拉因无法释怀而一直保留着那封信。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"your opinion about something, especially whether you think it is good or bad","cn":""},{"en":"your opinion about something, especially about a serious or important subject","cn":""},{"en":"what you think and feel about something or someone, especially when this is shown in the way you behave towards them","cn":""}]},"vocab":{"pos":"n","senses":[{"en":"Your opinion that most comedies are terrible and that you'd rather watch any other kind of movie could be described as your sentiment , or your attitude, about films."}]},"collocations":{"phrases":["ADJ. deep, strong | growing, rising | fine, lofty, noble All these noble sentiments have little chance of being put into practice. | nationa","VERB + SENTIMENT express | agree with, echo, endorse, share He agrees with the sentiments expressed in the editorial. | disagree with | arou","SENTIMENT + VERB grow","PREP. ~s about/on It would be a mistake to ignore their strong sentiments on the issue. | ~ against The killings at the weekend helped arous","PHRASES my sentiments exactly (= I agree) &lsquo;I don't see why we should change our plans just because of him.&rsquo; &lsquo;My sentiments"]},"media":{"uk":"media/ldoce/hwd/bre/6/sentiment0205.mp3","us":"media/ldoce/hwd/ame/e/sentiment.mp3"},"examples":[{"en":"There was no fatherly affection, no display of sentiment.","cn":"没有像父爱般的亲昵，没有显得过于激动。"},{"en":"Public sentiment is against any change to the law.","cn":"公众的意见是反对对该法律作任何修改。"}],"oxford":{"phon":"ˈsentɪmənt","pos":"noun","senses":[{"en":"a feeling or an opinion, especially one based on emotions","cn":"（基于情感的）观点，看法；情绪","g":"[countable, uncountable]","lab":"formal","ex":{"en":"the spread of nationalist sentiments","cn":"民族主义情绪的传播"}},{"en":"feelings of sympathy, romantic love, being sad, etc. which may be too strong or not appropriate","cn":"（失之过度或不恰当的）伤感，柔情，哀伤","g":"[uncountable]","lab":"sometimes disapproving","ex":{"en":"There was no fatherly affection, no display of sentiment.","cn":"没有温情脉脉的父爱流露。"}}]}},"self-indulgent":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"放纵自己的;任性的","en":"If you say that someone is self-indulgent, you mean that they allow themselves to have or do the things that they enjoy very much.","ex":{"en":"Why give publicity to this self-indulgent, adolescent oaf?","cn":"为什么要宣传报道这个行为任性、青春期未满的白痴呢？"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"allowing yourself to have or do things that you enjoy but do not need, especially if you do this too often – used to show disapproval","cn":"放纵自己的﹐纵容自己的〔含贬义〕"}]},"media":{"uk":"media/ldoce/hwd/bre/f/brelasdeself-indulgent.mp3","us":"media/ldoce/hwd/ame/b/laadself-indulgent.mp3"},"examples":[{"en":"It feels self-indulgent spending so much on a pair of shoes.","cn":"花这么多钱买一双鞋子﹐感觉太纵容自己了。"}],"oxford":{"phon":"ˌself ɪnˈdʌldʒənt","pos":"adjective","senses":[{"en":"allowing yourself to have or do things that you like, especially when you do this too much or too often","cn":"放纵自己的；任性的","ex":{"en":"a self-indulgent lifestyle","cn":"放任的生活方式"}}]}},"self-sacrificing":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"自我牺牲的","en":"Someone who is self-sacrificing gives up what they want so that other people can have what they need or want.","ex":{"en":"He was a generous self-sacrificing man.","cn":"他是一个慷慨大方、勇于自我牺牲的人。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"when you decide not to do or have something you want or need, in order to help someone else","cn":""}]},"media":{"uk":"media/ldoce/hwd/bre/0/self_sacrifice0205.mp3","us":"media/ldoce/hwd/ame/1/self-sacrifice.mp3"},"examples":[{"en":"several years of hard work and self-sacrifice","cn":""}],"oxford":{"phon":"ˌself ˈsækrɪfaɪsɪŋ","pos":"adjective","senses":[{"en":"not allowing yourself to have or do something in order to help other people","cn":"自我牺牲","ex":{"en":"self-sacrificing love","cn":"自我牺牲的爱"}}]}},"setter":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"赛特种猎犬(一种长毛猎狗，经训练后可以发现猎物位置)","en":"A setter is a long-haired dog that can be trained to show hunters where birds and animals are."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a long-haired dog often trained to help hunters find where animals or birds are","cn":"塞特猎犬﹐蹲伏猎狗〔一种长毛狗﹐常被训练帮助猎人寻找猎物〕"},{"en":"someone who does things that other people admire and try to copy","cn":"风格倡导者/潮流倡导者/标准制定者等"},{"en":"someone who decides or organizes something as part of a job","cn":"考试命题者/政策制定者等"}]},"media":{"uk":"media/ldoce/hwd/bre/a/ld41setter.mp3","us":"media/ldoce/hwd/ame/9/setter.mp3"},"examples":[{"en":"a quiz setter","cn":"命题人"},{"en":"Liz has always been a fashion-setter.","cn":"利兹一直是时尚的引领者。"}],"oxford":{"phon":"ˈsetə(r)","pos":"noun","senses":[{"en":"a large dog with long hair, sometimes used in hunting. There are several types of setter.","cn":"蹲伏猎狗，雪达犬（体大毛长，有几个品种）","ex":{"en":"an Irish setter","cn":"爱尔兰蹲伏猎狗"}},{"en":"a person who sets something","cn":"制定者；规定者；安排者","ex":{"en":"a quiz setter","cn":"命题人"}}]}},"seedling":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"秧苗;籽苗;幼苗","en":"A seedling is a young plant that has been grown from a seed."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a young plant or tree grown from a seed","cn":"籽苗﹐种苗﹐幼苗"}]},"media":{"uk":"media/ldoce/hwd/bre/1/seedling0205.mp3","us":"media/ldoce/hwd/ame/8/seedling.mp3"},"oxford":{"phon":"ˈsiːdlɪŋ","pos":"noun","senses":[{"en":"a young plant that has grown from a seed","cn":"秧苗；籽苗；幼苗","ex":{"en":"tomato seedlings","cn":"番茄苗"}}]}},"sentimentalize":{"collins":{"senses":[{"pos":"VERB 动词","cn":"使感伤;使带有感情色彩","en":"If you sentimentalize something, you make it seem sentimental or think about it in a sentimental way.","ex":{"en":"He seems either to fear women or to sentimentalize them","cn":"他似乎要么怕女人要么就对她们怀有浪漫想法。"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to speak, write, or think about only the good or happy things about something, not the bad things","cn":"只谈…的美好一面﹔感性对待"}]},"media":{"uk":"media/ldoce/hwd/bre/a/ld41sentimentalize.mp3","us":"media/ldoce/hwd/ame/a/sentimentalize.mp3"},"examples":[{"en":"Jackie was careful not to sentimentalize country life.","cn":"杰基很注意，没有过分渲染乡村生活。"},{"en":"novels that sentimentalize the past","cn":"怀旧小说"}],"oxford":{"phon":"ˌsentɪˈmentəlaɪz","pos":"verb","senses":[{"en":"to present something in an emotional way, emphasizing its good aspects and not mentioning its bad aspects","cn":"带着感情色彩描述好的方面","ex":{"en":"Jackie was careful not to sentimentalize country life.","cn":"杰基很注意，没有过分渲染乡村生活。"}}]}},"seaworthy":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"(船舶)适宜航海的，能出海的","en":"A ship or boat which is seaworthy is fit to travel at sea.","ex":{"en":"The ship was completely seaworthy.","cn":"这艘轮船在海上航行没问题。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"a ship that is seaworthy is in a suitable condition to sail 〔","cn":"船〕能安全行驶的﹐状况良好的﹐适于航行的"}]},"media":{"uk":"media/ldoce/hwd/bre/2/ld41seaworthy.mp3","us":"media/ldoce/hwd/ame/7/seaworthy.mp3"},"oxford":{"phon":"ˈsiːwɜːði","pos":"adjective","senses":[{"en":"in a suitable condition to sail","cn":"适宜航海的；能出海的"}]}},"serotonin":{"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"血清素","en":"Serotonin is a chemical produced naturally in your brain that affects the way you feel, for example making you feel happier, calmer, or less hungry."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a chemical in the body that helps carry messages from the brain and is believed to make you feel happy","cn":"血清素"}]},"media":{"uk":"media/ldoce/hwd/bre/5/ld41serotonin.mp3","us":"media/ldoce/hwd/ame/8/laadserotonin.mp3"},"oxford":{"phon":"ˌserəˈtəʊnɪn","pos":"noun","senses":[{"en":"a chemical in the brain that affects how messages are sent from the brain to the body, and also affects how a person feels","cn":"5–羟色胺，血清素（神经递质，亦影响情绪等）","ex":{"en":"the feel‐good hormone serotonin","cn":"感觉良好的激素血清素"}}]}},"self-willed":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"任性的;固执的;倔强的","en":"Someone who is self-willed is determined to do the things that they want to do and will not take advice from other people.","ex":{"en":"He was very independent and self-willed.","cn":"他非常独立而且固执己见。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"very determined to do what you want, whatever other people think – used to show disapproval","cn":"任性的﹐固执的﹐执拗的〔含贬义〕"}]},"media":{"uk":"media/ldoce/hwd/bre/2/self_willed0205.mp3","us":"media/ldoce/hwd/ame/c/laadself-willed.mp3"},"examples":[{"en":"a wild and self-willed child","cn":"一个放肆任性的小孩"}],"oxford":{"phon":"ˌself ˈwɪld","pos":"adjective","senses":[{"en":"determined to do what you want without caring about other people","cn":"任性的；固执的","ex":{"en":"Even at four years old, Carol was stubborn and self-willed.","cn":"即使只有四岁，卡罗尔就很固执、任性。"}}]}},"sequential":{"collins":{"senses":[{"pos":"ADJ 形容词","cn":"按次序的;顺序的;序列的","en":"Something that is sequential follows a fixed order.","ex":{"en":"...the sequential story of the universe","cn":"宇宙的变迁史"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"relating to or happening in a sequence","cn":"连续的﹔相继的﹔顺序的﹔序列的"}]},"vocab":{"pos":"adj","senses":[{"en":"Use the word sequential to describe something that has a particular order, like a recipe for chocolate chip cookies whose steps must be followed in a sequential order."}]},"media":{"uk":"media/ldoce/hwd/bre/e/ld41sequential.mp3","us":"media/ldoce/hwd/ame/9/sequential.mp3"},"examples":[{"en":"data stored sequentially on a computer","cn":"顺序存贮在计算机里的数据"},{"en":"sequential data processing","cn":"顺序数据处理"}],"oxford":{"phon":"sɪˈkwenʃl","pos":"adjective","senses":[{"en":"following in order of time or place","cn":"按次序的；顺序的；序列的","ex":{"en":"sequential data processing","cn":"顺序数据处理"}}]}},"self-evident":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"不证自明的;不言而喻的;明摆着的","en":"A fact or situation that is self-evident is so obvious that there is no need for proof or explanation.","ex":{"en":"It is self-evident that we will never have enough resources to meet the demand","cn":"不言而喻，我们永远都不会有足够的资源来满足需求。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"something that is obvious is very easy to notice or understand – used especially when you are surprised that other people cannot notice it","cn":""},{"en":"easy to notice that something is true, so that you feel sure about it and have no doubts","cn":""},{"en":"very easy to notice, especially because you can see, hear, smell, or feel something","cn":""}]},"collocations":{"phrases":["VERBS appear, be, seem | become","ADV. by no means These truths were by no means self-evident when Galileo first suggested them. | almost | largely | fairly","PREP. to It was self-evident to her that anything so wonderful could not have evolved accidentally."]},"media":{"uk":"media/ldoce/hwd/bre/3/self_evident0205.mp3","us":"media/ldoce/hwd/ame/7/self-evident.mp3"},"examples":[{"en":"The dangers of such action are self-evident.","cn":"这样的行动，其危险是明摆着的。"},{"en":"a self-evident truth","cn":"不证自明的真理"}],"oxford":{"phon":"ˌself ˈevɪdənt","pos":"adjective","senses":[{"en":"obvious and needing no further proof or explanation","cn":"显而易见的；不言而喻的；明摆着的","ex":{"en":"The dangers of such action are self-evident.","cn":"这样的行动，其危险是明摆着的。"}}]}},"septicaemia":{"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"败血病;败血症","en":"Septicaemia is blood poisoning."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a serious condition in which infection spreads from a part of your body through your blood","cn":"败血症"}]},"media":{"uk":"media/ldoce/hwd/bre/2/ld41septicaemia.mp3","us":"media/ldoce/hwd/ame/2/ld41septicaemia.mp3"},"oxford":{"phon":"ˌseptɪˈsiːmiə","pos":"noun","senses":[{"en":"infection of the blood by harmful bacteria","cn":"败血症"}]}},"sexualize":{"collins":{"senses":[{"pos":"VERB 动词","cn":"使有性别;使有性征;使发生性关系","en":"To sexualize something or someone means to make them sexual or consider them in a sexual way.","ex":{"en":"Referring to children's friends as girlfriends and boyfriends sexualizes them","cn":"将孩子们的朋友称为女朋友或男朋友就把他们的性别差异凸显出来了。"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to make someone or something sexual, especially in a way that is not suitable 〔","cn":"尤指以失当的方式〕使性化"}]},"media":{"uk":"media/ldoce/hwd/bre/4/ld5_sexualize.mp3","us":"media/ldoce/hwd/ame/4/ld5_sexualize.mp3"},"examples":[{"en":"I worry about the fact that children are sexualized at such a young age.","cn":"孩子这么小就被性化，这让我感到忧虑。"}],"oxford":{"phon":"ˈsekʃuəlaɪz","pos":"verb","senses":[{"en":"to make somebody/something seem sexually attractive","cn":"使性感"}]}},"semiskilled":{"collins":{"senses":[{"pos":"ADJ 形容词","cn":"半熟练的","en":"A semi-skilled worker has some training and skills, but not enough to do specialized work."}]}},"seaboard":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"(尤指北美的)沿海地区,海滨","en":"The seaboard is the part of a country that is next to the sea; used especially of the coasts of North America.","ex":{"en":"...the Eastern seaboard of the USA.","cn":"美国的东海岸"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"the part of a country that is close to the sea","cn":""},{"en":"the land along the edge of the sea or along the edge of a lake","cn":""},{"en":"the land along the edge of the sea, especially where there is sand and rocks","cn":""}]},"media":{"uk":"media/ldoce/hwd/bre/f/ld41seaboard.mp3","us":"media/ldoce/hwd/ame/7/seaboard.mp3"},"examples":[{"en":"Australia's eastern seaboard","cn":"澳大利亚东部沿海地区"}],"oxford":{"phon":"ˈsiːbɔːd","pos":"noun","senses":[{"en":"the part of a country that is along its coast","cn":"沿海地区；海滨","ex":{"en":"Australia’s eastern seaboard","cn":"澳大利亚东部沿海地区"}}]}},"semolina":{"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"(用于做布丁或意大利面食的)粗面粉","en":"Semolina consists of small hard grains of wheat that are used for making sweet puddings with milk and for making pasta."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"small grains of crushed wheat, used especially in making sweet dishes and pasta 〔","cn":"尤用于做甜食和意大利面食的〕粗面粉"},{"en":"a sweet dish made with these grains and milk","cn":"粗面粉布丁〔用粗面粉和牛奶做的甜食〕"}]},"media":{"uk":"media/ldoce/hwd/bre/4/ld41semolina.mp3","us":"media/ldoce/hwd/ame/8/semolina.mp3"},"oxford":{"phon":"ˌseməˈliːnə","pos":"noun","senses":[{"en":"large hard grains of wheat pressed and used for making pasta and sweet dishes","cn":"麦糁，粗面粉（用以制作意大利面食和甜食）"},{"en":"a sweet dish made from semolina and milk, eaten for dessert in the UK and for breakfast in the US","cn":"粗面粉布丁"}]}},"self-respecting":{"collins":{"senses":[{"pos":"ADJ 形容词","cn":"地道的，典型的(一类人)","en":"You can use self-respecting with a noun describing a particular type of person to indicate that something is typical of, or necessary for, that type of person.","ex":{"en":"He died as any self-respecting gangster should — in a hail of bullets","cn":"他死于乱枪之下——匪徒典型的最终下场。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"having respect for yourself and your abilities and beliefs","cn":"自尊的﹐有自尊心的"},{"en":"no/any self-respecting ... would do something No self-respecting actor would appear in a porn movie.","cn":"有自尊的演员是不会演色情电影的。"}]},"media":{"uk":"media/ldoce/hwd/bre/2/self_respectin0205.mp3","us":"media/ldoce/hwd/ame/9/self-respecting.mp3"},"examples":[{"en":"No self-respecting journalist would ever work for that newspaper.","cn":"凡有自尊心的记者都不会为那家报纸工作。"}],"oxford":{"phon":"ˌself rɪˈspektɪŋ","pos":"adjective","senses":[{"en":"being proud of yourself because you believe that what you do is right and good; good enough to deserve a particular name or description","cn":"有自尊心的","ex":{"en":"No self-respecting journalist would ever work for that newspaper.","cn":"凡有自尊心的记者都不会为那家报纸工作。"}}]}},"sepulchral":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"阴郁的;阴沉的;非常恐怖的","en":"Something that is sepulchral is serious or sad and rather frightening.","ex":{"en":"'He's gone,' Rory whispered in sepulchral tones.","cn":"“他已经走了，”罗里阴沉地小声说道。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"阴森的;空寂的","en":"A sepulchral place is dark, quiet, and empty.","ex":{"en":"He made his way along the sepulchral corridors.","cn":"他沿着阴森森的走廊走着。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"sad, serious, and slightly frightening","cn":"低沉忧郁的﹐阴沉的"},{"en":"dark, empty, and slightly frightening","cn":"空寂的﹐阴森森的"}]},"vocab":{"pos":"adj","senses":[{"en":"Something that reminds you of death is sepulchral . A dreary, misty graveyard at night usually feels sepulchral ."}]},"media":{"uk":"media/ldoce/hwd/bre/b/ld41sepulchral.mp3","us":"media/ldoce/hwd/ame/d/sepulchral.mp3"},"examples":[{"en":"He spoke in sepulchral tones.","cn":"他说话语气阴沉。"},{"en":"in the sepulchral gloom of the church","cn":"在教堂阴沉昏暗的光线中"}],"oxford":{"phon":"səˈpʌlkrəl","pos":"adjective","senses":[{"en":"looking or sounding sad and serious; making you think of death","cn":"阴沉的；阴森森的；死一般的","ex":{"en":"He spoke in sepulchral tones.","cn":"他说话语气阴沉。"}}]}},"serenade":{"collins":{"senses":[{"pos":"VERB 动词","cn":"(在所爱慕女子的窗下)为(其)唱(或演奏)小夜曲","en":"If one person serenades another, they sing or play a piece of music for them. Traditionally men did this outside the window of the woman they loved.","ex":{"en":"In the interval a blond boy dressed in white serenaded the company on the flute","cn":"幕间休息时,一位身着白衣的金发男孩用长笛为来宾演奏了一支小夜曲。"}},{"pos":"N-COUNT 可数名词","cn":"(古典音乐中为小型管弦乐队谱写的)组曲，小夜曲","en":"In classical music, a serenade is a piece in several parts written for a small orchestra.","ex":{"en":"...Vaughan Williams's Serenade to Music.","cn":"沃恩·威廉斯的《音乐小夜曲》"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a song sung to someone, especially one that a man performs for the woman he loves while standing below her window at night 〔","cn":"尤指男子晚上站在其意中人窗外唱或奏的〕小夜曲"},{"en":"a piece of gentle music","cn":"柔和的乐曲"},{"en":"if you serenade someone, you sing or play music to them, especially to show them that you love them 〔","cn":"尤为表爱慕之情而〕对…唱[奏]小夜曲"}]},"vocab":{"pos":"n v","senses":[{"en":"If you really want to win someone's heart, take your ukulele to his house at night and serenade him under his open window. When you serenade someone, you play or sing a song, often outdoors."}]},"media":{"uk":"media/ldoce/hwd/bre/4/serenade_n0205.mp3","us":"media/ldoce/hwd/ame/5/serenade1.mp3"},"oxford":{"phon":"ˌserəˈneɪd","pos":"noun","senses":[{"en":"(in the past) a song or tune played or sung at night by a man outside the window of the woman he loves","cn":"（男子在所爱慕的女子窗下演奏或歌唱的）小夜曲"},{"en":"a gentle piece of music in several parts, usually for a small group of instruments","cn":"（尤指供小型乐队演奏的）小夜曲"},{"en":"to sing or play music to somebody (as done in the past by a man singing under her window to the woman he loved)","cn":"（对某人）唱小夜曲，奏小夜曲","ex":{"en":"We were serenaded by a string quartet.","cn":"一支弦乐四重奏乐队为我们演奏小夜曲。"},"pos":"verb"}]}},"selfishness":{"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"thinking only about what you need or want, and not thinking about how other people feel or what other people want – used especially when criticizing a person or their behaviour","cn":""},{"en":"believing that what you do and think is the most important thing, and not paying attention to what anyone else thinks or does – used when describing someone’s personality","cn":""},{"en":"believing that you are better or more important than other people","cn":""}]},"collocations":{"phrases":["ADJ. pure, utter","PHRASES an act of selfishness an act of utter selfishness | greed and selfishness"]},"media":{"uk":"media/ldoce/hwd/bre/d/selfish0205.mp3","us":"media/ldoce/hwd/ame/c/selfish.mp3"},"examples":[{"en":"How can you be so selfish?","cn":""}],"oxford":{"phon":"ˈselfɪʃnəs","pos":"noun","senses":[{"en":"the fact of caring only about yourself rather than about other people","cn":"自私的","ex":{"en":"He was the victim of his own greed and selfishness.","cn":"他尝到了自己贪婪与自私带来的苦果。"}}]}},"seamy":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"丑恶的;污秽的;卑鄙的;暴力的","en":"If you describe something as seamy, you mean that it involves unpleasant aspects of life such as crime, sex, or violence.","ex":{"en":"...Hamburg's seamy St Pauli's district.","cn":"汉堡肮脏污秽的圣保利街区"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"involving unpleasant things such as crime, violence, or immorality","cn":"污秽的﹐丑恶的"}]},"vocab":{"pos":"adj","senses":[{"en":"Things that are seamy have lost all morality. Your mother wouldn't approve of you going to a seamy video arcade, especially not if you went with a group of seamy people."}]},"media":{"uk":"media/ldoce/hwd/bre/6/seamy0205.mp3","us":"media/ldoce/hwd/ame/0/seamy.mp3"},"examples":[{"en":"a seamy sex scandal","cn":"龌龊的性丑闻"},{"en":"the seamier side of life","cn":"生活的阴暗面"}],"oxford":{"phon":"ˈsiːmi","pos":"adjective","senses":[{"en":"unpleasant or morally wrong","cn":"污秽的；肮脏丑恶的","ex":{"en":"a seamy sex scandal","cn":"龌龊的性丑闻"}}]}},"sedentary":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"需要久坐的;长期伏案的;少活动的","en":"Someone who has a sedentary lifestyle or job sits down a lot of the time and does not take much exercise.","ex":{"en":"Obesity and a sedentary lifestyle has been linked with an increased risk of heart disease.","cn":"肥胖和久坐不动的生活方式被认为会增加患心脏病的几率。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"if someone is sedentary or they have a sedentary job, they spend most of their time sitting down","cn":""},{"en":"a meal etc in which everyone in a group, usually a large group, sits at tables","cn":""},{"en":"spending a lot of time sitting down, and not moving or exercising very much","cn":"久坐不动的"}]},"vocab":{"pos":"adj","senses":[{"en":"Scientists believe that one of the causes of the obesity epidemic sweeping the US is our sedentary lifestyle. Sedentary means sitting a lot and refers to a person or job that is not very physically active."}]},"media":{"uk":"media/ldoce/hwd/bre/1/sedentary0205.mp3","us":"media/ldoce/hwd/ame/2/sedentary.mp3"},"examples":[{"en":"He became increasingly sedentary in later life.","cn":"到晚年，他变得越来越不爱动了。"},{"en":"Rhinos are largely sedentary animals.","cn":"大致说来，犀牛是一种定栖动物。"}],"oxford":{"phon":"ˈsedntri","pos":"adjective","senses":[{"en":"in which you spend a lot of time sitting down","cn":"需要久坐的","ex":{"en":"a sedentary job/occupation/lifestyle","cn":"常久坐的工作／职业／生活方式"}},{"en":"spending a lot of time sitting down and not moving","cn":"惯于久坐不动的","ex":{"en":"He became increasingly sedentary in later life.","cn":"到晚年，他变得越来越不爱动了。"}},{"en":"that stay and live in the same place or area","cn":"定居的；定栖的；不迁徙的","lab":"specialist","ex":{"en":"Rhinos are largely sedentary animals.","cn":"大致说来，犀牛是一种定栖动物。"}}]}},"seventeenth":{"collins":{"senses":[{"pos":"ORD 序数词","cn":"第十七","en":"The seventeenth item in a series is the one that you count as number seventeen.","ex":{"en":"She gave birth to Annabel just after her seventeenth birthday.","cn":"她 17 岁生日刚过便生下了安娜贝尔。"}},{"pos":"FRACTION 分数词","cn":"十七分之一","en":"A seventeenth is one of seventeen equal parts of something."}]},"ldoce":{"phon":"hwd","pos":"","senses":[{"en":"the number 17","cn":""}]},"media":{"uk":"media/ldoce/hwd/bre/4/ld41seventeen.mp3","us":"media/ldoce/hwd/ame/2/seventeen.mp3"},"examples":[{"en":"a group of seventeen American military officers","cn":""},{"en":"I left home when I was seventeen (= 17 years old ) .","cn":""}],"oxford":{"phon":"ˌsevnˈtiːnθ","pos":"ordinal number","senses":[{"en":"17th","cn":"十七"},{"en":"each of 17 equal parts of something","cn":"七分之一","pos":"noun"}]}},"senegalese":{"collins":{"senses":[{"pos":"ADJ 形容词","cn":"塞内加尔的;塞内加尔人的","en":"Senegalese means belonging or relating to Senegal, or to its people or culture.","ex":{"en":"...the Senegalese navy.","cn":"塞内加尔海军"}},{"pos":"N-COUNT 可数名词","cn":"塞内加尔人;塞内加尔裔人","en":"A Senegalese is a Senegalese citizen, or a person of Senegalese origin."}]},"ldoce":{"phon":"hwd","pos":"","senses":[{"en":"a country in West Africa on the Atlantic coast. Population: 13,300,410 (2014). Capital: Dakar.","cn":""}]},"media":{"uk":"media/ldoce/hwd/bre/6/p028-000011010.mp3","us":"media/ldoce/hwd/ame/6/p028-000011010.mp3"},"oxford":{"phon":"ˌsenɪɡəˈliːz","pos":"noun, adjective","senses":[{"en":"(a person) from Senegal","cn":"塞内加尔人；塞内加尔的；塞内加尔人的"}]}},"sensor":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"(探测光、热等的)传感器,探测设备,敏感元件","en":"A sensor is an instrument which reacts to certain physical conditions or impressions such as heat or light, and which is used to provide information.","ex":{"en":"The latest Japanese vacuum cleaners contain sensors that detect the amount of dust and type of floor.","cn":"日本的最新真空吸尘器配有可探测灰尘多少和地板类型的传感器。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a piece of equipment used for discovering the presence of light, heat, movement etc 〔","cn":"探测光﹑热﹑活动等的〕传感器﹐感应装置"}]},"media":{"uk":"media/ldoce/hwd/bre/4/censor_n0205.mp3","us":"media/ldoce/hwd/ame/9/censor1.mp3"},"examples":[{"en":"security lights with an infrared sensor (= that come on when a person is near them)","cn":"带红外线传感器的保安灯"}],"oxford":{"phon":"ˈsensə(r)","pos":"noun","senses":[{"en":"a device that can react to light, heat, pressure, etc. in order to make a machine, etc. do something or show something","cn":"（探测光、热、压力等的）传感器，敏感元件","ex":{"en":"security lights with an infrared sensor (= that come on when a person is near them)","cn":"带红外线传感器的保安灯"}}]}},"self-possession":{"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"沉着;镇静;泰然自若","en":"Self-possession is the quality of being self-possessed.","ex":{"en":"She found her customary self-possession had deserted her.","cn":"她发现自己不像平时那样处事不惊了。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"sure that you have the ability to do something well or deal with situations successfully","cn":""},{"en":"confident, and not shy or nervous in social situations","cn":""},{"en":"confident, calm, and in control of your feelings even in a difficult situation","cn":""}]},"media":{"uk":"media/ldoce/hwd/bre/2/self_possessed0205.mp3","us":"media/ldoce/hwd/ame/1/self-possessed.mp3"},"examples":[{"en":"He soon recovered his usual self-possession.","cn":"他很快恢复了平时沉着冷静的样子。"},{"en":"She’s a confident self-possessed public speaker.","cn":""}],"oxford":{"phon":"ˌself pəˈzeʃn","pos":"noun","senses":[{"en":"the ability to remain calm and confident in a difficult situation","cn":"沉着的；镇定的；泰然自若的","ex":{"en":"He soon recovered his usual self-possession.","cn":"他很快就恢复了一贯的镇定。"}}]}},"settler":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"殖民者;移民","en":"Settlers are people who go to live in a new country.","ex":{"en":"The village was founded by settlers from the Volga region.","cn":"来自伏尔加地区的移民建起了这个村庄。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"all the people in a country or town or area, or the number of people who live in it","cn":""},{"en":"someone who lives in a particular area of a town, a particular street or building etc","cn":""},{"en":"one of the people who live in a place, especially in a town or city or in an area of a country","cn":""}]},"vocab":{"pos":"1 n 2 n","senses":[{"en":"A settler is a person who moves to a new place with the intention to stay there. Colonial America was built by settlers who came mainly from England."}]},"collocations":{"phrases":["ADJ. early, first, original","SETTLER + VERB move in/into sth When the first settlers moved into the area they faced immense hardships. | establish, found French settlers","PREP. ~ from settlers from France | ~ in Dutch settlers in Cape Town"]},"media":{"uk":"media/ldoce/hwd/bre/b/settler0205.mp3","us":"media/ldoce/hwd/ame/a/settler.mp3"},"examples":[{"en":"white settlers in Africa","cn":"非洲的白人移民"},{"en":"early settlers in Australia","cn":"澳大利亚的早期移民"}],"oxford":{"phon":"ˈsetlə(r)","pos":"noun","senses":[{"en":"a person who goes to live in a new country or region","cn":"移民；殖民者","ex":{"en":"Most of the settlers came from England.","cn":"多数移民来自英格兰。"}}]}},"sender":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"(信件、包裹的)寄件人，邮寄人;(无线电报的)发送人","en":"The sender of a letter, package, or radio message is the person who sent it.","ex":{"en":"The sender of the best letter every week will win a cheque for £20.","cn":"每周寄来的作品中，最优秀者将赢得 20 英镑的支票。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"the person who sent a particular letter, package, message etc 〔","cn":"信件﹑包裹﹑信息等的〕发送者﹐寄件人"}]},"media":{"uk":"media/ldoce/hwd/bre/4/ld41sender.mp3","us":"media/ldoce/hwd/ame/5/sender.mp3"},"examples":[{"en":"If undelivered, please return to sender.","cn":"若无法投递，请退还寄信人。"},{"en":"a package marked ‘ return to sender ’","cn":"标有“退回寄件人”字样的包裹"}],"oxford":{"phon":"ˈsendə(r)","pos":"noun","senses":[{"en":"a person who sends something","cn":"发送人；邮寄人","ex":{"en":"If undelivered, please return to sender.","cn":"若无法投递，请退还寄信人。"}}]}},"semantic":{"collins":{"senses":[{"pos":"ADJ 形容词","cn":"语义的","en":"Semantic is used to describe things that deal with the meanings of words and sentences.","ex":{"en":"He did not want to enter into a semantic debate.","cn":"他不想就语义进行争辩。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"relating to the meanings of words","cn":"语义的"}]},"vocab":{"pos":"adj","senses":[{"en":"If something is semantic , it has to do with the meaning of a word. If you're spending all this time reading the dictionary, you must be interested in semantic questions, unless you just need to do better on vocabulary quizzes."}]},"media":{"uk":"media/ldoce/hwd/bre/2/ld41semantic.mp3","us":"media/ldoce/hwd/ame/f/semantic.mp3"},"examples":[{"en":"semantically related words","cn":"语义上相关联的单词"}],"oxford":{"phon":"sɪˈmæntɪk","pos":"adjective","senses":[{"en":"connected with the meaning of words and sentences","cn":"语义的","ex":{"en":"semantic analysis","cn":"语义分析"}}]}},"seductive":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"非常吸引人的;诱惑的;有魅力的","en":"Something that is seductive is very attractive or makes you want to do something that you would not otherwise do.","ex":{"en":"It's a seductive argument.","cn":"这是一个非常吸引人的论点。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"性感的;撩人的","en":"A person who is seductive is very attractive sexually.","ex":{"en":"...a seductive woman","cn":"性感的女人"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"sexually attractive","cn":""},{"en":"seeming to show strong sexual feelings and a desire for sexual pleasure","cn":""},{"en":"intended to make someone feel sexually excited","cn":""}]},"vocab":{"pos":"adj","senses":[{"en":"Seductive is an adjective that describes the fascinating magnetic pull that someone or something has, an attractive quality that tempts you in some way."}]},"collocations":{"phrases":["VERBS be, look, seem, sound","ADV. extremely, very | infinitely These opportunities seemed infinitely seductive. | almost His words had a soothing, almost seductive quali"]},"media":{"uk":"media/ldoce/hwd/bre/4/seductive0205.mp3","us":"media/ldoce/hwd/ame/8/seductive.mp3"},"examples":[{"en":"The idea of retiring to the south of France is highly seductive.","cn":"退休后到法国南方去，这个主意令人心驰神往。"},{"en":"She used her most seductive voice.","cn":"她运用了自己最有魅力的嗓音。"}],"oxford":{"phon":"sɪˈdʌktɪv","pos":"adjective","senses":[{"en":"sexually attractive","cn":"性感的；有诱惑力的","ex":{"en":"a seductive woman","cn":"富有魅力的女人"}},{"en":"attractive in a way that makes you want to have or do something","cn":"有吸引力的；令人神往的","ex":{"en":"The idea of retiring to the south of France is highly seductive.","cn":"退休后到法国南方去，这个主意令人心驰神往。"}}]}},"self-assurance":{"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"自信;胸有成竹","en":"Someone who has self-assurance shows confidence in the things that they say and do because they are sure of their abilities."}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"sure that you have the ability to do something well or deal with situations successfully","cn":""},{"en":"confident, and not shy or nervous in social situations","cn":""},{"en":"confident, calm, and in control of your feelings even in a difficult situation","cn":""}]},"media":{"uk":"media/ldoce/hwd/bre/d/self_assured0205.mp3","us":"media/ldoce/hwd/ame/b/self-assured.mp3"},"oxford":{"phon":"ˌself əˈʃʊərəns","pos":"noun","senses":[{"en":"confidence in yourself and your abilities","cn":"自信的；胸有成竹的","ex":{"en":"He radiated an air of calm self-assurance.","cn":"他浑身散发着平静自信的气息。"}}]}},"seaplane":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"水上飞机","en":"A seaplane is a type of aeroplane that can take off from or land on water."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a plane that can take off from and land on a body of water","cn":"水上飞机"}]},"media":{"uk":"media/ldoce/hwd/bre/d/ld41seaplane.mp3","us":"media/ldoce/hwd/ame/4/seaplane.mp3","img":["media/thumb/seaplane.jpg"]},"oxford":{"phon":"ˈsiːpleɪn","pos":"noun","senses":[{"en":"a plane that can take off from and land on water","cn":"水上飞机"}]}},"seascape":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"海景画;海景照片","en":"A seascape is a painting or photograph of a scene at sea."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a picture of the sea","cn":"海景画"}]},"media":{"uk":"media/ldoce/hwd/bre/3/ld41seascape.mp3","us":"media/ldoce/hwd/ame/7/seascape.mp3"},"oxford":{"phon":"ˈsiːskeɪp","pos":"noun","senses":[{"en":"a picture or view of the sea","cn":"海景；海景画","ex":{"en":"a vast, sweeping seascape of sky, waves and sand","cn":"天空、海浪和沙滩组成的广阔无垠的海景"}}]}},"sealskin":{"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"海豹皮","en":"Sealskin is the fur of a seal, used to make coats and other clothing.","ex":{"en":"...waterproof sealskin boots.","cn":"海豹皮的防水靴"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"the skin or fur of some types of seal , used for making leather or clothes","cn":"海豹皮"}]},"media":{"uk":"media/ldoce/hwd/bre/6/ld41sealskin.mp3","us":"media/ldoce/hwd/ame/d/sealskin.mp3"},"oxford":{"phon":"ˈsiːlskɪn","pos":"noun","senses":[{"en":"the skin and fur of some types of seal, used for making clothes","cn":"海豹皮（用作衣料）"}]}},"send-off":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"欢送会;送行;送别","en":"If a group of people give someone who is going away a send-off, they come together to say goodbye to them.","ex":{"en":"All the people in the buildings came to give me a rousing send-off.","cn":"大楼里所有的人都热情地来给我送行。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a party or other occasion when people meet to say goodbye to someone who is leaving","cn":"欢送会﹐送别"}]},"media":{"uk":"media/ldoce/hwd/bre/5/send_off0205.mp3","us":"media/ldoce/hwd/ame/6/amelasdesend-off.mp3"},"examples":[{"en":"The department gave Tom a send-off he won’t forget!","cn":"该部门给汤姆开了一个让他永生难忘的欢送会！"}],"oxford":{"phon":"ˈsend ɒf","pos":"noun","senses":[{"en":"an occasion when people come together to say goodbye to somebody who is leaving","cn":"送行；送别","ex":{"en":"Her colleagues gave her a good send-off.","cn":"她的同事们为她热烈送行。"}}]}},"self-appointed":{"collins":{"senses":[{"pos":"ADJ 形容词","cn":"自己任命的;自封的","en":"A self-appointed leader or ruler has taken the position of leader or ruler without anyone else asking them or choosing them to have it.","ex":{"en":"...the new self-appointed leaders of the movement.","cn":"这一运动新近自封的领导者们"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"giving yourself a responsibility, job, position etc without the agreement of other people, especially those you claim to represent – used to show disapproval","cn":"自命的﹐自封的〔含贬义〕"}]},"media":{"uk":"media/ldoce/hwd/bre/4/ld41self-appointed.mp3","us":"media/ldoce/hwd/ame/b/self-appointed.mp3"},"oxford":{"phon":"ˌself əˈpɔɪntɪd","pos":"adjective","senses":[{"en":"giving yourself a particular title, job, etc., especially without the agreement of other people","cn":"自封的；自己任命的","ex":{"en":"self-appointed experts","cn":"自封的专家"}}]}},"set-aside":{"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"(欧盟的)退耕补贴方案(以防止作物产量过多或维持农产品价格)","en":"In the European Union, set-aside is a scheme in which some areas of farmland are not used for a period of time, either because too much is being produced already, or so that a crop does not become too cheap.","ex":{"en":"...set-aside land","cn":"退耕地"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"an arrangement in the European Union in which a government pays farmers to leave some of their fields empty, in order to avoid producing too much of a crop and to keep the price higher","cn":"休耕措施〔欧盟采取的一项措施﹐由政府给农民补贴让他们闲置部分农田﹐以防止某一作物产量过多﹐维持该作物较高的价格〕"},{"en":"an arrangement in the US in which a local government helps small businesses to develop by making financial help available to them","cn":"小企业补贴〔美国地方政府帮助小企业发展的一种补贴〕"},{"en":"an amount of money that is kept so that it can be used for a special purpose 〔","cn":"留作特殊用途的〕备用金"}]},"media":{"uk":"media/ldoce/hwd/bre/3/ld41set-aside.mp3","us":"media/ldoce/hwd/ame/3/ld41set-aside.mp3"},"examples":[{"en":"In 1976, Connecticut established one of the nation’s first set-aside programs. 1976","cn":"年﹐康涅狄格州制订了美国最早的小企业补贴计划之一。"}],"oxford":{"phon":"ˈset əsaɪd","pos":"noun","senses":[{"en":"a system in which the government pays farmers not to use some of their land for growing crops; the land that the farmers are paid not to use","cn":"退耕补贴制度（由政府补贴，鼓励农民退耕部分耕地）；退耕地","ex":{"en":"750 acres of set-aside","cn":"汤姆舒适地坐在桌子旁边。"}}]}},"seemingly":{"collins":{"senses":[{"pos":"ADV 副词","cn":"貌似，看似(但可能并非如此)","en":"If something is seemingly the case, you mean that it appears to be the case, even though it may not really be so.","ex":{"en":"A seemingly endless line of trucks waits in vain to load up.","cn":"一眼望不到头的一长列卡车眼巴巴地等着装货。"}},{"pos":"ADV 副词","cn":"似乎，好像(是事实)","en":"You use seemingly when you want to say that something seems to be true.","ex":{"en":"He has moved to Spain, seemingly to enjoy a slower style of life","cn":"他已经移居西班牙，似乎是想过一种更为悠闲的生活。"}}]},"ldoce":{"phon":"hwd","pos":"adverb","senses":[{"en":"if a person, place, or situation is pleasant, normal, calm etc on the surface , they seem that way until you know them better","cn":""},{"en":"if someone is outwardly calm, happy etc, that is how they seem to be, but in fact they are probably nervous, unhappy etc","cn":""},{"en":"use this when something seems to be true about someone or something especially when it is not true","cn":""}]},"vocab":{"pos":"adv","senses":[{"en":"Something seemingly true appears to be true. Use the adverb seemingly when you want to say \"on the face of it\" or \"apparently.\""}]},"media":{"uk":"media/ldoce/hwd/bre/3/brelasdeseemingly.mp3","us":"media/ldoce/hwd/ame/e/seemingly.mp3"},"examples":[{"en":"Seemingly, he borrowed the money from the bank.","cn":"据说，他从银行贷出了那笔钱。"},{"en":"a seemingly endless journey","cn":"似乎永远走不完的旅程"}],"oxford":{"phon":"ˈsiːmɪŋli","pos":"adverb","senses":[{"en":"in a way that appears to be true but may in fact not be","cn":"看似；貌似；表面上","ex":{"en":"a seemingly stupid question","cn":"看似愚蠢的问题"}},{"en":"according to what you have read or heard","cn":"据说；听说；看来","lab":"formal","ex":{"en":"Seemingly, he borrowed the money from the bank.","cn":"据说，他从银行贷出了那笔钱。"}}]}},"sequestrate":{"collins":{"senses":[{"pos":"VERB 动词","cn":"(通常指按照法庭决议)扣押，查封(债务人资产)","en":"When property is sequestrated, it is taken officially from someone who has debts, usually after a decision in a court of law. If the debts are paid off, the property is returned to its owner.","ex":{"en":"He tried to prevent union money from being sequestrated by the courts.","cn":"他试图阻止法院扣押工会的资产。"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to take property away from the person it belongs to because they have not paid their debts","cn":"扣押〔债务人的财产〕"}]},"media":{"uk":"media/ldoce/hwd/bre/7/ld41sequestrate.mp3","us":"media/ldoce/hwd/ame/7/ld41sequestrate.mp3"},"oxford":{"phon":"ˈsiːkwəstreɪt","pos":"verb","senses":[{"en":"to take control of somebody’s property or assets until a debt has been paid","cn":"强制管理，扣押（债务人资产）","ex":{"en":"The two businessmen were fined, and had their assets sequestrated.","cn":"这两名商人被罚款，并被没收资产。"}}]}},"self-disciplined":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"有自我约束力的;能律己的","en":"Someone who is self-disciplined has the ability to control themselves and to make themselves work hard or behave in a particular way without needing anyone else to tell them what to do.","ex":{"en":"Most religions teach you to be truthful and self-disciplined.","cn":"多数宗教教导人们要真诚和律己。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"if you control yourself or control your feelings, you continue to behave calmly and sensibly and do not become too angry, excited, or upset","cn":""},{"en":"the ability to behave calmly and sensibly and not become too angry, excited, or upset, even when you have a good reason to","cn":""},{"en":"to manage to stay calm and not become angry, especially when someone is trying to make you angry","cn":""}]},"media":{"uk":"media/ldoce/hwd/bre/a/self_disciplin0205.mp3","us":"media/ldoce/hwd/ame/6/self-discipline.mp3"},"examples":[{"en":"A lot of the kids seemed to lack self-discipline.","cn":""}]},"secessionist":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"脱离论者;分离论者;独立主义者","en":"Secessionists are people who want their region or group to become separate from the country or larger group to which it belongs.","ex":{"en":"...Lithuanian secessionists","cn":"立陶宛独立主义者"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"someone who wants their country or state to be independent of another country 〔","cn":"政治〕分离主义者"}]},"media":{"uk":"media/ldoce/hwd/bre/c/ld41secessionist.mp3","us":"media/ldoce/hwd/ame/c/ld41secessionist.mp3"},"examples":[{"en":"a military campaign against the secessionists","cn":"对分离主义者采取的军事行动"}],"oxford":{"phon":"sɪˈseʃənɪst","pos":"adjective","senses":[{"en":"supporting or connected with secession","cn":"赞成（或参与）脱离活动的；奉行分离主义的","ex":{"en":"secessionist groups","cn":"分裂主义团体"}},{"en":"a person who supports secession","cn":"赞成（或参与）脱离活动的；奉行分离主义的","ex":{"en":"a military campaign against the secessionists","cn":"对分离主义者采取的军事行动"},"pos":"noun"}]}},"seance":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"降神会(设法与亡灵对话的集会)","en":"A seance is a meeting in which people try to make contact with people who have died."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a meeting where people try to talk to or receive messages from the spirits of dead people","cn":"降神会〔试图与亡灵对话的集会〕"}]},"media":{"uk":"media/ldoce/hwd/bre/1/brelasdeseance.mp3","us":"media/ldoce/hwd/ame/2/amelasdeseance.mp3"},"oxford":{"phon":"ˈseɪɒ̃s","pos":"noun","senses":[{"en":"a meeting at which people try to make contact with and talk to the spirits of dead people","cn":"降神会（设法和亡灵说话）"}]}},"sergeant":{"collins":{"senses":[{"pos":"N-COUNT; N-TITLE; N-VOC可数名词；头衔名词；称呼名词","cn":"(陆军、海军陆战队或空军的)中士","en":"A sergeant is a non-commissioned officer of middle rank in the army, marines, or air force.","ex":{"en":"A sergeant with a detail of four men came into view.","cn":"一名中士和一个四人小分队出现在眼前。"}},{"pos":"N-COUNT; N-TITLE; N-VOC可数名词；头衔名词；称呼名词","cn":"(英国警察中的)巡佐;(美国警察中的)警佐，警司","en":"In the British police force, a sergeant is an officer with the next to lowest rank. In American police forces, a sergeant is an officer with the rank immediately below a captain.","ex":{"en":"... the unit headed by Sergeant Bell.","cn":"由贝尔巡佐带领的分队。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a low rank in the army, air force, police etc, or someone who has this rank","cn":"军士〔一种低级军阶〕﹔中士﹔〔警察的〕巡佐"}]},"vocab":{"pos":"n","senses":[{"en":"Sergeant describes a certain rank for a police or military officer. If you've been promoted to sergeant , congratulations are in order."}]},"collocations":{"phrases":["ADJ. flight, platoon • Note at RANK 2 officer in the police","ADJ. police | detective Detective Sergeant Peter Wiles | desk, duty, station Visitors to the police station should report to the station ser","PHRASES the rank of sergeant"]},"media":{"uk":"media/ldoce/hwd/bre/f/sergeant0205.mp3","us":"media/ldoce/hwd/ame/f/ld44sergeant.mp3"},"examples":[{"en":"Sergeant Salter","cn":"索尔特中士"}],"oxford":{"phon":"ˈsɑːdʒənt","pos":"noun","senses":[{"en":"a member of one of the middle ranks in the army and the air force, below an officer","cn":"陆军（或空军）中士","ex":{"en":"Sergeant Salter","cn":"索尔特中士"}},{"en":"(in the UK) a police officer just below the rank of an inspector","cn":"（英国警察）巡佐","ex":{"en":"Detective Sergeant Peter Wiles","cn":"彼得・怀尔斯探长"}},{"en":"(in the US) a police officer just below the rank of a lieutenant or captain","cn":"（美国警察）警佐"}]}},"seabird":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"海鸟","en":"Seabirds are birds that live near the sea and get their food from it.","ex":{"en":"The island is covered with seabirds.","cn":"岛上到处都是海鸟。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a bird that lives near the sea and finds food in it","cn":"海鸟"}]},"media":{"uk":"media/ldoce/hwd/bre/b/ld41seabird.mp3","us":"media/ldoce/hwd/ame/b/ld41seabird.mp3"},"oxford":{"phon":"ˈsiːbɜːd","pos":"noun","senses":[{"en":"a bird that lives close to the sea, for example on cliffs or islands, and gets its food from it","cn":"海鸟"}]}},"self-serving":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"只为个人打算的;一心谋私利的","en":"If you describe someone as self-serving, you are critical of them because they are only interested in what they can get for themselves.","ex":{"en":"They suggest that my motives for proposing reform are self-serving and mercenary.","cn":"他们暗示说我之所以提议改革是贪图金钱，想谋取私利。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"thinking only about what you need or want, and not thinking about how other people feel or what other people want – used especially when criticizing a person or their behaviour","cn":""},{"en":"believing that what you do and think is the most important thing, and not paying attention to what anyone else thinks or does – used when describing someone’s personality","cn":""},{"en":"believing that you are better or more important than other people","cn":""}]},"media":{"uk":"media/ldoce/hwd/bre/f/ld41self-serving.mp3","us":"media/ldoce/hwd/ame/9/laadself-serving.mp3"},"examples":[{"en":"self-serving politicians","cn":"只为自己打算的政客"}],"oxford":{"phon":"ˌself ˈsɜːvɪŋ","pos":"adjective","senses":[{"en":"interested only in gaining an advantage for yourself","cn":"只为个人打算的；一心谋私利的","ex":{"en":"He was a ruthless, self-serving politician.","cn":"他是一个冷酷无情、自私自利的政治家。"}}]}},"serialization":{"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"(书的)连续发表，连续刊载","en":"Serialization is the act of serializing a book."},{"pos":"N-COUNT 可数名词","cn":"连载小说;连续剧","en":"A serialization is a story, originally written as a book, which is being published or broadcast in a number of parts.","ex":{"en":"...in the serialisation of Jane Austen's Pride and Prejudice.","cn":"在根据简·奥斯汀的小说《傲慢与偏见》改编的系列剧中"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to print or broadcast a story in several separate parts","cn":""}]},"media":{"uk":"media/ldoce/hwd/bre/9/ld41serialize.mp3","us":"media/ldoce/hwd/ame/d/serialize.mp3"},"examples":[{"en":"a newspaper serialization of the book","cn":"这部书在报上的连载"},{"en":"His book was serialized in The New Yorker.","cn":""}],"oxford":{"phon":"ˌsɪəriəlaɪˈzeɪʃn","pos":"noun","senses":[{"en":"the act of publishing or broadcasting something in parts as a serial","cn":"连载；连播","ex":{"en":"a newspaper serialization of the book","cn":"这本书在报纸上的连载"}}]}},"semicircular":{"collins":{"senses":[{"pos":"ADJ 形容词","cn":"半圆形的","en":"Something that is semi-circular has the shape of half a circle.","ex":{"en":"...a semi-circular amphitheatre.","cn":"半圆形露天竞技场"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a shape with four straight sides that are equal in length and four angles of 90 degrees","cn":""},{"en":"a round shape that is like an O","cn":""},{"en":"half a circle","cn":""}]},"media":{"uk":"media/ldoce/hwd/bre/1/semicircle0205.mp3","us":"media/ldoce/hwd/ame/1/semicircle.mp3"},"examples":[{"en":"a semicircular driveway","cn":"半圆形车道"},{"en":"About 50 children sat in a semicircle around me.","cn":""}],"oxford":{"phon":"ˌsemiˈsɜːkjələ(r)","pos":"adjective","senses":[{"en":"forming or having a shape like one half of a circle","cn":"半圆的","ex":{"en":"a semicircular driveway","cn":"半圆形车道"}}]}},"serviceable":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"可用的;够用的;性能良好的","en":"If you describe something as serviceable, you mean that it is good enough to be used and to perform its function.","ex":{"en":"His Arabic was not as good as his English, but serviceable enough","cn":"他的阿拉伯语没有他的英语好，但是够用了。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"ready or able to be used","cn":"可供使用的﹐能用的"}]},"vocab":{"pos":"adj","senses":[{"en":"When something is serviceable , it's useful just the way it is. You might describe your rusty old car as perfectly serviceable if it always gets you where you need to go."}]},"media":{"uk":"media/ldoce/hwd/bre/5/ld41serviceable.mp3","us":"media/ldoce/hwd/ame/0/serviceable.mp3"},"examples":[{"en":"The carpet is worn but still serviceable.","cn":"地毯旧了，但还能用。"},{"en":"Some of these old tools are still serviceable.","cn":"这些旧工具有些仍可使用。"}],"oxford":{"phon":"ˈsɜːvɪsəbl","pos":"adjective","senses":[{"en":"of good enough quality to be used","cn":"能用的；可用的","ex":{"en":"The carpet is worn but still serviceable.","cn":"地毯旧了，但还能用。"}}]}},"sermon":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"布道;讲道","en":"A sermon is a talk on a religious or moral subject that is given by a member of the clergy as part of a church service."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a talk, especially a formal one about a particular subject, given to a group of people","cn":""},{"en":"a speech that a very important person gives to a large group of people","cn":""},{"en":"an occasion when someone speaks to a group of people giving them information about a particular subject or about their experiences","cn":""}]},"vocab":{"pos":"n","senses":[{"en":"A sermon is a speech, usually religious in nature, given by a priest, preacher, rabbi, or other religious leader as part of a service."}]},"collocations":{"phrases":["ADJ. lengthy, long | short","VERB + SERMON deliver, give, preach","PREP. during/in a/the ~ He fell asleep during the sermon. | ~ against He gave a long sermon against abortion. | ~ on She preached a sermon o"]},"media":{"uk":"media/ldoce/hwd/bre/7/sermon0205.mp3","us":"media/ldoce/hwd/ame/d/sermon.mp3"},"examples":[{"en":"The vicar gave a sermon on charity.","cn":"牧师作了一次关于仁爱的布道。"}],"oxford":{"phon":"ˈsɜːmən","pos":"noun","senses":[{"en":"a talk on a moral or religious subject, usually given by a religious leader during a service","cn":"布道；讲道","lab":"North American English","ex":{"en":"She preached a sermon on forgiveness.","cn":"她进行了一番关于宽恕的说教。"}},{"en":"moral advice that a person tries to give you in a long talk","cn":"冗长的说教","lab":"informal, usually disapproving，，","ex":{"en":"We had to listen to a long sermon on the evils of wasting time.","cn":"我们不得不听一场关于浪费时间的罪恶的长篇布道。"}}]}},"segregation":{"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"(因种族、性别、宗教不同而采取的)隔离措施，隔离政策","en":"Segregation is the official practice of keeping people apart, usually people of different sexes, races, or religions.","ex":{"en":"The Supreme Court unanimously ruled that racial segregation in schools was unconstitutional","cn":"联邦最高法院一致裁定学校实行的种族隔离措施违反宪法。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"the bringing or coming together of people of different races so that they live and work peacefully together","cn":""},{"en":"keeping people of different races apart and making them live, work, or study separately, especially because one race believes that it is better than the other","cn":""},{"en":"to keep two or more people apart, especially so that they cannot cause any trouble together","cn":""}]},"vocab":{"pos":"n","senses":[{"en":"Segregation is a system that keeps different groups separate from each other, either through physical dividers or using social pressures and laws."}]},"collocations":{"phrases":["ADJ. complete | racial, religious, residential, sex, social to bring an end to sex segregation within the school","VERB + SEGREGATION practise","PREP. ~ between Partitions provided a segregation between the smoking and non-smoking areas of the canteen. | ~ by segregation by race | ~ w"]},"media":{"uk":"media/ldoce/hwd/bre/7/ld41segregation.mp3","us":"media/ldoce/hwd/ame/b/segregation.mp3"},"examples":[{"en":"the segregation of smokers and non-smokers in restaurants","cn":"把餐馆中的吸烟者与非吸烟者分隔开的做法"},{"en":"segregation by age and sex","cn":"按照年龄和性别而实施的隔离"}],"oxford":{"phon":"ˌseɡrɪˈɡeɪʃn","pos":"noun","senses":[{"en":"the act or policy of separating people from different groups, for example people of different races, religions or sexes, and treating them in a different way","cn":"（对不同种族、宗教或性别的人所采取的）隔离并区别对待，隔离政策","lab":"British English","ex":{"en":"racial/religious segregation","cn":"种族／宗教隔离"}},{"en":"the act of separating people or things from a larger group","cn":"隔离（或分离）措施","lab":"formal","ex":{"en":"The report recommends segregation of cyclists from both cars and pedestrians.","cn":"报告建议把骑车人与汽车和行人分隔开。"}}]}},"sett":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"獾穴","en":"A sett is the place where a badger lives."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a passage in the ground made by a badger as a place to live","cn":"獾穴"}]},"media":{"uk":"media/ldoce/hwd/bre/8/ld41sett.mp3","us":"media/ldoce/hwd/ame/8/ld41sett.mp3"},"oxford":{"phon":"set","pos":"noun","senses":[{"en":"a hole in the ground where a badger lives","cn":"獾穴"}]}},"seaborne":{"collins":{"senses":[{"pos":"ADJ 形容词","cn":"在海上的;发生于海上的","en":"Seaborne actions or events take place on the sea in ships.","ex":{"en":"...a seaborne invasion.","cn":"海上入侵"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"carried on or arriving in ships","cn":"海运的﹐经由[来自]海上的"}]},"media":{"uk":"media/ldoce/hwd/bre/4/ld41seaborne.mp3","us":"media/ldoce/hwd/ame/f/seaborne.mp3"},"examples":[{"en":"a seaborne invasion","cn":"海上入侵"},{"en":"the threat of a seaborne invasion","cn":"海上入侵的威胁"}],"oxford":{"phon":"ˈsiːbɔːn","pos":"adjective","senses":[{"en":"carried in ships","cn":"海运的","ex":{"en":"a seaborne invasion","cn":"海上入侵"}}]}},"severance":{"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"(关系、联系的)断绝，中断","en":"Severance from a person or group, or the severance of a connection, involves the ending of a relationship or connection.","ex":{"en":"...his bitter sense of severance from his family.","cn":"他与家人断绝关系的痛楚"}},{"pos":"ADJ 形容词","cn":"离职金;遣散费","en":"Severance pay is a sum of money that a company gives to its employees when it has to stop employing them.","ex":{"en":"We were offered 13 weeks' severance pay.","cn":"我们拿到了 13 个星期的薪水作为遣散费。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"when you end your relationship or connection with another person, organization, country etc, especially because of a disagreement 〔","cn":"关系或联系的〕断绝﹐中断"},{"en":"money or other things that you get when you have to leave a company because your employer no longer has a job for you","cn":"解雇金/辞退补偿"}]},"vocab":{"pos":"n","senses":[{"en":"A severance is the ending of a connection or relationship. A terrible argument between you and your cousin could turn into a full-out feud and eventually, a complete severance between the two branches of your family."}]},"media":{"uk":"media/ldoce/hwd/bre/7/ld41severance.mp3","us":"media/ldoce/hwd/ame/1/laadseverance.mp3"},"examples":[{"en":"employees given notice of severance","cn":"接到解聘通知的雇员"},{"en":"the severance of diplomatic relations","cn":"外交关系的断绝"}],"oxford":{"phon":"ˈsevərəns","pos":"noun","senses":[{"en":"the act of ending a connection or relationship","cn":"断绝；中断","ex":{"en":"the severance of diplomatic relations","cn":"外交关系的断绝"}},{"en":"the act of ending somebody’s work contract","cn":"解雇；辞退","ex":{"en":"employees given notice of severance","cn":"接到解聘通知的雇员"}}]}},"self-government":{"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"自治","en":"Self-government is government of a country or region by its own people rather than by others."}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"political freedom from control by the government of another country","cn":""},{"en":"not controlled by any other country - used especially in an official or political contexts","cn":""},{"en":"part of a country or organization that is autonomous is partly independent and has the right to organize most of its own activities, business etc","cn":""}]},"media":{"uk":"media/ldoce/hwd/bre/6/self_governing0205.mp3","us":"media/ldoce/hwd/ame/d/self-governing.mp3"},"oxford":{"phon":"ˌself ˈɡʌvənmənt","pos":"noun","senses":[{"en":"the government or control of a country or an organization by its own people or members, not by others","cn":"自治","ex":{"en":"Senegal achieved self-government in 1958 and full independence in 1960.","cn":"塞内加尔于1958年实现自治，并于1960年完全独立。"}}]}},"self-will":{"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"任性;固执;倔强","en":"Someone's self-will is their determination to do what they want without caring what other people think.","ex":{"en":"She had a little core of self-will.","cn":"她有点固执。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"very determined to do what you want, whatever other people think – used to show disapproval","cn":""}]},"media":{"uk":"media/ldoce/hwd/bre/2/self_willed0205.mp3","us":"media/ldoce/hwd/ame/c/laadself-willed.mp3"},"examples":[{"en":"a wild and self-willed child","cn":""}]},"sextant":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"六分仪(用于测算船只或飞机的位置)","en":"A sextant is an instrument used for measuring angles, for example between the sun and the horizon, so that the position of a ship or aeroplane can be calculated."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a tool for measuring angles between stars in order to calculate the position of a ship or aircraft","cn":"六分仪〔用于测量星与星之间的角度以计算船或飞机的位置〕"}]},"vocab":{"pos":"n","senses":[{"en":"A sextant is a tool for measuring the angles between heavenly bodies — the kind found in outer space. Used as a navigational tool out at sea, it helps determine a ship's longitude and latitude."}]},"media":{"uk":"media/ldoce/hwd/bre/1/ld41sextant.mp3","us":"media/ldoce/hwd/ame/4/sextant.mp3"},"oxford":{"phon":"ˈsekstənt","pos":"noun","senses":[{"en":"an instrument for measuring angles and distances, used to calculate the exact position of a ship or an aircraft","cn":"六分仪（用以计算船舶或飞机的准确位置）"}]}},"self-deception":{"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"自欺;自我欺骗","en":"Self-deception involves allowing yourself to believe something about yourself that is not true, because the truth is more unpleasant.","ex":{"en":"Human beings have an infinite capacity for self-deception.","cn":"人类自欺的本事是无穷的。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"when you make yourself believe that something is true when it is not","cn":"自我欺骗﹐自欺"}]},"media":{"uk":"media/ldoce/hwd/bre/6/self_deception0205.mp3","us":"media/ldoce/hwd/ame/4/self-deception.mp3"},"oxford":{"phon":"ˌself dɪˈsepʃn","pos":"noun","senses":[{"en":"the act of making yourself believe something that you know is not true","cn":"自我欺骗"}]}},"segregationist":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"种族隔离主义者","en":"A segregationist is someone who thinks people of different races should be kept apart.","ex":{"en":"...a segregationist on the far Right","cn":"极右派种族隔离主义者"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"relating to the practice of keeping people of different races, sexes, or religions separate 〔","cn":"种族﹑性别﹑宗教上〕隔离主义的"}]},"media":{"uk":"media/ldoce/hwd/bre/9/ld41segregationist.mp3","us":"media/ldoce/hwd/ame/9/ld41segregationist.mp3"},"examples":[{"en":"segregationist policies","cn":"隔离主义政策"}],"oxford":{"phon":"ˌseɡrɪˈɡeɪʃənɪst","pos":"adjective","senses":[{"en":"believing that people from different groups should be separated and treated differently, especially according to their race","cn":"（性别、种族、宗教）隔离主义的","ex":{"en":"segregationist policies","cn":"隔离主义政策"}},{"en":"a person who believes that people from different groups should be separated and treated differently, especially according to their race","cn":"（性别、种族、宗教）隔离主义者","pos":"noun"}]}},"seam":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"(两块布的)缝，线缝,接缝","en":"A seam is a line of stitches which joins two pieces of cloth together."},{"pos":"N-COUNT 可数名词","cn":"煤层","en":"A seam of coal is a long, narrow layer of it underneath the ground.","ex":{"en":"The average UK coal seam is one metre thick.","cn":"英国煤层的平均厚度为 1 米。"}},{"pos":"PHRASE 短语","cn":"停止正常运行;崩溃","en":"If something is coming apart at the seams or is falling apart at the seams, it is no longer working properly and may soon stop working completely.","ex":{"en":"Britain's university system is in danger of falling apart at the seams.","cn":"英国的大学体系面临分崩离析的危险。"}},{"pos":"PHRASE 短语","cn":"(场所)过于拥挤，人满为患","en":"If a place is very full, you can say that it is bursting at the seams .","ex":{"en":"The hotels of Warsaw, Prague and Budapest were bursting at the seams.","cn":"华沙、布拉格和布达佩斯的旅馆均是人满为患。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a line where two pieces of cloth, leather etc have been stitched together 〔","cn":"两块布﹑皮革等连接处的〕缝﹐线缝"},{"en":"a layer of a mineral under the ground","cn":"矿层"},{"en":"if a plan, organization etc is coming apart at the seams, so many things are going wrong with it that it will probably fail 〔","cn":"计划〕接近失败﹔〔组织〕分崩离析"}]},"vocab":{"pos":"n v","senses":[{"en":"When you sew two pieces of fabric together, the line you are sewing is the seam . Coal appears in long, linear underground deposits referred to as seams ."}]},"collocations":{"phrases":["VERB + SEAM sew, stitch, tack She sewed the seam with small neat stitches. | unpick It took hours to unpick the seams. | iron, press","PHRASES be bursting at the seams (often figurative) The film is bursting at the seams with good performances. | come/fall apart at the seams","ADJ. coal | rich They're still mining a rich seam of high-grade coal.","VERB + SEAM mine"]},"media":{"uk":"media/ldoce/hwd/bre/f/ld44seam.mp3","us":"media/ldoce/hwd/ame/2/seam.mp3"},"examples":[{"en":"( figurative ) The book is a rich seam of information.","cn":"这本书是一座丰富的知识宝库。"},{"en":"She was falling apart at the seams, spending most of her time in tears.","cn":"她成天泪汪汪的，都快垮了。"}],"oxford":{"phon":"siːm","pos":"noun","senses":[{"en":"a line along which two edges of cloth, etc. are joined or sewn together","cn":"（缝合两块布等的）线缝，接缝","ex":{"en":"a shoulder seam","cn":"衣服肩膀上的接缝"}},{"en":"a thin layer of coal or other material, between layers of rock under the ground","cn":"矿层；煤层","lab":"figurative","ex":{"en":"They struck a rich seam of iron ore.","cn":"他们开出一个富铁矿层。"}},{"en":"a line where two edges meet, for example the edges of wooden boards","cn":"（合在一起的两块木板等之间的）接缝，缝隙，裂缝","ex":{"en":"Light was spilling in through the seams of the door.","cn":"光线从门缝漏进来。"}}]}},"semiotics":{"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"符号学","en":"Semiotics is the academic study of the relationship of language and other signs to their meanings."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"the way in which people communicate through signs and images, or the study of this","cn":"符号语言﹔符号学"}]},"vocab":{"pos":"n","senses":[{"en":"In philosophy and linguistics, semiotics is the branch of study concerned with the meanings and functions of signs and symbols."}]},"media":{"uk":"media/ldoce/hwd/bre/8/semiotics0205.mp3","us":"media/ldoce/hwd/ame/e/semiotics.mp3"},"examples":[{"en":"semiotic analysis","cn":"符号分析"}],"oxford":{"phon":"ˌsemiˈɒtɪks","pos":"noun","senses":[{"en":"the study of signs and symbols and of their meaning and use","cn":"符号学"}]}},"serialize":{"collins":{"senses":[{"pos":"VERB 动词","cn":"连载，连播(小说)","en":"If a book is serialized, it is broadcast on the radio or television or is published in a magazine or newspaper in a number of parts over a period of time.","ex":{"en":"A few years ago Tom Brown's Schooldays was serialised on television.","cn":"几年前《汤姆·布朗求学记》曾作为连续剧播出过。"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to print or broadcast a story in several separate parts","cn":"连载﹔连播"}]},"media":{"uk":"media/ldoce/hwd/bre/9/ld41serialize.mp3","us":"media/ldoce/hwd/ame/d/serialize.mp3"},"examples":[{"en":"The novel was serialized on TV in six parts.","cn":"这部小说分六集在电视上播出。"},{"en":"a newspaper serialization of the book","cn":"这部书在报上的连载"}],"oxford":{"phon":"ˈsɪəriəlaɪz","pos":"verb","senses":[{"en":"to publish or broadcast something in parts as a serial","cn":"连载；连播","ex":{"en":"The novel was serialized on TV in six parts.","cn":"这部小说分六集在电视上播出。"}}]}},"seashell":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"海贝壳","en":"Seashells are the empty shells of small sea creatures."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"the empty shell of a small sea creature","cn":"海贝壳"}]},"media":{"img":["media/ldoce/img/shell.jpg"],"uk":"media/ldoce/hwd/bre/9/seashell0205.mp3","us":"media/ldoce/hwd/ame/f/seashell.mp3"},"examples":[{"en":"jewelry made out of seashells","cn":"用贝壳做的首饰"}],"oxford":{"phon":"ˈsiːʃel","pos":"noun","senses":[{"en":"the shell of a small creature that lives in the sea, often found empty when the creature has died","cn":"海贝壳"}]}},"self-defence":{"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"(采取武力的)自卫，自我保护","en":"Self-defence is the use of force to protect yourself against someone who is attacking you.","ex":{"en":"Richards claimed he acted in self-defence after Pagett opened fire on him during a siege.","cn":"理查兹声称在一次围攻中他是在佩吉特朝他开火后才进行自卫的。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"(对待坏事的)自卫,自我保护","en":"Self-defence is the action of protecting yourself against something bad.","ex":{"en":"Jokes can be a form of self-defence.","cn":"开玩笑可以是一种自我保护。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"all the weapons, soldiers, systems, or activities that a country uses to defend itself against attack by an enemy","cn":""},{"en":"methods used by countries or people to stop themselves from being attacked or harmed","cn":""},{"en":"all the soldiers and equipment that are available for defending a country or place","cn":""}]},"collocations":{"phrases":["PREP. in ~ He told police that he had acted in self-defence. | ~ against self-defence against armed assailants","PHRASES an act of self-defence, the art of self-defence"]},"media":{"uk":"media/ldoce/hwd/bre/c/self_defence0205.mp3","us":"media/ldoce/hwd/ame/5/self-defense.mp3"},"examples":[{"en":"The man later told police that he was acting in self-defence.","cn":"事后那人告诉警察，他当时是出于自卫。"},{"en":"I'm taking classes in self-defence.","cn":"我在上课学防身术。"}],"oxford":{"phon":"ˌself dɪˈfens","pos":"noun","senses":[{"en":"something you say or do in order to protect yourself when you are being attacked, criticized, etc.","cn":"自卫；自我保护","ex":{"en":"I own a gun for self-defence.","cn":"我有支枪用以防身。"}},{"en":"the skill of being able to protect yourself from physical attack without using weapons","cn":"自卫术；防身术","ex":{"en":"I'm taking classes in self-defence.","cn":"我在上课学防身术。"}}]}},"seismology":{"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"地震学","en":"Seismology is the scientific study of earthquakes."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"the scientific study of earthquake s","cn":"对地震的科学研究"}]},"media":{"uk":"media/ldoce/hwd/bre/3/ld41seismology.mp3","us":"media/ldoce/hwd/ame/2/seismology.mp3"},"examples":[{"en":"the National Seismological Institute","cn":"国家地震研究所"}],"oxford":{"phon":"saɪzˈmɒlədʒi","pos":"noun","senses":[{"en":"the scientific study of earthquakes","cn":"地震学"}]}},"seasick":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"晕船的","en":"If someone is seasick when they are travelling in a boat, they vomit or feel sick because of the way the boat is moving.","ex":{"en":"It was quite rough at times, and she was seasick.","cn":"有时海上波涛汹涌，她就会晕船。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"feeling ill when you travel in a boat, because of the movement of the boat in the water","cn":"晕船的"},{"en":"get/feel/be seasick Hal was seasick almost at once.","cn":"哈尔几乎马上就晕船了。"}]},"media":{"uk":"media/ldoce/hwd/bre/d/seasick0205.mp3","us":"media/ldoce/hwd/ame/9/seasick.mp3"},"examples":[{"en":"to be/feel/get seasick","cn":"晕船"}],"oxford":{"phon":"ˈsiːsɪk","pos":"adjective","senses":[{"en":"feeling sick or wanting to vomit when you are travelling on a boat or ship","cn":"晕船","ex":{"en":"to be/feel/get seasick","cn":"晕船"}}]}},"sexuality":{"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"性欲;性兴趣;性感觉","en":"A person's sexuality is their sexual feelings.","ex":{"en":"In Britain, the growing discussion of women's sexuality raised its own disquiet.","cn":"在英国，对女性性欲的讨论日趋高涨，使得这一讨论本身就开始引起了不安。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"性取向","en":"You can refer to a person's sexuality when you are talking about whether they are sexually attracted to people of the same sex or a different sex.","ex":{"en":"He believes he has been discriminated against because of his sexuality.","cn":"他认为他的性取向令他一直备受歧视。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"relating to sexual feelings or behaviour","cn":""},{"en":"someone's sexual feelings or needs, that are part of their basic character","cn":""},{"en":"someone's desire to have sex - use this especially to talk about how strong or weak this is","cn":""}]},"vocab":{"pos":"n","senses":[{"en":"The noun sexuality can refer to sexual matters of all kinds. It often describes having sexual feelings. A novel about a teenager growing up may examine the awakening sexuality of its main character."}]},"collocations":{"phrases":["ADJ. female, male | human | deviant | gay, lesbian | overt Her overt sexuality shocked cinema audiences.","VERB + SEXUALITY express Victorian women were rarely allowed to express their sexuality. | come to terms with He couldn't come to terms with"]},"media":{"uk":"media/ldoce/hwd/bre/a/sexuality0205.mp3","us":"media/ldoce/hwd/ame/3/sexuality.mp3"},"examples":[{"en":"He was confused about his sexuality.","cn":"他对自己的性别感到困惑。"},{"en":"male/female sexuality","cn":"男性/女性性行为"}],"oxford":{"phon":"ˌsekʃuˈæləti","pos":"noun","senses":[{"en":"the feelings and activities connected with a person’s sexual desires","cn":"性本能；性欲；性行为","ex":{"en":"He was confused about his sexuality.","cn":"他对自己的性向感到困惑。"}}]}},"seahorse":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"海马;龙落子","en":"A seahorse is a type of small fish which appears to swim in a vertical position and whose head looks a little like the head of a horse."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a small sea fish with a head and neck that look like those of a horse","cn":"海马"}]},"media":{"img":["media/ldoce/img/seahorse.jpg"],"uk":"media/ldoce/hwd/bre/3/seahorse0205.mp3","us":"media/ldoce/hwd/ame/a/seahorse.mp3"},"oxford":{"phon":"ˈsiːhɔːs","pos":"noun","senses":[{"en":"a small sea fish that swims in a vertical position and has a head that looks like the head of a horse","cn":"海马"}]}},"seismic":{"collins":{"senses":[{"pos":"ADJ 形容词","cn":"地震的;地震引起的","en":"Seismic means caused by or relating to an earthquake.","ex":{"en":"Earthquakes produce two types of seismic waves","cn":"地震产生两种地震波。"}},{"pos":"ADJ 形容词","cn":"(转变、变化)突如其来的，巨大的，急剧的","en":"A seismic shift or change is a very sudden or dramatic change.","ex":{"en":"I have never seen such a seismic shift in public opinion in such a short period of time.","cn":"我从未见过公众舆论在如此短的时间内发生如此巨大的转变。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"relating to or caused by earthquake s","cn":"地震的﹐地震引起的"},{"en":"very great, serious, or important","cn":"极大的﹔极为严重的﹔非常重要的"}]},"vocab":{"pos":"adj","senses":[{"en":"For the ancient Greeks, \"seismos\" meant an earthquake. Later on, when the study of earthquakes became a science, anything seismic meant anything related to the study of the pressures in the Earth's crust."}]},"media":{"uk":"media/ldoce/hwd/bre/5/seismic0205.mp3","us":"media/ldoce/hwd/ame/2/seismic.mp3"},"examples":[{"en":"a seismic shift in the political process","cn":"政治进程中的剧变"},{"en":"seismic waves","cn":"地震波"}],"oxford":{"phon":"ˈsaɪzmɪk","pos":"adjective","senses":[{"en":"connected with or caused by earthquakes","cn":"地震的；地震引起的","ex":{"en":"seismic waves","cn":"地震波"}},{"en":"having a very great effect; of very great size","cn":"影响深远的；重大的","ex":{"en":"a seismic shift in the political process","cn":"政治进程中的剧变"}}]}},"self-help":{"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"(民间的)互助团体","en":"Self-help consists of people providing support and help for each other in an informal way, rather than relying on the government, authorities, or other official organizations.","ex":{"en":"She helped her Mum set up a self-help group for parents with overweight children.","cn":"她帮助母亲建起了一个互助会，帮助那些有肥胖孩子的家长。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"自助;自立;自救","en":"Self-help consists of doing things yourself to try and solve your own problems without depending on other people.","ex":{"en":"...a society that encourages competitiveness and self-help among the very young.","cn":"鼓励培养儿童的竞争意识和自立精神的社会"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"the use of your own efforts to deal with your problems, instead of depending on other people","cn":"自助﹐自立"}]},"media":{"uk":"media/ldoce/hwd/bre/9/self_help0205.mp3","us":"media/ldoce/hwd/ame/e/self-help.mp3"},"examples":[{"en":"a self-help discussion group for people suffering from depression (= whose members help each other)","cn":"抑郁症患者自助讨论小组"},{"en":"Our program emphasizes self-help.","cn":"我们这个计划强调的是自助。"}],"oxford":{"phon":"ˌself ˈhelp","pos":"noun","senses":[{"en":"the act of relying on your own efforts and abilities in order to solve your problems, rather than depending on other people for help","cn":"自助；自立"},{"en":"designed to help people solve their problems for themselves, rather than depending on other people for help","cn":"自助；自立","ex":{"en":"a self-help book/guru","cn":"一本自助书/大师"},"pos":"adjective"}]}},"secateurs":{"collins":{"senses":[{"pos":"N-PLURAL 复数名词","cn":"整枝剪;修枝剪","en":"Secateurs are a gardening tool that look like a pair of strong, heavy scissors. Secateurs are used for cutting the stems of plants."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"strong scissors used for cutting plant stems","cn":"修枝剪﹐整枝剪"}]},"media":{"uk":"media/ldoce/hwd/bre/c/ld41secateurs.mp3","us":"media/ldoce/hwd/ame/c/ld41secateurs.mp3"},"examples":[{"en":"a pair of secateurs","cn":"一把整枝剪"}],"oxford":{"phon":"ˌsekəˈtɜːz","pos":"noun","senses":[{"en":"a garden tool like a pair of strong scissors, used for cutting plant stems and small branches","cn":"整枝剪；修枝剪","ex":{"en":"a pair of secateurs","cn":"一把整枝剪"}}]}},"servile":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"奴性的;逢迎的;恭顺的","en":"If you say that someone is servile, you disapprove of them because they are too eager to obey someone or do things for them.","ex":{"en":"He was subservient and servile","cn":"他低声下气、卑躬屈膝。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"always willing to do what someone tells you to do even if it is unpleasant or they ask you in an unpleasant way","cn":""},{"en":"someone who always agrees with and obeys their employer or leader etc","cn":""},{"en":"obeying someone too eagerly and showing them too much respect","cn":""}]},"vocab":{"pos":"adj","senses":[{"en":"If you want to get someone to like you, don't offer to fetch them a Coke, rub their feet, or do their homework. They won't like you any better, and your servile attitude will only cost you their respect."}]},"media":{"uk":"media/ldoce/hwd/bre/9/servile0205.mp3","us":"media/ldoce/hwd/ame/2/servile.mp3"},"examples":[{"en":"a servile attitude","cn":"卑躬屈膝的态度"}],"oxford":{"phon":"ˈsɜːvaɪl","pos":"adjective","senses":[{"en":"wanting too much to please somebody and obey them","cn":"奴性的；逢迎的；恭顺的","ex":{"en":"Parents have no right to demand servile obedience from their children.","cn":"父母无权要求子女对自己百依百顺。"}}]}},"sepia":{"collins":{"senses":[{"pos":"COLOUR 颜色词","cn":"深棕色;旧照片色","en":"Something that is sepia is deep brown in colour, like the colour of very old photographs.","ex":{"en":"The walls are hung with sepia photographs of old school heroes.","cn":"墙上挂满了老牌英雄人物发黄的旧照片。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a dark reddish-brown colour","cn":"深褐色"},{"en":"a photograph, picture etc, especially an old one, that is dark reddish-brown","cn":"泛黄的照片/版画"},{"en":"a dark reddish-brown ink used for drawing","cn":"深褐色墨汁"}]},"media":{"uk":"media/ldoce/hwd/bre/5/ld41sepia.mp3","us":"media/ldoce/hwd/ame/e/sepia.mp3"},"examples":[{"en":"sepia ink/prints/photographs","cn":"深褐色墨水/印刷品/照片"}],"oxford":{"phon":"ˈsiːpiə","pos":"adjective","senses":[{"en":"made using sepia (= a brown substance used in inks and paints and used in the past for printing photographs)","cn":"乌贼墨颜料（或墨汁）","ex":{"en":"sepia photographs/prints/ink","cn":"棕褐色照片/印刷品/墨水"}},{"en":"red-brown in colour","cn":"赤褐色的","ex":{"en":"a sepia tone/tint","cn":"棕褐色调/色调"}},{"en":"a brown substance used in inks and paints and used in the past for printing photographs","cn":"乌贼墨颜料（或墨汁）","pos":"noun"},{"en":"a red-brown colour","cn":"深褐色","pos":"noun"}]}},"sealant":{"collins":{"senses":[{"pos":"N-MASS 物质名词","cn":"密封胶;密封剂;密封材料","en":"A sealant is a substance that is used to seal holes, cracks, or gaps."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a substance that is put on the surface of something to protect it from air, water etc","cn":"密封胶﹐密封剂﹐防渗漏剂"}]},"media":{"uk":"media/ldoce/hwd/bre/2/sealant0205.mp3","us":"media/ldoce/hwd/ame/5/laadsealant.mp3"},"oxford":{"phon":"ˈsiːlənt","pos":"noun","senses":[{"en":"a substance that is put onto a surface to stop air, water, etc. from entering or escaping from it","cn":"密封剂；密封胶；防渗漏剂"}]}},"sectional":{"collins":{"senses":[{"pos":"ADJ 形容词","cn":"(社会或国家中)某群体的，某阶层的","en":"Sectional interests are those of a particular group within a community or country.","ex":{"en":"He criticized the selfish attitude of certain sectional interests.","cn":"他批评了某些利益团体自私自利的态度。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"concerned only with your own small group in society or in an organization, as opposed to being concerned about society or the institution as a whole","cn":"某一群体的﹐局部的"},{"en":"a sectional drawing or view of something shows what it would look like if it were cut from top to bottom, or from side to side","cn":"剖面的﹔截面的"},{"en":"made up of sections that can be put together or taken apart","cn":"拼合而成的﹐可拆卸的"}]},"media":{"uk":"media/ldoce/hwd/bre/2/ld41sectional.mp3","us":"media/ldoce/hwd/ame/9/sectional.mp3"},"examples":[{"en":"the sectional interests of managers and workers","cn":"管理层和广大工人的不同利益"},{"en":"a sectional building","cn":"组合式建筑"}],"oxford":{"phon":"ˈsekʃənl","pos":"adjective","senses":[{"en":"connected with one particular group within a community or an organization","cn":"（社团或组织中）某群体的，某阶层的","ex":{"en":"the sectional interests of managers and workers","cn":"管理层和广大工人的不同利益"}},{"en":"made of separate sections","cn":"组合式的","ex":{"en":"a sectional building","cn":"组合式建筑"}},{"en":"connected with a cross section of something (= a surface or an image formed by cutting through something from top to bottom)","cn":"剖面的；断面的","ex":{"en":"a sectional drawing","cn":"剖面图"}}]}},"segmented":{"collins":{"senses":[{"pos":"ADJ 形容词","cn":"分割的;切断的;划分的","en":"Segmented means divided into parts that are loosely connected to each other.","ex":{"en":"...segmented oranges.","cn":"切成瓣的橙子"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"consisting of separate parts that are connected to each other","cn":"分节的﹐分段的"}]},"media":{"uk":"media/ldoce/hwd/bre/6/brelasdesegmented.mp3","us":"media/ldoce/hwd/ame/0/laadsegmented.mp3"},"examples":[{"en":"segmented worms","cn":"环节动物"}]},"sentry":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"哨兵;警卫","en":"A sentry is a soldier who guards a camp or a building.","ex":{"en":"The sentry would not let her enter","cn":"警卫不让她进去。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a soldier standing outside a building as a guard","cn":"哨兵﹐卫兵﹐岗哨"}]},"vocab":{"pos":"n","senses":[{"en":"A sentry is someone who stands guard or watches against some intrusion or unwelcome activity. Your dog stands sentry over your house, but he would be more effective if he barked at strangers instead of licking their hands."}]},"media":{"uk":"media/ldoce/hwd/bre/8/sentry0205.mp3","us":"media/ldoce/hwd/ame/0/sentry.mp3"},"examples":[{"en":"to be on sentry duty","cn":"放哨"}],"oxford":{"phon":"ˈsentri","pos":"noun","senses":[{"en":"a soldier whose job is to guard something","cn":"哨兵","ex":{"en":"to be on sentry duty","cn":"放哨"}}]}},"sensitize":{"collins":{"senses":[{"pos":"VERB 动词","cn":"使敏感;使意识到","en":"If you sensitize people to a particular problem or situation, you make them aware of it.","ex":{"en":"It seems important to sensitize people to the fact that depression is more than the blues","cn":"让人们意识到抑郁症不仅仅是心情忧郁，这点似乎很重要。"}},{"pos":"VERB 动词","cn":"使对…有反应;使敏化;使过敏","en":"If a substance is sensitized to something such as light or touch, it is made sensitive to it.","ex":{"en":"Skin is easily irritated, chapped, chafed, and sensitized.","cn":"皮肤很容易受到刺激、发生皴裂、擦得红肿和出现过敏。"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to give someone some experience or knowledge of a particular problem or situation so that they can notice it and understand it easily","cn":"使敏感﹐使意识到"},{"en":"if someone is sensitized to a particular substance, their body has begun to have a bad reaction whenever they touch it, breathe it etc","cn":"对…开始过敏﹐对…产生过敏反应"},{"en":"to treat a material or a piece of equipment so that it will react to physical or chemical changes","cn":"使〔对物理或化学变化〕敏感"}]},"media":{"uk":"media/ldoce/hwd/bre/9/ld41sensitize.mp3","us":"media/ldoce/hwd/ame/b/sensitize.mp3"},"examples":[{"en":"People are becoming more sensitized to the dangers threatening the environment.","cn":"人们越来越意识到危害环境的各种因素。"},{"en":"Volunteers need to be sensitized to the cultural differences they will meet in African countries.","cn":"志愿者需要认识到他们在非洲国家将遇到的文化差异。"}],"oxford":{"phon":"ˈsensətaɪz","pos":"verb","senses":[{"en":"to make somebody/something more aware of something, especially a problem or something bad","cn":"使敏感（尤指对问题或不好的事）；使意识到","ex":{"en":"People are becoming more sensitized to the dangers threatening the environment.","cn":"人们越来越意识到危害环境的各种因素。"}},{"en":"to make somebody/something sensitive to physical or chemical changes, or to a particular substance","cn":"使对…过敏","lab":"specialist","ex":{"en":"Anxious people can become acutely sensitized to their bodies, noticing and focussing on minor bodily changes.","cn":"焦虑的人会对自己的身体变得非常敏感，注意到并关注身体的微小变化。"}}]}},"settee":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"(可供两人以上坐的、有靠背及扶手的)长沙发，长靠椅","en":"A settee is a long comfortable seat with a back and arms, which two or more people can sit on."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a long comfortable seat with a back and usually with arms, for more than one person to sit on","cn":"长沙发﹐长靠椅"}]},"collocations":{"phrases":["ADJ. comfortable, comfy | chintz, leather-covered, etc. | three-seater, two-seater | wide","VERB + SETTEE sink down on/onto, sit (down) on, slump down on/onto He slumped down exhausted on the settee. | be sprawled on, lie on, sprawl","PREP. on the ~ She found her glasses lying on the settee.","PHRASES the arm/back of a settee"]},"media":{"img":["media/ldoce/img/sofa.jpg"],"uk":"media/ldoce/hwd/bre/2/settee0205.mp3","us":"media/ldoce/hwd/ame/c/settee.mp3"},"oxford":{"phon":"seˈtiː","pos":"noun","senses":[{"en":"a long comfortable seat with a back and arms, for two or more people to sit on","cn":"长沙发","ex":{"en":"He slumped down exhausted on the settee.","cn":"他筋疲力尽地跌坐在长椅上。"}}]}},"seafaring":{"collins":{"senses":[{"pos":"ADJ 形容词","cn":"以航海为业的;定期出海旅行的","en":"Seafaring means working as a sailor or travelling regularly on the sea.","ex":{"en":"The Lebanese were a seafaring people.","cn":"黎巴嫩人曾是一个航海民族。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"working or travelling on ships and the sea","cn":"海上劳作的﹔航海的"}]},"media":{"uk":"media/ldoce/hwd/bre/f/seafaring0205.mp3","us":"media/ldoce/hwd/ame/5/seafaring.mp3"},"examples":[{"en":"a seafaring nation","cn":"航海民族"},{"en":"a seafaring man","cn":"海员"}],"oxford":{"phon":"ˈsiːfeərɪŋ","pos":"adjective","senses":[{"en":"connected with work or travel on the sea","cn":"海上劳作（或航行）的","ex":{"en":"a seafaring nation","cn":"航海民族"}},{"en":"work or travel on the sea","cn":"海上劳作（或航行）的","pos":"noun"}]}},"self-denial":{"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"自我剥夺;自我牺牲;克己忘我","en":"Self-denial is the habit of refusing to do or have things that you would like, either because you cannot afford them, or because you believe it is morally good for you not to do them or have them.","ex":{"en":"Should motherhood necessarily mean sacrifice and self-denial?","cn":"做母亲就一定要牺牲和忘我吗？"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"when you do not do or have the things you enjoy, for moral or religious reasons 〔","cn":"出于道德或宗教原因的〕克己﹐苦行"}]},"media":{"uk":"media/ldoce/hwd/bre/a/ld41self-denial.mp3","us":"media/ldoce/hwd/ame/3/self-denial.mp3"},"oxford":{"phon":"ˌself dɪˈnaɪəl","pos":"noun","senses":[{"en":"the act of not having or doing the things you like, either because you do not have enough money, or for moral or religious reasons","cn":"克己；（宗教）弃绝自己","ex":{"en":"a life of self-denial and sacrifice","cn":"清苦、克己的生活"}}]}},"secularism":{"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"世俗主义;现世主义","en":"Secularism is a system of social organization and education where religion is not allowed to play a part in civil affairs."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a system of social organization that does not allow religion to influence the government, or the belief that religion should not influence a government","cn":"现世主义﹐世俗主义〔禁止或反对宗教对政府产生影响的社会组织体系〕"},{"en":"the quality of behaving in a way that shows religion does not influence you","cn":"现世化﹐世俗化〔指行为方式不受宗教影响〕"}]},"vocab":{"pos":"n","senses":[{"en":"Secularism is a way of life and thinking that rejects religion. So if you're into secularism , you're not into God, going to church, praying, or anything holy."}]},"media":{"uk":"media/ldoce/hwd/bre/e/ld41secularism.mp3","us":"media/ldoce/hwd/ame/a/secularism.mp3"},"examples":[{"en":"the secularism of popular culture","cn":"大众文化的世俗化"}],"oxford":{"phon":"ˈsekjələrɪzəm","pos":"noun","senses":[{"en":"the belief that religion should not be involved in the organization of society, education, etc.","cn":"现世主义，世俗主义（认为社会结构和教育等应排除宗教的影响）"}]}},"sentinel":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"哨兵;卫兵;岗哨","en":"A sentinel is a sentry."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a sentry","cn":"哨兵﹐卫兵﹐岗哨"}]},"vocab":{"pos":"n","senses":[{"en":"A sentinel is a guard, a lookout, a person keeping watch. It's often a soldier, but not always. If you're watching a pot, waiting for it to boil, you're standing sentinel over it — and incidentally, it won't boil until you leave."}]},"media":{"uk":"media/ldoce/hwd/bre/a/ld41sentinel.mp3","us":"media/ldoce/hwd/ame/4/sentinel.mp3"},"examples":[{"en":"( figurative ) a tall round tower standing sentinel over the river","cn":"一座高高的圆塔镇守在河边"}],"oxford":{"phon":"ˈsentɪnl","pos":"noun","senses":[{"en":"a soldier whose job is to guard something","cn":"哨兵","lab":"figurative","ex":{"en":"a tall round tower standing sentinel over the river","cn":"镇守在河边的一座高高的圆塔"}}]}},"self-styled":{"collins":{"senses":[{"pos":"ADJ 形容词","cn":"自诩的;自封的","en":"If you describe someone as a self-styled leader or expert, you disapprove of them because they claim to be a leader or expert but they do not actually have the right to call themselves this.","ex":{"en":"Two of those arrested are said to be self-styled area commanders","cn":"据说在那些被捕的人员中有两人自称是地区指挥官。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"a word used to describe someone or something that has been given a name that you think is wrong","cn":""},{"en":"a name that is not correct or does not seem suitable","cn":""},{"en":"having the name of a job or position in society, but not actually doing that job or having the responsibilities that go with it","cn":""}]},"media":{"uk":"media/ldoce/hwd/bre/7/ld41self-styled.mp3","us":"media/ldoce/hwd/ame/9/self-styled.mp3"},"oxford":{"phon":"ˌself ˈstaɪld","pos":"adjective","senses":[{"en":"using a name or title that you have given yourself, especially when you do not have the right to do it","cn":"自封的；自诩的"}]}},"self-knowledge":{"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"自知;自我认识","en":"Self-knowledge is knowledge that you have about your own character and nature.","ex":{"en":"The more self-knowledge we have, the more control we can exert over our feelings and behaviour.","cn":"我们越有自知之明就越能控制自己的感情和行为。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"an understanding of your own character and behaviour","cn":"自我认识﹐自知（之明）"}]},"media":{"uk":"media/ldoce/hwd/bre/f/ld41self-knowledge.mp3","us":"media/ldoce/hwd/ame/5/self-knowledge.mp3"},"oxford":{"phon":"ˌself ˈnɒlɪdʒ","pos":"noun","senses":[{"en":"an understanding of yourself","cn":"自我了解；自知之明"}]}},"second-rate":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"二流的;二等的;劣质的","en":"If you describe something as second-rate, you mean that it is of poor quality.","ex":{"en":"...second-rate restaurants.","cn":"二流餐馆"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"not good - use this when you are disappointed because you were expecting something better","cn":""},{"en":"something that is mediocre is of a lower standard than it should be, and does not show much quality or skill","cn":""},{"en":"not very bad, but not especially good","cn":""}]},"media":{"uk":"media/ldoce/hwd/bre/9/brelasdesecond-rate.mp3","us":"media/ldoce/hwd/ame/8/second-rate.mp3"},"examples":[{"en":"a second-rate player","cn":"平庸的运动员"},{"en":"a second-rate artist","cn":"二流艺术家"}],"oxford":{"phon":"ˌsekənd ˈreɪt","pos":"adjective","senses":[{"en":"not very good or impressive","cn":"二流的；平庸的；普通的","ex":{"en":"a second-rate player","cn":"平庸的运动员"}}]}}});
